// A-level Physics — Model Answers
// Covers all 33 past papers: AQA (7408), Edexcel (9PH0), OCR A (H556), OCR B (H557)
// Papers: June 2022, June 2023, June 2024 across all four boards
// Key format: "paperId::partCode"
window.PHYSICS_MODEL_ANSWERS = {
  "phys-aqa-7408-2022-p1::01.1": `²³⁸₉₂U → ²³⁴₉₀Th + ⁴₂He

The nucleon number decreases by 4 (238 − 4 = 234) and the proton number decreases by 2 (92 − 2 = 90), confirming alpha emission produces thorium-234.`,
  "phys-aqa-7408-2022-p1::01.2": `The exchange particle is the W⁻ boson. In the decay of tritium (³₁H → ³₂He + e⁻ + ν̄ₑ), a neutron changes into a proton; this involves a down quark changing into an up quark. This is a weak interaction, mediated by the W⁻ boson, which carries away the negative charge to produce the electron and antineutrino.`,
  "phys-aqa-7408-2022-p1::01.3": `Line C of the helium spectrum, at about 490 nm, lies at the same wavelength as one of the hydrogen lines, and line E, at about 590 nm, lies at the same wavelength as a sodium line. These two lines are evidence for the suggestion, because they could have been produced by hydrogen and sodium already known to be present in the Sun.

The evidence against the suggestion is line D, at about 505 nm. There is no line at this wavelength in either the sodium spectrum or the hydrogen spectrum, so line D cannot be explained by the presence of those two elements. Something else — a previously unknown element, helium — must be responsible for it.`,
  "phys-aqa-7408-2022-p1::01.4": `From Figure 1, spectral line E has a wavelength of approximately 588 nm (5.88 × 10⁻⁷ m).

Energy of photon: E = hf = hc/λ
E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) / (5.88 × 10⁻⁷)
E = 1.989 × 10⁻²⁵ / 5.88 × 10⁻⁷
E = 3.38 × 10⁻¹⁹ J

Converting to eV: E = 3.38 × 10⁻¹⁹ / 1.60 × 10⁻¹⁹ = 2.11 eV

The change in energy level responsible for line E is approximately 2.11 eV.`,
  "phys-aqa-7408-2022-p1::01.5": `In an emission spectrum, electrons in atoms are excited to higher energy levels (by heating or electrical discharge). When they fall back to lower energy levels, they emit photons of specific frequencies corresponding to the energy difference between the levels: ΔE = hf. This produces bright lines at discrete frequencies on a dark background.

In an absorption spectrum, white light (containing all frequencies) passes through a cool gas. Electrons absorb photons whose energies exactly match the difference between energy levels, exciting electrons to higher levels. The photons of these specific frequencies are removed from the transmitted light, producing dark lines at the same discrete frequencies on a continuous spectrum. Both spectra have lines at the same frequencies because the energy level differences are the same.`,
  "phys-aqa-7408-2022-p1::02.1": `In β⁻ decay, a down quark changes into an up quark (d → u).`,
  "phys-aqa-7408-2022-p1::02.2": `If only an electron were emitted in β⁻ decay, conservation of momentum and energy would require that all electrons have the same fixed kinetic energy (since the products are the recoiling nucleus and one electron). However, Figure 2 shows a continuous spectrum of kinetic energies for the β⁻ particles, ranging from zero up to a maximum value. This means energy is shared between the electron and another particle — the antineutrino (ν̄ₑ) — in varying proportions. The antineutrino carries the 'missing' energy and momentum, supporting its existence.`,
  "phys-aqa-7408-2022-p1::02.3": `Particle X is a neutron.

Charge is conserved: 0 + (+1) on the left must equal (+1) + charge of X, so X is neutral. Baryon number is conserved: 0 + 1 on the left must equal 0 + baryon number of X, so X is a baryon. (Lepton number also balances: −1 on the left, −1 for the positron, so X has lepton number 0.) The only neutral baryon here is the neutron.`,
  "phys-aqa-7408-2022-p1::02.4": `When a positron annihilates with an electron the minimum energy released is the total rest energy of the two particles:

E_min = 2 mₑc² = 2 × 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 1.6 × 10⁻¹³ J
(equivalently 2 × 0.51 MeV = 1.02 MeV = 1.6 × 10⁻¹³ J)

Two gamma photons are produced, so the minimum energy of each photon is

E = 1.6 × 10⁻¹³ / 2 = 8.2 × 10⁻¹⁴ J

G1 (5.0 × 10⁻¹⁴ J) and G2 (6.6 × 10⁻¹⁴ J) both carry less than 8.2 × 10⁻¹⁴ J, so neither can have come from annihilation. G3 has an energy of 1.0 × 10⁻¹³ J, which is greater than the minimum, the extra energy coming from the kinetic energy of the annihilating particles.

Only G3 could have been produced by positron annihilation.`,
  "phys-aqa-7408-2022-p1::03.1": `A is a solid cylinder of diameter 4.8 × 10⁻² m (radius 2.4 × 10⁻² m) and length 0.23 m.

Volume of A = πr²L = π × (2.4 × 10⁻²)² × 0.23 = 4.16 × 10⁻⁴ m³

If A were made of brass: mass = ρV = 8.6 × 10³ × 4.16 × 10⁻⁴ = 3.58 kg, so its weight would be 3.58 × 9.81 = 35 N.

This is exactly the weight given for A, so A is made of brass. (The same volume of iron would weigh 7.8 × 10³ × 4.16 × 10⁻⁴ × 9.81 = 32 N and of concrete only 9.8 N, so neither of those fits.)`,
  "phys-aqa-7408-2022-p1::03.2": `Pulleys P and M are frictionless and M is weightless, so the tension throughout the rope equals the weight of A, 35 N. Both sections of rope at M make an angle of 55° with the horizontal, so each pulls on M with a horizontal component of

35 cos 55° = 20.1 N

Cable C has to balance both of these components, so

tension in C = 2 × 20.1 = 40 N`,
  "phys-aqa-7408-2022-p1::03.3": `As pulley M is pulled to the left, the two sections of rope on either side of M become less steeply inclined, so the angle each makes with the horizontal decreases.

The pulleys are frictionless and M is weightless, so the tension in the rope stays the same, equal to the weight of A (35 N). The horizontal component of each section, 35 cos θ, therefore gets larger as θ gets smaller. Cable C must balance the sum of these two horizontal components, so the tension in cable C increases.`,
  "phys-aqa-7408-2022-p1::03.4": `The moment of the tension about the hinge = force × perpendicular distance from the hinge to the line of action of the force.

The perpendicular distance = horizontal distance × sin(angle between cable and door)
Perpendicular distance = 0.95 × sin(12°) = 0.95 × 0.2079 = 0.1975 m

Moment = T × perpendicular distance = 41 × 0.1975 = 8.1 N m

The moment of the tension about the hinge is 8.1 N m.`,
  "phys-aqa-7408-2022-p1::03.5": `Two independent changes that would increase the moment about the hinges due to cable C:

1. Increase the tension in cable C: This could be achieved by using a heavier counterweight A. A greater weight of A increases the tension in the rope, which (by the pulley arrangement) increases the tension in cable C. A greater tension, with the same geometry, produces a greater moment (moment = F × d).

2. Increase the perpendicular distance from the hinge to the line of action of cable C: This could be done by moving the attachment point D further from the hinge (increasing the distance along the gate), or by changing the angle at which cable C meets the gate so that the perpendicular distance is larger. For example, repositioning pulley R so that cable C approaches the gate at a larger angle (closer to 90°) to the gate would maximise the perpendicular distance and hence the moment.`,
  "phys-aqa-7408-2022-p1::04.1": `R = V²/P = (6.2)²/4.5 = 38.44/4.5 = 8.54 Ω ≈ 9 Ω ✓`,
  "phys-aqa-7408-2022-p1::04.2": `Resistance of the lamp at its working pd: R = V²/P = 6.2²/4.5 = 8.54 Ω

Current in the lamp: I = V/R = 6.2/8.54 = 0.73 A
Current in the 12 Ω resistor: I = 6.2/12 = 0.52 A

The lamp and the resistor are in parallel across the battery terminals, so the total current drawn from the battery is

I = 0.73 + 0.52 = 1.24 A

emf = terminal pd + Ir = 6.2 + (1.24 × 2.5) = 6.2 + 3.1 = 9.3 V`,
  "phys-aqa-7408-2022-p1::04.3": `Resistivity ρ = RA/L

Diameter d = 0.19 mm = 0.19 × 10⁻³ m
Cross-sectional area A = π(d/2)² = π × (0.095 × 10⁻³)² = π × 9.025 × 10⁻⁹ = 2.835 × 10⁻⁸ m²

ρ = RA/L = (9.0 × 2.835 × 10⁻⁸) / 5.0
ρ = 2.551 × 10⁻⁷ / 5.0
ρ = 5.1 × 10⁻⁸ Ω m

The resistivity of the wire is 5.1 × 10⁻⁸ Ω m.`,
  "phys-aqa-7408-2022-p1::04.4": `As the contact is moved to the right, the length of wire in series with the lamp increases, so the resistance of the variable resistor increases. With a greater total resistance in the circuit, the current decreases. A smaller current means less power dissipated in the lamp (P = I²R_lamp), so the lamp gets dimmer. Eventually (at maximum resistance), the current is at its minimum value and the lamp is at its dimmest.`,
  "phys-aqa-7408-2022-p1::04.5": `Moving the contact to the right increases the length of resistance wire connected in parallel with the lamp, so the resistance of that parallel branch increases.

The resistance of the parallel combination of lamp and wire therefore increases, so the total resistance of the external circuit increases and the current drawn from the battery falls. A smaller current through the battery means a smaller pd lost across its internal resistance (fewer "lost volts", Ir), so the terminal pd — which is the pd across the lamp — increases.

A larger pd across the lamp gives a larger current through it and more power dissipated in it, so the lamp gets brighter.`,
  "phys-aqa-7408-2022-p1::05.1": `The turntable rotates through 2π rad in one revolution at an angular speed of 1.8 rad s⁻¹.

T = angle/angular speed = 2π/ω = 2π/1.8 = 3.49 s

The time for one revolution is 3.5 s.`,
  "phys-aqa-7408-2022-p1::05.2": `The resultant force on the block points towards the centre of the turntable (centripetal direction). Since the turntable rotates clockwise and the block is at a fixed position on the turntable, the centripetal force points radially inward from the block toward the centre of the turntable. An arrow should be drawn on Figure 10 pointing from the block's position toward the centre of the circular path (i.e., toward the axis of rotation of the turntable).`,
  "phys-aqa-7408-2022-p1::05.3": `The resultant force on the block is the centripetal force.

F = mω²r = 0.12 × (1.8)² × 0.25
F = 0.12 × 3.24 × 0.25 = 0.0972 N

The magnitude of the resultant force is 0.097 N, directed towards the centre of the turntable.`,
  "phys-aqa-7408-2022-p1::05.4": `By Newton's first law, an object continues at constant velocity (constant speed in a straight line) unless acted upon by a resultant force. The block moves in a circle, which means its velocity direction is continuously changing. This change in velocity (direction) means the block is accelerating. By Newton's second law (F = ma), a non-zero acceleration requires a resultant force. The fact that the block travels in a circular path rather than a straight line is evidence that a resultant (centripetal) force acts on it.`,
  "phys-aqa-7408-2022-p1::05.5": `For the pendulum to swing in phase with the block, the period of the pendulum must equal the period of the turntable rotation: T = 2.50 s.

T = 2π√(l/g)
2.50 = 2π√(l/9.81)
√(l/9.81) = 2.50/(2π) = 0.3979
l/9.81 = 0.3979² = 0.1583
l = 0.1583 × 9.81 = 1.55 m

The length of the simple pendulum is 1.55 m.`,
  "phys-aqa-7408-2022-p1::05.6": `Amplitude: air resistance damps the pendulum, so the pendulum's oscillations lose energy and its amplitude falls. The block is driven by the turntable and keeps a constant amplitude, so the amplitude of the pendulum's shadow becomes smaller than the amplitude of the block's shadow.

Phase: as the amplitude of the pendulum falls its time period changes slightly (its frequency increases), while the block's period stays fixed at 2.50 s. The two shadows therefore no longer complete their oscillations in step, so the phase difference between them changes and they gradually drift out of phase.`,
  "phys-aqa-7408-2022-p1::06.1": `When light travels from a denser medium to a less dense medium, it bends away from the normal (the refracted ray makes a larger angle with the normal than the incident ray). From Figure 12, the ray bends away from the normal as it crosses from A into B, meaning the ray speeds up — so the speed of light in B is greater than in A. Since refractive index n = c/v_medium, a higher speed corresponds to a lower refractive index. Therefore the refractive index of A (higher n, slower light) is greater than the refractive index of B (lower n, faster light).`,
  "phys-aqa-7408-2022-p1::06.2": `Inside A the ray runs parallel to the bottom face of the block. The A–B boundary makes an angle of 43° with that face, so the normal to the boundary makes 43° with the vertical and the angle of incidence at the boundary is

i = 90° − 43° = 47°

Applying Snell's law at the boundary:

n_A sin i = n_B sin r
1.62 × sin 47° = 1.35 × sin r
sin r = (1.62 × 0.731)/1.35 = 0.878
r = 61.4°

So the angle of refraction in B is 61°, which is about 60°.`,
  "phys-aqa-7408-2022-p1::06.3": `At P the ray meets the bottom face of B, which is a boundary between the glass of B and air.

Critical angle for B: sin θ_c = 1/n_B = 1/1.35, so θ_c = 47.8° ≈ 48°

Angle of incidence at P: the refracted ray makes 90° − 61.4° = 28.6° with the A–B boundary, and that boundary is at 43° to the bottom face, so the ray meets the bottom face at 43° − 28.6° = 14.4°. Measured from the normal to the bottom face the angle of incidence is therefore

i = 90° − 14.4° = 75.6° ≈ 76°

(equivalently i = 180° − 43° − 61.4° = 75.6°)

Since 76° is greater than the critical angle of 48°, the ray is totally internally reflected at P.

To draw it: from P draw a straight ray back up into B, on the other side of the (vertical) normal at P and at the same 76° to that normal — i.e. travelling up and to the right, rising only about 14° above the horizontal — continuing until it reaches the top surface of the block (roughly beneath the "not to scale" label).`,
  "phys-aqa-7408-2022-p2::01.1": `Energy needed to raise the temperature of the plate:

Q = mcΔθ = 1.2 × 450 × (125 − 20) = 1.2 × 450 × 105 = 5.67 × 10⁴ J

All the energy from the 2.1 kW heater is transferred to the plate, so Q = Pt:

t = Q/P = 5.67 × 10⁴ / 2100 = 27 s`,
  "phys-aqa-7408-2022-p2::01.2": `Each kilogram of water must first be heated from 20 °C to 100 °C and then vaporised.

For the claimed rate of 60 g min⁻¹ = 0.060 kg per minute, the energy needed each minute is

E = mc_wΔθ + mL = 0.060 × 4200 × (100 − 20) + 0.060 × 2.3 × 10⁶
E = 2.0 × 10⁴ + 1.38 × 10⁵ = 1.58 × 10⁵ J

The power this would require is

P = 1.58 × 10⁵ / 60 = 2.6 × 10³ W

The heater supplies only 2.1 kW, which is less than the 2.6 kW needed, so the claim is not true.

(Equivalently: in one minute the heater delivers 2100 × 60 = 1.26 × 10⁵ J, which gives Δm = 1.26 × 10⁵/(4200 × 80 + 2.3 × 10⁶) = 0.048 kg, i.e. only 48 g of steam per minute.)`,
  "phys-aqa-7408-2022-p2::02.1": `Two additional assumptions made in deriving pV = ⅓Nm(c_rms)²:
1. The collisions between gas molecules and the container walls are perfectly elastic (no kinetic energy is lost).
2. The volume of the gas molecules themselves is negligible compared to the volume of the container (the molecules are point masses).`,
  "phys-aqa-7408-2022-p2::02.2": `Gas molecules move randomly and collide with the walls of the container. When a molecule hits a wall, its momentum changes (it bounces back), meaning there is a change in momentum, Δp, of the molecule. By Newton's second law, force = rate of change of momentum (F = Δp/Δt), so the wall must exert a force on the molecule to change its momentum. By Newton's third law, the molecule exerts an equal and opposite force on the wall. Since there are very many molecules hitting the wall each second, there is a continuous (average) force on the wall, which gives rise to the pressure.`,
  "phys-aqa-7408-2022-p2::02.3": `The mean kinetic energy of a gas molecule is related to temperature by:
½m⟨c²⟩ = (3/2)k_B T
So: k_B T = (2/3) × 6.7 × 10⁻²¹ = 4.467 × 10⁻²¹ J
T = 4.467 × 10⁻²¹ / (1.38 × 10⁻²³) = 323.7 K

Using the ideal gas law: pV = nRT
n = pV/(RT) = (220 × 10³ × 0.35) / (8.31 × 323.7)
n = 77 000 / 2690 = 28.6 mol

Alternatively using pV = Nk_BT:
N = pV/(k_BT) = (220 × 10³ × 0.35) / (4.467 × 10⁻²¹)
N = 77 000 / 4.467 × 10⁻²¹ = 1.724 × 10²⁵ molecules
n = N/N_A = 1.724 × 10²⁵ / 6.02 × 10²³ = 28.6 mol

The amount of gas in the container is 28.6 mol.`,
  "phys-aqa-7408-2022-p2::02.4": `At a fixed absolute temperature pV = nRT is constant, which is why Figure 2 is a rectangular hyperbola. Doubling the temperature to 2T doubles the constant, so at any given volume the pressure is twice as large.

Draw a second smooth curve of the same rectangular-hyperbola shape lying entirely above the original one, obtained by doubling the pressure of every point of the original curve at the same volume. Measuring in centimetre squares from the origin, the original curve passes through (2, 4), (4, 2) and (8, 1), so the new curve must pass through (2, 8), (4, 4) and (8, 2). Like the original it approaches both axes without ever touching them, and it never crosses or touches the original curve.`,
  "phys-aqa-7408-2022-p2::03.1": `The excess electrons are located on the outer surface of the sphere.

In a conducting material, electrons are free to move. The excess electrons all carry the same (negative) charge and therefore repel each other. They redistribute themselves on the surface of the conductor, moving as far from each other as possible. Since the sphere is a conductor in electrostatic equilibrium, the electric field inside must be zero. If any electrons were in the interior, they would experience a net force (due to mutual repulsion) and would move, which contradicts equilibrium. Therefore, all the excess electrons reside on the outer surface of the sphere, spread uniformly across it.`,
  "phys-aqa-7408-2022-p3::03.1": `One problem with using callipers to measure the diameter of the putty cylinder: the callipers may compress or deform the soft putty when they are closed around it, giving a reading that is smaller than the actual diameter. (Putty is soft and deformable, so the jaws of the callipers distort the sample.)`,
  "phys-aqa-7408-2022-p2::03.2": `Draw a tangent to the curve at r = 0.30 m, making it long enough to span most of the horizontal scale.

The tangent cuts the V axis at about −1.2 × 10⁶ V and reaches V = 0 at about r = 0.60 m, so

E = ΔV/Δr = [0 − (−1.2 × 10⁶)]/(0.60 − 0)
E = 1.2 × 10⁶/0.60 = 2.0 × 10⁶

electric field strength = 2.0 × 10⁶
unit: V m⁻¹ (N C⁻¹ is equally acceptable)`,
  "phys-aqa-7408-2022-p2::03.3": `Outside the sphere it behaves as though all its charge were at its centre, so at its surface (r = 0.10 m)

V = Q/(4πε₀r)

The sphere stores charge Q at potential V, so its capacitance is

C = Q/V = Q ÷ [Q/(4πε₀r)] = 4πε₀r
C = 4π × 8.85 × 10⁻¹² × 0.100 = 1.1 × 10⁻¹¹ F

which is approximately 1 × 10⁻¹¹ F as required.

(The same result follows from the graph: at the surface V = −1.8 × 10⁶ V, so Q = 4πε₀rV = 4π × 8.85 × 10⁻¹² × 0.100 × 1.8 × 10⁶ = 2.0 × 10⁻⁵ C, and C = Q/V = 2.0 × 10⁻⁵/1.8 × 10⁶ = 1.1 × 10⁻¹¹ F.)`,
  "phys-aqa-7408-2022-p2::03.4": `Using C = 1.1 × 10⁻¹¹ F from 03.3 and E = ½CV².

Fully charged, the potential of the sphere is 1.8 × 10⁶ V:
E₁ = ½ × 1.1 × 10⁻¹¹ × (1.8 × 10⁶)² = 18 J

When the potential has fallen to 1.0 × 10⁶ V:
E₂ = ½ × 1.1 × 10⁻¹¹ × (1.0 × 10⁶)² = 5.5 J

change in energy stored = 18 − 5.5 = 12.5 J

The energy stored has decreased by about 13 J.`,
  "phys-aqa-7408-2022-p2::04.1": `From Figure 4, the gravitational field lines of G are more closely spaced than those of H (or the equipotential surfaces are more closely packed around G), indicating a stronger field and therefore a greater mass for G. Gravitational field strength g = GM/r², and for the same distance, a stronger field implies a larger mass M. Therefore, the mass of G is greater than the mass of H.`,
  "phys-aqa-7408-2022-p2::04.2": `Gravitational field lines always point towards the mass producing the field, because the force on a test mass is attractive.

At X: draw a short arrow on the field line through X, tangential to that line, pointing along it towards G.

At Y: draw a short arrow on the field line through Y, tangential to that line, pointing along it towards H.

(Each arrowhead should be placed on or immediately beside the field line at the labelled point, and must not be drawn as a curve.)`,
  "phys-aqa-7408-2022-p2::04.3": `g = GM/R²
R² = GM/g = (6.67 × 10⁻¹¹ × 2.0 × 10²⁰) / 0.40
R² = (1.334 × 10¹⁰) / 0.40 = 3.335 × 10¹⁰ m²
R = √(3.335 × 10¹⁰) = 1.826 × 10⁵ m ≈ 1.8 × 10⁵ m

The radius of asteroid P is 1.8 × 10⁵ m.`,
  "phys-aqa-7408-2022-p2::04.4": `The axes of Figure 5 run from r = R to r = 3R, so the whole sketch shows the field outside the asteroid, where g = GM/r² — an inverse-square decrease.

Start the curve at the top left-hand corner, at (R, 0.40 N kg⁻¹), the surface value.
At r = 2R the field is a quarter of the surface value: 0.40/4 = 0.10 N kg⁻¹.
At r = 3R it is a ninth of the surface value: 0.40/9 = 0.044 N kg⁻¹.

Join these three points with a single smooth curve that falls steeply at first and then flattens out, staying above the r axis throughout.`,
  "phys-aqa-7408-2022-p2::04.5": `The area under a graph of gravitational field strength g against distance r represents the work done per unit mass (gravitational potential difference) in moving a test mass from r = R to r = 2R. In other words, the area equals the change in gravitational potential: ΔV = V(2R) − V(R), which is the gravitational potential energy change per kilogram when moving a 1 kg mass from the surface of P (at r = R) to a distance 2R from the centre. It is the energy needed per unit mass to move an object from the surface to twice the radius.`,
  "phys-aqa-7408-2022-p2::04.6": `Force on P from G: F_G = 6.38 × 10¹² N

Force on P from H:
F_H = GM_H × M_P / (HP)²
F_H = (6.67 × 10⁻¹¹ × 3.00 × 10²⁵ × 2.00 × 10²⁰) / (1.50 × 10¹¹)²
F_H = (6.67 × 10⁻¹¹ × 6.00 × 10⁴⁵) / (2.25 × 10²²)
F_H = (4.002 × 10³⁵) / (2.25 × 10²²)
F_H = 1.779 × 10¹³ N

The two forces act at right angles, so the resultant:
F_resultant = √(F_G² + F_H²)
F_resultant = √((6.38 × 10¹²)² + (1.779 × 10¹³)²)
F_resultant = √(4.070 × 10²⁵ + 3.165 × 10²⁶)
F_resultant = √(3.572 × 10²⁶)
F_resultant = 1.89 × 10¹³ N

Acceleration: a = F/M_P = 1.89 × 10¹³ / 2.00 × 10²⁰ = 9.45 × 10⁻⁸ m s⁻²`,
  "phys-aqa-7408-2022-p2::04.7": `For circular orbit around H, the net centripetal force must be directed toward H. However, G also exerts a gravitational force on P in a different direction (at right angles in this position). The resultant force on P is not directed toward H, so the net force cannot provide the centripetal acceleration required for a circular orbit around H. Additionally, for circular orbit the speed must be exactly right so that F_H provides the centripetal force, but the presence of G's force means the net force direction and magnitude are constantly changing in a way incompatible with circular orbit.`,
  "phys-aqa-7408-2022-p2::05.1": `The core: made of soft iron, it provides a path of low magnetic reluctance, concentrating and channelling the changing magnetic flux (produced by the alternating current in the primary coil) efficiently through to the secondary coil. This ensures nearly all the magnetic flux generated by the primary links with the secondary.

The secondary coil: by Faraday's law of electromagnetic induction, the changing magnetic flux through the secondary coil induces an EMF (and hence a voltage) in it. The magnitude of the induced EMF depends on the rate of change of flux linkage, which equals the number of turns in the secondary multiplied by the rate of change of flux: ε_s = N_s × dΦ/dt. The ratio of secondary to primary EMF equals the turns ratio N_s/N_p, allowing the voltage to be stepped up or down.`,
  "phys-aqa-7408-2022-p2::05.2": `The alternating magnetic flux in the iron core induces eddy currents in the core material. These eddy currents flow in closed loops within the core and dissipate energy as heat (I²R losses), reducing efficiency. By constructing the core from thin iron sheets (laminations) separated by an insulating material M, the electrical resistance of paths for eddy currents is greatly increased. The thin sheets restrict eddy currents to flow only within each lamination rather than across the full cross-section of the core, dramatically reducing their magnitude. Since power loss ∝ I², smaller eddy currents mean far less energy is wasted as heat, increasing the transformer's efficiency.`,
  "phys-aqa-7408-2022-p2::05.3": `Higher transmission voltages reduce current in the cables for the same power transmitted (P = IV, so I = P/V). Lower current means less power lost as heat in the cable resistance (P_loss = I²R). At 132 kV, power losses are much lower than at lower voltages, making transmission more efficient and economical. However, extremely high voltages (e.g. 400 kV) require more expensive insulation, larger pylons, greater safety exclusion zones, and more costly equipment. Engineers choose 132 kV as a compromise — low enough power loss for acceptable efficiency, but not so high that equipment and safety costs become prohibitive for the scale of power being transmitted.`,
  "phys-aqa-7408-2022-p2::05.4": `Power delivered to industrial consumers = 72 MW.
Efficiency of transformer 2 = 98%, efficiency of transmission line = 94%, efficiency of transformer 1 = 98%.

Overall efficiency from 25 kV supply to consumers:
η_total = 0.98 × 0.94 × 0.98 = 0.9025

Power input at 25 kV line from power station:
P_input = P_consumers / η_total = 72 × 10⁶ / 0.9025 = 7.979 × 10⁷ W ≈ 79.8 MW

Current in 25 kV line:
I = P_input / V = 79.8 × 10⁶ / 25 × 10³ = 3190 A ≈ 3200 A

The current in the 25 kV line from the power station is approximately 3200 A.`,
  "phys-aqa-7408-2022-p2::06.1": `The binding energy of a nucleus is the energy required to completely separate all the nucleons (protons and neutrons) in the nucleus into free, isolated nucleons. It is equivalently the energy released when the nucleus is assembled from its constituent free nucleons. It represents the work that must be done against the strong nuclear force to break the nucleus apart completely.`,
  "phys-aqa-7408-2022-p2::06.2": `Mass of proton m_p = 1.673 × 10⁻²⁷ kg; mass of neutron m_n = 1.675 × 10⁻²⁷ kg

⁵⁶₂₆Fe has 26 protons and 30 neutrons.

Total mass of separate nucleons:
m_nucleons = 26 × 1.673 × 10⁻²⁷ + 30 × 1.675 × 10⁻²⁷
m_nucleons = 4.3498 × 10⁻²⁶ + 5.025 × 10⁻²⁶ = 9.3748 × 10⁻²⁶ kg

Mass defect:
Δm = m_nucleons − m_nucleus = 9.3748 × 10⁻²⁶ − 9.288 × 10⁻²⁶ = 8.68 × 10⁻²⁸ kg

Binding energy:
E = Δm × c² = 8.68 × 10⁻²⁸ × (3.00 × 10⁸)²
E = 8.68 × 10⁻²⁸ × 9.00 × 10¹⁶ = 7.812 × 10⁻¹¹ J

In MeV: E = 7.812 × 10⁻¹¹ / 1.60 × 10⁻¹³ = 488 MeV

The binding energy of ⁵⁶₂₆Fe is approximately 488 MeV.`,
  "phys-aqa-7408-2022-p2::06.3": `On Figure 10, X lies at a nucleon number of about 240, on the falling part of the curve to the right of the peak.

Mark F1 and F2 as two points on the curve whose nucleon numbers add up to about 240 and which sit symmetrically either side of half that value (about 120) — for example F1 at a nucleon number of about 95 and F2 at about 145. Both must be to the right of the peak of the graph, so neither can have a nucleon number below about 55.

Both fragments lie higher on the curve than X, so each nucleon in them is more tightly bound than in X, and that increase in binding energy per nucleon is the energy released by the fission.`,
  "phys-aqa-7408-2022-p2::06.4": `Figure 11 shows that the stable nuclides curve above the N = Z line: the heavier a stable nuclide is, the larger its N/Z ratio.

X is a very heavy nuclide with a high N/Z ratio. When it splits, the two fragments keep roughly that same high N/Z ratio, but they have much smaller nucleon numbers, for which stability requires a lower N/Z. F1 and F2 therefore plot above and to the left of the line of stable nuclides in Figure 11 — they are neutron rich.

The likely initial decay mode for both F1 and F2 is therefore β⁻ decay. In β⁻ decay a neutron in the nucleus changes into a proton (emitting an electron and an antineutrino), so N falls by one and Z rises by one. On Figure 11 this moves each nuclide one step down and to the right, bringing it closer to the region of stable nuclides.`,
  "phys-aqa-7408-2022-p3::01.1": `Answer: Y-shift

The Y-shift moves the whole trace up or down the screen, so it is the control used to centre the trace vertically.`,
  "phys-aqa-7408-2022-p3::01.2": `From Figure 4 the time-base is set to 50 μs per division.

On Figure 3 the burst of oscillation — which lasts for exactly as long as the hammer is in contact with end L — occupies 6 divisions of the screen, so

contact time = 6 × 50 × 10⁻⁶ = 3.0 × 10⁻⁴ s

During that time the sound travels from L to R and back again:

distance = 2 × 0.870 = 1.740 m

speed = distance/time = 1.740 / (3.0 × 10⁻⁴)

speed of sound = 5800 m s⁻¹`,
  "phys-aqa-7408-2022-p3::01.3": `A rod of twice the length means the sound has twice as far to travel before it returns to L, so the contact time doubles, from 300 μs to 600 μs.

At the existing time-base setting of 50 μs per division that waveform would need 12 divisions, but the screen is only 10 divisions wide. The waveform would therefore extend beyond the edge of the screen and could not be displayed in full, so the contact time could not be measured.

To get an accurate result for the speed the time-base control must be turned to a slower setting of 0.1 ms per division. The 600 μs burst then occupies 6 divisions and fits on the screen, so the contact time — and hence the speed — can be measured as before.`,
  "phys-aqa-7408-2022-p3::02.1": `To avoid parallax error when reading the position of the pin against the ruler: position the eye so that it is directly level with (perpendicular to) both the pin and the ruler scale. If a mirror is placed behind the ruler, the observer should align their line of sight so that the image of the pin in the mirror is directly behind the actual pin — this ensures the eye is perpendicular to the scale and the pin, eliminating parallax. Alternatively, use a set square placed against the ruler to read off the position of the pin at right angles.`,
  "phys-aqa-7408-2022-p3::02.2": `The strip is the only one available, so w and t are fixed. Choose m as the single independent variable and keep L constant.

Procedure
• Clamp the strip between the blocks so that a length L of about 25 cm projects horizontally beyond them, and do not move it again: L is the control variable.
• Measure L with a millimetre rule, the width w with vernier callipers and the thickness t with a micrometer screw gauge, each in several places and averaged.
• Hang the 50 g mass hanger from the free end and measure the vertical displacement y of the pin against the clamped vertical ruler, using a mirror behind the ruler to avoid parallax.
• Add the four 50 g slotted masses one at a time so that m = 0.050, 0.100, 0.150, 0.200 and 0.250 kg, and record y for each value of m. Here y is the dependent variable and m the only independent variable.

Analysis
• Since y = 4mgL³/(Ewt³), rewriting it as y = [4gL³/(Ewt³)] × m shows that a graph of y (y-axis) against m (x-axis) should be a straight line through the origin of gradient 4gL³/(Ewt³).
• Plot the five points, draw the best-fit straight line and measure its gradient.
• Rearranging with E as the subject:

E = 4gL³ / (w t³ × gradient)

Substitute the measured L, w and t in metres, the gradient in m kg⁻¹ and g = 9.81 m s⁻² to obtain E in Pa.`,
  "phys-aqa-7408-2022-p3::03.2": `Mean diameter: d̄ = (34.5 + 34.2 + 32.9 + 33.4 + 34.0) / 5 = 169.0 / 5 = 33.8 mm

Range = 34.5 − 32.9 = 1.6 mm
Uncertainty in d = range/2 = 1.6/2 = 0.8 mm

Percentage uncertainty = (0.8 / 33.8) × 100% = 2.37% ≈ 2.4% ✓`,
  "phys-aqa-7408-2022-p3::03.3": `Volume of cylinder V = π(d/2)²L = πd²L/4

d = 33.8 mm = 33.8 × 10⁻³ m, % uncertainty in d = 2.4%
L = 71 mm = 71 × 10⁻³ m, absolute uncertainty in L = 2 mm, % uncertainty = (2/71) × 100% = 2.82%

V = π × (33.8)² × 71 / 4 = π × 1142.44 × 71 / 4 = π × 81113.24 / 4 = π × 20278 = 63 700 mm³

Percentage uncertainty in V:
% unc(V) = 2 × % unc(d) + % unc(L) = 2 × 2.4% + 2.82% = 4.8% + 2.82% = 7.62%

Absolute uncertainty in V = 7.62% × 63 700 = 0.0762 × 63 700 = 4850 mm³ ≈ 4900 mm³

The uncertainty in the volume is approximately 4900 mm³.`,
  "phys-aqa-7408-2022-p3::03.4": `Since R = ρL²/(5.83 × 10⁻⁵), the graph of R against L² is a straight line through the origin with

gradient = ρ / (5.83 × 10⁻⁵)

Draw a ruled best-fit line from the origin through the points (it passes just above the fourth point and just below the fifth). Taking the origin and the far end of the line, where L² = 45 × 10⁻³ m² and R = 29.2 Ω:

gradient = 29.2 / (45 × 10⁻³) = 649 Ω m⁻²

ρ = gradient × 5.83 × 10⁻⁵ = 649 × 5.83 × 10⁻⁵ = 3.78 × 10⁻² Ω m

ρ = 3.78 × 10⁻²
unit = Ω m`,
  "phys-aqa-7408-2022-p3::04.1": `If y were inversely proportional to M then the product My would be the same for every data point.

From Figure 10:
at M = 1.0 kg, y = 82.0 mm, so My = 82.0 kg mm
at M = 3.0 kg, y = 62.5 mm, so My = 188 kg mm

The second product is more than twice the first — they differ by about 130%, which is far greater than any uncertainty in reading the graph. My is therefore not constant, so y is not inversely proportional to M.`,
  "phys-aqa-7408-2022-p3::04.2": `With the valve closed no air can enter or leave the cylinder. As P begins to slide down, the trapped air above it expands, so the pressure of the trapped air falls.

It falls below atmospheric pressure, so there is now a pressure difference across the piston: the atmosphere pushes up on the lower face of P harder than the trapped air pushes down on its upper face.

P stops where this gives equilibrium — that is, where the pressure difference multiplied by the cross-sectional area of the piston is equal to the weight of P. There is then no resultant force on P, so it stays in the cylinder.

If the valve is opened, air enters until the pressure of the air above P equals atmospheric pressure. The pressure difference is removed, the upward force disappears, and the weight of P is no longer balanced, so P falls out.`,
  "phys-aqa-7408-2022-p3::04.3": `In the upright arrangement the air is compressed by the weight of the piston as well as by the added masses, so the compressing mass is M + 0.350 kg. When the cylinder is inverted the piston hangs below the trapped air, so its weight now acts to expand the air instead of to compress it: the effective compressing mass becomes −0.350 kg. Setting

M + 0.350 = −0.350 gives M = −0.700 kg

So draw a single smooth curve of decreasing gradient through all six points on Figure 10, and continue it backwards, still falling, past M = 0 to M = −0.700 kg. Reading the curve there gives

y = 112 mm

(any value in the range 108–116 mm from a properly drawn extrapolated curve).`,
  "phys-aqa-7408-2022-p3::04.4": `The error: the student read the scale at the top of the meniscus (the upper edge of the coloured oil) instead of at the bottom, the lowest point of the oil surface, which is where the boundary between the air and the oil should be read.

The lowest point of the meniscus is four 0.2 cm³ divisions below the 35 mark, so

volume = 35 + (4 × 0.2) = 35.8 cm³`,
  "phys-aqa-7408-2022-p3::04.5": `Boyle's law states that pV = constant for a fixed mass of gas at constant temperature. Taking logs of both sides:

log V + log p = log(constant)
log V = −log p + log(constant)

Comparing this with y = mx + c, a graph of log V against log p should be a straight line of gradient exactly −1.

Measuring the gradient of the line in Figure 13, using the two ends of the line:

gradient = Δlog V / Δlog p = (1.170 − 1.685) / (−0.600 − (−1.100)) = −0.515/0.500 = −1.03

The measured gradient is −1.03, which is equal to −1 within the uncertainty of the read-offs. A gradient of −1 means V ∝ 1/p, so pV is constant and the air obeys Boyle's law.`,
  "phys-aqa-7408-2022-p3::04.6": `The gradient of the line in Figure 13 is −1, so log V + log p is the same everywhere along it. Reading the upper end of the line, at log(p/MPa) = −1.100 the value of log(V/cm³) is 1.685, so

log V + log p = 1.685 + (−1.100) = 0.585
hence pV = 10^0.585 = 3.85 (MPa cm³)

At the largest gauge reading, p = 3.4 × 10⁵ Pa = 0.34 MPa, so log p = −0.469 and

log V = 0.585 − log p = 0.585 + 0.469 = 1.054
V = 10^1.054 = 11.3

V = 11 cm³`,
  "phys-aqa-7408-2022-p3::04.7": `The temperature of the trapped air must not change, because Boyle's law only holds for a fixed mass of gas at constant temperature.

This is achieved by raising the pressure in small steps and then waiting after each change, until the oil level has stopped moving, before reading p and V. Compressing the air warms it, and the wait lets it cool back to the temperature of the surroundings so that every pair of readings is taken at the same temperature.`,
  "phys-aqa-7408-2023-p1::01.1": `The quark structure of a Λ⁰ is uds (one up quark, one down quark, one strange quark).`,
  "phys-aqa-7408-2023-p1::01.2": `The decay is caused by the weak interaction.

The Λ⁰ has a strangeness of −1, while the π⁰ and the neutron both have a strangeness of 0, so the strangeness changes (from −1 to 0) in this decay — it is not conserved. Strangeness can only change in a weak interaction, so the interaction responsible here must be the weak interaction.`,
  "phys-aqa-7408-2023-p1::01.3": `X is an antineutron (n̄). Conservation of baryon number: the anti-Λ⁰ has baryon number −1; the neutral pion has baryon number 0; therefore X must have baryon number −1, so X is an antibaryon. Conservation of charge: the anti-Λ⁰ has charge 0; the π⁰ has charge 0; so X has charge 0. The antineutron (n̄) has baryon number −1 and charge 0, satisfying both conservation laws.`,
  "phys-aqa-7408-2023-p1::01.4": `E = hf = 6.63 × 10⁻³⁴ × 2.69 × 10²³ = 1.783 × 10⁻¹⁰ J

Converting to MeV (1 MeV = 1.60 × 10⁻¹³ J):

E = 1.783 × 10⁻¹⁰ ÷ (1.60 × 10⁻¹³) = 1.11 × 10³ MeV

rest energy = 1110 MeV`,
  "phys-aqa-7408-2023-p1::01.5": `The accelerators required to produce particles such as the Λ⁰ are extremely expensive to build and operate, so the cost must be shared between many countries / international funding is required. Alternatively: the expertise and specialised knowledge required spans many different scientific disciplines, so large teams of scientists from different countries are needed to provide the necessary range of skills.`,
  "phys-aqa-7408-2023-p1::02.1": `Average speed for the record = 1230 km h⁻¹ = 1230 × 1000 ÷ 3600 = 341.7 m s⁻¹

The record is the average over the two runs, so the total distance is 2 × 1.61 km = 3220 m and the total time is

t_total = 3220 ÷ 341.7 = 9.424 s

The run at 343 m s⁻¹ took

t₁ = 1610 ÷ 343 = 4.694 s

So the other run took

t₂ = 9.424 − 4.694 = 4.73 s

time = 4.73 s`,
  "phys-aqa-7408-2023-p1::02.2": `From Figure 1, at a distance of 5600 m from the start the speed of the car is 450 m s⁻¹.

E_k = ½mv² = ½ × 6.50 × 10³ × 450²
E_k = ½ × 6500 × 2.025 × 10⁵
E_k = 6.6 × 10⁸ J

kinetic energy = 6.6 × 10⁸ J`,
  "phys-aqa-7408-2023-p1::02.3": `At 5600 m the speed–distance graph is still the straight line through the origin, so its gradient there is

gradient = 450 ÷ 5600 = 0.0804 s⁻¹

acceleration = speed × gradient = 450 × 0.0804 = 36.2 m s⁻²

Resultant (accelerating) force:

F = ma = 6.50 × 10³ × 36.2 = 2.35 × 10⁵ N

Power used to accelerate the car at this instant:

P = Fv = 2.35 × 10⁵ × 450 = 1.06 × 10⁸ W = 106 MW

percentage = (106 ÷ 640) × 100 = 16.5 %

percentage of input power = 16.5 %`,
  "phys-aqa-7408-2023-p1::02.4": `From Figure 1 the car reaches a maximum speed of about 470 m s⁻¹ (at roughly 7500 m from the start) and then decelerates to rest at about 15 000 m, so the braking distance is

s ≈ 15 000 − 7500 = 7500 m

Using v² = u² + 2as with u = 470 m s⁻¹ and v = 0:

a = −u² ÷ 2s = −470² ÷ (2 × 7500) = −220 900 ÷ 15 000 = −15 m s⁻²

3g = 3 × 9.81 = 29.4 m s⁻²

The average deceleration of 15 m s⁻² is about half of 3g, so it is less than 3g and the recommendation is met.`,
  "phys-aqa-7408-2023-p1::03.1": `The emf of the cell is the energy transferred to each coulomb of charge, so one coulomb of charge gains ε joules of energy as it is driven through the cell.

As that same coulomb travels round the circuit it transfers energy: V₁ (= IR₁) joules in R₁, V₂ (= IR₂) joules in R₂, and Ir joules inside the cell itself (the "lost volts").

Energy cannot be created or destroyed, so the energy given to the coulomb by the cell must equal the total energy it transfers on one complete circuit:

ε = IR₁ + IR₂ + Ir  (that is, ε = V₁ + V₂ + Ir)`,
  "phys-aqa-7408-2023-p1::03.2": `With C at end B the whole conducting layer (125 Ω) is the external resistance, and the voltmeter reads the terminal pd of the battery, 2.89 V.

Current in the circuit:

I = V ÷ R = 2.89 ÷ 125 = 0.02312 A

Applying conservation of energy to the circuit, the emf equals the terminal pd plus the lost volts:

ε = V + Ir
3.00 = 2.89 + 0.02312r

r = (3.00 − 2.89) ÷ 0.02312 = 0.11 ÷ 0.02312 = 4.76 Ω

So r is approximately 4.8 Ω, as required.`,
  "phys-aqa-7408-2023-p1::03.3": `With C at 1/5 of the distance from A, the resistance between A and C is 25.0 Ω.

The resistance between C and B is 125 − 25 = 100 Ω (total variable resistor = 125 Ω).

The voltmeter is connected between A and C (measuring pd across 25 Ω section).

Current in circuit: I = ε / (r + R_total) = 3.00 / (4.8 + 125) = 3.00 / 129.8 = 0.02311 A

Voltmeter reading = I × R_AC = 0.02311 × 25.0 = 0.578 V ≈ 0.58 V`,
  "phys-aqa-7408-2023-p1::03.4": `The sketch should be a line made of four straight sections plus a step, starting at 0 V when C is at A and finishing at 3.0 V when C is at B:

• From A to P: a straight line rising from 0 V. This section is relatively steep, because the layer between A and P is thinner and so has the larger resistance per unit length.

• From P to Q: a straight line that continues to rise but with a noticeably smaller (still positive) gradient, because the layer beyond P is thicker and so has a lower resistance per unit length.

• At Q: a short, almost vertical step up in pd, over a horizontal distance no wider than the "Q" label. The scratch cuts into the layer, so a large extra resistance is concentrated at that point and a large share of the 3.0 V is dropped across it.

• From Q to R: a straight line with about the same gradient as the P-to-Q section, reaching exactly 3.0 V at R.

• From R to B: a horizontal line held at 3.0 V, because the conducting connector laid over this part of the layer short-circuits it, so C stays at the potential of B.`,
  "phys-aqa-7408-2023-p1::04.1": `At the critical angle c the angle of refraction is 90°, so

sin c = 1 ÷ n

n = 1 ÷ sin c = 1 ÷ sin 41.5° = 1 ÷ 0.6626 = 1.51

The refractive index is 1.51, which is about 1.5 as stated.`,
  "phys-aqa-7408-2023-p1::04.2": `The ray meets the longest side at normal incidence, so it enters the prism without being deviated.

Because the prism is a right-angled isosceles triangle, the ray then strikes each of the two shorter sides in turn at an angle of incidence of 45°. This is greater than the critical angle of 41.5°, so the light is totally internally reflected at both of those surfaces.

Each reflection turns the ray through 90°, so after the two reflections the ray has been turned through 180° and travels back to the longest side. It meets the longest side along the normal, at an angle of incidence of 0°, so it leaves without being refracted.

The emergent ray therefore travels along the same line direction as the incident ray, i.e. parallel to it.`,
  "phys-aqa-7408-2023-p1::04.3": `Continue the ray that has already reflected off the left-hand shorter side:

• At the point where it meets the second (right-hand) shorter side, draw only one ray leaving that point — the totally internally reflected ray. Do not draw any refracted ray escaping through that side, because the angle of incidence there is 41.5°, i.e. at the critical angle, so all the light is reflected.

• Draw that reflected ray so that it is parallel (by eye) to the first refracted ray, i.e. to the section of the ray between the entry point on the longest side and the first shorter side, but travelling in the opposite sense — down and to the left, back towards the longest side.

• Where that ray meets the longest side, draw it refracting out of the prism, bending away from the normal, and draw the emergent ray parallel (by eye) to the original incident ray, with an arrow showing it travelling away from the prism.`,
  "phys-aqa-7408-2023-p1::04.4": `θ is the largest angle of incidence for which all the light still leaves through the longest side, so at the second reflecting surface the light must only just be totally internally reflected:

angle of incidence at the 2nd reflecting side = critical angle = 41.5°

The two shorter sides are at right angles to each other, so at the first reflecting side

angle of reflection (and incidence) = 90° − 41.5° = 48.5°

The longest side makes an angle of 45° with each shorter side, so the angle of refraction where the ray enters the longest side is

r = 48.5° − 45° = 3.5°   (= 90° − 45° − 41.5°)

Applying Snell's law at the longest side with n = 1.5:

sin θ = n sin r = 1.5 × sin 3.5° = 1.5 × 0.06105 = 0.0916

θ = 5.3°

So θ is about 5°, as required.`,
  "phys-aqa-7408-2023-p1::04.5": `Neither suggestion would work.

Suggestion 1 – the equilateral (60°) prism

In the original prism the two reflecting sides are at 90° to each other, which is what turns the light through 180° and sends it back out through the longest side along the original line. In an equilateral prism the two reflecting sides meet at 60°, so the light is no longer turned through 180° and would not leave the prism at the original angle.

Worse, the geometry at the second reflection is destroyed. A ray entering the base with a small angle of refraction r meets the first sloping side at (60° + r), but it then meets the second sloping side at an angle of incidence of only about r — a few degrees. That is far less than the critical angle of 41.5°, so the light is no longer totally internally reflected at the second surface and simply escapes through it. Light escapes even for very small angles of incidence, so θ is not increased at all.

Suggestion 2 – the original shape made from glass of smaller refractive index

Since sin c = 1/n, reducing n increases the critical angle c. In the original design the limiting condition is that the angle of incidence at the second reflecting side equals c, which makes the angle of refraction at entry r = 45° − c. A larger c therefore gives a smaller r, and with sin θ = n sin r both a smaller n and a smaller r make θ smaller.

For example, with the original n = 1.51 (c = 41.5°) we get r = 3.5° and θ = 5.3°, but with n = 1.45 the critical angle rises to 43.6°, r falls to 1.4° and θ falls to about 2.0°. So a smaller refractive index reduces θ rather than increasing it.

Neither change achieves a larger θ; the manufacturer should keep the right-angled isosceles shape and, if anything, use glass of higher refractive index.`,
  "phys-aqa-7408-2023-p1::05.1": `The Young modulus is the gradient of the straight (linear) part of the stress–strain graph.

Taking a point well along the straight section, e.g. stress = 105 MPa at a strain of 7.5 × 10⁻⁴ (the line passes through the origin):

E = stress ÷ strain = (105 × 10⁶) ÷ (7.5 × 10⁻⁴)

E = 1.4 × 10¹¹ Pa

Young modulus = 1.4 × 10¹¹ Pa`,
  "phys-aqa-7408-2023-p1::05.2": `The graph is a straight line up to a strain of roughly 9 × 10⁻⁴, and the metal then fractures at a strain of only about 1.27 × 10⁻³.

So beyond the linear section the metal stretches only a very small amount more before it breaks — fracture happens almost at the limit of proportionality, with no long region of plastic deformation and no necking. That very small extra strain before fracture is what shows the metal is brittle.`,
  "phys-aqa-7408-2023-p1::05.3": `The total weight of AB and lamp = (4.4 + 16.0) × 9.81 = 20.4 × 9.81 = 200.1 N

Since the lamp is at the midpoint and the beam is uniform, each wire supports half the total load:
F = 200.1 / 2 = 100.0 N

Cross-sectional area of each wire:
d = 0.800 mm = 0.800 × 10⁻³ m, r = 0.400 × 10⁻³ m
A = π r² = π × (0.400 × 10⁻³)² = π × 1.60 × 10⁻⁷ = 5.027 × 10⁻⁷ m²

Using E = (F L) / (A × e):
e = FL / (AE) = (100.0 × 1.20) / (5.027 × 10⁻⁷ × 2.10 × 10¹¹)
e = 120.0 / (1.056 × 10⁵)
e = 1.14 × 10⁻³ m = 1.14 mm`,
  "phys-aqa-7408-2023-p1::05.4": `Let the tension in the steel wire (left, A-side) be T_s and in the aluminium wire (right, B-side) be T_Al.

For AB to be horizontal, both wires must extend by the same amount e:

For steel: e = T_s × L / (A_s × E_s)
A_s = π(0.400 × 10⁻³)² = 5.027 × 10⁻⁷ m²
e_s = T_s × 1.20 / (5.027 × 10⁻⁷ × 2.10 × 10¹¹) = T_s × 1.20 / (1.056 × 10⁵)

For aluminium: diameter = 1.60 mm, r = 0.800 × 10⁻³ m
A_Al = π(0.800 × 10⁻³)² = 2.011 × 10⁻⁶ m²
e_Al = T_Al × 1.20 / (2.011 × 10⁻⁶ × 7.00 × 10¹⁰) = T_Al × 1.20 / (1.408 × 10⁵)

For equal extensions: e_s = e_Al
T_s / (1.056 × 10⁵) = T_Al / (1.408 × 10⁵)
T_s / T_Al = 1.056 / 1.408 = 0.750
T_s = 0.750 T_Al

Taking moments about A for the beam AB (the lamp is at distance x from A, beam length = 2.00 m):
Total weight W = (4.4 + 16.0) × 9.81 = 200.1 N

The beam weight acts at its midpoint (1.00 m from A): 4.4 × 9.81 = 43.16 N at 1.00 m
The lamp weight: 16.0 × 9.81 = 156.96 N at distance x from A

Moments about A: T_Al × 2.00 = 43.16 × 1.00 + 156.96 × x

Vertical equilibrium: T_s + T_Al = 200.1 N
0.750 T_Al + T_Al = 200.1
1.750 T_Al = 200.1
T_Al = 114.3 N
T_s = 200.1 − 114.3 = 85.8 N

From moments about A:
114.3 × 2.00 = 43.16 × 1.00 + 156.96 × x
228.6 = 43.16 + 156.96x
156.96x = 185.4
x = 1.18 m from A`,
  "phys-aqa-7408-2023-p1::06.1": `For SHM, the acceleration must be proportional to the displacement from the equilibrium position and directed toward the equilibrium position.

For a pencil of length l floating vertically, if pushed down a small distance y from equilibrium, the restoring force is the net upward force (increased buoyancy minus weight): F = −ρ_water × A × g × y, where A is the cross-sectional area.

By Newton's second law: ma = −ρ_water A g y
So a = −(ρ_water A g / m) y

Since ρ_water, A, g and m are all constants, a ∝ −y (acceleration is proportional to displacement and oppositely directed). This satisfies the defining condition for SHM.`,
  "phys-aqa-7408-2023-p1::06.2": `Period of oscillation:
T = 2π√(l/g) = 2π√(0.085 / 9.81) = 2π√(8.665 × 10⁻³) = 2π × 0.09308 = 0.5849 s

Angular frequency:
ω = 2π / T = 2π / 0.5849 = 10.74 rad s⁻¹

Amplitude A = 5.0 mm = 5.0 × 10⁻³ m

Maximum acceleration:
a_max = ω² A = (10.74)² × 5.0 × 10⁻³ = 115.3 × 5.0 × 10⁻³ = 0.577 m s⁻² ≈ 0.58 m s⁻²`,
  "phys-aqa-7408-2023-p1::06.3": `Resonance occurs when the frequency of the applied driving force equals the natural frequency of vibration of the system. At resonance, the amplitude of oscillation becomes very large (maximum) because energy is transferred from the driver to the oscillating system most efficiently. The system absorbs maximum energy from the driver when the driving frequency matches the system's natural frequency.`,
  "phys-aqa-7408-2023-p1::06.4": `Compare the frequency at which the waves force the ship to heave in each case with its natural heave frequency of 0.13 Hz.

Option 1 – stop the motors and anchor

The ship is stationary, so the waves pass it at their own speed and the forcing frequency is the wave frequency:

f = v ÷ λ = 14.2 ÷ 118 = 0.12 Hz

This is very close to the natural frequency of 0.13 Hz, so the ship would be driven at, or very near, resonance and the heave oscillations would build up to a large amplitude. The ship would not be steady.

Option 2 – keep sailing at 8.0 m s⁻¹ in the same direction as the waves

The waves now overtake the ship at a relative speed of 14.2 − 8.0 = 6.2 m s⁻¹, so the ship meets waves at

f = 6.2 ÷ 118 = 0.053 Hz

This is far below the natural frequency of 0.13 Hz, so the ship is driven well away from resonance and the amplitude of its heave oscillations stays small.

Conclusion: continuing to sail at 8.0 m s⁻¹ is the better option, because the forcing frequency is then much further from the ship's resonant frequency, so the ship remains far steadier and the doctor can operate.`,
  "phys-aqa-7408-2023-p2::01.1": `The internal energy of an ideal gas is the sum of the kinetic energies of all the molecules in the gas. (For an ideal gas there are no intermolecular forces, so there is no potential energy contribution — the internal energy consists entirely of the random kinetic energy of the molecules.)`,
  "phys-aqa-7408-2023-p2::01.2": `Momentum is a vector quantity. Before the collision, P has momentum +mc (taking the direction toward W as positive). After the elastic collision with the wall W, P rebounds with the same speed but in the opposite direction, so its momentum is −mc. The change in momentum = final momentum − initial momentum = −mc − (+mc) = −2mc.`,
  "phys-aqa-7408-2023-p2::01.3": `After one collision with W, P travels back across the box (length l), bounces off the opposite wall, and returns to W — a total distance of 2l — before the next collision with W.

Time for one complete cycle = 2l / c
Frequency of collisions with W = 1 / (2l/c) = c / (2l) ✓`,
  "phys-aqa-7408-2023-p2::01.4": `By Newton's second law, the force exerted on P by W equals P's rate of change of momentum. Each collision changes P's momentum by 2mc, and collisions happen at frequency c/2l, so

F = 2mc × c/2l = mc²/l

By Newton's third law, P exerts an equal and opposite force of mc²/l on W.

Pressure = force/area, and the area of W is l², so
p = (mc²/l) / l² = mc²/l³ = mc²/V`,
  "phys-aqa-7408-2023-p2::02.1": `Volume of gas (from Figure 2) = volume of outer cylinder − volume of rim cylinder, using V = πd²h/4 with h = 0.370 m:
outer: π × 0.660² × 0.370 / 4 = 0.1266 m³
rim: π × 0.330² × 0.370 / 4 = 0.0316 m³
gas volume V = 0.1266 − 0.0316 = 0.0949 m³

T = 100 + 273 = 373 K. Using n = pV/RT:
before: n₁ = (1.01 × 10⁵ × 0.0949)/(8.31 × 373) = 3.09 mol
after: n₂ = (2.11 × 10⁵ × 0.0949)/(8.31 × 373) = 6.46 mol
gas added = 6.46 − 3.09 = 3.37 mol

Mass of gas added = 14.991 − 14.897 = 0.094 kg

Molar mass = 0.094 / 3.37 = 0.028 kg mol⁻¹`,
  "phys-aqa-7408-2023-p2::02.2": `At constant volume the pressure of a fixed amount of gas is proportional to its absolute temperature (p ∝ T). If the tyre were hot when checked, the gas would be at a higher pressure, so the tyre could reach the required pressure (and pass the check) while containing less than the minimum amount of gas. Limiting the temperature stops this.`,
  "phys-aqa-7408-2023-p2::03.1": `Two properties of a radial gravitational field:
1. The field lines (directions of the gravitational force on a test mass) are directed radially inward toward the centre of the massive body from all directions, like the spokes of a wheel converging at the hub.
2. The magnitude of the gravitational field strength g decreases with increasing distance r from the centre of the mass, following an inverse-square law: g ∝ 1/r².`,
  "phys-aqa-7408-2023-p2::03.2": `The shaded area (force × distance) is the work done against gravity, i.e. the minimum energy needed to raise the space probe from the Earth's surface to a height of 8 × 10⁶ m (its gain in gravitational potential energy).`,
  "phys-aqa-7408-2023-p2::03.3": `g_S = GM_S/r² = (6.67 × 10⁻¹¹ × 1.99 × 10³⁰)/(1.50 × 10¹¹)² = 5.90 × 10⁻³ N kg⁻¹

g_E = 9.81 N kg⁻¹

g_S/g_E = 5.90 × 10⁻³ / 9.81 = 6.0 × 10⁻⁴`,
  "phys-aqa-7408-2023-p2::03.4": `Once the probe is far from the Earth, the Earth's pull on it is tiny compared with the Sun's pull at similar distances because the Sun's mass is so much larger, and the total work that must be done to escape the Sun's field is far greater than that needed to escape the Earth's field — so the Sun's field governs the probe's motion.`,
  "phys-aqa-7408-2023-p2::03.5": `The probe loses gravitational potential energy and gains kinetic energy as it moves from A to B.

Gain in kinetic energy:
ΔE_k = ½m(v_B² − v_A²) = ½ × 4.9 × 10⁴ × [(1.3 × 10³)² − (1.1 × 10³)²] = ½ × 4.9 × 10⁴ × 4.8 × 10⁵ = 1.18 × 10¹⁰ J

Loss in gravitational potential energy:
ΔE_p = GMm(1/r_B − 1/r_A) = 6.67 × 10⁻¹¹ × M × 4.9 × 10⁴ × (1/1.7 × 10⁵ − 1/6.0 × 10⁶)
= M × 3.268 × 10⁻⁶ × 5.716 × 10⁻⁶ = M × 1.868 × 10⁻¹¹ J

Equating: M × 1.868 × 10⁻¹¹ = 1.18 × 10¹⁰

M = 6.3 × 10²⁰ kg`,
  "phys-aqa-7408-2023-p2::04.1": `Draw a horizontal straight line at a constant, non-zero value of E from d = 0 (mesh) to about d = 3 mm (more than half the distance), where the equipotentials are evenly spaced (uniform field). From there the line curves upwards, rising more and more steeply towards d = 5 mm (the wire), where the equipotentials crowd together and the field is strongest.`,
  "phys-aqa-7408-2023-p2::04.2": `Both the electron and argon ion start from rest at P and are accelerated through the same potential difference V (electron to the wire, argon ion to the mesh). Using energy conservation:

For electron: ½ m_e v_e² = eV → v_e = √(2eV/m_e)
For argon ion: ½ m_Ar v_Ar² = eV → v_Ar = √(2eV/m_Ar)

(Both have charge magnitude e since argon is singly ionised.)

Ratio: v_e / v_Ar = √(m_Ar / m_e) = √(6.64 × 10⁻²⁶ / 9.11 × 10⁻³¹)
= √(7.29 × 10⁴)
= 270

v_e / v_Ar ≈ 270`,
  "phys-aqa-7408-2023-p2::04.3": `The argon ion is much more likely to collide with air molecules (it is more ionising) and loses more energy/speed in these collisions than the electron does, so the argon ion's final speed is reduced proportionally more and the ratio becomes larger.`,
  "phys-aqa-7408-2023-p2::04.4": `Test of Student A (inverse square): if N ∝ 1/h², then Nh² should be constant.
h = 1.0 cm, N = 10 × 10³: Nh² = 10 × 10³ × 1.0² = 10 × 10³
h = 2.0 cm, N ≈ 1.1 × 10³: Nh² = 1.1 × 10³ × 2.0² ≈ 4.4 × 10³
Nh² is not constant, so Student A is wrong.

Test of Student B (exponential): N should halve in equal intervals of h.
N falls from 10 × 10³ to 5 × 10³ between h = 1.00 cm and h ≈ 1.25 cm (Δh ≈ 0.25 cm)
N falls from 5 × 10³ to 2.5 × 10³ between h ≈ 1.25 cm and h ≈ 1.56 cm (Δh ≈ 0.31 cm)
The halving distance increases, so N does not fall by the same fraction in equal intervals of h and Student B is also wrong.

Neither student is correct: Nh² is not constant and the decrease is not exponential.`,
  "phys-aqa-7408-2023-p2::05.1": `For charging through R₁ from 0 V with V₀ = 6.0 V: V = V₀(1 − e^(−t/R₁C)), so t = −R₁C ln(1 − V/V₀).

Time to reach 2.0 V: t₁ = −R₁C ln(1 − 2.0/6.0) = −R₁C ln(0.667) = 0.41R₁C
Time to reach 4.0 V: t₂ = −R₁C ln(1 − 4.0/6.0) = −R₁C ln(0.333) = 1.10R₁C

Time to charge from 2.0 V to 4.0 V = t₂ − t₁ = 1.10R₁C − 0.41R₁C = 0.69R₁C ≈ 0.7R₁C`,
  "phys-aqa-7408-2023-p2::05.2": `From Figure 9, at t = 0 the capacitor is uncharged, so the whole 6.0 V is across R₁ and I₀ = 6.0 × 10⁻⁵ A:
R₁ = 6.0 / 6.0 × 10⁻⁵ = 1.0 × 10⁵ Ω

At t = 11 s the capacitor pd is 4.0 V, so 2.0 V is across R₁ and I = 2.0 × 10⁻⁵ A (consistent with R₁ = 1.0 × 10⁵ Ω).

Using I = I₀e^(−t/R₁C):
R₁C = t / ln(I₀/I) = 11 / ln(6.0/2.0) = 11 / 1.099 = 10.0 s

C = 10.0 / 1.0 × 10⁵ = 1.0 × 10⁻⁴ F

(Check: the area under the graph from 0 to 11 s is about 80 cm² squares × 0.5 × 10⁻⁵ C ≈ 4.0 × 10⁻⁴ C, and C = Q/V = 4.0 × 10⁻⁴ / 4.0 = 1.0 × 10⁻⁴ F.)`,
  "phys-aqa-7408-2023-p2::05.3": `During discharge the capacitor discharges through R₁ and R₂ in series (R_total = R₁ + R₂).

From Figure 10 the pd falls from 4.0 V to 2.0 V (halves) between t = 11 s and t = 32 s, so the half-time is 21 s.

t½ = 0.69R_total C
R_total = 21 / (0.69 × 1.0 × 10⁻⁴) = 3.0 × 10⁵ Ω

R₁ = 1.0 × 10⁵ Ω (from 05.2), so
R₂ = 3.0 × 10⁵ − 1.0 × 10⁵ = 2.0 × 10⁵ Ω`,
  "phys-aqa-7408-2023-p2::06.1": `Two advantages of using high-energy electrons rather than alpha particles:
1. High-energy electrons have a much shorter de Broglie wavelength, which is comparable to the diameter of a nucleus. This allows electron diffraction to resolve nuclear-scale structures (alpha particles at the same energy would have a longer wavelength and poorer resolution).
2. Electrons are not subject to the strong nuclear force (they are leptons), so the diffraction pattern is produced purely by the electromagnetic interaction with the nuclear charge distribution, making analysis simpler and more directly related to nuclear size. Alpha particles interact via the strong nuclear force as well, complicating the analysis.`,
  "phys-aqa-7408-2023-p2::06.2": `Draw a smooth curve starting high at small θ, with the intensity falling as θ increases to a single minimum that does not reach zero (the minimum is above the θ axis), then rising slightly to a small secondary maximum and falling away again, the whole curve showing an overall decrease in intensity with θ and spanning most of the θ axis.`,
  "phys-aqa-7408-2023-p2::06.3": `If R = R₀A^(1/3), then the volume of a nucleus is:
V = (4/3)πR³ = (4/3)π(R₀A^(1/3))³ = (4/3)πR₀³A

The mass of a nucleus with nucleon number A is approximately A × u (where u is the atomic mass unit, since each nucleon has mass ≈ u).

Density ρ = mass / volume = (A × u) / [(4/3)πR₀³A] = u / [(4/3)πR₀³]

Since u and R₀ are constants, ρ = constant, independent of A.

Therefore, if R = R₀A^(1/3), all nuclei have the same density. ✓`,
  "phys-aqa-7408-2023-p2::06.4": `The density derived from this equation is only approximate because the equation R = R₀A^(1/3) is an empirical fit to experimental data, and nuclei do not have perfectly sharp, well-defined edges — the nuclear surface is diffuse (the nuclear density does not drop sharply to zero at R, but tapers off over a finite distance). The assumption that all nucleons have exactly the same mass (= u) is also an approximation, since there is a small mass difference between protons and neutrons, and binding energy also contributes to mass variation.`,
  "phys-aqa-7408-2023-p2::06.5": `For ³⁵₁₇Cl: A = 35, R = 4.02 × 10⁻¹⁵ m

Finding R₀:
R = R₀A^(1/3)
R₀ = R / A^(1/3) = 4.02 × 10⁻¹⁵ / 35^(1/3)
35^(1/3) = 3.271
R₀ = 4.02 × 10⁻¹⁵ / 3.271 = 1.229 × 10⁻¹⁵ m ≈ 1.23 × 10⁻¹⁵ m (1.23 fm)

Finding density of nuclear material:
mass of nucleus ≈ A × u = 35 × 1.661 × 10⁻²⁷ = 5.81 × 10⁻²⁶ kg
volume = (4/3)πR³ = (4/3)π × (4.02 × 10⁻¹⁵)³
= (4/3)π × 6.49 × 10⁻⁴⁴
= 2.72 × 10⁻⁴³ m³

ρ = m/V = 5.81 × 10⁻²⁶ / 2.72 × 10⁻⁴³ = 2.14 × 10¹⁷ kg m⁻³ ≈ 2.1 × 10¹⁷ kg m⁻³`,
  "phys-aqa-7408-2023-p2::07.1": `Heavy water (deuterium oxide, D₂O) is commonly used as a moderator in thermal nuclear reactors. (Alternatively: water, H₂O, is also used in light-water reactors.)`,
  "phys-aqa-7408-2023-p2::07.2": `1. Slow (thermal) neutrons are much more likely to be absorbed by uranium-235 nuclei and cause fission, so a chain reaction can be sustained.
2. Slow neutrons cause less damage to (less fatigue of) the reactor structure and shielding than fast neutrons.`,
  "phys-aqa-7408-2023-p2::07.3": `From Figure 15, at m_M/m_N = 12, v/u = 0.85.

Final KE / initial KE = (½m_N v²)/(½m_N u²) = (v/u)² = 0.85² = 0.72

Fraction of kinetic energy lost = 1 − 0.72 = 0.28, i.e. about 28% ≈ 30%`,
  "phys-aqa-7408-2023-p2::07.4": `A thermal neutron has kinetic energy equal to the average kinetic energy of an ideal gas particle at T = 350 K:
E_thermal = (3/2)k_BT = (3/2) × 1.38 × 10⁻²³ × 350 = 7.245 × 10⁻²¹ J

Converting initial energy to joules:
E₀ = 1.0 MeV = 1.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.60 × 10⁻¹³ J

Using E_f = E₀ e^(−by):
7.245 × 10⁻²¹ = 1.60 × 10⁻¹³ × e^(−0.73y)
e^(−0.73y) = 7.245 × 10⁻²¹ / 1.60 × 10⁻¹³ = 4.528 × 10⁻⁸
−0.73y = ln(4.528 × 10⁻⁸) = −16.908
y = 16.908 / 0.73 = 23.2

Minimum value of y ≈ 24 (rounding up to ensure E_f ≤ E_thermal)`,
  "phys-aqa-7408-2023-p2::07.5": `Figure 15 shows that v/u increases as m_M/m_N increases, so the lighter the moderator nucleus, the smaller the neutron's rebound speed and the greater the fraction of its kinetic energy lost in each collision. Moderator nuclei with a small nucleon number therefore slow the neutrons down in fewer collisions, so less moderator is needed.`,
  "phys-aqa-7408-2023-p3::01.1": `Answer: 4.5 × 10⁻²

The duty cycle T₁/T₂ is greatest for the longest flash (T₁ = 300 μs) together with the shortest time between flashes (T₂ = 1/150 Hz = 6.67 × 10⁻³ s): 300 × 10⁻⁶ / 6.67 × 10⁻³ = 4.5 × 10⁻².`,
  "phys-aqa-7408-2023-p3::01.2": `T₁ must be very short so that the ball moves only a negligible distance while a flash lasts. If each flash lasted longer, the image of the ball would be blurred and elongated rather than a sharp circle, and the position of the bottom of the ball in each image could not be determined precisely.`,
  "phys-aqa-7408-2023-p3::01.3": `Dividing the given equation through by n turns it into a three-term straight-line equation with (H − h)/n as the subject:

H − h = u₀(n/f) + (g/2)(n/f)²
(H − h)/n = u₀/f + (g/2f²)n

Comparing this with y = mx + c, where y = (H − h)/n, the quantity that should be plotted on the x-axis is n (the image number).

The graph is then a straight line of gradient m = g/(2f²), so g is determined from

g = 2f² × gradient

(and the y-intercept, u₀/f, gives u₀ = f × intercept).`,
  "phys-aqa-7408-2023-p3::01.4": `Counting the images in Figure 1, the ball first reaches the floor at the N = 17 image, so h = 0 when n = 17.

t = n/f = 17/31.0 = 0.5484 s

Putting h = 0 into H − h = u₀(n/f) + (g/2)(n/f)²:

H = u₀t + ½gt²
1.550 = u₀ × 0.5484 + 0.5 × 9.79 × 0.5484²
1.550 = 0.5484u₀ + 1.472
u₀ = (1.550 − 1.472)/0.5484 = 0.142

u₀ = 0.14 m s⁻¹ (directed downwards)`,
  "phys-aqa-7408-2023-p3::01.5": `Between the second and third contacts the ball is a projectile, so there is no horizontal force on it and its horizontal velocity is constant. It is therefore the horizontal distance travelled divided by the time taken.

Counting images from the labelled n = 40 point on Figure 3, the image just after the second contact (n = 43) is at s = 2200 mm and the image just before the third contact (n = 62) is at s = 3170 mm.

Δs = 3170 − 2200 = 970 mm
Δt = (62 − 43)/f = 19/31.0 = 0.613 s

horizontal velocity = 970/0.613 = 1580 mm s⁻¹ ≈ 1.6 × 10³ mm s⁻¹`,
  "phys-aqa-7408-2023-p3::01.6": `Annotate Figure 3 by drawing a smooth curve through the four highest points of the bounce (the images either side of the peak, n ≈ 53–56) and drawing a horizontal line from the top of that curve across to the h-axis. This gives the maximum height reached between the second and third contacts:

h_max = 497 mm = 0.497 m

At the top of the bounce the vertical velocity is zero, so the time to fall from there back to the floor, using s = ut + ½gt² with u = 0, is

t₁ = √(2h_max/g) = √(2 × 0.497 / 9.79) = 0.319 s

The upward and downward halves of the bounce take equal times, so the time between the second and third contacts is

t = 2t₁ = 2 × 0.319 = 0.64 s`,
  "phys-aqa-7408-2023-p3::02.1": `The data logger records at 2.5 Hz, so successive points plotted on Figure 4 are separated in time by

Δt (per interval) = 1/2.5 = 0.40 s

On Figure 4 the point at V = 3.30 V and the point at V = 11.47 V are 13 recording intervals apart, so

Δt = 13 × 0.40 = 5.2 s
ΔV = 11.47 − 3.30 = 8.17 V

rate of increase of V = ΔV/Δt = 8.17/5.2 = 1.57 V s⁻¹`,
  "phys-aqa-7408-2023-p3::02.2": `Two advantages of using data logging for this experiment:
1. Data logging records voltage and current values at very short, regular time intervals automatically, providing many more data points than could be recorded manually, giving a more detailed and accurate I–V characteristic.
2. The data logger records values continuously and simultaneously, avoiding the time delay between reading two separate meters that would occur with manual readings, reducing the error due to the changing temperature of the filament during the measurement.`,
  "phys-aqa-7408-2023-p3::02.3": `Circuit 2 can produce all of the data. With X connected as a potential divider, the pd applied to L can be varied continuously from 0 V right up to the full 12 V of the supply, which covers the whole range of Figure 4.

Circuit 1 cannot. There X is in series with L, so the current is smallest when X is set to its maximum resistance of 14.9 Ω:

minimum I = 12/(14.9 + 2.3) = 12/17.2 = 0.70 A
(equivalently the minimum pd across L is 0.70 × 2.3 = 1.6 V)

The first data point on Figure 4 is at I = 0.36 A (V ≈ 0.7 V). Since 0.36 A is well below the 0.70 A that is the smallest current circuit 1 can give, circuit 1 cannot reach the low-current, low-voltage end of the data.

So only circuit 2 is able to produce all the data shown in Figure 4.`,
  "phys-aqa-7408-2023-p3::02.4": `Row 2: P = VI = 5.17 × 1.32 = 6.82 W

Row 4: reading the curve on Figure 4 at V = 9.58 V gives I = 1.77 A
P = VI = 9.58 × 1.77 = 17.0 W

Completed Table 2 (all values to 3 significant figures):
• 3.30 V, 1.07 A, 3.53 W
• 5.17 V, 1.32 A, 6.82 W
• 7.69 V, 1.59 A, 12.2 W
• 9.58 V, 1.77 A, 17.0 W
• 11.47 V, 1.94 A, 22.3 W`,
  "phys-aqa-7408-2023-p3::02.5": `Label the vertical axis P / W and choose a linear scale that uses most of the grid — for example 2 W per centimetre square, marked 0, 2, 4 … up to 24 W — with the printed V / V scale on the horizontal axis.

Plot the five points from the completed Table 2:
(3.30, 3.53), (5.17, 6.82), (7.69, 12.2), (9.58, 17.0), (11.47, 22.3)

Mark each as a small neat cross, then draw a single thin, continuous, smooth curve that is the best fit through them and extends at least from the first point to the fifth. The curve must not be a straight line: because P = VI and I itself rises as V rises, P increases faster than V does, so the curve gets steadily steeper — it has an increasing gradient and is concave upwards.`,
  "phys-aqa-7408-2023-p3::02.6": `Extend the best-fit curve on Figure 6 to the right-hand edge of the grid, V = 12 V, and read off the rated power there:

P_r = 23.8 W

The two identical lamps in series across the 12 V supply have the same resistance, so each has 6.0 V across it. Reading the same graph at V = 6.0 V gives the power in one lamp:

P₂ = 8.5 W

Total power dissipated in the series circuit = 2 × 8.5 = 17.0 W

percentage of P_r = (17.0/23.8) × 100 = 71%`,
  "phys-aqa-7408-2023-p3::03.1": `A search coil is not a suitable sensor here. A search coil relies on electromagnetic induction: an emf is induced in it only while the magnetic flux linking it is changing.

In this arrangement the coil on the frame carries a constant direct current, so the flux density at Q is constant and the flux linking a search coil placed at Q does not change. With no change of flux, no emf is induced in the search coil, so it gives no reading and cannot be used to measure B_H.`,
  "phys-aqa-7408-2023-p3::03.2": `The flux density produced at the centre of the coil acts along the coil's axis, and its magnitude is unchanged because the current is unchanged. Rotating the coil through 25° tilts that axis 25° away from the horizontal, so the horizontal component that the sensor detects becomes

new B_H = B_H cos 25°

percentage change = (B_H cos 25° − B_H)/B_H × 100
= (cos 25° − 1) × 100
= (0.906 − 1) × 100
= −9.4 %

So B_H decreases by 9.4%.`,
  "phys-aqa-7408-2023-p3::03.3": `The protractor in Figure 9 is divided into 1° intervals, so a single judgement of the position of the frame against the scale can be made to about ±0.5°.

The angle rotated through is obtained from the difference between two such judgements — the reading with the coil vertical and the reading in the new position — so the absolute uncertainties add:

absolute uncertainty in θ = 2 × 0.5° = ±1°

percentage uncertainty = (1/25) × 100 = 4%`,
  "phys-aqa-7408-2023-p3::03.4": `The experiment 2 curve in Figure 11 peaks where the sensor is at the centre of coil 2, which is a distance r from Q, so

r = 68 mm

For experiment 1, B_H at Q (x = 0) is 0.665 mT, so half of this is 0.33 mT. Following the experiment 1 curve out from Q, B_H has fallen to 0.33 mT at

x₀.₅ = 52 mm

x₀.₅/r = 52/68 = 0.76`,
  "phys-aqa-7408-2023-p3::03.5": `In experiment 3 the currents are in the same sense, so the two fields are in the same direction and the resultant flux density at any point is the sum of the two values read from Figure 11 at that value of x.

Take x = 34 mm, which is r/2 and so lies within the region between r/4 and 3r/4. This is where the two curves cross: experiment 1 gives 0.475 mT and experiment 2 gives 0.475 mT.

B_H = 0.475 + 0.475 = 0.95 mT`,
  "phys-aqa-7408-2023-p3::03.6": `Two characteristics of the magnetic field lines in the uniform central region between x = r/4 and x = 3r/4:
1. The field lines are parallel to each other (and parallel to the common axis PR of the two coils).
2. The field lines are equally spaced (uniform density), indicating a uniform magnetic field of constant magnitude throughout the region.`,
  "phys-aqa-7408-2023-p3::03.7": `First work out the two end values from Figure 11, remembering that reversing the current in coil 2 means its field now subtracts from that of coil 1.

At x = 0: coil 1 gives 0.665 mT and coil 2 gives 0.235 mT in the opposite direction, so B_H = 0.665 − 0.235 = +0.43 mT.
At x = r: the situation is the mirror image, so B_H = 0.235 − 0.665 = −0.43 mT.
At x = r/2: the two coils are equidistant, so their contributions are equal in size and opposite in direction and B_H = 0.

What to draw: add a vertical axis at x = 0, labelled B_H / mT, and mark a scale on it that goes both above and below the given horizontal axis, so the graph occupies two quadrants; mark +0.43 on it above the axis and −0.43 below. Then draw a single continuous line from the point (0, +0.43 mT) which falls steadily with a negative gradient all the way to (r, −0.43 mT), crossing the horizontal axis (B_H = 0) exactly at x = r/2. The line should be a smooth curve, steepest near the middle and antisymmetric about the point (r/2, 0), so that the value at x = r is equal and opposite to the value at x = 0.`,
  "phys-edexcel-9ph0-2022-p1::11(a)": `At constant velocity, the driving force equals the total resistive force. The component of weight along the slope = mg sin θ = 60 × 9.81 × sin 5.7° = 60 × 9.81 × 0.09930 = 58.4 N. Total force opposing motion = weight component + resistive force = 58.4 + 18 = 76.4 N. At constant velocity, driving force = 76.4 N. Power = F × v = 76.4 × 2.8 = 214 W ≈ 210 W.`,
  "phys-edexcel-9ph0-2022-p1::11(b)": `The wiring dissipates energy at a rate P = I²R.

55 W = (24 A)² × R
R = 55 W / 576 A² = 0.095 Ω

Resistance of the wiring = 0.095 Ω`,
  "phys-edexcel-9ph0-2022-p1::12(a)": `The free-body diagram should show four forces acting on the bicycle and cyclist: (1) Weight (W = mg) acting vertically downward from the centre of mass; (2) Normal contact force from the road acting vertically upward; (3) Friction force on the rear wheel acting horizontally forward (already drawn); (4) Air resistance / drag force acting horizontally backward (opposing motion). All four arrows should be drawn at appropriate points on the object with correct directions and labelled clearly.`,
  "phys-edexcel-9ph0-2022-p1::12(b)(i)": `The graph should show velocity on the y-axis and time on the x-axis. The velocity starts at a positive value (the initial speed when pedalling stops) at t = 0 and decreases linearly (straight line with negative gradient) to zero at t = 5.2 s, since the deceleration is stated to be constant. The line must be straight and must reach exactly zero at t = 5.2 s.`,
  "phys-edexcel-9ph0-2022-p1::12(b)(ii)": `Using v² = u² + 2as with v = 0 and s = 7.80 m: 0 = u² + 2a(7.80). Also using v = u + at with t = 5.2 s: 0 = u + a(5.2), so u = −5.2a. Substituting: 0 = (−5.2a)² + 15.6a → 0 = 27.04a² + 15.6a → a = −15.6/27.04 = −0.577 m s⁻². Alternatively, using s = ½(u + v)t: 7.80 = ½ × u × 5.2, so u = 3.0 m s⁻¹. Then a = (v − u)/t = (0 − 3.0)/5.2 = −0.577 m s⁻². Force = ma = 28.0 × 0.577 = 16.2 N ≈ 16 N.`,
  "phys-edexcel-9ph0-2022-p1::13": `Measure the angle θ between the string and the vertical pole on the photograph with a protractor: it is about 52° (to within about ±2°).

The ball travels in a horizontal circle, so the only forces on it are its weight mg (vertically down) and the tension T along the string, which makes an angle θ with the vertical pole.

Vertically there is no acceleration:  T cos θ = mg
Horizontally the resultant force is the centripetal force:  T sin θ = mv²/r

Dividing the second equation by the first eliminates T and m:

tan θ = v²/(rg) = (3.8 m s⁻¹)² / (1.2 m × 9.81 m s⁻²) = 14.44 / 11.77 = 1.227

θ = 50.8° ≈ 51°

The angle calculated from the quoted radius and speed, about 51°, agrees with the angle of about 52° measured from the photograph, well within the uncertainty of measuring an angle from a photograph. The values given are therefore consistent with the photograph. (The mass of the ball is not needed, as it cancels.)`,
  "phys-edexcel-9ph0-2022-p1::14(a)(i)": `f = 1/T = 1/0.02 = 50 Hz.`,
  "phys-edexcel-9ph0-2022-p1::14(a)(ii)": `V_rms = V_peak / √2 = 4.0 / √2 = 2.83 V ≈ 2.8 V.`,
  "phys-edexcel-9ph0-2022-p1::14(b)(i)": `A diode conducts only in one direction: it has a very low resistance when forward biased and a very high resistance when reverse biased. The four diodes are arranged as a bridge rectifier.

During the half-cycle in which the top of the bridge is made positive, D2 and D4 are forward biased while D1 and D3 are reverse biased. Current passes through D2 to X, down through R from X to Y, and returns to the supply through D4.

During the next half-cycle the polarity of V_in reverses, so D2 and D4 are now reverse biased and D1 and D3 conduct instead. Current passes through D3 to X, again down through R from X to Y, and returns through D1.

In both half-cycles the current in R is in the same direction (X to Y), so V_out has the same polarity throughout: the alternating input has been full-wave rectified, which is why the output graph shows a positive hump for every half-cycle of the input.`,
  "phys-edexcel-9ph0-2022-p1::14(b)(ii)": `Between the peaks the capacitor discharges through R, so V = V₀e^(−t/RC), i.e. ln V = ln V₀ − t/RC.

Read a corresponding pair of values from the graph: the output is at a peak of V₀ = 4.0 V at t = 5 ms and has fallen to V = 3.5 V at t = 13 ms, so t = 8.0 × 10⁻³ s.

ln 3.5 = ln 4.0 − 0.0080 s / (2200 Ω × C)
0.1335 = 0.0080 s / (2200 Ω × C)
C = 0.0080 / (2200 × 0.1335)

Capacitance = 2.7 × 10⁻⁵ F (27 μF)`,
  "phys-edexcel-9ph0-2022-p1::15(a)": `A linac consists of a long line of hollow metal drift tubes mounted end to end along the axis of an evacuated tube. Alternate tubes are connected to opposite terminals of a high-voltage alternating supply, so at any instant one tube is at a positive potential and the tube next to it is at a negative potential.

The electron is accelerated by the electric field in the gap between two adjacent tubes. The tube it is leaving is negative and the tube ahead of it is positive, so the field exerts a force on the electron along the axis and does work on it: the electron gains kinetic energy eV as it crosses each gap.

Inside a drift tube there is no electric field, because the metal tube screens the electron, so the electron simply travels through the tube at a constant speed.

While the electron is inside a tube the alternating supply reverses the polarity of the tubes. Consequently, when the electron emerges into the next gap, the tube in front of it has become positive again and the electron is accelerated once more rather than decelerated.

Because the supply alternates at a fixed frequency, the electron must spend the same time inside every tube if it is to stay in step with the field. The electron moves faster after each acceleration, so each successive tube has to be longer than the one before, with the gaps between tube centres increasing along the accelerator.

In this way a modest alternating p.d. accelerates the electron many times over, and it leaves the linac with a very high energy.`,
  "phys-edexcel-9ph0-2022-p1::15(b)": `To resolve the internal structure of a proton, the de Broglie wavelength of the electron must be smaller than or comparable to the size of the proton (≈ 10⁻¹⁵ m). The de Broglie wavelength λ = h/p, so a very short wavelength requires a very large momentum, which in turn requires a very high kinetic energy. Therefore electrons must have high energies so their de Broglie wavelength is small enough to diffract at the scale of the proton's internal structure.`,
  "phys-edexcel-9ph0-2022-p1::15(c)(i)": `Momentum has units of kg m s⁻¹. Energy in eV or GeV has units of kg m² s⁻². Dividing energy by c (units m s⁻¹) gives units of kg m² s⁻² / (m s⁻¹) = kg m s⁻¹, which are the base units of momentum. Therefore GeV/c has the same base units as momentum (kg m s⁻¹) and can correctly be used as a unit of momentum.`,
  "phys-edexcel-9ph0-2022-p1::15(c)(ii)": `Before the collision: electron momentum = 20 GeV/c (horizontal), proton momentum = 0. Total initial momentum = 20 GeV/c horizontally. After the collision: electron momentum = 9.1 GeV/c at 20° to the original direction. Horizontal component = 9.1 × cos 20° = 9.1 × 0.9397 = 8.55 GeV/c. Vertical component = 9.1 × sin 20° = 9.1 × 0.3420 = 3.11 GeV/c. For momentum to be conserved, the proton must have: horizontal component = 20 − 8.55 = 11.45 GeV/c, vertical component = −3.11 GeV/c (downward). Magnitude of proton momentum = √(11.45² + 3.11²) = √(131.1 + 9.67) = √140.8 = 11.9 GeV/c. This matches the given proton momentum of 11.9 GeV/c, so the law of conservation of momentum is obeyed.`,
  "phys-edexcel-9ph0-2022-p1::15(c)(iii)": `An inelastic collision is one in which kinetic energy is not conserved; the total kinetic energy after the collision is less than before (some kinetic energy is converted into other forms, such as rest mass energy of new particles created).`,
  "phys-edexcel-9ph0-2022-p1::16(a)(i)": `When the motor is switched on, the rotating magnetic field of the motor changes the magnetic flux through the copper disc. By Faraday's law, a changing magnetic flux induces an electromotive force (emf) in the disc, which drives eddy currents (induced currents) within the conducting copper disc.`,
  "phys-edexcel-9ph0-2022-p1::16(a)(ii)": `By Lenz's law, the induced eddy currents flow in a direction such that they oppose the change that caused them. The eddy currents in the copper disc create their own magnetic field, which interacts with the rotating magnetic field of the motor. This interaction produces a force on the current-carrying disc in the magnetic field. Since the induced currents oppose the relative motion (i.e., they try to reduce the relative motion between the disc and the rotating field), the disc is dragged around in the same direction as the rotating field of the motor, causing it to rotate.`,
  "phys-edexcel-9ph0-2022-p1::16(b)": `Angular speed ω = 2π × (revolutions per second) = 2π × (500/60) = 2π × 8.333 = 52.4 rad s⁻¹.`,
  "phys-edexcel-9ph0-2022-p1::16(c)": `The turning effect increases as the angular speed increases, and the data show the two are approximately proportional: 1.0/52.4 = 0.019 N cm per rad s⁻¹ and 2.0/104.7 = 0.019 N cm per rad s⁻¹ (the third pair, 2.8/157.1 = 0.018, falls a little below strict proportionality).

The faster the magnets on the plastic disc are rotated, the greater the rate at which the copper disc cuts the magnetic flux, so the greater the rate of change of flux linkage.

By Faraday's law, a greater rate of change of flux linkage induces a larger e.m.f., and so larger eddy currents flow in the copper disc.

These larger induced currents are in the magnetic field of the magnets, so the force on the copper disc — and hence the turning effect transmitted to the load — is correspondingly greater.`,
  "phys-edexcel-9ph0-2022-p1::17(a)": `The collision is between a cosmic-ray proton and a stationary proton, producing a neutron and a positive pion: p + p → p + n + π⁺`,
  "phys-edexcel-9ph0-2022-p1::17(b)": `A proton (p) has quark structure: uud. A neutron (n) has quark structure: udd. A positive pion (π⁺) has quark structure: ud̄ (up quark and anti-down quark). [Verification: π⁺ charge = +2/3 + 1/3 = +1 ✓]`,
  "phys-edexcel-9ph0-2022-p1::17(c)": `Mass of pion in MeV/c²: 140 MeV/c². Convert to kg using E = mc²: m = E/c² = (140 × 10⁶ × 1.60 × 10⁻¹⁹) / (3.00 × 10⁸)² = (2.24 × 10⁻¹¹) / (9.00 × 10¹⁶) = 2.49 × 10⁻²⁸ kg ≈ 2.5 × 10⁻²⁸ kg.`,
  "phys-edexcel-9ph0-2022-p1::17(d)": `The student's suggestion is incorrect. In this collision, the initial proton has momentum and both the proton and neutron in the products also carry momentum. By conservation of momentum, the system must have the same total momentum before and after. In the centre-of-mass frame, the minimum kinetic energy needed is the rest-mass energy of the pion (140 MeV) since all products can be created at rest. However, in the lab frame (where the target proton is stationary), the system has a net momentum that cannot be zero after the collision — the products must still move forward to conserve momentum. Therefore the products cannot all be at rest; they must carry kinetic energy. By conservation of energy, the incident proton must supply both the rest-mass energy of the pion (140 MeV) and the kinetic energy of the products. The minimum kinetic energy of the incident proton is thus greater than 140 MeV. The student's suggestion is wrong because they have not accounted for the kinetic energy that the products must retain to conserve momentum.`,
  "phys-edexcel-9ph0-2022-p1::18(a)": `The track is a rectangular strip, so its cross-sectional area is

A = width × thickness = 5.0 × 10⁻³ m × t

Using R = ρl/A with l = 115 mm = 0.115 m:

12.0 × 10³ Ω = (0.49 Ω m × 0.115 m) / (5.0 × 10⁻³ m × t)

t = (0.49 × 0.115) / (12.0 × 10³ × 5.0 × 10⁻³) = 0.05635 / 60

Thickness t = 9.4 × 10⁻⁴ m`,
  "phys-edexcel-9ph0-2022-p1::18(b)(i)": `The track is uniform, so the potential difference between two points on it is proportional to the length of track between them.

A displacement of 60 mm from end X gives a maximum p.d. of 5.0 V between Z and X, and the full track from X to Y is 115 mm long, so

V_XY = (115 mm / 60 mm) × 5.0 V = 9.58 V

which is about 10 V, as required.`,
  "phys-edexcel-9ph0-2022-p1::18(b)(ii)": `The potentiometer track (12.0 kΩ) and R are in series across the 12 V supply, and the p.d. across the track is 9.6 V.

Current in the circuit:  I = V_XY / R_XY = 9.6 V / 12.0 × 10³ Ω = 8.0 × 10⁻⁴ A

p.d. across R:  12 V − 9.6 V = 2.4 V

R = V/I = 2.4 V / 8.0 × 10⁻⁴ A

R = 3.0 × 10³ Ω (3000 Ω)`,
  "phys-edexcel-9ph0-2022-p1::18(b)(iii)": `The battery has an internal resistance r. When current flows, there is a voltage drop (lost volts) across the internal resistance of the battery: V_lost = Ir. The terminal pd of the battery is therefore less than the emf: V_terminal = emf − Ir < 12 V. Since the whole circuit is driven by the terminal pd (not the emf), the pd across the potentiometer track is proportionally reduced, and so the maximum output from the potentiometer is slightly less than 5.0 V. Additionally, any resistance in the connecting wires would have a similar effect.`,
  "phys-edexcel-9ph0-2022-p1::18(b)(iv)": `The speed of the tool is the gradient of the displacement–time graph, so the greatest speed occurs where the curve is steepest, at about t = 0.1 s.

Draw a tangent to the curve at that point and extend it over a large interval. The tangent cuts the 60 mm level at t = 0.056 s and the time axis (displacement 0) at t = 0.144 s, a base of 0.088 s.

gradient = (60 − 0) mm / (0.144 − 0.056) s = 60 / 0.088 = 682 mm s⁻¹ = 0.68 m s⁻¹

The maximum speed of the tool is about 0.68 m s⁻¹, which is less than 0.8 m s⁻¹, so the tool does not exceed the stated speed.`,
  "phys-edexcel-9ph0-2022-p2::11(a)": `With the camera focused on a very distant object the light arrives effectively parallel, so the image forms at the focal point and the lens sits a distance v₁ = f = 4.25 mm from the sensors.
For an object at u = 25.0 cm = 0.250 m, use 1/u + 1/v = 1/f with u and f in the same units:
1/v = 1/f − 1/u = 1/(4.25 × 10⁻³ m) − 1/(0.250 m) = 235.3 − 4.0 = 231.3 m⁻¹
v = 1/231.3 = 4.32 × 10⁻³ m = 4.32 mm
The lens must therefore move so that its distance from the light sensors increases from 4.25 mm to 4.32 mm.
Displacement of lens = v − f = 4.32 − 4.25 = 0.07 mm (0.0735 mm), directed away from the sensors.`,
  "phys-edexcel-9ph0-2022-p2::11(b)": `In a mobile phone camera, the object distance is always very large (much greater than the focal length), so the image always forms very close to the focal plane. The image distance barely changes regardless of object distance, so the lens and sensors can be fixed at a separation equal to the focal length.`,
  "phys-edexcel-9ph0-2022-p2::12": `The gravitational potential a distance r from the centre of Mars is V_grav = −GM/r, so the change in potential between the two points is ΔV_grav = GM(1/r₁ − 1/r₂).
Distances from the centre of Mars: r₁ = 3390 km + 11.0 km = 3.401 × 10⁶ m (parachutes open) and r₂ = 3390 km + 2.1 km = 3.3921 × 10⁶ m (parachutes detach).
GM = 6.67 × 10⁻¹¹ × 6.39 × 10²³ = 4.26 × 10¹³ N m² kg⁻¹
ΔV_grav = 4.26 × 10¹³ × (2.9403 × 10⁻⁷ − 2.9480 × 10⁻⁷) = 4.26 × 10¹³ × (−7.71 × 10⁻¹⁰) = −3.29 × 10⁴ J kg⁻¹
ΔE_grav = m × ΔV_grav = 1030 × (−3.29 × 10⁴) = −3.4 × 10⁷ J
The gravitational potential energy of the spacecraft therefore decreases by 3.4 × 10⁷ J during the parachute section of the descent.`,
  "phys-edexcel-9ph0-2022-p2::13": `The decay constant is λ = ln2/t½, so λ(Ac-225) = ln2/10 = 0.0693 day⁻¹ and λ(Bi-210) = ln2/5 = 0.139 day⁻¹. The decay constant of the actinium is half that of the bismuth.
Activity A = λN, and both samples start with the same number of nuclei N₀, so initially A₀(Ac) = 0.0693N₀ and A₀(Bi) = 0.139N₀ — the actinium starts with only half the activity of the bismuth.
In 10 days the actinium passes through exactly one half-life, so N(Ac) = N₀/2 and A(Ac) = 0.0693 × N₀/2 = 0.0347N₀.
In the same 10 days the bismuth passes through two half-lives, so N(Bi) = N₀/4 and A(Bi) = 0.139 × N₀/4 = 0.0347N₀.
The two activities are equal. The bismuth begins with twice the activity of the actinium, but in 10 days it decays through one extra half-life and so loses an extra factor of two — the two effects exactly cancel and both samples have the same activity after 10 days.`,
  "phys-edexcel-9ph0-2022-p2::14(a)": `The Doppler shift in wavelength is given by Δλ/λ = v/c, so Δλ = λv/c. For a given recession speed v, a longer wavelength λ produces a larger Δλ (the shift is directly proportional to the original wavelength). Therefore, spectral lines at longer wavelengths are shifted by a greater absolute amount (in nm) than lines at shorter wavelengths, even though the fractional shift Δλ/λ = v/c is the same for all lines.`,
  "phys-edexcel-9ph0-2022-p2::14(b)": `In spectrum B the line corresponding to the 656 nm laboratory line has moved towards the red end, to about 740 nm.
Δλ = 740 − 656 = 84 nm
z = Δλ/λ = (84 × 10⁻⁹)/(656 × 10⁻⁹) = 0.128
v = zc = 0.128 × 3.00 × 10⁸ = 3.8 × 10⁷ m s⁻¹
The wavelength has increased, so this is a red shift and the light is being stretched as the source moves away. The conclusion is that the distant star is receding from the Earth at about 3.8 × 10⁷ m s⁻¹, roughly 13% of the speed of light.`,
  "phys-edexcel-9ph0-2022-p2::15": `Energy needed to heat one can from room temperature to the melting point:
E = mcΔθ = 14 × 10⁻³ × 902 × (660 − 293) = 4.63 × 10³ J
Energy needed to melt it:
E = Lm = 396 × 10³ × 14 × 10⁻³ = 5.54 × 10³ J
Total energy to recycle the can = 4.63 × 10³ + 5.54 × 10³ = 1.02 × 10⁴ J.
This is only 5% of the energy that would be needed to extract the same aluminium from raw materials, so extraction would take 1.02 × 10⁴/0.05 = 2.04 × 10⁵ J. The energy saved by recycling is the remaining 95%:
energy saved = 0.95 × 2.04 × 10⁵ = 1.93 × 10⁵ J
For the phone: P = VI = 3.7 × 120 × 10⁻³ = 0.444 W, and 7 days = 7 × 24 × 3600 = 6.05 × 10⁵ s, so
E = Pt = 0.444 × 6.05 × 10⁵ = 2.69 × 10⁵ J
The energy saved (1.93 × 10⁵ J) is less than the energy the phone would use (2.69 × 10⁵ J), so the claim is not valid. The saving would actually run the phone for 1.93 × 10⁵/0.444 = 4.3 × 10⁵ s, which is about 5 days rather than the 7 days claimed.`,
  "phys-edexcel-9ph0-2022-p2::16(a)": `Draw the straight line of best fit through the plotted points and extend it across the graph, then take two widely separated points that lie on the line — for example (68 × 10¹³ Hz, 0.55 eV) and (99 × 10¹³ Hz, 1.84 eV).
gradient = ΔE/Δf = (1.84 − 0.55) eV ÷ (99 − 68) × 10¹³ Hz = 1.29/(3.1 × 10¹⁴) = 4.16 × 10⁻¹⁵ eV s
Einstein's photoelectric equation E = hf − φ shows that the gradient of a graph of maximum kinetic energy against frequency is the Planck constant. Here E is in electronvolts, so convert the gradient to joules using 1 eV = 1.60 × 10⁻¹⁹ J:
h = 4.16 × 10⁻¹⁵ × 1.60 × 10⁻¹⁹ = 6.7 × 10⁻³⁴ J s
h ≈ 6.7 × 10⁻³⁴ J s, close to the accepted value of 6.63 × 10⁻³⁴ J s.`,
  "phys-edexcel-9ph0-2022-p2::16(b)": `Extrapolate the line of best fit back until it crosses the frequency axis at E = 0. This x-intercept is the threshold frequency: f₀ = 55 × 10¹³ Hz = 5.5 × 10¹⁴ Hz.
At the threshold the photon energy just equals the work function, so
φ = hf₀ = 6.7 × 10⁻³⁴ × 5.5 × 10¹⁴ = 3.7 × 10⁻¹⁹ J
φ = (3.7 × 10⁻¹⁹)/(1.60 × 10⁻¹⁹) = 2.3 eV
Comparing this with the table — caesium 2.0 eV, calcium 2.9 eV, magnesium 3.7 eV — the calculated work function of 2.3 eV is much closer to caesium than to either of the others, so the metal used in the investigation was caesium.`,
  "phys-edexcel-9ph0-2022-p2::17(a)(i)": `In normal adjustment (final image at infinity), the intermediate image formed by the objective lens acts as the object for the eyepiece. For the final image to be at infinity, this intermediate image must be located at the focal point of the eyepiece (distance f_e from the eyepiece). The objective lens forms the intermediate image at its focal point (distance f_o from the objective, for a distant object). Therefore the total separation = f_o + f_e, the sum of the two focal lengths.`,
  "phys-edexcel-9ph0-2022-p2::17(a)(ii)": `The objective lens produces a real, inverted image. The eyepiece then acts as a magnifying glass on this already-inverted image, producing a virtual image that is still inverted relative to the original object. Since the objective inverts the image and the eyepiece does not re-invert it (it simply magnifies), the final image is inverted.`,
  "phys-edexcel-9ph0-2022-p2::17(b)(i)": `For destructive interference of reflected light, the path difference must be an odd number of half-wavelengths. Light reflected from the outer surface of the coating undergoes a phase change of π (half cycle) because it reflects off a denser medium (n_c > n_air). Light transmitted through the coating and reflected from the lens surface also undergoes a phase change of π (because n_glass > n_c). Since both reflections undergo the same phase change, they cancel, and the condition for destructive interference is a path difference of λ_coating/2, i.e. 2d = λ_coating/2, so d = λ_coating/4. First find the wavelength of green light in the coating: λ_coating = c/(f × n_c) = (3.00 × 10⁸)/(6.00 × 10¹⁴ × 1.38) = (3.00 × 10⁸)/(8.28 × 10¹⁴) = 3.62 × 10⁻⁷ m. Minimum thickness: d = λ_coating/4 = 3.62 × 10⁻⁷/4 = 9.06 × 10⁻⁸ m ≈ 91 nm.`,
  "phys-edexcel-9ph0-2022-p2::17(b)(ii)": `The coating is designed to eliminate (by destructive interference) the reflection of green light, which is in the middle of the visible spectrum. The remaining reflected light consists of the colours at the two ends of the visible spectrum — red and blue/violet — which are not eliminated. The combination of red and blue/violet light appears purple (or magenta) to the observer.`,
  "phys-edexcel-9ph0-2022-p2::18(a)(i)": `A length L of the string is a cylinder of radius r, so its volume is V = πr²L and its mass is m = ρV = ρπr²L.
μ = m/L = ρπr²L/L = ρπr²
The diameter is 1.14 mm, so r = 0.57 mm = 0.57 × 10⁻³ m, and ρ = 1070 kg m⁻³:
μ = 1070 × π × (0.57 × 10⁻³)² = 1070 × π × 3.249 × 10⁻⁷ = 1.09 × 10⁻³ kg m⁻¹
This is about 1.1 × 10⁻³ kg m⁻¹, as required.`,
  "phys-edexcel-9ph0-2022-p2::18(a)(ii)": `For a string vibrating in its fundamental mode (first harmonic), the frequency is f = (1/2L)√(T/μ). Rearranging: T = 4L²f²μ. L = 0.410 m, f = 440 Hz, μ = 1.1 × 10⁻³ kg m⁻¹. T = 4 × (0.410)² × (440)² × 1.1 × 10⁻³ = 4 × 0.1681 × 193600 × 1.1 × 10⁻³ = 4 × 0.1681 × 213.0 = 143 N ≈ 143 N.`,
  "phys-edexcel-9ph0-2022-p2::18(b)": `The graph shows that the Young modulus E of the nylon falls as the temperature rises, so when the string warms up during playing E decreases.
The string is held between fixed points, so its length and extension are essentially fixed. Since the tension is given by T = EA×(extension)/(original length), a smaller Young modulus means a smaller tension — the string slackens.
The speed of a transverse wave on the string is v = √(T/μ), so a smaller tension gives a smaller wave speed.
The distance between the fixed ends is unchanged, so the wavelength of the fundamental (λ = 2L) is unchanged. From f = v/λ, a smaller wave speed with the same wavelength means a lower frequency.
The note produced therefore falls slightly in pitch — the string goes flat as it warms up.`,
  "phys-edexcel-9ph0-2022-p2::19(a)": `Volume of spherical bulb: V = (4/3)π r³ = (4/3)π(0.080)³ = (4/3)π(5.12 × 10⁻⁴) = 2.145 × 10⁻³ m³. Temperature T = 25 + 273 = 298 K. Using ideal gas law pV = NkT: N = pV/(kT) = (1.25 × 2.145 × 10⁻³)/(1.38 × 10⁻²³ × 298) = (2.681 × 10⁻³)/(4.112 × 10⁻²¹) = 6.52 × 10¹⁷ atoms ≈ 6.5 × 10¹⁷.`,
  "phys-edexcel-9ph0-2022-p2::19(b)": `When electrons collide with neon atoms in the tube, they transfer energy to the atoms, exciting electrons in the neon atoms from their ground state to higher energy levels (excited states). These energy levels are discrete (quantised), so only specific amounts of energy can be absorbed. The excited neon atoms are unstable and the electrons rapidly fall back down to lower energy levels, releasing energy in the form of photons. The energy of each photon is given by E = hf = E₂ − E₁, where E₂ and E₁ are the energies of the higher and lower levels respectively. Since the energy levels are discrete and fixed for neon, only specific photon energies (and hence specific frequencies/wavelengths) are emitted, producing a line spectrum rather than a continuous spectrum. The visible lines in the spectrum correspond to electron transitions between specific pairs of energy levels that release photon energies in the range 1.8–3.1 eV (corresponding to visible wavelengths 400–700 nm). Different transitions produce different coloured lines, giving the characteristic line emission spectrum of neon.`,
  "phys-edexcel-9ph0-2022-p2::20(a)": `For a mass-spring system in SHM: f = (1/2π)√(k/m). First find k from the static extension: k = mg/x = (0.065 × 9.81)/0.085 = 0.6377/0.085 = 7.50 N m⁻¹. Then f = (1/2π)√(7.50/0.065) = (1/2π)√(115.4) = (1/2π) × 10.74 = 1.71 Hz. The stated frequency is 2.5 Hz. Since 1.71 Hz ≠ 2.5 Hz, the statement is incorrect — the flamingo will oscillate at approximately 1.7 Hz, not 2.5 Hz.`,
  "phys-edexcel-9ph0-2022-p2::20(b)": `The oscillation is damped because energy is transferred from the flamingo to the surrounding air (and possibly the spring/support). Air resistance (drag) acts on the flamingo as it moves, dissipating kinetic energy as thermal energy. As energy is removed from the system with each oscillation, the amplitude decreases until all the energy has been transferred to the surroundings and the flamingo comes to rest at the equilibrium position.`,
  "phys-edexcel-9ph0-2022-p2::20(c)(i)": `For a simple pendulum: T = 2π√(L/g) = 2π√(1.25/9.81) = 2π√(0.1274) = 2π × 0.3569 = 2.243 s ≈ 2.2 s. ✓`,
  "phys-edexcel-9ph0-2022-p2::20(c)(ii)": `Maximum velocity occurs at the equilibrium position: v_max = Aω = A × (2π/T). A = 7.5 cm = 0.075 m, T = 2.2 s. ω = 2π/2.2 = 2.856 rad s⁻¹. v_max = 0.075 × 2.856 = 0.214 m s⁻¹ ≈ 0.21 m s⁻¹.`,
  "phys-edexcel-9ph0-2022-p2::21(a)": `In β⁻ decay the mass number stays the same and the atomic number increases by 1. ⁸⁷₃₇Rb → ⁸⁷₃₈Sr + ⁰₋₁β⁻ + ⁰₀ν̄ₑ`,
  "phys-edexcel-9ph0-2022-p2::21(b)": `λ = ln2/t½ = ln2/(4.88 × 10¹⁰ year) = 1.42 × 10⁻¹¹ year⁻¹
Every strontium atom in the sample came from a rubidium atom, so the original number of rubidium nuclei was N₀ = N_R + N_S while the number remaining now is N = N_R. Hence
N₀/N = (N_R + N_S)/N_R = 1 + N_S/N_R = 1 + 0.0532 = 1.0532
Using N = N₀e⁻λᵗ, which rearranges to N₀/N = eλᵗ:
t = ln(1.0532)/λ = 0.0518/(1.42 × 10⁻¹¹) = 3.7 × 10⁹ years
The Moon rock is therefore about 3.7 × 10⁹ years old, whereas the Earth is 4.5 × 10⁹ years old — the rock is some 0.8 × 10⁹ years younger. This ratio is not consistent with the Earth and the Moon forming at the same time; on this evidence the Moon rock solidified well after the Earth formed.`,
  "phys-edexcel-9ph0-2022-p2::21(c)": `The half-life of rubidium-87 is extremely long (about 4.88 × 10¹⁰ years), which means its activity is extremely low. The activity A = λN = (ln2/T½) × N is so small that it is very difficult to measure accurately above background radiation levels, making a direct determination of T½ by measuring activity over a practical timescale impossible.`,
  "phys-edexcel-9ph0-2022-p2::21(d)": `If the half-life is larger than previously accepted, then the decay constant λ = ln2/T½ is smaller. For the same measured ratio N_S/N_R, using a larger T½ in the calculation t = T½ × ln((N_R + N_S)/N_R)/ln2 gives a larger value of t. Therefore the ages calculated by this dating method would be larger (older) than previously determined — the rocks and hence the Earth/Moon would appear older than previously thought.`,
  "phys-edexcel-9ph0-2022-p3::1(a)": `Two criticisms can be made of the way the results have been recorded. First, the extensions are not all given to the same number of decimal places (or significant figures): the value for the 0.25 kg mass is written as 0.1 m, while every other reading is given to three decimal places, such as 0.019 m and 0.085 m. It should have been recorded as 0.100 m, to match the resolution of the metre rule used for all the other readings.
Second, the position of the bottom of the mass holder has not been recorded at all. Only the calculated extensions appear in the table, so the raw measurements — the unloaded position and the loaded positions — from which those extensions were worked out cannot be checked.`,
  "phys-edexcel-9ph0-2022-p3::1(b)": `The student should use a set square (or a metre rule held vertically) alongside a ruler fixed vertically beside the spring to take readings. A fiducial marker (e.g. a pin or a small piece of paper attached to the spring coil) should be used to mark the exact position being measured, eliminating parallax error. The student should read the ruler at eye level directly in line with the marker to avoid parallax. Take the reading with the spring at rest (not oscillating). Measure the unloaded position and the loaded position multiple times and calculate the extension as the difference, repeating to obtain a mean value.`,
  "phys-edexcel-9ph0-2022-p3::2(a)": `She should have measured the thickness of a stack of several slides (e.g. 10 slides) together, then divided by the number of slides. This increases the total measured thickness, which reduces the percentage uncertainty (since the absolute uncertainty of the micrometer is fixed, dividing by a larger total gives a smaller percentage uncertainty).`,
  "phys-edexcel-9ph0-2022-p3::2(b)": `The statement confuses three different ideas: precision, accuracy and resolution.
Precision describes how closely repeated measurements of the same quantity agree with one another — the spread of the values. The number of decimal places shown on a balance says nothing about that spread, so the reason she gives for calling her value precise is not a valid one.
Accuracy is a different idea: it is how close a measured value is to the true value. A balance that has not been zeroed correctly can give a tight cluster of readings that are all wrong, so being precise does not make a value accurate.
What '0.01 g' actually describes is the resolution of the balance — the smallest difference it can display — which gives an uncertainty of about ±0.005 g (half a scale division) in each individual reading.
Her final sentence is sound: repeating the measurement several times and taking a mean does reduce the effect of random error on the result, although it will not reduce any systematic error in the balance itself.`,
  "phys-edexcel-9ph0-2022-p3::3(a)": `Kinetic energy of the hand just before each slap:
Ek = ½mv² = ½ × 1.75 × (6.25)² = 34.2 J
Only 65% of this is transferred to the chicken, so the energy delivered by 8000 slaps is
E = 0.65 × 8000 × 34.2 = 1.78 × 10⁵ J
Energy needed to raise the chicken from 23 °C to 165 °C, a rise of 142 K:
E = mcΔθ = 0.875 × 1770 × 142 = 2.20 × 10⁵ J
The energy supplied by 8000 slaps, 1.78 × 10⁵ J, is less than the 2.20 × 10⁵ J required, so the data does not confirm the claim — 8000 slaps would not be sufficient.
(Equivalently: each slap delivers 0.65 × 34.2 = 22.2 J, so 2.20 × 10⁵/22.2 ≈ 9900 slaps would be needed; or 8000 slaps would give a temperature rise of only 1.78 × 10⁵/(0.875 × 1770) = 115 K, taking the chicken to about 138 °C rather than 165 °C.)`,
  "phys-edexcel-9ph0-2022-p3::3(b)": `The assumption that no energy is transferred from the chicken to the surroundings is not realistic. In practice, the chicken would lose thermal energy to the surrounding air by convection, conduction, and radiation throughout the cooking process. This means more slaps would be needed than calculated, as some of the energy added is continuously lost rather than retained by the chicken. Therefore the assumption makes the answer an underestimate of the required number of slaps.`,
  "phys-edexcel-9ph0-2022-p3::4": `The procedure could be improved in the following ways. First, the student should measure more complete oscillations (e.g. 20 or more) rather than just a few, and divide the total time by the number of oscillations to get the period T. This reduces the percentage uncertainty in T since the uncertainty in starting and stopping the stopwatch is spread over more oscillations. Second, the student should repeat the timing measurement several times (at least 3) and calculate a mean value, to reduce the effect of random errors such as reaction time. Third, the student should measure from the same point in the oscillation each time (e.g. at the equilibrium position where the pendulum moves fastest), using a fiducial marker, to improve consistency. Fourth, a light gate and datalogger could be used instead of a stopwatch to eliminate human reaction time. Fifth, the student should ensure the amplitude of oscillation is small (less than 10° of arc) so that the motion is truly simple harmonic and the standard formula T = 2π√(L/g) applies.`,
  "phys-edexcel-9ph0-2022-p3::5": `When the torch is shaken, the strong magnet is driven backwards and forwards along the tube and passes through the copper coil. As it moves, the magnetic flux linking the coil changes — the turns of the coil cut through the magnet's field lines.
By Faraday's law, this rate of change of flux linkage induces an e.m.f. across the ends of the coil. Because the coil forms part of a complete circuit, that induced e.m.f. drives a pulse of current round the circuit each time the magnet sweeps past.
The magnet passes through the coil in both directions as the torch is shaken, so the induced e.m.f. reverses and the current pulses alternate in direction. The diode connected between the coil and the capacitor conducts in one direction only, so only the pulses of one polarity are passed on to the capacitor.
Each of those pulses pushes charge onto the plates of the capacitor. Shaking the torch for a few minutes produces a great many pulses, so the capacitor is charged up repeatedly and builds up a substantial potential difference across it, storing energy. The diode also prevents the capacitor from discharging back through the coil between shakes, so the charge is retained.
When the switch is then closed, the capacitor is connected across the LED and discharges through it. The current from the discharging capacitor passes through the LED in its forward direction and the LED emits light. Because a capacitor stores only a limited amount of charge, the p.d. and the current fall as it discharges, which is why the LED lights only for a short while before the torch has to be shaken again.`,
  "phys-edexcel-9ph0-2022-p3::6(a)": `The student moved microphone 2 only as far as the first position at which the two signals came back into phase, so he has measured a distance equal to just one wavelength. A single measurement of about 20 cm made with a metre rule carries a fairly large percentage uncertainty, and that uncertainty is carried straight through into λ.
He should instead have kept moving the microphone through several successive in-phase positions — say ten of them — measured the total distance moved and divided by the number of wavelengths. The absolute uncertainty in reading the rule stays the same while the distance measured is about ten times larger, so the percentage uncertainty in d, and hence in λ, is much smaller.`,
  "phys-edexcel-9ph0-2022-p3::6(b)": `From the trace, successive peaks are 3.0 divisions apart, so one complete cycle occupies 3.0 divisions. With the time base set to 0.20 ms div⁻¹:
T = 3.0 × 0.20 × 10⁻³ = 6.0 × 10⁻⁴ s
f = 1/T = 1/(6.0 × 10⁻⁴) = 1.67 × 10³ Hz
The microphone was moved until the signals were in phase again, so the distance between the microphones is one whole wavelength:
λ = d = 20.5 cm = 0.205 m
v = fλ = 1.67 × 10³ × 0.205 = 342 m s⁻¹
Speed of sound in air ≈ 340 m s⁻¹.`,
  "phys-edexcel-9ph0-2022-p3::7(a)": `Take the projectile (65 g = 0.065 kg) and the block (2.400 kg) moving together after the impact; their combined mass is 2.465 kg.
They rise 55 cm before stopping, so all of their kinetic energy just after the impact becomes gravitational potential energy:
Egrav = mgΔh = 2.465 × 9.81 × 0.55 = 13.3 J
½ × 2.465 × v² = 13.3, so v = 3.28 m s⁻¹ — the speed of the block and projectile immediately after the collision.
Momentum is conserved during the collision. Momentum of the projectile before impact, p = mu, equals the momentum of the combined mass afterwards:
0.065 × u = 2.465 × 3.28 = 8.09 kg m s⁻¹
u = 8.09/0.065 = 124.6 m s⁻¹ — the speed of the projectile just before impact.
Kinetic energy of the projectile before the collision:
Ek = ½mu² = ½ × 0.065 × (124.6)² = 504 J
Energy dissipated = kinetic energy before − kinetic energy after = 504 − 13.3 = 4.9 × 10² J (about 490 J).`,
  "phys-edexcel-9ph0-2022-p3::7(b)": `The principle of conservation of energy states that energy cannot be created or destroyed, only transferred between forms. In this inelastic collision, kinetic energy is not conserved — the total kinetic energy after the collision is less than before. However, total energy is still conserved: the 'lost' kinetic energy is transferred into other forms, primarily thermal energy (heating the projectile and block due to deformation and friction) and sound energy (the impact produces sound). The total energy of the system (kinetic + thermal + sound + gravitational PE) remains constant throughout.`,
  "phys-edexcel-9ph0-2022-p3::8(a)": `Beta radiation is detected, not alpha. Alpha radiation has a very short range in air (a few centimetres) and is stopped by even a thin sheet of paper or the walls of the plastic bottle. Alpha particles from inside the bottle would not penetrate through the plastic bottle walls to reach the GM tube outside. Beta particles have a much greater range in air (up to about 1 m) and can penetrate thin materials such as plastic bottle walls. Therefore only beta radiation from inside the bottle can reach and be detected by the GM tube placed outside.`,
  "phys-edexcel-9ph0-2022-p3::8(b)(i)": `The logged points scatter because radioactive decay is a random process, so first draw a smooth best-fit curve through them.
Read the initial count rate from the curve: at t = 0 it is 9.0 s⁻¹.
The curve falls to half of this, 4.5 s⁻¹, at about t = 75 s, so one half-life is about 75 s.
It halves again, to 2.25 s⁻¹, at about t = 150 s — a further 75 s.
The two intervals agree, and taking the mean gives
half-life of protactinium ≈ 75 s (any value in the range 60–80 s is consistent with the curve).
Taking two halvings and averaging is better than taking just one, because it reduces the effect of the random fluctuations in the plotted points.`,
  "phys-edexcel-9ph0-2022-p3::8(b)(ii)": `The count rate does not reach zero because there is always a background radiation count rate from natural sources (cosmic rays and radioactive materials in the environment). The GM tube detects this background radiation even when no sample is present. As the protactinium decays, its contribution to the count rate decreases, but the background count rate remains constant, so the total count rate approaches the background level but never reaches zero.`,
  "phys-edexcel-9ph0-2022-p3::9(a)": `Both circuits would allow the student to collect the data she needs: in each one the ammeter reads the current in the filament lamp and the voltmeter reads the p.d. across it, so she can record pairs of values and plot the current–potential difference graph.
In circuit 1 the lamp is connected across the output of a potential divider. Moving the sliding contact from one end of the resistance track to the other varies the fraction of the supply p.d. that is tapped off, and that fraction can be made anything from zero up to the whole of the supply p.d. The lamp can therefore be operated at any p.d. between 0 V and the full battery p.d.
In circuit 2 the variable resistor is simply in series with the lamp, so the battery p.d. is shared between the two of them. Adjusting the variable resistor changes the total resistance of the circuit and so changes the current, and with it the p.d. across the lamp. However, the lamp and the variable resistor always form a series pair, so some of the supply p.d. must always appear across the lamp. The smallest p.d. that can be reached across the lamp is greater than zero and depends on how large the variable resistor's maximum resistance is compared with the resistance of the lamp; the maximum p.d. is still the supply p.d., obtained when the variable resistor is turned down to zero.
Circuit 1 is therefore the more suitable of the two. Because it can deliver p.d.s right down to 0 V, it gives a much wider range of readings, and in particular it allows readings near the origin, which is exactly the region where a filament lamp's characteristic curve is most interesting — the filament is still cool there and the graph is close to a straight line before it bends over as the filament heats up and its resistance rises. Circuit 2 would leave a gap at the low-p.d. end of the graph, so the student should choose circuit 1.`,
  "phys-edexcel-9ph0-2022-p3::9(b)(i)": `Total pd in the circuit = 12 V. Pd across resistor = I × R = 17.5 × 10⁻³ × 560 = 9.80 V. Pd across filament lamp = 12 − 9.80 = 2.20 V ≈ 2.2 V.`,
  "phys-edexcel-9ph0-2022-p3::9(b)(ii)": `When the voltmeter (resistance 1.5 kΩ) is connected across the filament lamp, it is in parallel with the lamp, creating a parallel combination with a lower total resistance than the lamp alone. The total resistance in the circuit decreases, so the total current from the battery increases. A greater current flows through the series resistor (560 Ω), producing a larger pd across it (V_R = IR). Since the supply voltage is fixed at 12 V and more voltage is now dropped across the series resistor, the pd across the parallel combination (lamp + voltmeter) must be smaller. Therefore the pd across the filament lamp (and voltmeter) decreases.`,
  "phys-edexcel-9ph0-2022-p3::10(a)": `The most serious fault is the position of the first rubber band. It is near the top of the cylinder, just below the surface of the honey, so when the ball bearing passes it the ball is still accelerating and has not yet reached its terminal velocity. The timed section therefore does not correspond to steady-speed motion, and the velocity calculated from it is not the terminal velocity that the viscosity formula requires.
Secondly, with only two bands the student has no way of checking whether the ball is travelling at terminal velocity over the timed section at all. He should move the first band well below the surface of the honey and add several more bands at equal spacings down the cylinder; if the ball takes the same time to travel between each successive pair of bands, that confirms it is falling at a constant speed.`,
  "phys-edexcel-9ph0-2022-p3::10(b)(i)": `Mean time t_mean = (6.40 + 6.35 + 6.36 + 6.38)/4 = 25.49/4 = 6.3725 s ≈ 6.37 s. Mean velocity v = distance/time = 0.250/6.3725 = 0.03923 m s⁻¹ ≈ 0.039 m s⁻¹ ≈ 0.04 m s⁻¹. ✓`,
  "phys-edexcel-9ph0-2022-p3::10(b)(ii)": `Using the mean velocity from part (b)(i), v = 3.92 × 10⁻² m s⁻¹:
η = 2r²g(ρB − ρH)/(9v)
= [2 × (5.50 × 10⁻³)² × 9.81 × (7750 − 1360)] ÷ (9 × 3.92 × 10⁻²)
Numerator: 2 × 3.025 × 10⁻⁵ × 9.81 × 6390 = 3.79
Denominator: 9 × 3.92 × 10⁻² = 0.353
η = 3.79/0.353 = 10.7 Pa s
This is very close to the quoted viscosity of honey A (10.6 Pa s) and well below those of honey B (12.5 Pa s) and honey C (13.6 Pa s), so the student used honey A.`,
  "phys-edexcel-9ph0-2022-p3::11(a)": `The thermistor is a semiconductor with a negative temperature coefficient. As the water cools, the thermistor cools with it, and less thermal energy is available to free charge carriers, so the number of free charge carriers (electrons) per unit volume in the thermistor decreases.
With fewer charge carriers available to carry the current, the resistance of the thermistor increases.
The thermistor and the fixed resistor are connected in series across the supply, forming a potential divider. As the thermistor's resistance becomes a larger fraction of the total circuit resistance, a larger fraction of the supply p.d. appears across it, so the voltmeter reading V increases as the water cools. (Equivalently: the larger total resistance means a smaller current in the circuit, so the p.d. across the fixed resistor falls and the p.d. across the thermistor must rise.)`,
  "phys-edexcel-9ph0-2022-p3::11(b)(i)": `Taking natural logarithm of V = V₀e^(−bθ): lnV = lnV₀ + ln(e^(−bθ)) = lnV₀ − bθ. This is of the form y = c + mx, where y = lnV, x = θ, gradient m = −b (a constant), and intercept c = lnV₀ (a constant). Since both b and V₀ are constants, the graph of lnV against θ is a straight line with gradient −b and y-intercept lnV₀.`,
  "phys-edexcel-9ph0-2022-p3::11(b)(ii)": `Calculate lnV for each data point: θ = 89.0°C: lnV = ln(1.9) = 0.642; θ = 74.0°C: ln(2.9) = 1.065; θ = 53.5°C: ln(4.9) = 1.589; θ = 32.5°C: ln(9.1) = 2.208; θ = 18.5°C: ln(12.6) = 2.534; θ = 3.5°C: ln(18.7) = 2.928. Plot lnV (y-axis) against θ/°C (x-axis). The points should lie approximately on a straight line with negative gradient. Draw the best-fit straight line through all six points. The line should have a negative gradient (lnV decreases as θ increases). Ensure the axes are labelled with lnV (no units) and θ/°C, and the scale is appropriate for the data range.`,
  "phys-edexcel-9ph0-2022-p3::11(b)(iii)": `Take a large triangle using two points that lie on the line of best fit, well separated along the line. The line passes close to (3.5 °C, 2.93) and (89.0 °C, 0.64):
gradient = (0.64 − 2.93)/(89.0 − 3.5) = −2.29/85.5 = −0.0268 °C⁻¹
From part (b)(i), lnV = lnV₀ − bθ, so the gradient of the line is −b:
b = 0.027 °C⁻¹ (equivalently 0.027 K⁻¹)
The intercept on the lnV axis is lnV₀. Extending the line back to θ = 0 gives lnV₀ = 3.02, so
V₀ = e³·⁰² = 20 V (2 s.f.)`,
  "phys-edexcel-9ph0-2022-p3::12(a)(i)": `In β⁻ decay, the mass number is unchanged and the atomic number increases by 1. ¹³⁷₅₅Cs → ¹³⁷₅₆Ba + ⁰₋₁β⁻ + ⁰₀ν̄ₑ. Mass number of Ba = 137, atomic number of Ba = 56.`,
  "phys-edexcel-9ph0-2022-p3::12(a)(ii)": `Total activity of all the water in the reservoir at the start:
A₀ = 2.35 × 10¹² Bq m⁻³ × 5000 m³ = 1.175 × 10¹⁶ Bq
Decay constant: λ = ln2/t½ = ln2/30 = 2.31 × 10⁻² year⁻¹
Using A = A₀e⁻λᵗ with A = 100 Bq:
100/(1.175 × 10¹⁶) = 8.51 × 10⁻¹⁵ = e⁻λᵗ
ln(8.51 × 10⁻¹⁵) = −32.4 = −(2.31 × 10⁻²)t
t = 32.4/(2.31 × 10⁻²) = 1.40 × 10³ years
It would take about 1400 years for the caesium-137 to decay to the suggested safe level.`,
  "phys-edexcel-9ph0-2022-p3::12(b)": `Initial number of iodine-131 nuclei N₀ = 1.25 × 10²⁸. Half-life of I-131 = 8.0 days. After 32 days = 4 half-lives: N_I remaining = N₀ × (1/2)⁴ = 1.25 × 10²⁸ / 16 = 7.8125 × 10²⁶. Number of Xe atoms produced = N₀ − N_I = 1.25 × 10²⁸ − 7.8125 × 10²⁶ = 1.25 × 10²⁸ − 0.078125 × 10²⁸ = 1.1719 × 10²⁸ ≈ 1.17 × 10²⁸. Now check if this exerts pressure ≥ 1.0 × 10⁵ Pa in volume V = 450 m³ at T = 293 K. Using ideal gas law pV = NkT: p = NkT/V = (1.17 × 10²⁸ × 1.38 × 10⁻²³ × 293) / 450 = (1.17 × 10²⁸ × 4.041 × 10⁻²¹) / 450 = (4.728 × 10⁷) / 450 = 1.05 × 10⁵ Pa. Since 1.05 × 10⁵ Pa > 1.0 × 10⁵ Pa, yes, enough xenon would have collected to exert the required pressure.`,
  "phys-edexcel-9ph0-2022-p3::12(c)": `Treat the motion of the 9th floor as simple harmonic.
From the graph, the largest acceleration reached is about 9 m s⁻² (the tallest peaks lie just below the 10 m s⁻² gridline, at about t = 83.5 s).
To find the period, count several complete cycles rather than relying on one: there are about 7 cycles between t = 81.0 s and t = 89.2 s, so
T = (89.2 − 81.0)/7 = 1.2 s
ω = 2π/T = 2π/1.2 = 5.2 rad s⁻¹
For simple harmonic motion a = −ω²x, and the acceleration has its greatest magnitude when the displacement is the amplitude A, so
A = a_max/ω² = 9/(5.2)² = 9/27.2 = 0.33 m
The maximum displacement of the 9th floor from its normal position is therefore about 0.33 m, i.e. 33 cm. This is greater than 30 cm, so the report is accurate. It is worth noting that the margin is small: reading a slightly lower peak acceleration or a slightly shorter period off the graph would bring the amplitude below 30 cm, so the report is only just supported by this data.`,
  "phys-edexcel-9ph0-2022-p3::13(a)": `The vibrating tuning fork, held against the wire at one bridge, sends a progressive transverse wave travelling along the wire. When that wave reaches the other bridge it is reflected there and travels back along the wire, so two waves of the same frequency, wavelength and very nearly the same amplitude travel in opposite directions along the wire and superpose.
The wire is held down at each bridge and cannot move there, so each bridge is a node. The mid-point of the wire lies the same distance from both bridges, so the incident wave and the reflected wave have travelled equal path lengths to reach it. The path difference is zero, so they always arrive in phase there.
Where the two waves meet in phase their displacements add — constructive interference — giving a point of maximum displacement, which is an antinode. With a single loop between the bridges the wire is half a wavelength long, so this antinode lies exactly midway between them.`,
  "phys-edexcel-9ph0-2022-p3::13(b)(i)": `Safety precaution: wear eye protection (safety goggles) in case the wire snaps under tension and flies up. Alternatively: do not lean over the wire, or place a guard/screen around the hanging mass in case it falls.`,
  "phys-edexcel-9ph0-2022-p3::13(b)(ii)": `For the fundamental mode of a stretched string: f = (1/2L)√(T/μ), where L is the length between bridges, T is the tension, and μ is the mass per unit length. Rearranging: 2Lf = √(T/μ) → (2Lf)² = T/μ → 4L²f² = T/μ → L² = (T/μ) × (1/f²) × (1/4) = T/(4μ) × (1/f²). So L² = [T/(4μ)] × (1/f²). This is of the form y = mx, where y = L², x = 1/f², and gradient m = T/(4μ). Therefore the gradient of L² against 1/f² equals T/(4μ). ✓`,
  "phys-edexcel-9ph0-2022-p3::13(b)(iii)": `The line of best fit passes through the origin, so use a large triangle from the origin to the top of the line. At 1/f² = 15.0 × 10⁻⁶ s² the line gives L² = 0.043 m², so
gradient = (0.043 − 0)/(15.0 × 10⁻⁶ − 0) = 2.87 × 10³ m² s⁻²
The tension comes from the hanging mass: T = mg = 2.10 × 9.81 = 20.6 N.
From part (b)(ii) the gradient equals T/4μ, so
μ = T/(4 × gradient) = 20.6/(4 × 2.87 × 10³) = 1.79 × 10⁻³ kg m⁻¹ = 1.8 g m⁻¹
Comparing with the table, 1.8 g m⁻¹ is much closer to the 1.95 g m⁻¹ of 24 SWG wire than to 3.15 g m⁻¹ (22 SWG) or 1.31 g m⁻¹ (26 SWG), so the student used 24 SWG steel wire.`,
  "phys-edexcel-9ph0-2022-p3::13(c)(i)": `The student should take several readings of the diameter at different positions along the wire and in different orientations (rotate the wire 90° between readings) to account for any non-circularity of the cross-section. The student should also close the micrometer thimble slowly until it just contacts the wire, and use the ratchet (if present) to apply a consistent, light pressure — avoiding over-tightening which would compress the wire and give an underestimate. The zero reading should be checked and any zero error noted and subtracted from all readings.`,
  "phys-edexcel-9ph0-2022-p3::13(c)(ii)": `Step 1: Calculate mean diameter. d values: 0.55, 0.59, 0.57, 0.58 mm. Mean d = (0.55 + 0.59 + 0.57 + 0.58)/4 = 2.29/4 = 0.5725 mm = 5.725 × 10⁻⁴ m. Step 2: Calculate uncertainty in d. Range = 0.59 − 0.55 = 0.04 mm. Uncertainty = ±0.02 mm (half range) = ±2 × 10⁻⁵ m. Percentage uncertainty in d = (0.02/0.5725) × 100 = 3.5%. Step 3: Calculate μ from mean d and given density ρ = 8700 kg m⁻³. μ = ρ × π × (d/2)² = 8700 × π × (5.725 × 10⁻⁴/2)² = 8700 × π × (2.8625 × 10⁻⁴)² = 8700 × π × 8.194 × 10⁻⁸ = 8700 × 2.574 × 10⁻⁷ = 2.239 × 10⁻³ kg m⁻¹. Step 4: Calculate percentage uncertainty in μ. Since μ ∝ d², percentage uncertainty in μ = 2 × (percentage uncertainty in d) + percentage uncertainty in ρ = 2 × 3.5% + (200/8700 × 100%) = 7.0% + 2.3% = 9.3%. Step 5: Uncertainty in μ = 9.3% × 2.239 × 10⁻³ = 0.208 × 10⁻³ kg m⁻¹. Range: μ = (2.24 ± 0.21) × 10⁻³ kg m⁻¹, i.e. 2.03 × 10⁻³ to 2.45 × 10⁻³ kg m⁻¹. The stated value of μ = 2.14 × 10⁻³ kg m⁻¹ lies within this range (2.03 to 2.45 × 10⁻³ kg m⁻¹), so the student's data does support the stated value.`,
  "phys-edexcel-9ph0-2023-p1::11(a)": `When the a.c. supply is switched on, an alternating current flows through the coil beneath the hob. This creates a changing magnetic field. The changing magnetic field passes through the base of the steel pan, causing a change in magnetic flux linkage through the pan. By Faraday's law, this induces an e.m.f. in the pan. Because the pan is a conducting material (steel), this e.m.f. drives eddy currents in circular paths within the base of the pan. These eddy currents have a heating effect (by I²R), so the pan becomes hot due to the electrical energy dissipated as thermal energy in the resistance of the steel.`,
  "phys-edexcel-9ph0-2023-p1::11(b)": `A higher frequency means the magnetic flux through the pan changes more rapidly per unit time. By Faraday's law, a greater rate of change of flux induces a larger e.m.f. in the pan. This drives larger eddy currents, which dissipate more power (P = I²R), so the pan heats up more quickly. The advantage is that the hob is more efficient and heats the pan faster, reducing cooking time and energy waste.`,
  "phys-edexcel-9ph0-2023-p1::12(a)": `A vector quantity is one that has both magnitude and direction.`,
  "phys-edexcel-9ph0-2023-p1::12(b)": `The current is given by I = nAvq, where n is the number density of free electrons and q is the charge on an electron. Both n and q are fixed properties of the conducting material, and I is the same at every cross-section because charge is conserved, so v ∝ 1/A.

Therefore, as A decreases towards end Y, the drift velocity of the free electrons must increase, and the electrons drift fastest at the narrow end Y.`,
  "phys-edexcel-9ph0-2023-p1::12(c)": `We need to show that the units of ρ = E/j are the same on both sides.

Left-hand side: units of ρ are Ω m.

Right-hand side: E has units of N C⁻¹ = V m⁻¹ (since 1 V = 1 J C⁻¹ = 1 N m C⁻¹, so 1 N C⁻¹ = 1 V m⁻¹). j (current density) has units of A m⁻².

So E/j has units of (V m⁻¹) / (A m⁻²) = V m⁻¹ × m² A⁻¹ = V m A⁻¹.

Since V A⁻¹ = Ω, this gives units of Ω m.

Left-hand side = Ω m = Right-hand side. Therefore the units are consistent.`,
  "phys-edexcel-9ph0-2023-p1::13(a)": `The 333 Ω resistor and the LDR form a potential divider across the 7.0 V supply, and the input to the transistor is the potential difference across the 333 Ω resistor. Because the transistor can be assumed to have infinite resistance it draws no current, so the divider is unloaded.

From the graph, at a light level of 30 lux the resistance of the LDR is 3000 Ω.

Current in the series circuit: I = 7.0 V / (333 Ω + 3000 Ω) = 2.1 × 10⁻³ A
Potential difference across the 333 Ω resistor: V = 2.1 × 10⁻³ A × 333 Ω = 0.70 V
(Equivalently, by the potential divider ratio, V = 7.0 V × 333/(333 + 3000) = 0.70 V.)

So at a light level of exactly 30 lux the input to the transistor is 0.70 V. As the light level rises above 30 lux the resistance of the LDR falls below 3000 Ω, so the LDR takes a smaller share of the supply p.d. and the p.d. across the 333 Ω resistor rises above 0.7 V. The transistor therefore switches on just as the light level increases above 30 lux, so the circuit does respond as required.`,
  "phys-edexcel-9ph0-2023-p1::13(b)": `As the light level increases, more photons per unit time are incident on the LDR. These photons have sufficient energy to free more electrons from atoms in the semiconductor material of the LDR (by the photoelectric effect / promoting electrons across the band gap). This increases the number of charge carriers available for conduction. With more free electrons, the resistance of the LDR decreases.`,
  "phys-edexcel-9ph0-2023-p1::14(a)(i)": `Rod X is in equilibrium, so take moments about the right-hand end of X, where it is attached to the column. This eliminates the unknown force exerted on X by the column.

Weight of the cable: W = mg = 45 kg × 9.81 N kg⁻¹ = 441 N, acting at a distance of 1.5 m from the column.

The force T from rod Y acts at the point 1.3 m from the column, at 35° to rod X, so the component of T perpendicular to X is T sin 35°.

Taking moments about the column end:
45 kg × 9.81 N kg⁻¹ × 1.5 m = T × 1.3 m × sin 35°
662 N m = T × 0.746 m
T = 888 N ≈ 890 N

This force acts along rod Y, which is in compression and so pushes rod X upwards and away from the column.`,
  "phys-edexcel-9ph0-2023-p1::14(a)(ii)": `Three forces act on rod X. The weight of the cable is already drawn as an arrow pointing vertically downwards from the left-hand end of X, 1.5 m from the column. Two more arrows are needed.

1. The force from rod Y: draw it starting at the point 1.3 m from the column where rod Y meets rod X, pointing up and to the left at about 35° above the horizontal, and label it 'force from rod Y'. Rod Y is a strut in compression, so it thrusts along its own length, away from the column.

2. The force from the column: draw it starting at the right-hand end of rod X, pointing (approximately) horizontally to the right, i.e. towards the column, and label it 'force from column'. Its direction must be such that the three arrows together can add to zero.

The horizontal component of the thrust from Y (T cos 35° ≈ 730 N to the left) is balanced by the force from the column, while its vertical component (T sin 35° ≈ 510 N upwards) balances the 441 N weight of the cable together with any small vertical component at the column.`,
  "phys-edexcel-9ph0-2023-p1::14(b)": `For an inverse square law: E ∝ 1/r², so E × r² = constant.

At r = 3 m: E × r² = 1200 × 3² = 1200 × 9 = 10 800 N C⁻¹ m²
At r = 25 m: E × r² = 100 × 25² = 100 × 625 = 62 500 N C⁻¹ m²

Since 10 800 ≠ 62 500, the values of E × r² are not equal. Therefore, these data are NOT consistent with an inverse square law.`,
  "phys-edexcel-9ph0-2023-p1::15(a)(i)": `The diagram shows the pion and proton tracks curving in opposite directions in the magnetic field. Because the tracks curve in opposite directions, they must have opposite charges. The proton has charge +e, so the pion must have charge −e. Since these are the only two decay products and they have equal and opposite charges, the total charge of the products is zero. Therefore, the delta particle must have been neutral (charge = 0).`,
  "phys-edexcel-9ph0-2023-p1::15(a)(ii)": `By conservation of charge: charge before = charge after. The Δ⁰ has charge 0. The proton has charge +e. Therefore the pion must have charge 0 − (+e) = −e. The pion has a charge of −e (i.e. −1 in units of elementary charge).`,
  "phys-edexcel-9ph0-2023-p1::15(a)(iii)": `Δ⁰ → p + π⁻

(The delta neutral particle decays into a proton and a negative pion.)`,
  "phys-edexcel-9ph0-2023-p1::15(a)(iv)": `The delta particle must be classified as a baryon because baryon number is conserved. In the decay Δ⁰ → p + π⁻, the proton has baryon number +1 and the pion has baryon number 0. So the total baryon number after is +1. For baryon number to be conserved, the Δ⁰ must also have baryon number +1, which means it is a baryon.`,
  "phys-edexcel-9ph0-2023-p1::15(a)(v)": `A charged particle moving at right angles to the magnetic field of the detector follows a circular arc whose radius r is given by p = BQr, so for two particles carrying the same magnitude of charge in the same field the momentum is proportional to the radius of curvature of the track.

In the diagram the proton's track is almost straight, so its radius of curvature is very large, whereas the pion's track is much more strongly curved and therefore has a much smaller radius.

Since p ∝ r, the momentum of the proton is much larger than the momentum of the pion.`,
  "phys-edexcel-9ph0-2023-p1::15(b)(i)": `Using E = mc²:

First convert 1232 MeV to joules:
1232 MeV = 1232 × 10⁶ × 1.60 × 10⁻¹⁹ J = 1.9712 × 10⁻¹⁰ J

Using E = mc²:
m = E/c² = (1.9712 × 10⁻¹⁰) / (3.00 × 10⁸)²
m = (1.9712 × 10⁻¹⁰) / (9.00 × 10¹⁶)
m = 2.19 × 10⁻²⁷ kg`,
  "phys-edexcel-9ph0-2023-p1::15(b)(ii)": `The sum of the rest masses of the proton (939 MeV/c²) and the pion (139 MeV/c²) is 1078 MeV/c², which is less than the mass of the delta particle (1232 MeV/c²). The difference in mass (1232 − 1078 = 154 MeV/c²) is converted into kinetic energy of the decay products, in accordance with conservation of energy (E = mc²). The delta particle has greater mass-energy than the combined rest masses of its products, and this difference in rest mass energy is released as kinetic energy shared between the proton and pion. Since the delta particle is unstable, the decay is energetically possible precisely because the products have less combined rest mass than the parent particle.`,
  "phys-edexcel-9ph0-2023-p1::16(a)": `The battery drives a current through the carbon brushes and the split ring into the coil, so that the current flows from D to C along one long side of the coil, round through C to B, and then from B to A along the other long side.

Each of these sides is a current-carrying conductor lying at right angles to the magnetic field between the north and south poles of the magnet, so each experiences a force given by F = BIl, with its direction given by Fleming's left-hand rule.

Because the current in DC is in the opposite direction to the current in BA, the two forces are in opposite directions: the force on side DC is vertically downwards while the force on side BA is vertically upwards.

These two equal and opposite forces do not act along the same line, so they form a couple. Each provides a moment about the axis in the same sense, and this resultant turning effect makes the coil start to rotate.

As the coil turns, the two halves of the split ring turn with it, and after every half turn each half of the ring leaves one brush and makes contact with the other. This reverses the direction of the current in the coil relative to the magnetic field, so that the side which has just passed the vertical is always carrying current in the direction that pushes it back downwards, and the other side is always pushed upwards.

The moment therefore always acts in the same rotational sense. Instead of coming to rest after half a turn the coil keeps being pushed round, so it rotates continuously in the same direction for as long as the current flows.`,
  "phys-edexcel-9ph0-2023-p1::16(b)": `Work done by the motor = Pt = 390 × 10³ W × 4.0 s = 1.56 × 10⁶ J

Kinetic energy gained by the car = ½mv² = ½ × 1950 kg × (28 m s⁻¹)² = 7.644 × 10⁵ J

The work done by the motor is shared between increasing the kinetic energy of the car and doing work against the resistive forces, so

Work done by resistive forces = 1.56 × 10⁶ J − 7.644 × 10⁵ J = 7.96 × 10⁵ J (≈ 8.0 × 10⁵ J)`,
  "phys-edexcel-9ph0-2023-p1::16(c)": `An increase in internal resistance means that when the battery supplies current, a greater proportion of the battery's EMF is used to drive current through the internal resistance (lost volts = Ir). This leaves a smaller terminal voltage available to the external circuit (motor). With a lower terminal voltage, the motor receives less power (P = V²/R), so the car's performance is reduced. Additionally, more energy is wasted as heat within the battery itself (P = I²r), which reduces the efficiency of the battery and means it can deliver less useful energy overall. This shortens the range of the vehicle and increases charging frequency.`,
  "phys-edexcel-9ph0-2023-p1::17(a)": `Resolve the initial velocity of the ball into components:
horizontal: vₕ = 23.8 cos 50.0° = 15.30 m s⁻¹
vertical: vᵥ = 23.8 sin 50.0° = 18.23 m s⁻¹

The horizontal velocity is constant, so the time taken for the ball to travel the 55.0 m to the fielder is
t = 55.0 m / 15.30 m s⁻¹ = 3.595 s

Vertically, taking upwards as positive with a = −9.81 m s⁻²:
s = vᵥt − ½gt² = 18.23 × 3.595 − ½ × 9.81 × 3.595²
s = 65.5 m − 63.4 m = 2.1 m

So when the ball reaches the fielder it is 2.1 m above the height at which it was hit. This is less than three metres, so the fielder can catch the ball and the batter is out.`,
  "phys-edexcel-9ph0-2023-p1::17(b)(i)": `Momentum = mass × velocity = 0.140 × 23.8 = 3.332 N s ≈ 3.3 N s ✓`,
  "phys-edexcel-9ph0-2023-p1::17(b)(ii)": `Momentum is conserved in the collision, so
p(bat before) + p(ball before) = p(bat after) + p(ball after)

On the vector diagram, the two 'before' arrows are already drawn nose-to-tail: the ball's arrow ends where the bat's arrow begins, so the resultant momentum before the hit is the line from the tail of the ball's arrow to the head of the bat's arrow. The same resultant must be made up of the two 'after' vectors.

Starting from the tail of the p(ball before) arrow, use a ruler to draw the momentum of the ball after the hit: the diagram is drawn to a scale of 1 cm ≡ 1 N s, so draw a line 3.3 cm long at 50° above the horizontal and label it 'ball after', with an arrowhead. The momentum of the bat after the hit is then the line drawn from the head of that arrow to the head of the p(bat before) arrow; label it 'bat after' and measure its length and angle.

Checking by components, taking the direction in which the ball is hit as positive:
before the hit: bat 15.0 N s at 25° → (13.6, 6.34) N s; ball 4.6 N s at 10°, travelling towards the batter → (−4.53, 0.80) N s
total before = (9.06, 7.14) N s
ball after: 3.33 N s at 50° → (2.14, 2.55) N s
bat after = (9.06 − 2.14, 7.14 − 2.55) = (6.92, 4.59) N s

magnitude = √(6.92² + 4.59²) = 8.3 N s
angle = tan⁻¹(4.59/6.92) = 34°

The momentum of the bat after it hit the ball is 8.3 N s at 34° to the horizontal.`,
  "phys-edexcel-9ph0-2023-p1::18(a)(i)": `V_rms = V_peak / √2 = 5 / √2 = 5/1.414 = 3.54 V`,
  "phys-edexcel-9ph0-2023-p1::18(a)(ii)": `The formula V = 5 sin(100πt) produces a sinusoidal variation in V with time. The peak value is 5 V (the amplitude of the sine function). The angular frequency ω = 100π rad s⁻¹, so the frequency f = ω/(2π) = 100π/(2π) = 50 Hz, giving a period T = 1/50 = 0.02 s. The graph therefore shows a sine wave with peak value 5 V and period 0.02 s, which is consistent with the graph displayed — the voltage oscillates between +5 V and −5 V with a period of 0.02 s.`,
  "phys-edexcel-9ph0-2023-p1::18(b)(i)": `Cell E10 is the final charge Q(final) stored on the capacitor at the end of the time step that ends at t = 0.0080 s.

It is calculated from Q = CV, using the capacitance of the capacitor, C = 1 mF = 0.001 F, and the potential difference for that row, which is in cell C10:

E10 = 0.001 × C10 = 0.001 F × 2.94 V = 0.00294 C

which is the value shown in the spreadsheet.`,
  "phys-edexcel-9ph0-2023-p1::18(b)(ii)": `Cell G11 = F11 / B11

This is ΔQ/Δt = current I. The current is calculated by dividing the change in charge (ΔQ, from column F) by the time step (Δt, from column B).`,
  "phys-edexcel-9ph0-2023-p1::18(b)(iii)": `Maximum energy stored when voltage is at its peak value, V_peak = 5 V.

E = ½CV² = ½ × 1×10⁻³ × 5² = ½ × 1×10⁻³ × 25 = 0.0125 J = 12.5 mJ`,
  "phys-edexcel-9ph0-2023-p1::18(c)": `The instantaneous power is given by P = IV, so corresponding values of I and V must be read from the two graphs at the same time.

During the first quarter of a cycle, from t = 0 to t = 0.005 s, V and I are both positive: for example at t = 0.0020 s the graphs give V ≈ +2.9 V and I ≈ +1.4 A, so P ≈ +4 W. Energy is being transferred to the capacitor as it charges.

During the next quarter of a cycle V is still positive but the current has reversed: at t = 0.0070 s, V = +4.05 V and I = −0.71 A, so P = 4.05 × (−0.71) = −2.9 W. The capacitor is now discharging and returning energy to the supply.

The current graph is a quarter of a cycle (90°) ahead of the potential difference graph, so this pattern repeats in the second half of the cycle with both quantities negative and then with opposite signs again. Every quarter cycle in which the power is positive is matched by an identical quarter cycle in which the power is negative.

The positive and negative contributions therefore cancel exactly, the mean power over a complete cycle is zero, and so the capacitor dissipates no power — it only stores energy and then gives it back to the supply.`,
  "phys-edexcel-9ph0-2023-p2::11": `The frequency of a vibrating string is given by f = (1/2L)√(T/μ), where L is the length, T is the tension, and μ is the mass per unit length (linear density).

For strings of the same length and tension, f ∝ 1/√μ.

A thicker string has a greater cross-sectional area. Since μ = ρA (where ρ is the density of the material and A is the cross-sectional area), a thicker string has a greater mass per unit length μ.

Since f ∝ 1/√μ, a greater μ gives a lower frequency.

Therefore, a thicker string produces a note of lower frequency compared with a thinner string.`,
  "phys-edexcel-9ph0-2023-p2::12": `Assume that the energy lost by the metal block is equal to the energy gained by the water and the glass container, and use ΔE = mcΔθ for each.

Energy gained by the water = 0.300 kg × 4200 J kg⁻¹ K⁻¹ × (23 − 19) K = 5040 J
Energy gained by the glass = 0.050 kg × 840 J kg⁻¹ K⁻¹ × (23 − 19) K = 168 J
Total energy gained = 5208 J

The block cools from 100 °C to 23 °C, a temperature change of 77 K, so
0.220 kg × c × 77 K = 5208 J
16.94 c = 5208
c = 307 J kg⁻¹ K⁻¹

This lies between the two tabulated values, but the block must be copper. The experimental value is an underestimate, because some energy is transferred to the surroundings and the block is unlikely to have reached the full 100 °C, so the true specific heat capacity is higher than 307 J kg⁻¹ K⁻¹ and therefore closer to the 390 J kg⁻¹ K⁻¹ of copper.

Tin can also be ruled out directly: for tin the block would have to cool by 5208 J / (0.220 kg × 230 J kg⁻¹ K⁻¹) = 103 K, so it would have to start at 23 + 103 = 126 °C. That is impossible, because the block was heated in boiling water at 100 °C. The block is therefore made from copper.`,
  "phys-edexcel-9ph0-2023-p2::13(a)": `Inside a fusion reactor, the conditions are extremely extreme:
1. Very high temperature — of the order of 10⁸ K (hundreds of millions of degrees Celsius). This is necessary so that hydrogen nuclei (e.g. deuterium and tritium) have sufficient kinetic energy to overcome the electrostatic repulsion between their positive charges and come close enough for the strong nuclear force to cause fusion.
2. Very high pressure — the plasma must be confined at very high density so that collisions between nuclei are frequent enough to sustain the fusion reaction.
3. The plasma (ionised gas of nuclei and free electrons) must be confined, typically using powerful magnetic fields (in a tokamak design) or inertial confinement, since no material container could withstand such temperatures.`,
  "phys-edexcel-9ph0-2023-p2::13(b)": `In fusion, two small nuclei join together to form a larger nucleus. The graph shows that the binding energy per nucleon rises very steeply over the first part of the curve, so the nucleus produced is much more tightly bound than the nuclei that formed it.

For example, the graph gives a binding energy per nucleon of about 1 MeV for a nucleus of nucleon number 2 and about 7 MeV for one of nucleon number 4, an increase of roughly 6 MeV for every nucleon involved; by a nucleon number of 50 the value has risen to about 8.7 MeV.

Because the binding energy per nucleon increases, the total binding energy of the product is greater than that of the original nuclei, so the product has a larger mass deficit and the total rest mass has decreased. That lost mass appears as released energy according to ΔE = c²Δm, and since c² is very large and the change in binding energy per nucleon is several MeV, each fusion reaction releases a large amount of energy.`,
  "phys-edexcel-9ph0-2023-p2::14(a)": `When the stove uses the butane gas, the gas escapes from the canister and is burned. To replace this gas, liquid butane inside the canister evaporates. Evaporation requires energy (the latent heat of vaporisation), which is the energy needed to break the intermolecular bonds between liquid molecules so they can escape as gas.

This energy must come from the internal (thermal) energy of the remaining liquid butane and the canister itself, since the evaporation happens rapidly and heat cannot flow in from the surroundings quickly enough. As the internal energy of the liquid decreases, its temperature falls.

Therefore the temperature of the canister decreases because the thermal energy of the butane (and the canister) is used to supply the latent heat needed for evaporation.`,
  "phys-edexcel-9ph0-2023-p2::14(b)(i)": `Volume of canister: V = πr²h = π × (0.11)² × 0.23 = π × 0.0121 × 0.23 = 8.745 × 10⁻³ m³

Pressure: p = 220 kPa = 220 × 10³ Pa
Temperature: T = 21 + 273 = 294 K

Using the ideal gas equation: pV = NkT
where k = 1.38 × 10⁻²³ J K⁻¹

N = pV/(kT) = (220 × 10³ × 8.745 × 10⁻³) / (1.38 × 10⁻²³ × 294)
N = (1923.9) / (4.0572 × 10⁻²¹)
N = 4.74 × 10²³ molecules`,
  "phys-edexcel-9ph0-2023-p2::14(b)(ii)": `Using ½m<c²> = (3/2)kT, so <c²> = 3kT/m:

c_rms = √(3kT/m) = √(3 × 1.38 × 10⁻²³ × 294 / (9.6 × 10⁻²⁶))
= √(3 × 4.0572 × 10⁻²¹ / 9.6 × 10⁻²⁶)
= √(1.2172 × 10⁻²⁰ / 9.6 × 10⁻²⁶)
= √(1.268 × 10⁵)
= 356 m s⁻¹`,
  "phys-edexcel-9ph0-2023-p2::15(a)(i)": `Assuming the universe has been expanding at a constant rate (constant speed) since the Big Bang:

For a galaxy at distance d moving away at speed v, Hubble's law gives: v = H₀d.

Time since the Big Bang (age of universe): T = d/v = d/(H₀d) = 1/H₀.

Therefore T = 1/H₀.`,
  "phys-edexcel-9ph0-2023-p2::15(a)(ii)": `One assumption: the rate of expansion of the universe has been constant throughout its history (i.e. the universe has been expanding at the same speed since the Big Bang, with no acceleration or deceleration).`,
  "phys-edexcel-9ph0-2023-p2::15(a)(iii)": `The galaxies formed shortly after the big bang, so the age of the universe is about 13 × 10⁹ years.

Convert to seconds: T = 13 × 10⁹ × 3.16 × 10⁷ s = 4.11 × 10¹⁷ s

Using T = 1/H₀:
H₀ = 1/T = 1 / (4.11 × 10¹⁷ s) = 2.43 × 10⁻¹⁸ s⁻¹

Convert to km s⁻¹ Mpc⁻¹. One megaparsec is 10⁶ × 3.1 × 10¹⁶ m = 3.1 × 10²² m, so
H₀ = 2.43 × 10⁻¹⁸ s⁻¹ × 3.1 × 10²² m Mpc⁻¹ = 7.5 × 10⁴ m s⁻¹ Mpc⁻¹ = 75 km s⁻¹ Mpc⁻¹

This value of 75 km s⁻¹ Mpc⁻¹ lies between 60 and 80 km s⁻¹ Mpc⁻¹, so the JWST observation does lead to a value of the Hubble constant within the accepted range.`,
  "phys-edexcel-9ph0-2023-p2::15(b)(i)": `The redshift z is defined as: z = (λ_observed − λ_emitted) / λ_emitted

So λ_emitted = λ_observed / (1 + z) = (4.0 × 10⁻⁶) / (1 + 14) = (4.0 × 10⁻⁶) / 15 = 2.67 × 10⁻⁷ m

This corresponds to ultraviolet wavelength (267 nm), which is in the ultraviolet part of the spectrum.`,
  "phys-edexcel-9ph0-2023-p2::15(b)(ii)": `The light was emitted by Maisie as ultraviolet radiation (wavelength ~267 nm). As the universe has expanded during the time the light has been travelling towards us, the space through which the light travels has stretched. This stretching of space causes the wavelength of the light to increase in proportion to the expansion — this is cosmological redshift. The wavelength has been stretched by a factor of (1 + z) = 15, from ~267 nm (UV) to 4.0 × 10⁻⁶ m (4000 nm = infrared). So the light arrives at the telescope as infrared radiation because its wavelength has been redshifted by the expansion of the universe.`,
  "phys-edexcel-9ph0-2023-p2::15(c)": `Work function φ = 0.30 eV = 0.30 × 1.60 × 10⁻¹⁹ J = 4.80 × 10⁻²⁰ J

The wavelength of the light from Maisie arriving at the telescope is λ = 4.0 × 10⁻⁶ m.

Energy of a photon: E = hc/λ = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) / (4.0 × 10⁻⁶)
= (1.989 × 10⁻²⁵) / (4.0 × 10⁻⁶)
= 4.97 × 10⁻²⁰ J

Convert work function to joules: φ = 4.80 × 10⁻²⁰ J

Since E_photon = 4.97 × 10⁻²⁰ J > φ = 4.80 × 10⁻²⁰ J, the photon has more energy than the work function.

Therefore the detector CAN detect the light from Maisie, because the photon energy is sufficient to eject electrons from the detector material (photoelectric emission occurs).`,
  "phys-edexcel-9ph0-2023-p2::16(a)": `Within the elastic limit means that the material will return to its original shape and size when the deforming force is removed. The deformation is fully reversible and no permanent (plastic) deformation occurs.`,
  "phys-edexcel-9ph0-2023-p2::16(b)(i)": `Each spring supports a quarter of the weight of the car, so the mass supported by one spring is
m = 1100 kg / 4 = 275 kg

Force on each spring: F = mg = 275 kg × 9.81 N kg⁻¹ = 2698 N

The spring is within the limit of proportionality, so Hooke's law F = kx applies, with x = 152 mm = 0.152 m:
k = F/x = 2698 N / 0.152 m = 17 750 N m⁻¹

This is about 18 000 N m⁻¹, as required.`,
  "phys-edexcel-9ph0-2023-p2::16(b)(ii)": `For a mass oscillating on a spring, T = 2π√(m/k).

Each spring supports a quarter of the car, so take m = 1100 kg / 4 = 275 kg with k = 17 700 N m⁻¹ for that spring. (Treating the whole car of 1100 kg on four springs in parallel, of combined stiffness 4 × 17 700 = 70 800 N m⁻¹, gives exactly the same ratio m/k.)

T = 2π√(275 kg / 17 700 N m⁻¹) = 2π√(0.01554 s²) = 2π × 0.1247 s = 0.783 s

f = 1/T = 1 / 0.783 s = 1.28 Hz ≈ 1.3 Hz`,
  "phys-edexcel-9ph0-2023-p2::16(c)": `The conditions for simple harmonic motion are:
1. The acceleration of the object must be proportional to its displacement from the equilibrium position.
2. The acceleration must always be directed towards the equilibrium position (i.e. the restoring force acts opposite to the displacement).`,
  "phys-edexcel-9ph0-2023-p2::16(d)": `Oil of high viscosity has a greater resistance to flow (it is thicker/more viscous). When the piston moves through the oil-filled cylinder, the oil must flow past or through the piston. A more viscous oil exerts a larger viscous drag force on the piston that opposes its motion. This drag force is proportional to the velocity of the piston (for viscous flow). The large resistive force removes energy from the oscillating system much more quickly than a less viscous oil would. When the energy is removed rapidly, the amplitude of oscillation decreases rapidly — this is heavy (or overdamped) damping. The system quickly returns to equilibrium without oscillating.`,
  "phys-edexcel-9ph0-2023-p2::17(a)": `A diffraction grating has a very large number of equally spaced slits. When the light reaches the grating, each slit acts as a source of secondary waves, and the waves spreading out from the different slits overlap and superpose.

In a direction where the path difference between the waves from adjacent slits is a whole number of wavelengths, the waves all arrive in phase and interfere constructively, giving a sharp bright line. In every other direction the waves from the many slits are out of phase with one another and cancel, so the regions between the bright lines are dark. The condition for a bright line is nλ = d sinθ, where d is the spacing of the slits, θ is the angle from the straight-through direction and n is the order.

Straight ahead, θ = 0 and the path difference is zero whatever the wavelength, so the red light and the blue light both form their zero-order maximum in exactly the same place. The central line is therefore a mixture of the two colours and appears purple (magenta).

For every other order the position does depend on wavelength. Rearranging the grating equation, sinθ = nλ/d, so the longer the wavelength the greater the angle at which that order is formed. Blue light has a shorter wavelength than red light, so in the first order the blue line is diffracted through a smaller angle and appears closer to the central line, with the red line of the same order further out from the centre.

The same argument applies to the second and higher orders, and because θ increases with n the gap between the blue line and the red line of a given order gets wider as the order increases.

The pattern seen is therefore a purple central line, with a separate blue line and a separate red line on each side of it for each order, the blue line of each order always lying nearer to the centre than the red line of that order, and the colours separating further as the order number increases.`,
  "phys-edexcel-9ph0-2023-p2::17(b)(i)": `As light from the star passes through the star's own atmosphere, photons interact with atoms of specific elements (hydrogen, magnesium, sodium, etc.) present in the atmosphere. Each element has a unique set of discrete energy levels.

Electrons in these atoms can only absorb photons of specific energies that exactly match the energy difference between two electron energy levels (ΔE = hf). When such a photon is absorbed, the electron is excited to a higher energy level. The absorbed photon is removed from the beam of light travelling towards us.

Although the excited electron eventually re-emits a photon of the same energy when it returns to a lower level, this re-emitted photon is sent out in a random direction — not specifically towards the observer. The net effect is that photons of specific frequencies (corresponding to specific electron energy transitions) are removed from the continuous spectrum that the star's core emits, resulting in dark lines (absorption lines) at those wavelengths in the spectrum we observe.`,
  "phys-edexcel-9ph0-2023-p2::17(b)(ii)": `First find the peak wavelength from Wien's law, λ(max)T = 2.898 × 10⁻³ m K:
λ(max) = 2.898 × 10⁻³ m K / 5800 K = 5.0 × 10⁻⁷ m = 0.50 μm

Draw a single smooth black-body curve on the axes:
• start at the origin, with the intensity exactly zero when the wavelength is zero;
• rise steeply to one maximum at a wavelength of 0.50 μm, i.e. half way to the '1' marked on the wavelength axis;
• then fall away much more gradually on the long-wavelength side, getting closer and closer to the wavelength axis without ever meeting it again.

The curve must be clearly asymmetric: steeper on the short-wavelength side of the peak than on the long-wavelength side, so that at every intensity it is narrower to the left of the peak than to the right. It should be one continuous smooth line, with no absorption lines drawn on it.`,
  "phys-edexcel-9ph0-2023-p2::17(b)(iii)": `In main sequence stars, the outward radiation pressure (and gas pressure) from nuclear fusion reactions in the core exactly balances the inward gravitational force due to the star's own mass. The energy released by nuclear fusion (hydrogen fusing into helium) provides sufficient outward pressure to prevent gravitational collapse. This is a state of hydrostatic equilibrium: the two opposing forces are balanced, so the star maintains a stable size.`,
  "phys-edexcel-9ph0-2023-p2::18(a)": `The image formed by a converging lens lies at the focal length of the lens only when the light reaching the lens is a parallel beam, because parallel rays are brought to a focus in the focal plane.

The same conclusion follows from 1/u + 1/v = 1/f: putting v = f gives 1/u = 1/f − 1/f = 0, so u is infinite.

The object being viewed must therefore be a very large distance away — effectively at infinity.`,
  "phys-edexcel-9ph0-2023-p2::18(b)": `Virtual: A virtual image is one that cannot be formed on a screen; the light rays appear to diverge from the image position but do not actually pass through it. The image is formed by extending diverging rays backwards (with dashed lines) to where they appear to meet.

Upright: An upright image is one that has the same orientation as the object — it is not inverted. The image appears the right way up relative to the object.`,
  "phys-edexcel-9ph0-2023-p2::18(c)": `The light travels from right to left, from the converging lens towards the eye, and the image I acts as the object for the diverging lens. Two rays are needed.

First ray: draw a straight line coming in from the top right, aimed at the centre of the diverging lens. It passes through the centre of the lens without being deviated, and continues down and to the left so that it passes exactly through the arrowhead of the image I.

Second ray: draw a straight line coming in from the right below the principal axis and parallel to it. At the lens it is refracted away from the axis, so that on the eye side it travels along the line that, extended back through the lens, passes through the focal point F marked on the right-hand side of the lens. In other words, rule a line from F through the point where the incoming ray meets the lens and continue it to the left of the lens.

Put an arrowhead on at least one of the emerging rays, pointing to the left towards the eye.

Because I is at the focal point of the diverging lens, the two rays leaving the lens are parallel to each other, so the final image is at infinity and is virtual and upright — which is what the eye sees through this telescope.`,
  "phys-edexcel-9ph0-2023-p2::18(d)": `For a Galilean telescope: magnification M = f_objective / f_eyepiece (where f_eyepiece is the focal length of the diverging lens, taken as negative, but magnitude used here).

The distance between the lenses = f_objective − |f_eyepiece| (for a Galilean telescope, since the eyepiece is inside the focal point of the objective).

Let f_c = focal length of converging lens, f_d = focal length of diverging lens (magnitude).
M = f_c / f_d = 10
f_c − f_d = 90 cm

From M = 10: f_c = 10 f_d
Substituting: 10 f_d − f_d = 90
9 f_d = 90
f_d = 10 cm
f_c = 100 cm

Focal length of converging lens = 100 cm; focal length of diverging lens = 10 cm.`,
  "phys-edexcel-9ph0-2023-p2::18(e)": `Ganymede's orbital data:
Orbital radius: r = 1.07 × 10⁶ km = 1.07 × 10⁹ m
Orbital period: T = 171 hours = 171 × 3600 s = 615 600 s

Using Newton's law of gravitation and circular motion:
GM_J / r² = (4π²r) / T²

So M_J = (4π²r³) / (GT²)

M_J = (4π² × (1.07 × 10⁹)³) / (6.67 × 10⁻¹¹ × (615 600)²)

Numerator: 4π² × (1.07)³ × 10²⁷ = 4 × 9.870 × 1.2250 × 10²⁷ = 48.34 × 10²⁷ = 4.834 × 10²⁸

Denominator: 6.67 × 10⁻¹¹ × (615 600)² = 6.67 × 10⁻¹¹ × 3.790 × 10¹¹ = 6.67 × 3.790 = 25.27

M_J = 4.834 × 10²⁸ / 25.27 = 1.91 × 10²⁷ kg`,
  "phys-edexcel-9ph0-2023-p3::1(a)": `Using the diffraction grating equation: d sinθ = nλ

Grating: 300 lines per mm, so d = 1/300 mm = 3.33 × 10⁻³ mm = 3.33 × 10⁻⁶ m
λ = 520 nm = 520 × 10⁻⁹ m

For first order (n = 1): sinθ = λ/d = (520 × 10⁻⁹)/(3.33 × 10⁻⁶) = 0.1561
θ = arcsin(0.1561) = 8.97°

Expected x (distance from central maximum to first-order maximum):
tan θ = x/D
x = D tan θ = 2.75 × tan(8.97°) = 2.75 × 0.1579 = 0.434 m = 43.4 cm

The measured value of x = 43.5 cm.

The expected value (43.4 cm) is very close to the measured value (43.5 cm). The difference is only 0.1 cm, which is within the precision of the metre rule (0.1 cm). Therefore the spacing of the diffraction pattern is consistent with d = 3.33 × 10⁻⁶ m and λ = 520 nm.`,
  "phys-edexcel-9ph0-2023-p3::1(b)": `The student has used the wrong word for the instrument and has confused two different ideas.

A metre rule has a resolution of 0.1 cm — that is the smallest division on its scale — rather than a "precision" of 0.1 cm.

Precision describes how closely together repeated readings of the same quantity lie, whereas accuracy describes how close a measured value is to the true value. Being able to read the rule to 0.1 cm therefore says nothing on its own about how accurate the value of x is.

The measurement could still contain a systematic error that shifts every reading away from the true value — for example a zero error at the end of the rule, or parallax in reading the scale — and it is difficult to judge exactly where the centre of a diffraction maximum lies. The conclusion that x was determined "with a high degree of accuracy" is therefore not justified.`,
  "phys-edexcel-9ph0-2023-p3::2(a)": `The bulb operates normally at 12 V and 40 W, so its resistance is

R = V²/P = (12 V)² / 40 W = 3.6 Ω

With the switch open, bulb 1 and the internal resistance are in series across the e.m.f., so the sum of the e.m.f.s equals the sum of the p.d.s:

12 V = I × (3.6 Ω + 0.50 Ω)
I = 12 V / 4.1 Ω = 2.93 A

Terminal p.d. = p.d. across the bulb = IR = 2.93 A × 3.6 Ω = 10.5 V

(Equivalently V = ε − Ir = 12 V − 2.93 A × 0.50 Ω = 10.5 V.)

Terminal p.d. of battery = 10.5 V`,
  "phys-edexcel-9ph0-2023-p3::2(b)": `When the switch is closed, bulb 2 is connected in parallel with bulb 1. The parallel combination of bulb 1 and bulb 2 has a lower combined resistance than bulb 1 alone.

With a lower external resistance, the total circuit resistance (R_parallel + r) decreases, so the total current drawn from the battery increases.

A larger current flows through the internal resistance, so the lost volts (Ir) increase, meaning the terminal voltage of the battery decreases.

Although more current flows from the battery, less current flows through bulb 1 (because the terminal voltage is lower, and V = I₁R₁, so I₁ = V_terminal/R₁ which is lower than before). Therefore, bulb 1 becomes dimmer when the switch is closed.`,
  "phys-edexcel-9ph0-2023-p3::3(a)": `The milliammeter is not in series with the heater. It is in the branch containing the supply and the variable resistor, so it measures the total current drawn from the supply rather than the current in the heater; it should be connected in series with the heater itself.

The meter is also a milliammeter, so its range is far too small: the student intends to use currents of up to 5 A, which is thousands of times its full-scale deflection, so the meter would simply be overloaded. An ammeter reading to at least 5 A is needed.`,
  "phys-edexcel-9ph0-2023-p3::3(b)(i)": `Label the vertical axis "reading on balance / g" and the horizontal axis "time / s".

Draw a single straight line sloping downwards from left to right, i.e. with a constant negative gradient: the heater transfers energy at a constant rate once the water is boiling, so water is vaporised at a constant rate and the reading on the balance falls steadily.

The line must not meet the time axis — only a few grams of water boil away, so the balance still reads a large positive value (the beaker, heater and remaining water) at the end of the measurements.`,
  "phys-edexcel-9ph0-2023-p3::3(b)(ii)": `Energy supplied by heater: E = VIt = 12 × 4.2 × (6.0 × 60) = 12 × 4.2 × 360 = 18 144 J

Mass of water evaporated: m = 7.5 g = 7.5 × 10⁻³ kg

Specific latent heat: L = E/m = 18 144 / (7.5 × 10⁻³) = 2.42 × 10⁶ J kg⁻¹`,
  "phys-edexcel-9ph0-2023-p3::3(b)(iii)": `A significant source of error is heat loss to the surroundings. Not all the electrical energy supplied by the heater goes into evaporating the water — some energy is lost to the surrounding air by convection and radiation from the surface of the beaker and the water. This means the energy available to vaporise the water is less than the electrical energy input (VIt). As a result, the calculated value of L (= VIt/m) is an overestimate of the true specific latent heat, because the measured mass change m is smaller than it would be if all the electrical energy went into vaporisation. This makes L larger than the true value.`,
  "phys-edexcel-9ph0-2023-p3::4": `Evidence from Geiger-Marsden (Rutherford scattering) experiments using alpha particles fired at thin gold foil supports the nuclear model in several ways:

Most alpha particles passed straight through the foil with little or no deflection. This shows that atoms are mostly empty space — the nuclear model has a tiny, dense nucleus occupying only a small fraction of the atom's volume, with most of the atom being empty, through which alpha particles pass undeflected.

A small fraction of alpha particles were deflected through large angles (greater than 90°). This shows that within the atom there is a very small, highly concentrated region of positive charge (the nucleus). When an alpha particle (also positively charged) travels close to this concentrated positive charge, the large electrostatic repulsion causes significant deflection. If charge were spread uniformly throughout the atom (as in the Thomson 'plum pudding' model), the repulsive force would be too weak and diffuse to cause large-angle deflections.

A very small number of alpha particles were deflected almost straight back (close to 180°). This shows the nucleus is not only very small but also very massive — the alpha particle bounced back off a target much more massive than itself, similar to a ball bouncing off a heavy wall. This rules out a model where positive charge is spread throughout the atom.

The proportion of particles deflected at each angle is consistent with a Coulomb repulsion from a point (nuclear) charge. Analysis of the scattering distribution allowed Rutherford to estimate the size of the nucleus (~10⁻¹⁴ m), which is much smaller than the atom (~10⁻¹⁰ m), supporting the nuclear model with a concentrated central nucleus.`,
  "phys-edexcel-9ph0-2023-p3::5(a)(i)": `One advantage of using a reference wire alongside the test wire is that it compensates for any changes in temperature during the experiment. Both wires are made of the same material and are in the same environment, so any thermal expansion (which would change the length and thus the reading) affects both wires equally. Differences in readings between the two wires are therefore due to the applied load only, not to temperature changes.`,
  "phys-edexcel-9ph0-2023-p3::5(a)(ii)": `A reference load was applied to the reference wire to keep it taut and under a constant tension. This ensures the reference wire is straight and does not sag, so that the vernier scale (measuring the difference in extension between the two wires) gives an accurate reading. Without a reference load, the reference wire might sag unevenly, introducing errors into the measurement of extension.`,
  "phys-edexcel-9ph0-2023-p3::5(b)": `For a given load, a thin wire has a small cross-sectional area, so the stress F/A in it is large.

For a given stress, a long wire gives a large extension, because the extension Δx = ε × x is proportional to the original length x of the wire.

Making the wire both long and thin therefore produces the largest possible extension for the loads available. The extension is read from the vernier scale with a fixed absolute uncertainty, so the larger the extension, the smaller the percentage uncertainty in Δx and hence in the value obtained for the Young modulus.`,
  "phys-edexcel-9ph0-2023-p3::5(c)": `Cross-sectional area of the test wire:

A = πd²/4 = π × (5.60 × 10⁻⁴ m)² / 4 = 2.46 × 10⁻⁷ m²

The Young modulus is

E = σ/ε = (F/A) / (Δx/x) = (F/Δx) × (x/A)

The graph is of Δx against F, so its gradient is Δx/F and therefore E = (1/gradient) × (x/A).

Using a large triangle on the best-fit line, between the points (5 N, 0.75 mm) and (32.0 N, 3.6 mm):

gradient = (3.6 − 0.75) × 10⁻³ m / (32.0 − 5) N = 1.06 × 10⁻⁴ m N⁻¹

E = (1 / 1.06 × 10⁻⁴ m N⁻¹) × (2.75 m / 2.46 × 10⁻⁷ m²)

Young modulus of brass = 1.1 × 10¹¹ N m⁻² (1.1 × 10¹¹ Pa)`,
  "phys-edexcel-9ph0-2023-p3::6(a)": `Instead of timing a single oscillation, she should time a large number of complete oscillations — say 20 — and divide the total time by the number of oscillations. The uncertainty caused by her reaction time is then spread over many periods, so the percentage uncertainty in T is much smaller.

She should repeat the timing several times and take a mean, which reduces the effect of random errors.

She should set up a fiducial marker, such as a pointer or a mark on the bench at the equilibrium position, so that it is easier to judge exactly when the trolley passes a fixed point.

She should start and stop the stopwatch as the trolley passes this mid-point, where the trolley is moving fastest and the timing error is smallest, and allow the oscillations to settle down before starting to time.`,
  "phys-edexcel-9ph0-2023-p3::6(b)": `One complete cycle of the trace occupies 2 divisions, and the time-base is 250 ms div⁻¹, so

T = 2 div × 250 ms div⁻¹ = 500 ms = 0.50 s

Angular frequency: ω = 2π/T = 2π / 0.50 s = 12.6 rad s⁻¹

For simple harmonic motion v = −Aω sin ωt, so the maximum speed is v = Aω, with amplitude A = 6.0 cm = 6.0 × 10⁻² m:

v = 6.0 × 10⁻² m × 12.6 rad s⁻¹ = 0.754 m s⁻¹

Maximum velocity of trolley = 0.75 m s⁻¹`,
  "phys-edexcel-9ph0-2023-p3::6(c)(i)": `As the driving frequency is increased from zero the amplitude of the trolley's oscillations grows, rises to a sharp maximum of about 5.0 cm at a driving frequency of 2.0 Hz, and then falls away again at higher frequencies.

2.0 Hz is the natural frequency of the trolley-and-springs system.

When the vibrator drives the trolley at its natural frequency the driving force stays in step with the motion of the trolley, so the rate at which energy is transferred from the vibrator to the trolley is a maximum and the amplitude builds up to its largest value.

This is resonance. At frequencies well above or below 2.0 Hz the driver and the trolley are out of step, so much less energy is transferred each cycle and the amplitude is small; damping of the system keeps the peak amplitude finite.`,
  "phys-edexcel-9ph0-2023-p3::6(c)(ii)": `The amplitude is a maximum at a driving frequency of 2.0 Hz, so this is the natural frequency of the system and the natural period is

T = 1/f = 1/2.0 Hz = 0.50 s

For a mass oscillating on springs, T = 2π√(m/k), so

k = 4π²m/T² = 4π² × 0.87 kg / (0.50 s)² = 137 N m⁻¹

k = 140 N m⁻¹ (2 s.f.)`,
  "phys-edexcel-9ph0-2023-p3::7(a)": `When there is an electric current between the electrodes, free electrons in the external circuit are accelerated through the potential difference between the electrodes. These electrons collide with neon atoms in the gas between the electrodes.

In these collisions, electrons transfer energy to the neon atoms, exciting (raising) the orbital electrons in the neon atoms from their ground state to higher energy levels. This process is called electron excitation.

The excited neon atoms are unstable in these higher energy states. After a very short time (of the order of nanoseconds), the excited electrons fall back down to lower energy levels (including the ground state), releasing the excess energy as photons of electromagnetic radiation.

The energy of each photon emitted equals the energy difference between the two levels: E = hf = E₂ − E₁. Because neon has a specific set of discrete energy levels, only photons of specific frequencies (and hence wavelengths) are emitted — producing the characteristic line emission spectrum of neon, including visible light wavelengths that are emitted as electromagnetic radiation.`,
  "phys-edexcel-9ph0-2023-p3::7(b)": `Using the photoelectric equation: hf = φ + ½mv²_max

Energy of photon: E = hf = 6.63 × 10⁻³⁴ × 5.56 × 10¹⁴ = 3.686 × 10⁻¹⁹ J

Maximum KE of electrons: ½mv²_max = ½ × 9.11 × 10⁻³¹ × (2.68 × 10⁵)²
= ½ × 9.11 × 10⁻³¹ × 7.182 × 10¹⁰
= 3.271 × 10⁻²⁰ J

Work function: φ = hf − ½mv²_max
= 3.686 × 10⁻¹⁹ − 3.271 × 10⁻²⁰
= 3.686 × 10⁻¹⁹ − 0.3271 × 10⁻¹⁹
= 3.359 × 10⁻¹⁹ J

Comparing with the table:
Caesium: 3.36 × 10⁻¹⁹ J
Potassium: 3.68 × 10⁻¹⁹ J
Sodium: 3.84 × 10⁻¹⁹ J

The calculated work function (3.359 × 10⁻¹⁹ J) matches caesium (3.36 × 10⁻¹⁹ J) most closely.

The light is incident upon caesium.`,
  "phys-edexcel-9ph0-2023-p3::8(a)": `For a capacitor discharging through a resistor, V = V₀e^(−t/RC), so ln(V/V₀) = −t/RC.

Reading a corresponding pair of values from the graph: V₀ = 6.0 V at t = 0, and V = 1.0 V at t = 40 s.

ln(1.0 V / 6.0 V) = −40 s / (82 × 10³ Ω × C)
−1.79 = −40 s / (82 × 10³ Ω × C)
C = 40 s / (1.79 × 82 × 10³ Ω) = 2.7 × 10⁻⁴ F = 270 μF

The capacitor is marked 220 μF ± 20%, so the stated range is

largest value = 1.20 × 220 μF = 264 μF
smallest value = 0.80 × 220 μF = 176 μF

The value from the student's data, 270 μF, is greater than 264 μF, so it lies just outside the stated range: her data do not give a capacitance within the marked tolerance.`,
  "phys-edexcel-9ph0-2023-p3::8(b)": `The time constant of this circuit is only about 20 s, so all the readings have to be taken in a short time. A data logger has a high sampling rate, so it can record far more pairs of V and t, and at far more regular intervals, than the student can manage by hand.

Reading the voltmeter and the stopwatch at exactly the same instant is very difficult, and her reaction time introduces a random error into every pair of readings; a data logger removes this problem completely because it records V and t simultaneously.

The student's suggestion is therefore correct: the data logger would give more, and more reliable, points for the graph and hence a more accurate value for the capacitance.`,
  "phys-edexcel-9ph0-2023-p3::9(a)(i)": `The oil drop is positively charged and is at rest, so the electric force on it must act vertically upwards to balance its weight. The force on a positive charge acts in the direction of the electric field, so the field must point upwards, from the bottom plate towards the top plate.

On the diagram, mark the bottom plate (or the bottom terminal of the power supply) positive, and the top plate (or top terminal) negative.`,
  "phys-edexcel-9ph0-2023-p3::9(a)(ii)": `At equilibrium (oil drop stationary): electric force = weight
qE = mg

Where E = V/d (uniform field between parallel plates):
q = mgd/V

Given:
- V = 4870 V
- d = 1.55 cm = 1.55 × 10⁻² m
- ρ_oil = 920 kg m⁻³
- r = 1.78 × 10⁻⁶ m

Mass of oil drop: m = ρ × (4/3)πr³ = 920 × (4/3)π × (1.78 × 10⁻⁶)³
= 920 × 4.189 × (5.640 × 10⁻¹⁸)
= 920 × 2.363 × 10⁻¹⁷
= 2.174 × 10⁻¹⁴ kg

Weight: mg = 2.174 × 10⁻¹⁴ × 9.81 = 2.133 × 10⁻¹³ N

Charge: q = mgd/V = (2.133 × 10⁻¹³ × 1.55 × 10⁻²) / 4870
= (3.306 × 10⁻¹⁵) / 4870
= 6.79 × 10⁻¹⁹ C

Dividing by e = 1.60 × 10⁻¹⁹ C:
n = 6.79 × 10⁻¹⁹ / 1.60 × 10⁻¹⁹ = 4.24

This is close to a whole number (4) but not exactly. The expected charge is a whole-number multiple of e, so q should be ≈ 4 × 1.60 × 10⁻¹⁹ = 6.40 × 10⁻¹⁹ C. The calculated value (6.79 × 10⁻¹⁹ C) is approximately 4e within the uncertainty of the measurement. Given the experimental uncertainties (particularly in measuring the radius r, since m ∝ r³, a small error in r causes a large error in m), this is broadly consistent with 4 electrons' worth of charge. The student's expectation is approximately confirmed, with n ≈ 4.`,
  "phys-edexcel-9ph0-2023-p3::9(b)(i)": `When the power supply is disconnected, the oil drop begins to fall under gravity. Initially the drop may not yet be moving at terminal velocity — it must accelerate from rest until the viscous drag force equals its weight. The student should wait until the drop has reached terminal velocity (i.e., constant velocity) before beginning to measure its speed. If measurements are taken too soon, the drop is still accelerating and the measured velocity will be less than the terminal velocity, giving an inaccurate result for the weight calculation.`,
  "phys-edexcel-9ph0-2023-p3::9(b)(ii)": `Read the two positions of the drop from the millimetre scale in the microscope view: the drop starts at 2.50 mm and finishes at 6.65 mm, so the distance fallen is

s = 6.65 mm − 2.50 mm = 4.15 mm = 4.15 × 10⁻³ m

The time interval is t = 120 s, so

v = s/t = 4.15 × 10⁻³ m / 120 s = 3.46 × 10⁻⁵ m s⁻¹

Terminal velocity = 3.5 × 10⁻⁵ m s⁻¹`,
  "phys-edexcel-9ph0-2023-p3::9(c)": `The tallest bars in the chart are at 1.6, 3.2, 4.8, 6.4 and 8.0 × 10⁻¹⁹ C. These are exactly 1e, 2e, 3e, 4e and 5e with e = 1.6 × 10⁻¹⁹ C, so the charges do tend to cluster at whole-number multiples of the charge on an electron, as the student predicted.

However, those five bars contain only 5 + 4 + 6 + 5 + 4 = 24 of the 50 drops. The remaining 26 drops — just over half of them — have charges that are not whole-number multiples of e, and there are drops in almost every interval across the chart.

The bar chart therefore supports the prediction only partly: the peaks fall where the student predicts, but with fewer than half of the drops at integer multiples of e the evidence is inconclusive. The spread of the other values suggests a large experimental uncertainty in each calculated charge, mainly because the charge depends on the cube of the measured radius of the drop.`,
  "phys-edexcel-9ph0-2023-p3::10(a)(i)": `Using T = 2π√(l/g):

T = 2.50 s

Rearranging: l = g(T/2π)² = 9.81 × (2.50/(2π))² = 9.81 × (0.3979)² = 9.81 × 0.1583 = 1.553 m

l ≈ 1.55 m`,
  "phys-edexcel-9ph0-2023-p3::10(a)(ii)": `The amplitude of oscillation did not stay constant because the pendulum experiences resistive (damping) forces as it oscillates. Air resistance (drag) acts on the bob and string, opposing the motion. This resistive force removes energy from the oscillating system, converting kinetic and potential energy into thermal (heat) energy in the air and the string. As energy is removed, the amplitude decreases over time — this is called damping. With each successive swing, slightly less energy remains in the system, so the pendulum swings through a smaller angle.`,
  "phys-edexcel-9ph0-2023-p3::10(b)(i)": `The relationship is A = A₀ e^(−kt/T).

Taking the natural logarithm of both sides:
ln A = ln A₀ − kt/T

This is of the form y = c + mx (where y = ln A, x = t, c = ln A₀, and m = −k/T).

Since ln A₀ and k/T are both constants, ln A is a linear function of t. Therefore a graph of ln A against t gives a straight line, with y-intercept = ln A₀ and gradient = −k/T.`,
  "phys-edexcel-9ph0-2023-p3::10(b)(ii)": `Process the data by calculating ln(A/cm) for each value of A, giving every value to the same number of decimal places (3 d.p. here):

t/s: 2.5, 5.0, 7.5, 10.0, 12.5
A/cm: 17.6, 14.3, 11.6, 9.4, 7.6
ln(A/cm): 2.868, 2.660, 2.451, 2.241, 2.028

Plot ln(A/cm) on the vertical axis against t on the horizontal axis, labelling the axes "ln (A/cm)" (no unit) and "t/s".

Choose sensible scales that spread the points over more than half of each axis — for example 2.5 s per large square on the t axis starting at t = 0, and 0.10 per large square on the ln(A/cm) axis running from 2.00 up to about 3.10. Starting the t axis at zero and allowing room above 2.87 lets the line be extended back to the intercept needed in part (b)(iii).

Plot each point to within half a small square and draw a single thin straight best-fit line through them; the points lie very close to a straight line of negative gradient.`,
  "phys-edexcel-9ph0-2023-p3::10(b)(iii)": `From the graph of ln A against t:

Gradient = (Δ ln A)/(Δt) = (2.028 − 2.867)/(12.5 − 2.5) = −0.839/10.0 = −0.0839 s⁻¹

Since gradient = −k/T and T = 2.50 s:
k = −gradient × T = 0.0839 × 2.50 = 0.210

Y-intercept: when t = 0, ln A = ln A₀.
Extrapolating the best-fit line to t = 0:
ln A₀ = 2.867 − (gradient × 2.5) = 2.867 + 0.0839 × 2.5 = 2.867 + 0.210 = 3.077
(Or read directly from the y-axis intercept of the best-fit line.)

A₀ = e^3.077 = 21.7 cm ≈ 22 cm

So: A₀ ≈ 22 cm and k ≈ 0.21`,
  "phys-edexcel-9ph0-2023-p3::11(a)": `A half metre rule has a resolution of 1 mm.

That is acceptable for the diameters, which are several centimetres, but it is not suitable for measuring the thickness t, which is only about 4 mm: an uncertainty of at least ±0.5 mm in a reading of 4 mm is a percentage uncertainty of more than 10%, which is far too large when this value is used to find the volume.

She should measure the washer with vernier callipers, which have a resolution of 0.1 mm, or better with digital callipers or a micrometer, which have a resolution of 0.01 mm; the percentage uncertainty in t would then be well below 1%.`,
  "phys-edexcel-9ph0-2023-p3::11(b)": `To obtain a more accurate mean value for t (the thickness of a washer):

The student should measure the thickness of all five washers together in a stack, then divide by 5 to get the mean thickness per washer. This means only one pair of readings is taken across the stack of 5 washers, so the absolute uncertainty in the total thickness (from the instrument's precision) is spread across 5 washers, giving a much smaller uncertainty per washer.

For example, if the uncertainty in a single thickness measurement is ±0.05 mm, measuring a stack of 5 gives an uncertainty of ±0.05 mm in the total of 5t, so the uncertainty per washer is ±0.01 mm — 5 times smaller than measuring individually.`,
  "phys-edexcel-9ph0-2023-p3::11(c)(i)": `The area formula is A = (π/4)(d₁ + d₂)(d₁ − d₂).

Let u = d₁ + d₂ and v = d₁ − d₂.
Then A = (π/4)uv.

Percentage uncertainty in u = (d₁ + d₂):
Δu = √(Δd₁² + Δd₂²) = √(0.02² + 0.02²) = √(0.0008) = 0.0283 cm
(or using addition in quadrature; simpler: Δu = 0.02 + 0.02 = 0.04 cm for worst case)
%u = 0.04/(4.52 + 2.53) × 100% = 0.04/7.05 × 100% = 0.57%

Percentage uncertainty in v = (d₁ − d₂):
Δv = 0.02 + 0.02 = 0.04 cm
%v = 0.04/(4.52 − 2.53) × 100% = 0.04/1.99 × 100% = 2.01%

Percentage uncertainty in A = %u + %v = 0.57% + 2.01% = 2.58% ≈ 3% ✓

The dominant source of uncertainty is in (d₁ − d₂), since it is a small difference of two nearly equal quantities.`,
  "phys-edexcel-9ph0-2023-p3::11(c)(ii)": `Mean thickness:

t = (4.3 + 4.2 + 4.1 + 3.9 + 4.0) mm / 5 = 4.1 mm = 0.41 cm

Percentage uncertainty in t, using half the range:

% U = [(4.3 − 3.9)/2] mm / 4.1 mm × 100% = 0.20/4.1 × 100% = 4.9%

Area of a washer:

A = (π/4)(d₁ + d₂)(d₁ − d₂) = (π/4) × 7.05 cm × 1.99 cm = 11.0 cm²

Volume: V = A × t = 11.0 cm² × 0.41 cm = 4.52 cm³

Density: ρ = m/V = 32.0 g / 4.52 cm³ = 7.08 g cm⁻³

The uncertainty in the mass is negligible, so the percentage uncertainty in ρ is the percentage uncertainty in A plus that in t:

% U in ρ = 2.6% + 4.9% = 7.5%

Maximum density = 1.075 × 7.08 = 7.61 g cm⁻³
Minimum density = 0.925 × 7.08 = 6.55 g cm⁻³

Iron, at 6.9 g cm⁻³, lies within this range, but steel, at 7.9 g cm⁻³, does not. The washers are therefore made from iron.`,
  "phys-edexcel-9ph0-2024-p1::11(a)": `The moment of a force about a point is the product of the force and the perpendicular distance from the point to the line of action of the force.`,
  "phys-edexcel-9ph0-2024-p1::11(b)": `Taking moments about the pivot:

First, define positions relative to the centre of the bus (length 11.0 m).
Let y = distance of pivot from centre of bus.

The centre of mass of the gold bars is 1.5 m from one end, so (5.5 − 1.5) = 4.0 m from the centre, on the left side (say).
The centre of mass of the bank robbers is 1.0 m from the other end, so (5.5 − 1.0) = 4.5 m from the centre, on the right side.

For the bus to be balanced, clockwise moments = anticlockwise moments about the pivot.

Taking the pivot as reference, let the gold-bar end be to the left:
- Distance from pivot to gold bars = (4.0 − y)
- Distance from pivot to bank robbers = (4.5 + y)
- The bus weight acts at its centre of mass, which is at distance y from the pivot (since bus is uniform)

Clockwise moments (gold side):
Moment of gold bars = 31000 × (4.0 − y)

Anticlockwise moments (robber side):
Moment of bank robbers = 8700 × (4.5 + y)
Moment of bus weight = 32000 × y

Setting clockwise = anticlockwise:
31000(4.0 − y) = 8700(4.5 + y) + 32000y
124000 − 31000y = 39150 + 8700y + 32000y
124000 − 39150 = 8700y + 32000y + 31000y
84850 = 71700y
y = 84850 / 71700
y = 1.18 m ≈ 1.2 m

The pivot is 1.2 m from the centre of the bus (towards the gold-bar end).`,
  "phys-edexcel-9ph0-2024-p1::12": `Step 1: Calculate the resistance of the cable.
Cross-sectional area: A = π(d/2)² = π × (0.075)² = 1.767 × 10⁻² m²
Resistance: R = ρL/A = (1.7 × 10⁻⁸ × 720 × 10³) / (1.767 × 10⁻²)
R = 12240 / (1.767 × 10⁻²) = 0.693 Ω ≈ 0.693 Ω

Step 2: Calculate the current transmitted.
P = VI → I = P/V = (1400 × 10⁶) / (1100 × 10³) = 1273 A

Step 3: Calculate the power dissipated in the cable.
P_loss = I²R = (1273)² × 0.693 = 1.620 × 10⁶ × 0.693 = 1.12 × 10⁶ W ≈ 1.12 MW

Step 4: Calculate efficiency.
Efficiency = (P_transmitted − P_loss) / P_transmitted × 100
= (1400 − 1.12) / 1400 × 100 = 1398.88 / 1400 × 100 ≈ 99.92%

This is very close to 100%, so the claim that efficiency is almost 100% is correct. The power loss in the cable is only about 1.12 MW out of 1400 MW transmitted, which is less than 0.1% — consistent with the website's claim.`,
  "phys-edexcel-9ph0-2024-p1::13(a)": `Using E = mc², the rest mass energy of a proton:
m_p = 1.673 × 10⁻²⁷ kg
E = m_p c² = 1.673 × 10⁻²⁷ × (3.00 × 10⁸)² = 1.506 × 10⁻¹⁰ J

Convert to MeV: E = 1.506 × 10⁻¹⁰ / (1.60 × 10⁻¹³) = 941 MeV

An antiproton has the same rest mass as a proton (particles and antiparticles have equal rest mass).

Therefore the rest mass energy of an antiproton ≈ 941 MeV.
In units of MeV/c²: rest mass ≈ 941 MeV/c² ≈ 900 MeV/c² (to 1 sig. fig.).

This confirms the rest mass of an antiproton is about 900 MeV/c².`,
  "phys-edexcel-9ph0-2024-p1::13(b)": `Check conservation laws for: p + p → p + p + p + p̄

1. Conservation of charge:
Left side: +1 + 1 = +2
Right side: +1 + 1 + 1 + (−1) = +2 ✓

2. Conservation of baryon number:
Left side: 1 + 1 = 2
Right side: 1 + 1 + 1 + (−1) = 2 ✓ (antiproton has baryon number −1)

3. Conservation of lepton number:
No leptons involved on either side: 0 = 0 ✓

4. Conservation of energy/mass:
Left side: 2 proton rest masses + kinetic energy available.
Minimum energy needed = rest mass energy of the extra p + p̄ produced = 2 × 941 MeV ≈ 1882 MeV of kinetic energy required.
This can be supplied by sufficiently energetic protons.

All conservation laws are satisfied, so it is possible to produce an antiproton in this way, provided the colliding protons have sufficient kinetic energy (at least ~1882 MeV between them in the centre-of-mass frame).`,
  "phys-edexcel-9ph0-2024-p1::14(a)": `All leptons are fundamental particles — they have no internal structure and are not made up of quarks.

They all have a baryon number of zero and a lepton number that is not zero (+1 for a lepton, −1 for its antiparticle), and this lepton number is conserved in every interaction.`,
  "phys-edexcel-9ph0-2024-p1::14(b)": `μ⁺ → e⁺ + νₑ + ν̅μ

Charge: +1 → (+1) + 0 + 0
Electron lepton number: 0 → (−1) + (+1) + 0
Muon lepton number: −1 → 0 + 0 + (−1)

so charge and both lepton numbers are conserved.`,
  "phys-edexcel-9ph0-2024-p1::14(c)": `A magnetic field is applied perpendicular to the plane of the detector. The Lorentz force (F = Bqv) acts on any moving charged particle, causing it to travel in a circular arc. The radius of curvature of the arc is related to the momentum of the particle by r = p/(Bq), so by measuring the radius of curvature of the track, the momentum of the particle can be determined. The direction of curvature (curving left or right) indicates the sign of the charge of the particle, since positive and negative charges curve in opposite directions in the same field.`,
  "phys-edexcel-9ph0-2024-p1::14(d)": `The positron track leaves the decay point in a different direction from the direction in which the muon was travelling, and the two tracks have different radii of curvature in the detector's magnetic field.

Since the radius of a charged particle's circular path is given by r = p/BQ, a different radius and a different direction mean that the positron's momentum is different, in both magnitude and direction, from the momentum the muon had just before it decayed.

Momentum must be conserved in the decay, so the vector sum of the momenta of all the particles produced has to equal the momentum of the muon. The positron on its own cannot account for it.

Therefore at least one further particle must have been produced, carrying away the missing momentum. These particles leave no tracks because they are uncharged, so they do not ionise the detector.`,
  "phys-edexcel-9ph0-2024-p1::15(a)(i)": `Draw at least three straight horizontal lines in the gap between the plates. They must be parallel to one another, equally spaced, and run from one plate to the other meeting each plate at right angles, because the field between parallel plates is uniform.

Put an arrowhead on each line pointing to the right, that is from the positive left-hand plate towards the negative right-hand plate, to show the direction of the field.`,
  "phys-edexcel-9ph0-2024-p1::15(a)(ii)": `The gap between the plates is filled with air, which is an insulator, so the circuit is not complete and no current is drawn from the power supply.

With no current there is no potential difference across the internal resistance of the supply — there are no 'lost volts' — so the terminal potential difference is equal to the e.m.f. The voltmeter, which is connected across the terminals, therefore indicates the e.m.f. of the power supply.`,
  "phys-edexcel-9ph0-2024-p1::15(b)(i)": `Using E = V/d, where E = 3.0 × 10⁶ V m⁻¹ and d = 2.0 mm = 2.0 × 10⁻³ m:

V = E × d = 3.0 × 10⁶ × 2.0 × 10⁻³ = 6000 V = 6.0 kV

The minimum potential difference across the plates for sparks to be created is 6000 V (6.0 kV).`,
  "phys-edexcel-9ph0-2024-p1::15(b)(ii)": `When sparks are produced, the air between the plates becomes conducting (ionised), providing a low-resistance path between the plates. This means a large current flows through this path and also through the internal resistance of the power supply. The significant current flowing through the internal resistance causes a large voltage drop across it (V = Ir). By Kirchhoff's voltage law, the terminal voltage (voltmeter reading) = e.m.f. − Ir, so the voltmeter reading decreases significantly. The supply cannot maintain the full e.m.f. at its terminals when such a large current is drawn.`,
  "phys-edexcel-9ph0-2024-p1::16(a)": `The bulb is labelled '1.5 V, 0.50 W', so when it is operating normally V = 1.5 V and P = 0.50 W.

Using P = V²/R:
R = V²/P = (1.5)² / 0.50 = 2.25 / 0.50 = 4.5 Ω

This is about 5 Ω, as stated.`,
  "phys-edexcel-9ph0-2024-p1::16(b)": `With the slider at A there is no length of the potentiometer track between A and the slider, so the potential difference across the filament bulb is zero. No current passes through the bulb and it is not lit.

As the slider is moved from A towards B, the resistance of the section of track between the slider and B (the section in series with the bulb) decreases, while the resistance of the section across which the bulb is connected increases. Because the total resistance of the potentiometer is very much larger than the resistance of the bulb, the bulb draws almost no current from the track, so the potentiometer behaves as an ideal potential divider: the 1.5 V from the supply is shared between the two sections in proportion to their resistances. The potential difference across the bulb therefore increases steadily as the slider moves towards B.

As the potential difference across the bulb rises, the current in it rises too, so the power dissipated in the filament increases and the bulb becomes brighter. The filament has to reach a high temperature before it glows visibly, so the bulb stays apparently dark over much of the travel and only lights noticeably as the slider approaches B.

When the slider reaches B the whole of the supply potential difference, 1.5 V, is across the bulb, the current is at its maximum and the bulb is operating normally at full brightness.

So the brightness increases continuously as the slider is moved from A to B, from zero at A to normal (maximum) brightness at B.`,
  "phys-edexcel-9ph0-2024-p1::16(c)": `The capacitor is initially uncharged, so at the instant the switch is closed the potential difference across the capacitor is zero and the whole of the 1.5 V supply potential difference is across the bulb. The current is therefore a maximum at the start, I = V/R = 1.5/5 = 0.3 A, and the bulb is lit at its brightest.

As charge flows onto the capacitor the potential difference across it rises, so the potential difference across the bulb falls and the current decreases. The bulb therefore becomes steadily dimmer.

The current, and hence the brightness, falls exponentially. The time constant of the circuit is RC = 5.0 Ω × 1.2 F = 6.0 s, so the bulb takes of the order of 30 s (about five time constants) to fade out, after which the capacitor is charged to 1.5 V and no current flows.`,
  "phys-edexcel-9ph0-2024-p1::17(a)": `Rutherford proposed that the atom consists of a very small, dense, positively charged nucleus at the centre, which contains most of the mass of the atom. The electrons orbit the nucleus at relatively large distances, so most of the atom is empty space. The nucleus is very small compared to the overall size of the atom (the nuclear radius is of order 10⁻¹⁵ m while the atomic radius is of order 10⁻¹⁰ m). The positive charge of the nucleus is equal in magnitude to the total negative charge of the orbiting electrons, so the atom is overall neutral.`,
  "phys-edexcel-9ph0-2024-p1::17(b)(i)": `At the point of closest approach, all the kinetic energy of the alpha particle has been converted to electrostatic potential energy.

Electrostatic potential energy at distance r:
Ep = kQ₁Q₂/r = (1/4πε₀) × (2e × 79e) / r

Using k = 8.99 × 10⁹ N m² C⁻²:
Ep = (8.99 × 10⁹ × 2 × 1.60 × 10⁻¹⁹ × 79 × 1.60 × 10⁻¹⁹) / (5.0 × 10⁻¹⁴)
= (8.99 × 10⁹ × 2 × 79 × (1.60 × 10⁻¹⁹)²) / (5.0 × 10⁻¹⁴)
= (8.99 × 10⁹ × 158 × 2.56 × 10⁻³⁸) / (5.0 × 10⁻¹⁴)
= (8.99 × 10⁹ × 4.045 × 10⁻³⁶) / (5.0 × 10⁻¹⁴)
= (3.636 × 10⁻²⁶) / (5.0 × 10⁻¹⁴)
= 7.27 × 10⁻¹³ J

This equals the initial kinetic energy of 7.3 × 10⁻¹³ J to 2 significant figures.

Since the calculated potential energy at 5.0 × 10⁻¹⁴ m (7.27 × 10⁻¹³ J) matches the initial kinetic energy (7.3 × 10⁻¹³ J), the textbook statement is correct.`,
  "phys-edexcel-9ph0-2024-p1::17(b)(ii)": `The alpha particle has mass m = 4u = 4 × 1.66 × 10⁻²⁷ = 6.64 × 10⁻²⁷ kg and initial kinetic energy Eₖ = 7.3 × 10⁻¹³ J.

Using Eₖ = p²/2m:
p = √(2mEₖ) = √(2 × 6.64 × 10⁻²⁷ × 7.3 × 10⁻¹³)
p = √(9.69 × 10⁻³⁹)
p = 9.9 × 10⁻²⁰ kg m s⁻¹`,
  "phys-edexcel-9ph0-2024-p1::17(c)(i)": `An elastic interaction is one in which both momentum and kinetic energy are conserved. No kinetic energy is converted to other forms (e.g., no excitation of internal energy, no radiation).`,
  "phys-edexcel-9ph0-2024-p1::17(c)(ii)": `The gold atoms recoil (are set into motion) as a result of the elastic collisions with the alpha particles. This means the atoms in the gold foil gain kinetic energy and vibrate more, but since the gold nucleus is very much more massive than the alpha particle, the recoil of each gold atom is very small. The gold atoms are not ionised or structurally changed by these elastic interactions.`,
  "phys-edexcel-9ph0-2024-p1::18(a)": `As the wheels of the train turn they rotate the coil in the magnetic field of the magnet, so the magnetic flux linking the coil is continually changing. By Faraday's law this rate of change of flux linkage induces an e.m.f. across the ends of the coil.

The ends of the coil are connected through the copper rings and the carbon blocks to the power transmission system, so there is a complete circuit and the induced e.m.f. drives an induced current back into the transmission system.

By Lenz's law the induced current is in the direction that opposes the change producing it. The current-carrying coil lies in the magnetic field, so it experiences a force (a couple) that acts to oppose its rotation.

This opposing torque is transmitted to the wheels, so the wheels do not turn as fast and the train slows down. The kinetic energy of the train is transferred to electrical energy in the transmission system instead of being wasted as heat in friction brakes.`,
  "phys-edexcel-9ph0-2024-p1::18(b)(i)": `Convert the speed to m s⁻¹:
360 km hour⁻¹ = 360 000 m / 3600 s = 100 m s⁻¹

From the speed–time graph the train reaches 360 km hour⁻¹ at a time of 450 s after starting from rest, and the graph is a straight line over this interval, so the acceleration is the gradient of the graph:

a = Δv/Δt = 100 m s⁻¹ / 450 s
a = 0.22 m s⁻²

(Equivalently, working in the units of the graph, a = 360 km hour⁻¹ ÷ (450/3600) hour = 2880 km hour⁻².)`,
  "phys-edexcel-9ph0-2024-p1::18(b)(ii)": `The distance travelled while the train accelerates to 360 km hour⁻¹ is the area under the speed–time graph up to t = 450 s. The graph is a straight line from the origin over this interval, so

s = ((u + v)/2) × t = ((0 + 100 m s⁻¹)/2) × 450 s
s = 50 × 450 = 22 500 m = 22.5 km

The specification requires the train to reach 360 km hour⁻¹ within 40 km of level track.

22.5 km is less than 40 km, so the performance of the train did meet the specification on this test run.`,
  "phys-edexcel-9ph0-2024-p1::18(c)(i)": `When a train travels on a curved track, it must follow a circular path. To maintain circular motion, a centripetal force must act on the train directed towards the centre of curvature of the track. This centripetal force is provided by the horizontal component of the contact (normal) force from the rails on the train's wheels (the rails push the train inward).

The required centripetal force is F = mv²/r. As speed increases, the required centripetal force increases. The maximum centripetal force the track can safely exert on the train is limited (by the strength of the rails, the friction between wheels and rails, and the risk of the train tipping or derailing). If the speed is too high, the required centripetal force exceeds what the track can provide, and the train may derail or tip over. Therefore there is a maximum safe speed that depends on the radius of curvature of the track.`,
  "phys-edexcel-9ph0-2024-p1::18(c)(ii)": `The centripetal force required is F = mv²/r. Assuming the maximum safe centripetal force is the same at both speeds (it is set by the track geometry/banking):

mv₁²/r₁ = mv₂²/r₂
v₁²/r₁ = v₂²/r₂
r₂ = r₁ × (v₂/v₁)²

v₁ = 200 km h⁻¹, r₁ = 1800 m
v₂ = 360 km h⁻¹

r₂ = 1800 × (360/200)² = 1800 × (1.8)² = 1800 × 3.24 = 5832 m ≈ 5800 m

The minimum safe radius of curvature for a speed of 360 km h⁻¹ is approximately 5800 m.`,
  "phys-edexcel-9ph0-2024-p2::11": `Using the diffraction grating equation: d sin θ = nλ

d = 1.67 × 10⁻⁶ m, θ = 73.3°, n = 3

λ = d sin θ / n = (1.67 × 10⁻⁶ × sin 73.3°) / 3

sin 73.3° = 0.9583

λ = (1.67 × 10⁻⁶ × 0.9583) / 3 = (1.600 × 10⁻⁶) / 3 = 5.33 × 10⁻⁷ m = 533 nm

The wavelength of the green light is 533 nm.`,
  "phys-edexcel-9ph0-2024-p2::12(a)(i)": `The threshold frequency is the minimum frequency of electromagnetic radiation that can cause the photoelectric effect from a particular metal surface. Below this frequency, no photoelectrons are emitted regardless of the intensity of the radiation.`,
  "phys-edexcel-9ph0-2024-p2::12(a)(ii)": `According to the wave theory of light, the energy delivered to the surface is spread continuously and depends on intensity (energy per unit area per unit time). A wave of any frequency, given sufficient intensity and time, should be able to supply enough energy to eject an electron — there should be no threshold frequency. However, experimentally a threshold frequency is observed, below which no electrons are emitted no matter how intense the radiation. This cannot be explained by wave theory and so is inconsistent with it.`,
  "phys-edexcel-9ph0-2024-p2::12(b)": `A photon is a discrete quantum (packet) of electromagnetic energy. The energy of a photon is E = hf, where h is the Planck constant and f is the frequency of the electromagnetic radiation. Photons have zero rest mass and travel at the speed of light.`,
  "phys-edexcel-9ph0-2024-p2::13": `Surface temperature from Wien's law:
T = 2.898 × 10⁻³ / 7.43 × 10⁻⁷ = 3900 K

Surface area: A = 4πr² = 4π × (3.14 × 10¹⁰)² = 1.24 × 10²² m²

Luminosity: L = σAT⁴ = 5.67 × 10⁻⁸ × 1.24 × 10²² × (3900)⁴

L = 1.63 × 10²⁹ W`,
  "phys-edexcel-9ph0-2024-p2::14(a)": `P = 1/f with f in metres:
P₁ = 1/0.10 m = 10 D
P₂ = 1/0.15 m = 6.7 D

For thin lenses in combination, P = P₁ + P₂ = 10 + 6.7 = 16.7 D ≈ 17 D, which is about 20 D.`,
  "phys-edexcel-9ph0-2024-p2::14(b)": `Using the lens equation with P_total ≈ 16.7 D (F = 6.0 cm = 0.060 m) and object distance u = −4 cm = −0.04 m (using sign convention where distances are measured from the lens, object on left is negative):

1/v − 1/u = 1/f
1/v = 1/f + 1/u = 1/0.06 + 1/(−0.04)
= 16.67 − 25.0 = −8.33 m⁻¹
v = 1/(−8.33) = −0.12 m = −12 cm

The image distance is −12 cm (i.e., 12 cm on the same side as the object — a virtual image).`,
  "phys-edexcel-9ph0-2024-p2::14(c)": `Linear magnification: m = v/u = (−0.12)/(−0.04) = 3.0

Image height = m × object height = 3.0 × 1.4 cm = 4.2 cm

The image height is 4.2 cm.`,
  "phys-edexcel-9ph0-2024-p2::14(d)": `Two other properties of the image (in addition to being magnified):
1. The image is virtual (it cannot be projected onto a screen).
2. The image is upright (the same way up as the object).`,
  "phys-edexcel-9ph0-2024-p2::15(a)": `The vibrating toothbrush head acts as a source of periodic waves that travel along the string (transverse waves). These waves travel towards the fixed end of the string and are reflected back. The reflected wave travels back in the opposite direction along the string.

The incident wave and the reflected wave have the same frequency, wavelength, and amplitude (assuming little energy loss) but travel in opposite directions. When these two waves superpose (add together according to the principle of superposition), they form a standing wave. At certain positions along the string, the two waves are always in antiphase and the displacement is always zero — these are nodes. At other positions, the waves are always in phase and the amplitude is a maximum — these are antinodes.

For a standing wave (and hence a loop) to form, the length of the string must equal a whole number of half-wavelengths. The toothbrush head must be vibrating at the right frequency to produce this resonance condition. The single loop visible in Photograph 2 corresponds to the fundamental mode, where the length of the string equals half a wavelength, with a node at the fixed end and at the point of attachment to the toothbrush, and an antinode in the middle.`,
  "phys-edexcel-9ph0-2024-p2::15(b)": `Step 1: Determine the wavelength for 4 loops.
With 4 loops, the string length = 4 × (λ/2) = 2λ
So λ = L/2 = 0.69/2 = 0.345 m

Step 2: Determine the wave speed in the string.
Using v = √(T/μ) where T is tension and μ is mass per unit length.
Tension T = weight of hanging mass = mg = 0.010 × 9.81 = 0.0981 N
μ = 9.1 × 10⁻⁴ kg m⁻¹
v = √(0.0981 / 9.1 × 10⁻⁴) = √(107.8) = 10.38 m s⁻¹

Step 3: Calculate the frequency.
f = v/λ = 10.38 / 0.345 = 30.1 Hz ≈ 30 Hz

The frequency of vibration of the toothbrush head is approximately 30 Hz.`,
  "phys-edexcel-9ph0-2024-p2::16(a)": `T = 1/f = 1/0.34 = 2.94 s

T = 2π√(m/k), so m = kT²/4π² = 350 × 2.94² / 4π² = 76.7 kg

This is the total oscillating mass, so mass of astronaut = 76.7 − 5.7 = 71 kg`,
  "phys-edexcel-9ph0-2024-p2::16(b)(i)": `Amplitude A = 0.29 / 2 = 0.145 m
ω = 2πf = 2π × 0.34 = 2.14 rad s⁻¹
Maximum acceleration = ω²A = 2.14² × 0.145 = 0.66 m s⁻²`,
  "phys-edexcel-9ph0-2024-p2::16(b)(ii)": `The astronaut starts from maximum displacement, so v = −Aω sin ωt.

ωt = 2.14 × 3.5 = 7.48 rad
speed = 0.145 × 2.14 × sin(7.48 rad) = 0.310 × 0.93 = 0.29 m s⁻¹`,
  "phys-edexcel-9ph0-2024-p2::17(a)": `Step 1: Find the density of air at 120°C.
Using the ideal gas law at constant pressure (since envelope is open):
ρ ∝ 1/T (at constant pressure)
T₁ = 20°C = 293 K, ρ₁ = 1.2 kg m⁻³
T₂ = 120°C = 393 K
ρ₂ = ρ₁ × T₁/T₂ = 1.2 × 293/393 = 1.2 × 0.7455 = 0.895 kg m⁻³

Step 2: Find the mass of hot air in the envelope.
Mass of hot air = ρ₂ × V = 0.895 × 2800 = 2505 kg

Step 3: Find the total weight of balloon + air + passengers.
Total mass = 380 + 2505 + 340 = 3225 kg
Total weight = 3225 × 9.81 = 31638 N ≈ 31600 N

Step 4: Compare with upthrust.
Upthrust = 33000 N

Since upthrust (33000 N) > total weight (31600 N), the net upward force = 33000 − 31600 = 1400 N > 0.

The balloon can take off, as the upthrust exceeds the total weight.`,
  "phys-edexcel-9ph0-2024-p2::17(b)(i)": `One assumption of the kinetic theory of gases: the molecules of a gas are in continuous random motion, and the volume of the molecules themselves is negligible compared to the volume of the gas (molecules are treated as point masses).`,
  "phys-edexcel-9ph0-2024-p2::17(b)(ii)": `From kinetic theory, the pressure exerted by an ideal gas is:
pV = (1/3)Nm⟨c²⟩

For n moles, N = nNA, and using pV = nRT (ideal gas law):
(1/3)Nm⟨c²⟩ = nRT
(1/3)(N/NA)(NAm)⟨c²⟩ = nRT

For one molecule, the mean kinetic energy is:
Ek = (1/2)m⟨c²⟩

From pV = NkT (where k = R/NA, N = total number of molecules):
(1/3)Nm⟨c²⟩ = NkT
(1/3)m⟨c²⟩ = kT
(1/2)m⟨c²⟩ = (3/2)kT

Therefore mean kinetic energy of a molecule = (3/2)kT.`,
  "phys-edexcel-9ph0-2024-p2::17(b)(iii)": `T = 120°C = 393 K
Mass of one nitrogen molecule: m = 28 × u = 28 × 1.661 × 10⁻²⁷ = 4.651 × 10⁻²⁶ kg

Using mean kinetic energy = (3/2)kT = (1/2)m⟨c²⟩:
⟨c²⟩ = 3kT/m = (3 × 1.38 × 10⁻²³ × 393) / (4.651 × 10⁻²⁶)
= (1.627 × 10⁻²⁰) / (4.651 × 10⁻²⁶)
= 3.499 × 10⁵ m² s⁻²

c_rms = √⟨c²⟩ = √(3.499 × 10⁵) = 591 m s⁻¹

The root-mean-square speed of nitrogen molecules at 120°C is approximately 591 m s⁻¹.`,
  "phys-edexcel-9ph0-2024-p2::18(a)": `The Sun emits a continuous spectrum of electromagnetic radiation (white light) from its hot, dense photosphere. This continuous spectrum contains all wavelengths across the visible and other regions of the spectrum.

Above the photosphere is the Sun's atmosphere (the chromosphere), which contains gases at a lower temperature. These cooler gases are composed of atoms of specific elements (such as hydrogen, helium, sodium, and calcium), each of which can absorb photons of specific, discrete wavelengths corresponding to the differences between their allowed energy levels. When white light from the photosphere passes through the cooler atmospheric gases, photons of these specific wavelengths are absorbed as electrons in the gas atoms are excited to higher energy levels.

This absorption removes those particular wavelengths from the continuous spectrum. The re-emitted photons are radiated in all directions (not just towards the observer), so the observer sees a continuous spectrum with dark lines (missing wavelengths) at positions corresponding to the absorbed frequencies. Each element absorbs a unique set of wavelengths, so each dark line can be matched to a specific element, allowing the composition of the Sun's atmosphere to be identified. These dark lines are called Fraunhofer absorption lines.`,
  "phys-edexcel-9ph0-2024-p2::18(b)": `The hydrogen-alpha line has wavelength λ = 656.46 nm.
Energy of this photon: E = hc/λ = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) / (656.46 × 10⁻⁹)
= (1.989 × 10⁻²⁵) / (6.5646 × 10⁻⁷)
= 3.031 × 10⁻¹⁹ J

Convert to eV: E = 3.031 × 10⁻¹⁹ / 1.60 × 10⁻¹⁹ = 1.894 eV

This absorption line involves transitions from n = 2, so look for a transition from n = 2 to a higher level:
ΔE(n=2 to n=3) = −1.51 − (−3.40) = 1.89 eV ✓

This matches 1.894 eV within rounding.

The hydrogen-alpha line corresponds to the transition from n = 2 to n = 3 (i.e., electron excited from the n = 2 energy level to the n = 3 energy level, absorbing a photon of 1.89 eV).`,
  "phys-edexcel-9ph0-2024-p2::18(c)(i)": `Huggins's suggestion is well-founded. The Doppler effect causes a shift in the observed wavelength of light when there is relative motion between the source and observer. If a star moves away from the Earth, the observed wavelength is longer (redshift); if it moves towards the Earth, the observed wavelength is shorter (blueshift). This principle is valid for light (electromagnetic waves), and the formula Δλ/λ ≈ v/c applies for speeds much less than c. Since stellar speeds are typically much less than c, the approximation is valid. By measuring the shift in wavelength of a known spectral line (such as the hydrogen-alpha line), the component of the star's velocity along the line of sight (radial velocity) can be calculated, and the direction of the shift tells us whether the star is moving towards or away from Earth. Huggins's suggestion is therefore correct and this method (spectroscopic Doppler measurement) is widely used in astronomy.`,
  "phys-edexcel-9ph0-2024-p2::18(c)(ii)": `Using the Doppler formula: Δλ/λ = v/c

v = 5.5 km s⁻¹ = 5500 m s⁻¹ (moving away, so redshift)
λ₀ = 656.46 nm

Δλ = λ₀ × v/c = 656.46 × 10⁻⁹ × (5500 / 3.00 × 10⁸)
= 656.46 × 10⁻⁹ × 1.833 × 10⁻⁵
= 1.203 × 10⁻¹¹ m = 0.01203 nm

Observed wavelength = λ₀ + Δλ = 656.46 + 0.012 = 656.47 nm

The wavelength of the hydrogen-alpha line as seen in the spectrum of Sirius A is approximately 656.47 nm.`,
  "phys-edexcel-9ph0-2024-p2::19(a)(i)": `Spontaneous: nuclear decay is spontaneous because it is not triggered or influenced by external conditions such as temperature, pressure, or chemical environment — it occurs without any external cause.

Random: nuclear decay is random because it is impossible to predict which particular nucleus in a sample will decay next, or exactly when a given nucleus will decay. Each nucleus has the same probability of decaying per unit time, but the moment of decay cannot be predetermined.`,
  "phys-edexcel-9ph0-2024-p2::19(a)(ii)": `Although individual nuclear decays are random, the decay constant λ is the probability of decay per unit time for a single nucleus. When a very large number of nuclei are present (as in any macroscopic sample, where N ~ 10²³), statistical averaging means the number of decays per unit time is essentially constant and predictable. By measuring the activity (number of decays per second) of a known quantity of the isotope over time, the decay constant can be determined from A = λN. The randomness affects individual nuclei but the overall rate for a large ensemble is statistically stable, allowing λ to be measured precisely.`,
  "phys-edexcel-9ph0-2024-p2::19(b)": `Method to determine the percentage of activity due to beta radiation:

1. Set up the Geiger-Müller (GM) tube and ratemeter with the source at a fixed distance. Measure the background count rate with the source removed, record this as B (counts per minute).

2. Place the source in front of the GM tube (at a fixed, measured distance) without any absorber. Record the count rate R_total. Subtract background: corrected total activity = R_total − B.

3. Place a sheet of paper or a few cm of air between the source and the GM tube. This absorbs all the alpha radiation (alpha particles are stopped by a few cm of air or a sheet of paper) but allows the beta particles to pass through. Record the new count rate R_beta. Subtract background: corrected beta activity = R_beta − B.

4. Calculate the percentage due to beta radiation:
% beta = (R_beta − B) / (R_total − B) × 100%`,
  "phys-edexcel-9ph0-2024-p2::19(c)(i)": `Using A = A₀ × (1/2)^(t/t½), where t = 34 years and t½ = 432 years:

A/A₀ = (1/2)^(34/432) = (1/2)^(0.07870)

(1/2)^0.07870 = e^(−0.07870 × ln2) = e^(−0.07870 × 0.6931) = e^(−0.05454) = 0.9469

Percentage remaining = 0.9469 × 100 = 94.7% ≈ 94.7%

Approximately 94.7% of the initial activity would be expected to remain today.`,
  "phys-edexcel-9ph0-2024-p2::19(c)(ii)": `The student's statement requires assessment based on the decay chain:

Neptunium-237 (t½ = 2.1 × 10⁶ years) builds up extremely slowly from americium-241 decay — after 34 years, only a negligible fraction of the Am-241 has decayed, so the amount of Np-237 present is very small.

Protactinium-233 is produced by the alpha decay of Np-237. Since the half-life of Np-237 is 2.1 × 10⁶ years, its activity (and hence the rate of production of Pa-233) is extremely low after only 34 years. Although Pa-233 has a short half-life of 27 days (meaning it quickly reaches secular equilibrium), the amount of Pa-233 in equilibrium with Np-237 is proportional to the activity of Np-237, which is tiny.

Therefore, the activity of Pa-233 (and hence beta radiation from the source) is negligible compared to the alpha activity of the Am-241. The student's claim is incorrect — the amount of beta radiation from Pa-233 would not be significant after 34 years.`,
  "phys-edexcel-9ph0-2024-p3::1(a)": `The raw data has not been recorded. The table shows only the calculated extensions, not the measured positions of the bottom of the mass holder from which those extensions were worked out, so the processing cannot be checked.

The values in each column are not recorded to the same precision. The masses are given to differing numbers of decimal places (0.05, 0.25 and 0.75 kg to two, but 0.1, 0.5 and 1.0 kg to one), and the extensions are not all to the same number of significant figures (0.4 cm and 0.8 cm to one, the rest to two). Every reading in a column should be recorded to the same number of decimal places / significant figures.`,
  "phys-edexcel-9ph0-2024-p3::1(b)": `To determine the extension as accurately as possible:
1. Use a metre rule (or vernier callipers for small extensions) aligned vertically alongside the nylon line, with a set square to ensure the rule is truly vertical and to read the position of the end of the line without parallax error.
2. Mark the initial position of the bottom of the line clearly (e.g., with a small marker or pointer) before any load is applied, and measure the position of this marker both before and after loading; the extension = final position − initial position.
3. Take repeat readings of the extension for each load and calculate a mean, to reduce random errors. Ensure the line is in equilibrium (has stopped moving) before taking each reading.`,
  "phys-edexcel-9ph0-2024-p3::1(c)(i)": `The yield point is the point on a stress-strain (or force-extension) graph beyond which the material undergoes plastic deformation — it no longer returns to its original length when the load is removed. Beyond the yield point, the extension is no longer proportional to the applied force (Hooke's law no longer applies) and permanent deformation occurs.`,
  "phys-edexcel-9ph0-2024-p3::1(c)(ii)": `The strain at the yield point is 0.04 and the original length of the line is 2.00 m, so the extension at the yield point is

Δx = ε × x = 0.04 × 2.00 = 0.080 m = 8.0 cm

The largest extension the student recorded was 7.2 cm, which is less than 8.0 cm.

(Equivalently, the strain at the largest extension was 0.072/2.00 = 0.036, which is less than 0.04.)

So the fishing line was not stretched beyond its yield point.`,
  "phys-edexcel-9ph0-2024-p3::2(a)(i)": `The coin is a cylinder, so V = πr²t = π(d/2)²t.

V = π × (22.16 × 10⁻³ / 2)² × 1.54 × 10⁻³
= π × (1.108 × 10⁻²)² × 1.54 × 10⁻³
= π × 1.2277 × 10⁻⁴ × 1.54 × 10⁻³
V = 5.94 × 10⁻⁷ m³

The digital calipers read to 0.01 mm, so the uncertainty in each reading is half the resolution, ±0.005 mm.

% uncertainty in d = (0.005 / 22.16) × 100 = 0.023 %
Since V ∝ d², the contribution of d to the uncertainty in V is 2 × 0.023 = 0.045 %
% uncertainty in t = (0.005 / 1.54) × 100 = 0.325 %

% uncertainty in V = 0.045 + 0.325 = 0.37 % ≈ 0.4 %

V = 5.94 × 10⁻⁷ m³, with a percentage uncertainty of 0.4 %.`,
  "phys-edexcel-9ph0-2024-p3::2(a)(ii)": `Density of the coin:
ρ = m/V = 11.2 × 10⁻³ kg / 5.94 × 10⁻⁷ m³ = 1.89 × 10⁴ kg m⁻³

The balance has a resolution of 0.1 g, so the uncertainty in the mass is ±0.05 g:
% uncertainty in m = (0.05 / 11.2) × 100 = 0.45 %

% uncertainty in ρ = % uncertainty in m + % uncertainty in V = 0.45 + 0.36 = 0.81 %

Absolute uncertainty in ρ = 0.0081 × 1.89 × 10⁴ = 150 kg m⁻³

So the largest density the coin could have is 1.89 × 10⁴ + 150 = 1.905 × 10⁴ ≈ 1.9 × 10⁴ kg m⁻³.

Even this maximum possible density is below the density of pure gold, 1.93 × 10⁴ kg m⁻³, so the coin could not be made from pure gold.`,
  "phys-edexcel-9ph0-2024-p3::2(b)": `Measure the thickness of a stack of several identical coins (say ten) with the calipers, or the mass of a stack of coins on the balance, and divide by the number of coins. The absolute uncertainty of the reading stays the same, ±0.005 mm, while the quantity measured is ten times larger, so the percentage uncertainty in the thickness — which is by far the largest contribution to the uncertainty in the volume — is reduced by a factor of ten.

Repeat each measurement and take a mean: measure the diameter in several different directions across the coin, the thickness at several different points, and the mass more than once. Averaging repeated readings reduces the effect of random errors and of any slight non-uniformity in the coin.

(A further improvement would be to check the calipers and the balance for a zero error before use and correct the readings for it, which removes a systematic error from every measurement.)`,
  "phys-edexcel-9ph0-2024-p3::3": `Before S2 is closed, bulb 3 is disconnected, so bulbs 1 and 2 are in series with each other across the 6 V battery. The same current passes through both, and as the bulbs are identical they have the same resistance, so the 6 V is shared equally and each bulb has 3 V across it. Both are therefore operating normally, and bulb 1 and bulb 2 are equally bright.

When S2 is closed, a current can flow in bulb 3, which is connected in parallel with bulb 1. The resistance of the parallel combination of bulbs 1 and 3 is less than the resistance of bulb 1 alone, so the total resistance of the circuit falls and the current drawn from the battery (read on the ammeter) increases.

The 6 V is now shared between the parallel combination and bulb 2 in proportion to their resistances. The parallel combination takes a smaller share than bulb 1 did on its own, so the potential difference across bulb 1 (and bulb 3) falls below 3 V, while the potential difference across bulb 2 rises above 3 V.

The current in bulb 2 is therefore larger than before, so using P = V²/R its power and brightness increase; the current in bulb 1 is smaller than before, because the increased circuit current now divides between bulbs 1 and 3, so its power and brightness decrease.

So, once S2 is closed, bulb 1 is no longer as bright as bulb 2: bulb 2 is brighter than bulb 1, whereas before S2 was closed the two were equally bright.`,
  "phys-edexcel-9ph0-2024-p3::4(a)": `Step 1: Calculate the volume of the canister.
V = (4/3)πr³ = (4/3) × π × (4.36 × 10⁻²)³
= (4/3) × π × 8.287 × 10⁻⁵
= 4.189 × 8.287 × 10⁻⁵
= 3.471 × 10⁻⁴ m³

Step 2: Use ideal gas law to find the number of moles.
pV = nRT
n = pV/(RT) = (1.65 × 10⁷ × 3.471 × 10⁻⁴) / (8.31 × (273 + 18.5))
= (5727) / (8.31 × 291.5)
= 5727 / 2422
= 2.365 mol

Step 3: Calculate the mass.
Molar mass of helium: 1 mol has mass 4.00 × 10⁻³ kg (since 6.02 × 10²³ atoms has mass 4.00 × 10⁻³ kg)
mass = n × M = 2.365 × 4.00 × 10⁻³ = 9.46 × 10⁻³ kg

The mass of helium gas in the full canister is approximately 9.46 × 10⁻³ kg (9.46 g).`,
  "phys-edexcel-9ph0-2024-p3::4(b)": `Assessing the students' suggestions:

Student Y is correct. When helium is released from the canister (to fill balloons), the mass of helium remaining inside the canister decreases. Since weight = mg, and m decreases, the weight of the canister and its contents decreases. This is straightforward conservation of mass.

Student X's reasoning is incorrect. The upthrust on the canister is exerted by the surrounding air (not by the helium inside the canister). The upthrust equals the weight of air displaced by the volume of the canister (Archimedes' principle). Since the volume and external shape of the canister do not change as helium is released, the upthrust on the canister from the surrounding air remains constant. The helium inside the canister does not exert an upthrust on the canister — it is enclosed within it and its pressure acts on the inside walls. Therefore Student X's reasoning is flawed.

Conclusion: Student Y is correct — the weight decreases as helium is released.`,
  "phys-edexcel-9ph0-2024-p3::5(a)": `Timing a single oscillation means that the student's reaction time in starting and stopping the stopwatch is a large fraction of the time measured. She should instead time a number of complete oscillations — ten or twenty, say — and divide the total time by the number of oscillations to obtain a mean value of T. The reaction-time error is then spread over a much longer measured time, so its effect on T is greatly reduced. She should also repeat the whole timing several times and take a mean, which further reduces the effect of random error.

She should not start the stopwatch at the instant of release, but allow the trolley to settle into steady oscillation for a few cycles first, so that what she times is the regular simple harmonic motion.

She should set up a fiducial marker — for example a pin, or a mark on the bench lined up with a chosen point on the trolley — and start and stop the stopwatch as the trolley passes it, so that the start and end of the timing are unambiguous.

The marker should be placed at the centre of the oscillation, at the equilibrium position, because the trolley is travelling fastest there. It passes the marker in the shortest time, so the instant of passing is easiest to judge and the effect of reaction time on the timing is smallest.`,
  "phys-edexcel-9ph0-2024-p3::5(b)": `From the equation for a mass-spring system:
T = 2π√((M + m)/k)
T² = 4π²(M + m)/k = (4π²/k)m + (4π²M/k)

This is of the form T² = gradient × m + intercept, where:
- gradient = 4π²/k
- intercept = 4π²M/k

From the graph of T² against m:
- Measure the gradient of the best-fit straight line.
- From the gradient = 4π²/k, first determine k: k = 4π²/gradient.
- Then read off the y-intercept (when m = 0): intercept = 4π²M/k.
- Rearrange to find M: M = intercept × k / 4π² = intercept / gradient.

Alternatively, extend the best-fit line to the x-axis: the line intersects the x-axis at m = −M (since when T² = 0, (4π²/k)(m + M) = 0 → m = −M). The magnitude of this x-intercept gives M directly.`,
  "phys-edexcel-9ph0-2024-p3::6(a)": `When a standing wave is formed on the plate, the plate vibrates with nodes (points of zero displacement) and antinodes (points of maximum displacement). The sand lying on the surface of the plate experiences the vibrations of the plate beneath it. At the antinodes, the plate surface is vibrating with large amplitude, so the sand is thrown upward and cannot settle there — it bounces around. At the nodes, the plate is stationary (zero amplitude of vibration), so the sand can settle and accumulate there. Over time, the sand migrates from the antinodes to the nodes, collecting in the pattern of the nodal lines, which reveals the shape of the standing wave pattern (Chladni figures).`,
  "phys-edexcel-9ph0-2024-p3::6(b)": `From the oscilloscope trace, one complete cycle of the signal occupies 4.6 divisions.

T = 4.6 div × 0.50 ms div⁻¹ = 2.3 ms = 2.3 × 10⁻³ s

f = 1/T = 1 / (2.3 × 10⁻³) = 435 Hz

The plate vibrates at the frequency of the signal driving the vibration generator, and the wavelength of the waves in the plate is 0.32 m, so

v = fλ = 435 × 0.32 = 139 m s⁻¹ ≈ 140 m s⁻¹

The speed of sound in air is 340 m s⁻¹, so the waves in the plate travel at less than half that speed. The data therefore does support the statement that the waves produced in the plate travel much more slowly than sound in air.`,
  "phys-edexcel-9ph0-2024-p3::6(c)": `Graphical method to determine the speed of sound:

For a standing wave in a tube closed at the water end (node at water surface) and open at the top (antinode at open end), the resonance condition is:
L = (2n − 1)λ/4 for n = 1, 2, 3, ...

Since v = fλ → λ = v/f, we get:
L = (2n−1)v/(4f)

For the fundamental (n=1): L = λ/4 = v/(4f), so v = 4fL.

The student can vary f (using different tuning forks) and for each tuning fork find the length L at which resonance occurs. Plotting L against 1/f (or plotting L × f against a constant) gives a straight line through the origin with gradient v/4.

Specifically: plot L (y-axis) against 1/f (x-axis). The gradient of the best-fit line = v/4 (for the fundamental mode), so v = 4 × gradient. This gives the speed of sound in air.`,
  "phys-edexcel-9ph0-2024-p3::7(a)": `Conservation of mass number: 220 = A + 4 → A = 216
Conservation of atomic number: 86 = Z + 2 → Z = 84

Polonium has atomic number 84, so:
²²⁰₈₆Rn → ²¹⁶₈₄Po + ⁴₂α`,
  "phys-edexcel-9ph0-2024-p3::7(b)": `Radon is a radioactive gas. As it decays, it emits alpha particles. Alpha radiation is highly ionising and causes significant biological damage to living tissue (particularly the cells lining the lungs) if the radon gas is inhaled. Being a gas, radon can be breathed in and become trapped in the lungs, where the alpha particles emitted from the decay are absorbed directly by the surrounding lung tissue, potentially causing damage to DNA and increasing the risk of lung cancer. Because alpha radiation has a very short range in tissue, all its ionising energy is deposited very locally, making it particularly damaging when the source is inside the body.`,
  "phys-edexcel-9ph0-2024-p3::7(c)(i)": `When radon decays, it emits alpha particles (⁴₂α, which are helium nuclei). The alpha particles are positively charged (+2e). As the alpha particles travel through the air in the decay chamber, they collide with air molecules and ionise them, producing positive ions and free electrons. An electric field is applied between the two electrodes inside the chamber (one positive, one negative). The free electrons are attracted to the positive electrode, and the positive ions are attracted to the negative electrode. This movement of charge carriers constitutes an electric current between the electrodes, which is detected by the ammeter.`,
  "phys-edexcel-9ph0-2024-p3::7(c)(ii)": `To find the time for activity to fall to less than 1% of initial value:
A/A₀ = (1/2)^(t/t½) < 0.01
(1/2)^(t/55.6) < 0.01
Taking log: (t/55.6) × log(0.5) < log(0.01)
(t/55.6) × (−0.3010) < −2
t/55.6 > 2/0.3010 = 6.645
t > 6.645 × 55.6 = 369 s

Alternatively using natural logs:
(t/55.6) × ln(0.5) < ln(0.01)
−0.6931 × t/55.6 < −4.605
t > 4.605/0.6931 × 55.6 = 6.644 × 55.6 = 369 s

The time required for the activity to fall below 1% is approximately 369 s, which is less than 450 s. Therefore the teacher's claim is correct — within 450 s, the activity of the radon in the chamber will be less than 1% of its initial value.`,
  "phys-edexcel-9ph0-2024-p3::8(a)": `This answer addresses the system from the instant the spring gun is released to the instant the bob reaches its maximum height.

Principle of momentum conservation: The total momentum of the system (spring gun + modelling clay + pendulum bob) is conserved at all times when no external horizontal force acts. However, during the collision between the modelling clay and the pendulum bob, momentum is conserved in the horizontal direction (assuming the collision time is very short, so the impulse from the string tension is negligible). The clay has an initial horizontal momentum (from being fired by the spring gun), and after the perfectly inelastic collision (clay embeds in the bob), the combined clay-and-bob system moves together with a new, smaller horizontal velocity, such that the total horizontal momentum is unchanged.

Principle of energy conservation: Energy is always conserved, but it is not necessarily conserved as kinetic energy alone. The spring gun initially has elastic potential energy stored in the compressed spring. When released, this elastic potential energy is converted into the kinetic energy of the clay. When the clay collides with the pendulum bob (an inelastic collision), some kinetic energy is converted to internal energy (heat, sound, deformation) — total energy is still conserved, but kinetic energy is not. After the collision, as the bob swings upward, kinetic energy is converted to gravitational potential energy, with the system decelerating until all kinetic energy has been converted to gravitational potential energy at maximum height. At maximum height, the kinetic energy is zero (momentarily at rest) and the gravitational potential energy is at its maximum. Throughout, the total energy of the system remains constant, provided no work is done against air resistance.`,
  "phys-edexcel-9ph0-2024-p3::8(b)(i)": `The pendulum swings from its lowest position (maximum KE) to its highest position (maximum PE) — this is a quarter of a complete oscillation.

Time period of pendulum: T = 2π√(L/g) where L = 1.25 m
T = 2π√(1.25/9.81) = 2π√(0.1274) = 2π × 0.3569 = 2.243 s

Time from lowest to highest position = T/4 = 2.243/4 = 0.561 s ≈ 0.6 s

This confirms the stated time of about 0.6 s.`,
  "phys-edexcel-9ph0-2024-p3::8(b)(ii)": `The period of the pendulum (T ≈ 2.24 s) equals the period of the bob on the spring.
For a mass-spring system: T = 2π√(m/k), where k = 0.12 N m⁻¹

2.243 = 2π√(m/0.12)
(2.243/2π)² = m/0.12
(0.3569)² = m/0.12
0.1274 = m/0.12
m = 0.12 × 0.1274 = 0.01529 kg ≈ 0.015 kg

The mass of the pendulum bob is approximately 0.015 kg (15 g).`,
  "phys-edexcel-9ph0-2024-p3::9(a)(i)": `Criticisms of the student's plan:

1. The intensity of light from a point source is inversely proportional to the square of the distance (I ∝ 1/x²), not proportional to x. Therefore decreasing x by equal intervals does NOT produce uniform (equal) increases in intensity — the increase in intensity is much greater for small x than for large x. The student's assumption that intensity increases uniformly with equal decreases in x is incorrect.

2. The range of distances (10 cm to 20 cm) is too small — it may not produce a sufficient range of intensities to show a clear trend, and small absolute errors in positioning would represent large percentage errors at these close distances.

3. The student should take repeat readings at each position to check for reproducibility and reduce random error, rather than a single reading at each distance.`,
  "phys-edexcel-9ph0-2024-p3::9(a)(ii)": `The student should carry out the experiment in a darkened room, with the room lights off and the apparatus screened from any other light source.

Light from the surroundings also falls on the LDR and lowers its resistance, so it increases the ammeter reading. If the background light is not excluded, the current measured is not due to the lamp alone and the readings will be inaccurate.`,
  "phys-edexcel-9ph0-2024-p3::9(b)": `When the LDR is brought closer to the lamp, the intensity of light falling on it increases. The increased intensity means more photons per unit time strike the semiconductor material of the LDR. These photons have sufficient energy to excite electrons from the valence band to the conduction band of the semiconductor, creating additional free electrons (and holes) — charge carriers that can conduct electricity. As more charge carriers are created, the resistance of the LDR decreases. With a lower resistance of the LDR in the circuit, the current flowing through the ammeter increases (since by Ohm's law, for the same supply voltage, lower resistance means higher current).`,
  "phys-edexcel-9ph0-2024-p3::10(a)": `For simple harmonic motion a = −ω²x, so the graph of a against x is a straight line through the origin whose gradient has magnitude ω².

From the graph, a = −20.0 cm s⁻² when x = 5.0 cm, so

ω² = 20.0 / 5.0 = 4.0 s⁻², giving ω = 2.0 s⁻¹

The maximum velocity occurs as the baby passes through the equilibrium position, where

v_max = ωA = 2.0 × 0.22 m = 0.44 m s⁻¹

0.44 m s⁻¹ is less than the suggested limit of 0.5 m s⁻¹, so it is safe for the baby to oscillate in the jumperoo with an amplitude of 22 cm.`,
  "phys-edexcel-9ph0-2024-p3::10(b)": `The heavier baby in the jumperoo has a greater mass. For a spring-mass system, the natural frequency is f = (1/2π)√(k/m). With greater mass m and the same spring stiffness k, the natural frequency is lower (period is longer). The baby must push at the natural frequency of the system to achieve resonance (maximum amplitude). Since the natural frequency is lower for the heavier baby, the heavier baby pushes at a lower frequency than the original (lighter) baby. Therefore the frequency of pushing of the larger baby is less than the frequency of pushing of the original baby.`,
  "phys-edexcel-9ph0-2024-p3::11(a)": `When the slider S is at position X, it is at one end of the potential divider (the end connected directly to one terminal of the supply). The resistance between X and S is zero, so the voltage output V = 0 (assuming the voltmeter is connected between the slider and the lower terminal). As S moves from X towards Y, the length of the resistance wire between X and S increases. Since the voltmeter has a very high resistance (negligible current drawn), the potential divider acts ideally, and V is proportional to the fraction of the total resistance between X and S. So V increases linearly as S moves from X to Y. When S reaches Y, V = full supply voltage. Therefore V increases linearly from 0 (at X) to the maximum (supply voltage) at Y.`,
  "phys-edexcel-9ph0-2024-p3::11(b)": `The graph of I against V for the filament bulb is not a straight line through the origin (it is not ohmic). As V increases, the current I increases, but the rate of increase of I decreases (the graph curves, becoming less steep at higher V). This is because as the potential difference increases, more power is dissipated in the filament (P = IV), which causes the temperature of the filament to rise significantly. Metals have a positive temperature coefficient of resistance — as temperature increases, the resistance of the filament increases. The increasing resistance means the current does not increase as much as it would for a constant-resistance device, so the I-V graph curves rather than being linear.`,
  "phys-edexcel-9ph0-2024-p3::11(c)(i)": `Taking logarithms of T = aVᵇ:
log T = log a + b log V

This is of the form Y = mX + c, where Y = log T, X = log V, gradient m = b, and intercept c = log a. This is a linear equation in log T and log V, so a graph of log T (y-axis) against log V (x-axis) will give a straight line.`,
  "phys-edexcel-9ph0-2024-p3::11(c)(ii)": `Processed data (log₁₀ values):

T/K | V/V | log(T) | log(V)
1480 | 5.03 | 3.170 | 0.7016
1680 | 6.89 | 3.225 | 0.8382
1850 | 8.95 | 3.267 | 0.9518
2010 | 11.11 | 3.303 | 1.0457
2140 | 12.94 | 3.330 | 1.1119
2280 | 15.06 | 3.358 | 1.1779

The student should plot these six points on the grid with log(V) on the x-axis (range approximately 0.70 to 1.18) and log(T) on the y-axis (range approximately 3.17 to 3.36). The points should lie on or close to a straight line. A best-fit straight line should be drawn through the points.`,
  "phys-edexcel-9ph0-2024-p3::11(c)(iii)": `The gradient b is found by selecting two widely separated points on the best-fit line (not data points).

Using the endpoints of the best-fit line from the processed data:
At log V = 0.70, log T ≈ 3.170
At log V = 1.18, log T ≈ 3.358

Gradient b = Δ(log T) / Δ(log V) = (3.358 − 3.170) / (1.178 − 0.70) = 0.188 / 0.478 = 0.393 ≈ 0.39

The value of b is approximately 0.39 (accept 0.37 to 0.41 depending on the best-fit line drawn).`,
  "phys-edexcel-9ph0-2024-p3::12(a)(i)": `Mean time for the ball to fall 22.5 cm:
t = (9.6 + 9.9 + 9.6) / 3 = 9.7 s

Terminal velocity:
v = s/t = 0.225 m / 9.7 s = 0.0232 m s⁻¹

Rearranging v = 2r²g(ρB − ρC)/9η for the viscosity:
η = 2r²g(ρB − ρC) / 9v
= 2 × (4.25 × 10⁻³)² × 9.81 × (7750 − 1330) / (9 × 0.0232)
= 2 × 1.806 × 10⁻⁵ × 9.81 × 6420 / 0.209
= 2.275 / 0.209
η = 10.9 Pa s

Reading the graph at η = 10.9 Pa s gives a cocoa content of about 30 %, not 35 %.

Looking at it the other way round, the graph gives η ≈ 4.5 Pa s for 35 % cocoa, which would give a terminal velocity of about 0.056 m s⁻¹ and a fall time of about 4 s, not the 9.7 s measured.

The student's timing data therefore does not support the 35 % cocoa content claimed on the wrapper; it indicates a cocoa content of about 30 %.`,
  "phys-edexcel-9ph0-2024-p3::12(a)(ii)": `One reason why the data may have led to an inaccurate conclusion: The student only took three timing measurements and used a handheld stopwatch, which introduces human reaction time errors (typically ±0.2 s) into each measurement. The spread in the data (9.6 s, 9.9 s, 9.6 s) shows some variability. A reaction time error of 0.2 s on a total time of ~9.7 s gives a percentage uncertainty of about 2%, which translates into a 2% uncertainty in velocity and hence in viscosity — this could shift the apparent cocoa content reading on the graph by a noticeable amount. Using a more precise timing method (e.g., a light gate or video analysis) would reduce this source of inaccuracy.`,
  "phys-edexcel-9ph0-2024-p3::12(b)": `Step 1: Energy released when 65 g of chocolate is digested.
E_digested = 345 kcal × 4200 J kcal⁻¹ = 1.449 × 10⁶ J

Step 2: 15% of energy released:
0.15 × 1.449 × 10⁶ = 2.174 × 10⁵ J

Step 3: Energy needed to raise temperature of 65 g chocolate from 15°C to 32°C.
m = 65 × 10⁻³ kg, c = 3.9 × 10³ J kg⁻¹ K⁻¹, ΔT = 32 − 15 = 17 K
E_heat = mcΔT = 65 × 10⁻³ × 3.9 × 10³ × 17 = 65 × 3.9 × 17 × 10⁰ = 4305 × 10⁰ = 4305 J

Step 4: Energy needed to melt the chocolate (latent heat).
L = 1.50 × 10⁵ J kg⁻¹
E_melt = mL = 65 × 10⁻³ × 1.50 × 10⁵ = 9750 J

Step 5: Total energy to melt the chocolate.
E_total = E_heat + E_melt = 4305 + 9750 = 14055 J ≈ 1.41 × 10⁴ J

Step 6: Compare with 15% of digested energy.
15% of digested energy = 2.174 × 10⁵ J
Energy to melt = 1.41 × 10⁴ J

1.41 × 10⁴ J is much less than 2.174 × 10⁵ J (the energy to melt is only about 6.5% of 15% of the digested energy, or about 0.97% of the total digested energy).

The suggestion that the energy to melt the chocolate is at least 15% of the energy released by digestion is incorrect. The energy required to melt the chocolate is only about 1.4 × 10⁴ J, whereas 15% of the digested energy is about 2.2 × 10⁵ J — the melting energy is far less than 15% of the digested energy.`,
  "phys-ocra-h556-2022-p1::16(a)": `To determine the force constant of an elastic cord: attach one end of the cord to a clamp stand and hang masses from the other end. Measure the natural (unstretched) length of the cord with a ruler. Add known masses m (e.g. 50 g increments) and record the new length each time, calculating the extension x = new length − natural length. Plot a graph of force F (= mg) on the y-axis against extension x on the x-axis. Since the cord obeys Hooke's law, the graph will be a straight line through the origin. The gradient of this line equals the force constant k (units: N m⁻¹). Use a fiducial marker at the bottom of the cord to reduce parallax error when measuring length. Take readings whilst loading and unloading to check for hysteresis.`,
  "phys-ocra-h556-2022-p1::16(b)(i)": `When the centre of the cord is pulled back by d = 10 cm, the graph gives an extension of the cord of 6.0 cm = 0.060 m.
The cord obeys Hooke's law with force constant k = 500 N m⁻¹, so the elastic potential energy stored is
E = ½kx² = ½ × 500 × (0.060)²
E = ½ × 500 × 3.6 × 10⁻³ = 0.90 J
This is about 1 J, as required.`,
  "phys-ocra-h556-2022-p1::16(b)(ii)": `Assume that all of the elastic potential energy stored in the cord is transferred to kinetic energy of the ball; this gives the maximum possible launch speed.
E = ½mv², with E = 0.90 J from (b)(i) and m = 30 g = 0.030 kg:
0.90 = ½ × 0.030 × v²
v² = (2 × 0.90)/0.030 = 60 m² s⁻²
v = √60 = 7.7 m s⁻¹
So the maximum speed at which the ball leaves the catapult is about 8 m s⁻¹.`,
  "phys-ocra-h556-2022-p1::16(b)(iii)": `The ball is launched horizontally, so its initial vertical velocity is zero and the horizontal and vertical motions can be treated independently.
Vertical motion (free fall through 1.5 m):
h = ½gt² → 1.5 = ½ × 9.81 × t²
t² = 3.0/9.81 = 0.306 s², so t = 0.55 s
Horizontal motion (constant velocity of 7.7 m s⁻¹ from (b)(ii)):
R = vt = 7.7 × 0.55
R = 4.2 m`,
  "phys-ocra-h556-2022-p1::16(b)(iv)": `The actual value of R will be less than 4.4 m. This is because air resistance acts on the ball during flight, removing kinetic energy and reducing both the horizontal speed and the range. Additionally, some of the elastic potential energy stored in the cord is converted to thermal energy (heat) due to the inelastic nature of the cord, and some energy is stored in the vibrations of the cord itself, so the actual kinetic energy of the ball at launch is less than 1 J, giving a lower launch speed and therefore a shorter range.`,
  "phys-ocra-h556-2022-p1::17(a)": `The engine reaches its maximum speed when all of the work done by the engine has been transferred to kinetic energy, so the minimum time is the time for the constant power output to deliver the maximum kinetic energy.
Power = energy transferred / time, so t = E/P
t = (15 × 10⁶)/(280 × 10³) = 54 s
This is about 1 minute. In practice the time is longer, because some of the work done is transferred against resistive forces rather than to kinetic energy.`,
  "phys-ocra-h556-2022-p1::17(b)": `The engine travels at constant velocity, so it is in equilibrium and the forces balance both vertically and horizontally.
The missing force is the total resistive (drag) force on the engine. It should be drawn on the free-body diagram as a horizontal arrow pointing to the left, i.e. opposite to the motion, and the same length as the arrow for F.
Vertically: N = W = mg = 17 000 × 9.81 = 1.7 × 10⁵ N
Horizontally: at the maximum speed, P = Fv, so F = P/v = (280 × 10³)/42 = 6700 N, and the resistive force drawn to the left also has magnitude 6700 N.
So N = 170 000 N (upwards), W = 170 000 N (downwards) and F = 6700 N (to the right).`,
  "phys-ocra-h556-2022-p1::17(c)": `Thinking distance – during the driver's reaction time the engine continues at 42 m s⁻¹:
s₁ = vt = 42 × 0.40 = 17 m
Braking distance – the constant opposing force of 120 kN decelerates the engine:
a = F/m = (120 × 10³)/17 000 = 7.1 m s⁻²
Using v² = u² − 2as with v = 0 and u = 42 m s⁻¹:
s₂ = u²/(2a) = 42²/(2 × 7.06) = 1764/14.1 = 125 m
Total stopping distance = 17 + 125 = 142 m
142 m is less than the 167 m to the obstruction, so the engine stops before reaching it.`,
  "phys-ocra-h556-2022-p1::18(a)(i)": `Area of the shaded side of the tent:
A = 6.0 × 1.9 = 11.4 m²
In 3.0 s the wind carries a column of air of length vt = 12 × 3.0 = 36 m through this area, so
volume of air = A × v × t = 11.4 × 12 × 3.0 = 410 m³
mass of air = ρ × volume = 1.2 × 410.4 = 492 kg
This is about 490 kg, as required.`,
  "phys-ocra-h556-2022-p1::18(a)(ii)": `The air deflects at 90° so all horizontal momentum is transferred to the tent. Change in velocity of air = 12 m s⁻¹ (from 12 m s⁻¹ horizontal to 0 horizontal component).
Change in momentum = mass × change in velocity = 490 × 12 = 5880 N s
Force = change in momentum / time = 5880 / 3.0 = 1960 N ≈ 2000 N
F = 2.0 kN`,
  "phys-ocra-h556-2022-p1::18(b)": `The force the wind exerts on the tent is the rate of change of momentum of the air, F = Δp/Δt. The mass of air arriving each second is ρAv, and if the air is turned through 90° each kilogram loses all of its forward velocity v, so F = ρAv². Doubling the wind speed from 20 m s⁻¹ to 40 m s⁻¹ therefore doubles both the mass of air arriving per second and the velocity change, so the momentum change per second, and hence the force, becomes four times larger. The ropes and the tent must be modified to cope with this four-fold increase.

Modifying the ropes. The tension in each rope will be about four times greater. Since stress = tension / cross-sectional area, keeping the stress below the breaking (yield) stress of the same material requires the cross-sectional area of each rope to be increased by a factor of four, i.e. the diameter of the rope must be at least doubled. Alternatively the ropes could be made from a different material whose breaking or yield stress is at least four times greater, such as a high-strength synthetic fibre or steel wire. Using more than three ropes along each side shares the load so that the tension in each individual rope is smaller. The ropes should also be pegged further from the tent so that they make a smaller angle with the ground: the wind force is horizontal, so a smaller angle means less of the tension is 'wasted' as a component perpendicular to the ground and a smaller tension is needed to hold the tent.

Modifying the shape. The tent should be reshaped so that the air is not stopped or deflected through a large angle. A low, curved, streamlined shape (a dome or a wedge) lets the air flow over and around the tent, so the air keeps most of its forward momentum. The change in momentum per second is then much smaller and so is the force: deflecting the air through only about 15° instead of 90° would reduce the momentum change by the factor of four needed to offset the doubling of the wind speed. A lower profile also reduces the area A presented to the wind, which reduces F = ρAv² directly, and sloping sides mean the wind exerts a downward component of force that presses the tent onto the ground instead of lifting it, reducing the tension needed in the ropes.

Taken together – thicker or stronger ropes pegged at a shallower angle, and a lower, streamlined, curved tent – the tent could withstand wind speeds above 40 m s⁻¹.`,
  "phys-ocra-h556-2022-p1::19(a)": `When liquid nitrogen changes to gas at constant temperature, the molecules move from a liquid state (where they are close together with significant intermolecular attractive forces and ordered arrangement) to a gaseous state (where they are far apart and move randomly with negligible intermolecular forces).

The total internal energy U = kinetic energy + potential energy of molecules. At constant temperature, the mean kinetic energy of the molecules remains the same (since temperature is unchanged). However, the molecules move much further apart, increasing their intermolecular potential energy (since work is done against the attractive intermolecular forces to separate them). Therefore the total internal energy increases, even though the temperature stays constant.`,
  "phys-ocra-h556-2022-p1::19(b)(i)": `Using the ideal gas equation pV = nRT:
n = pV/(RT)
p = 100 × 10³ Pa, V = 15 m³, T = 23 + 273 = 296 K, R = 8.31 J mol⁻¹ K⁻¹
n = (100 × 10³ × 15)/(8.31 × 296)
n = 1 500 000/2 459.76
n = 609.8 ≈ 600 mol ✓`,
  "phys-ocra-h556-2022-p1::19(b)(ii)": `Mass = n × M_r = 610 × 0.028 = 17.08 ≈ 17 kg
(Using n = 600 mol: mass = 600 × 0.028 = 16.8 ≈ 17 kg)`,
  "phys-ocra-h556-2022-p1::19(b)(iii)": `Increase the temperature at which the nitrogen is added. For a fixed volume and pressure, pV = nRT gives n = pV/RT, so a higher temperature means fewer moles, and therefore a smaller mass, of nitrogen in the same 15 m³ each hour. (Reducing the pressure of the nitrogen would have the same effect.)`,
  "phys-ocra-h556-2022-p1::19(b)(iv)": `The liquid nitrogen absorbs heat from the air to vaporise. The heat Q is supplied by the condensation and freezing of water vapour to form ice on the pipe. Heat released by 1.3 kg of water vapour forming ice at 0 °C:
Q = m_water × L_vap(water) + m_water × L_fus(ice)
Q = 1.3 × 2.26 × 10⁶ + 1.3 × 3.34 × 10⁵
Q = 2.938 × 10⁶ + 4.342 × 10⁵
Q = 3.372 × 10⁶ J
This heat is used to vaporise the liquid nitrogen:
Q = m_N₂ × L_N₂
L_N₂ = Q/m_N₂ = 3.372 × 10⁶ / 17
L_N₂ = 1.98 × 10⁵ J kg⁻¹ ≈ 2.0 × 10⁵ J kg⁻¹`,
  "phys-ocra-h556-2022-p1::20(a)": `Left side: acceleration a has SI base units of m s⁻².
Right side: ω² has units of (rad s⁻¹)² = s⁻², and x has units of m, so ω²x has units of s⁻² × m = m s⁻².
Both sides reduce to m s⁻², so the equation is homogeneous. ✓`,
  "phys-ocra-h556-2022-p1::20(b)(i)": `The pressure difference supports the water column. The vertical height difference between the levels is 10.0 cm = 0.100 m (with x = 5.0 cm on each side).
p = ρgh = 1000 × 9.81 × 0.100
p = 981 Pa ≈ 980 Pa`,
  "phys-ocra-h556-2022-p1::20(b)(ii)1": `Comparing a = −(2gAρ/m)x with SHM equation a = −ω²x:
ω² = 2gAρ/m = (2 × 9.81 × 1.0 × 10⁻⁴ × 1000)/0.052
ω² = (1.962)/0.052 = 37.73 rad² s⁻²
ω = 6.143 rad s⁻¹
T = 2π/ω = 2π/6.143 = 1.023 s ≈ 1 s ✓`,
  "phys-ocra-h556-2022-p1::20(b)(ii)2": `The graph should show a cosine curve (since at t = 0, x = 5.0 cm = maximum displacement). Starting at x = +5.0 cm at t = 0, the curve decreases to zero at t = T/4 ≈ 0.25 s, reaches a minimum of approximately −4 cm (slightly less than −5.0 cm due to damping) at t ≈ 0.5 s, returns through zero at t ≈ 0.75 s, and reaches a reduced maximum of about +4 cm at t = T ≈ 1.0 s. The amplitude decreases gradually with each oscillation (exponential envelope). Time axis values: 0, 0.5, 1.0, 1.5, 2.0 s. The oscillations are slightly damped so the amplitude reduces with each cycle while the period remains approximately constant at 1 s.`,
  "phys-ocra-h556-2022-p1::20(b)(ii)3": `The natural frequency of the water's oscillation is approximately 1 Hz (T ≈ 1 s). The driving frequency from the gas supply is also about 1 Hz. This means the driving frequency matches the natural frequency of the U-tube water system, causing resonance. At resonance, the amplitude of oscillation of the water increases significantly (would increase to very large values if undamped, but the slight damping limits the amplitude to a large but finite value). The water will oscillate with large amplitude.`,
  "phys-ocra-h556-2022-p1::21(a)": `The initial collapse of the nebula is caused by gravity (gravitational attraction between the gas and dust particles). The gravitational potential energy of the particles is converted to kinetic energy as they fall inward.`,
  "phys-ocra-h556-2022-p1::21(b)(i)": `Diameter = 6.4 pc; radius = 3.2 pc
Convert to metres: r = 3.2 × 3.1 × 10¹⁶ = 9.92 × 10¹⁶ m
Volume = (4/3)πr³ = (4/3) × π × (9.92 × 10¹⁶)³
= (4/3) × π × 9.762 × 10⁵⁰
= 4.189 × 9.762 × 10⁵⁰
= 4.089 × 10⁵¹ ≈ 4.1 × 10⁵¹ m³ ✓`,
  "phys-ocra-h556-2022-p1::21(b)(ii)": `Total number of particles N = n × V = 1.0 × 10¹² × 4.1 × 10⁵¹ = 4.1 × 10⁶³
Mean kinetic energy per particle = (3/2)k_BT = (3/2) × 1.38 × 10⁻²³ × 250
= 1.5 × 3.45 × 10⁻²¹ = 5.175 × 10⁻²¹ J
Total kinetic energy:
E_k = N × (3/2)k_BT = 4.1 × 10⁶³ × 5.175 × 10⁻²¹
= 2.12 × 10⁴³ J ≈ 2.1 × 10⁴³ J`,
  "phys-ocra-h556-2022-p1::21(c)(i)": `Number of particles is proportional to volume (assuming same particle density of 1.0 × 10¹² m⁻³).
Volume ∝ diameter³.
V_X/V_Sun_nebula = (6.4/3.0)³ = (2.133)³ = 9.703
Mass ∝ Volume (same particle density and same composition means same average particle mass).
Mass_X/Mass_Sun_nebula = 9.703
Since nebula that formed the Sun has mass ≈ mass of Sun:
Mass_X/Mass_Sun = 9.7 ≈ 9.7
Ratio ≈ 9.7`,
  "phys-ocra-h556-2022-p1::21(c)(ii)": `After forming as a stable main-sequence star (much more massive than the Sun), nebula X will burn through its hydrogen fuel relatively quickly due to its high luminosity. When its core hydrogen is exhausted, the star will expand into a red supergiant. The core will contract and heat, fusing heavier elements (helium, then carbon, oxygen, neon, silicon) successively until an iron core forms. Since iron fusion is endothermic, no further energy can be released by fusion. The iron core collapses catastrophically under gravity, triggering a supernova explosion. The outer layers are ejected as a supernova remnant (forming a nebula). The remnant core, if massive enough (above about 3 solar masses), will collapse further to form a black hole; otherwise it forms a neutron star.`,
  "phys-ocra-h556-2022-p1::22(a)": `From Stefan's law: L = 4πr²σT⁴, so r = √(L/(4πσT⁴)).
The fractional uncertainty in r is:
Δr/r = (1/2)(ΔL/L) + 2(ΔT/T)
The term from T has a factor of 2 (from T⁴, which gives 4 × ΔT/T, combined with the ½ from the square root → 2ΔT/T). If the percentage uncertainty in T is larger than ΔL/L after accounting for these factors, then T should be measured more precisely. Since ΔT/T is multiplied by 2 but ΔL/L is multiplied by ½, a given percentage uncertainty in T contributes four times as much to the uncertainty in r as the same percentage uncertainty in L. Therefore the astronomers should measure T more precisely to have the greater effect on reducing the uncertainty in r.`,
  "phys-ocra-h556-2022-p1::22(b)": `Determining b: From the table, plotting lg(L/L☉) against lg(M/M☉) gives a straight line with gradient b. Using the data points:
• Pi Andromedae A: lg(6.5) = 0.813, lg(800) = 2.903
• 70 Ophiuchi A: lg(0.78) = −0.108, lg(0.4) = −0.398
Gradient = (2.903 − (−0.398))/(0.813 − (−0.108)) = 3.301/0.921 = 3.58
So b ≈ 3.6 (or 3.5–3.9 range is acceptable).

Comparing lifespans using the HR diagram: Hotter main-sequence stars are more luminous and more massive. Since L ∝ M^b, hotter stars have much greater luminosity and fuse hydrogen far faster. The main-sequence lifetime of a star is proportional to M/L ∝ M/M^b = M^(1−b). Since b > 1 (b ≈ 3.6), the exponent (1 − b) is negative, meaning lifetime ∝ M^(1−b) decreases with increasing mass. Therefore hotter (more massive, more luminous) stars have shorter lifespans than cooler stars. A star ten times as massive lives far less than one-tenth as long.`,
  "phys-ocra-h556-2022-p1::23(a)": `For a planet of mass m in circular orbit of radius r around a star of mass M:
Gravitational force provides centripetal force:
GMm/r² = mv²/r = mω²r = m(2π/T)²r
GM/r² = (4π²/T²)r
GM × T² = 4π²r³
T² = (4π²/GM)r³
Since G, π, and M are constants for a given star:
T² ∝ r³ ✓`,
  "phys-ocra-h556-2022-p1::23(b)(i)": `Using Kepler's third law: T²/r³ = constant (same for all objects orbiting the Sun).
T_Earth = 365 days, r_Earth = 1.50 × 10¹¹ m
T_satellite = 168 days
r_satellite³ = r_Earth³ × (T_satellite/T_Earth)²
r_satellite³ = (1.50 × 10¹¹)³ × (168/365)²
= 3.375 × 10³³ × 0.2120
= 7.155 × 10³² m³
r_satellite = (7.155 × 10³²)^(1/3) = 8.946 × 10¹⁰ m ≈ 8.9 × 10¹⁰ m`,
  "phys-ocra-h556-2022-p1::23(b)(ii)": `The total mechanical energy E = KE + GPE is conserved.
At furthest point: r_far = 1.37 × 10¹¹ m
At closest point: r_close = 4.20 × 10¹⁰ m
Change in KE = −(change in GPE)
ΔKE = KE_close − KE_far = −(GPE_close − GPE_far)
ΔKE = GPE_far − GPE_close = −GMm/r_far − (−GMm/r_close)
ΔKE = GMm(1/r_close − 1/r_far)
G = 6.67 × 10⁻¹¹ N m² kg⁻², M = 2.0 × 10³⁰ kg, m = 209 kg
GMm = 6.67 × 10⁻¹¹ × 2.0 × 10³⁰ × 209 = 2.790 × 10²² J m
ΔKE = 2.790 × 10²² × (1/(4.20 × 10¹⁰) − 1/(1.37 × 10¹¹))
= 2.790 × 10²² × (2.381 × 10⁻¹¹ − 7.299 × 10⁻¹²)
= 2.790 × 10²² × 1.651 × 10⁻¹¹
= 4.61 × 10¹¹ J ≈ 4.6 × 10¹¹ J`,
  "phys-ocra-h556-2022-p1::23(b)(iii)": `During launch from Earth's surface, energy is provided to the satellite by the rocket engines (fuel is burned), increasing the total mechanical energy of the satellite. The satellite gains both kinetic energy and gravitational potential energy during the launch phase. Therefore the total energy of the satellite in its orbit around the Sun is greater than it would have been if it had simply been moved there without engines, and is different from the energy state at the surface of the Earth.`,
  "phys-ocra-h556-2022-p2::16(a)(i)": `The wavelength of the wave is 2.0 cm.
The two points are 2.5 − 1.5 = 1.0 cm apart, which is exactly half a wavelength.
Phase difference φ = (path difference / λ) × 2π = (1.0/2.0) × 2π
φ = π rad (3.1 rad)`,
  "phys-ocra-h556-2022-p2::16(a)(ii)": `The wave is progressive and travels in the direction of increasing x, so in a time of 3T/4 the whole waveform moves 3λ/4 = 3 × 2.0/4 = 1.5 cm to the right.
The displacement at x = 1.5 cm at t = 3T/4 is therefore the displacement that was at x = 1.5 − 1.5 = 0 at t = 0.
At t = 0 the graph shows a trough at x = 0, so
s = −5.0 cm`,
  "phys-ocra-h556-2022-p2::16(b)": `M is the central bright fringe, where the path difference is zero. Working outwards from M, the fringes are N (the first dark fringe, path difference ½λ), O (the first bright fringe, path difference λ), P (the second dark fringe) and Q (the second bright fringe, path difference 2λ).
P is the second dark fringe, so the waves from the two slits arrive one and a half wavelengths out of step:
φ = 540°
d = 1.5λ`,
  "phys-ocra-h556-2022-p2::16(c)(i)": `At the nodes, the air molecules are stationary (zero displacement). The powder is moved away from antinodes (where displacement is maximum) towards the nodes by the oscillating air, and accumulates at the nodes because there is no net force to move it once it reaches a stationary point.`,
  "phys-ocra-h556-2022-p2::16(c)(ii)": `The powder collects at the nodes of the stationary wave, and adjacent nodes are half a wavelength apart.
The 25.0 cm marked on Fig. 16.2 is measured from the first to the fifth of the five piles, so it spans four node-to-node gaps:
4 × λ/2 = 25.0 cm, i.e. 2λ = 25.0 cm
λ = 12.5 cm = 0.125 m
v = fλ = 2720 × 0.125
v = 340 m s⁻¹`,
  "phys-ocra-h556-2022-p2::16(c)(iii)": `The tube is closed at one end and open at the loudspeaker end, so any stationary wave in it has a node at the closed end and an antinode at the open end.
There are six nodes in the tube: the powder at the closed end plus the five piles. The fifth pile is therefore 5 × λ/2 = 5 × 6.25 = 31.25 cm from the closed end, and the open end is a further λ/4 = 3.125 cm beyond it, so the length of the tube is
L = 31.25 + 3.125 = 34.4 cm = 0.344 m (= 11λ/4)
For the fundamental there is just one node (at the closed end) and one antinode (at the open end), so L = λ₀/4 and
λ₀ = 4L = 4 × 0.34375 = 1.375 m
f₀ = v/λ₀ = 340/1.375 = 247 Hz (about 250 Hz)
Equivalently, since L = 11λ/4 the 2.72 kHz note is the 11th harmonic, so f₀ = 2720/11 = 247 Hz.`,
  "phys-ocra-h556-2022-p2::17(a)": `From eV = hc/λ, rearranging: h = eVλ/c.
SI base units of each quantity:
• e (charge): A s (ampere × second)
• V (potential difference): kg m² s⁻³ A⁻¹ (= J/C = J A⁻¹ s⁻¹)
• λ (wavelength): m
• c (speed of light): m s⁻¹
h = (A s)(kg m² s⁻³ A⁻¹)(m)/(m s⁻¹)
= (A s × kg m² s⁻³ A⁻¹ × m × s)/(m)
= kg m² s⁻¹
SI base units of h: kg m² s⁻¹`,
  "phys-ocra-h556-2022-p2::17(b)": `Equipment needed: a set of LEDs with known wavelengths (or wavelengths measured with a diffraction grating/spectrometer), a variable power supply, a voltmeter, a milliammeter, and connecting wires.

Determining λ: Use a diffraction grating with known slit spacing d. Illuminate the grating with light from the lit LED. Measure the angle θ of the first-order maximum using a protractor or optical bench. Use nλ = d sinθ (n = 1) to calculate λ accurately for each LED colour.

Determining V (threshold voltage): Connect each LED in series with the power supply, voltmeter, and milliammeter. Gradually increase the voltage from zero while monitoring the current. Record the threshold voltage V at which the LED just begins to emit light (indicated by a small current flowing). This threshold voltage corresponds to the photon energy: eV = hc/λ.

Plotting the graph: Rearrange eV = hc/λ to give V = (hc/e) × (1/λ). Plot V (y-axis) against 1/λ (x-axis). A straight line through the origin (or with small intercept due to contact potential) should result. The gradient = hc/e. Since c and e are known, calculate h = gradient × e/c from the gradient of the best-fit line.`,
  "phys-ocra-h556-2022-p2::18(a)": `The e.m.f. of the battery represents the energy transferred to the charge per unit charge by the chemical processes inside the battery (energy input per coulomb). The potential difference (p.d.) across the variable resistor represents the energy transferred from electrical energy to thermal energy (heat) per unit coulomb in the resistor (energy output per coulomb). The e.m.f. equals the total p.d. around the circuit (Kirchhoff's second law); the p.d. across the variable resistor is the e.m.f. minus the p.d. across the internal resistance.`,
  "phys-ocra-h556-2022-p2::18(b)": `The length of the wire. Since R = ρL/A, increasing the length of the wire included in the circuit increases the resistance of the variable resistor.`,
  "phys-ocra-h556-2022-p2::18(c)(i)": `E = I(R + r) [Kirchhoff's second law / e.m.f. equation]
Divide both sides by IE:
1/I = (R + r)/E
1/I = R/E + r/E ✓`,
  "phys-ocra-h556-2022-p2::18(c)(ii)1": `From the graph, when R = 3.0 Ω the value of 1/I is 0.80 A⁻¹.
I = 1/0.80 = 1.25 A
Power dissipated in the variable resistor:
P = I²R = 1.25² × 3.0 = 4.69
P = 4.7 W`,
  "phys-ocra-h556-2022-p2::18(c)(ii)2": `Comparing 1/I = R/E + r/E with y = mx + c, the intercept on the 1/I axis (where R = 0) is r/E.
Extrapolating the straight line back to R = 0 gives an intercept of 0.20 A⁻¹.
r/E = 0.20 A⁻¹
r = 0.20 × E = 0.20 × 5.0
r = 1.0 Ω`,
  "phys-ocra-h556-2022-p2::19(a)": `Einstein's photoelectric equation: hf = φ + KE(max)
Energy of each incident photon:
hf = 6.63 × 10⁻³⁴ × 6.3 × 10¹⁴ = 4.18 × 10⁻¹⁹ J
In electronvolts: 4.18 × 10⁻¹⁹ / 1.60 × 10⁻¹⁹ = 2.61 eV
The maximum kinetic energy of the photoelectrons is 0.30 eV, so the work function is
φ = 2.61 − 0.30
φ = 2.3 eV
(In joules: φ = 4.18 × 10⁻¹⁹ − 4.8 × 10⁻²⁰ = 3.70 × 10⁻¹⁹ J, which is 2.3 eV.)`,
  "phys-ocra-h556-2022-p2::19(b)(i)": `The plates are parallel, so the electric field between them is uniform:
E = V/d = 0.30/(6.0 × 10⁻³) = 50 V m⁻¹
The electric force on the photoelectron (charge e = 1.60 × 10⁻¹⁹ C) is
F = eE = 1.60 × 10⁻¹⁹ × 50 = 8.0 × 10⁻¹⁸ N
This force acts back towards plate E, opposing the motion, so from F = ma the magnitude of the deceleration is
a = F/mₑ = 8.0 × 10⁻¹⁸ / 9.11 × 10⁻³¹
a = 8.78 × 10¹² m s⁻², i.e. 8.8 × 10¹² m s⁻² as required.`,
  "phys-ocra-h556-2022-p2::19(b)(ii)": `KE = ½m_e v²
4.8×10⁻²⁰ = ½ × 9.11×10⁻³¹ × v²
v² = (2 × 4.8×10⁻²⁰)/(9.11×10⁻³¹)
= 9.6×10⁻²⁰ / 9.11×10⁻³¹
= 1.054×10¹¹ m² s⁻²
v = 3.24×10⁵ m s⁻¹ ≈ 3×10⁵ m s⁻¹ ✓`,
  "phys-ocra-h556-2022-p2::19(b)(iii)": `The electron decelerates from v₀ = 3.24×10⁵ m s⁻¹ to rest (v = 0) over a distance of 6.0 mm = 6.0×10⁻³ m (since at plate C its KE = 0, as V = 0.30 V just stops it exactly).
Using v = v₀ − at:
0 = 3.24×10⁵ − 8.8×10¹² × t
t = 3.24×10⁵ / 8.8×10¹² = 3.7×10⁻⁸ s
Or using v² = v₀² − 2as and then v = v₀ − at:
t = v₀/a = 3.24×10⁵ / 8.8×10¹² = 3.7×10⁻⁸ s ≈ 37 ns`,
  "phys-ocra-h556-2022-p2::19(b)(iv)": `The graph of KE against x from plate E should show: starting at KE = 4.8×10⁻²⁰ J (i.e. 4.8 on the Ek/10⁻²⁰ J axis) at x = 0. Since the electric field between parallel plates is uniform, the force on the electron is constant, so the deceleration is constant. This means KE decreases linearly with distance x (since work done = Fx, so KE = KE₀ − Fx). The graph is a straight line with negative gradient, starting at (0, 4.8) and ending at (6.0 mm, 0). The line is perfectly straight (constant deceleration → linear decrease in KE with distance).`,
  "phys-ocra-h556-2022-p2::19(c)": `A photon of higher frequency carries more energy, since E = hf. The work function of potassium is unchanged, so from hf = φ + KE(max) the photoelectrons are now emitted from plate E with a greater maximum kinetic energy, and therefore a greater speed.
Previously the fastest photoelectrons only just reached plate C, arriving with zero kinetic energy, so no charge flowed and the ammeter read zero. Now the electrons have more kinetic energy than is needed to work against the retarding p.d., so they arrive at plate C with kinetic energy to spare, charge flows round the circuit and the ammeter gives a reading (it is no longer zero).`,
  "phys-ocra-h556-2022-p2::20(a)": `The two forces acting between the proton and the neutron are the strong nuclear force and the gravitational force.

The strong nuclear force has a very short range, acting only up to a separation of about 3 fm (3 × 10⁻¹⁵ m) and falling to zero beyond this. It is attractive for separations between about 0.5 fm and 3 fm, which is what binds the proton and neutron together, but it becomes repulsive at separations below about 0.5 fm, which stops the nucleons being pulled into one another. It acts equally between all nucleons and does not depend on charge.

The gravitational force acts between the two hadrons because they both have mass. It is always attractive, obeys an inverse square law and has an infinite (unlimited) range, but at nuclear separations it is many orders of magnitude weaker than the strong nuclear force and so is negligible.

(There is no electrostatic force between them, because the neutron carries no charge.)`,
  "phys-ocra-h556-2022-p2::20(b)": `Carbon-14 and beta-minus decay. A carbon-14 nucleus contains 14 nucleons: 6 protons and 8 neutrons. In β⁻ decay one neutron changes into a proton, emitting an electron and an antineutrino:
¹⁴₆C → ¹⁴₇N + ⁰₋₁e (+ antineutrino)
After the decay the nucleus has 7 protons and 7 neutrons. A proton is the quark combination uud and a neutron is udd, so before the decay there are (6 × 2) + (8 × 1) = 20 up quarks and (6 × 1) + (8 × 2) = 22 down quarks, and afterwards there are 21 up quarks and 21 down quarks. In other words a single down quark inside one neutron has changed into an up quark, turning that neutron into a proton.

Uranium-235 and alpha decay. A uranium-235 nucleus contains 92 protons and 143 neutrons. In alpha decay an alpha particle (a helium-4 nucleus, 2 protons and 2 neutrons) is emitted:
²³⁵₉₂U → ²³¹₉₀Th + ⁴₂He
The daughter nucleus has 90 protons and 141 neutrons. The two protons and two neutrons carried away contain (2 × 2) + (2 × 1) = 6 up quarks and (2 × 1) + (2 × 2) = 6 down quarks, so the nucleus is left with 6 fewer up quarks and 6 fewer down quarks. No quark changes flavour in alpha decay.

Densities. Taking 1 u = 1.66 × 10⁻²⁷ kg and modelling each nucleus as a sphere of volume (4/3)πr³:
Carbon-14: m = 14.0 × 1.66 × 10⁻²⁷ = 2.32 × 10⁻²⁶ kg; V = (4/3)π(2.9 × 10⁻¹⁵)³ = 1.02 × 10⁻⁴³ m³;
ρ = 2.32 × 10⁻²⁶ / 1.02 × 10⁻⁴³ = 2.3 × 10¹⁷ kg m⁻³
Uranium-235: m = 235.0 × 1.66 × 10⁻²⁷ = 3.90 × 10⁻²⁵ kg; V = (4/3)π(7.4 × 10⁻¹⁵)³ = 1.70 × 10⁻⁴² m³;
ρ = 3.90 × 10⁻²⁵ / 1.70 × 10⁻⁴² = 2.3 × 10¹⁷ kg m⁻³
Both nuclei have a density of about 2.3 × 10¹⁷ kg m⁻³, so they have the same density. This is because the mass ratio, 235.0/14.0 = 16.8, is essentially the same as the volume ratio, (7.4/2.9)³ = 16.6; the nuclear radius is proportional to the cube root of the nucleon number, so mass and volume increase in the same proportion and nuclear density is constant.`,
  "phys-ocra-h556-2022-p2::21(a)": `Initially, with the switch closed, a steady direct current flows through coil A, creating a constant magnetic field through the iron rod. A constant magnetic field means constant (steady) magnetic flux linking coil B, and therefore zero rate of change of flux linkage. By Faraday's law, the induced e.m.f. in coil B is zero, so no current flows through the lamp, and it is off.

When the switch is opened, the current in coil A falls to zero. The magnetic flux through the iron rod (and through coil B) decreases rapidly from its steady value to zero. By Faraday's law, this changing flux linkage induces an e.m.f. in coil B equal to −N × dΦ/dt. This e.m.f. drives a brief current through the lamp, causing it to flash on momentarily.

Once the current in A has fully dropped to zero, the flux becomes constant (at zero), so dΦ/dt = 0 again and the induced e.m.f. in B returns to zero. The lamp goes off and remains off.`,
  "phys-ocra-h556-2022-p2::21(b)(i)": `An oscilloscope (cathode-ray oscilloscope or digital oscilloscope).`,
  "phys-ocra-h556-2022-p2::21(b)(ii)1": `The 'rate' part of Faraday's law refers to the rate of change of flux. In the equation E₀ = KI₀ANf sinθ, the quantity linked to the rate is f (frequency), since higher frequency means the flux changes more rapidly (the flux oscillates faster, so dΦ/dt is larger in proportion to f).`,
  "phys-ocra-h556-2022-p2::21(b)(ii)2": `The 'change of magnetic flux linkage' part involves: I₀ (the maximum current, which determines the maximum magnetic field strength and hence the maximum flux), A (cross-sectional area of the search coil, which determines how much flux links the coil), N (number of turns of the search coil, since flux linkage = NΦ), and sinθ (the component of the flux perpendicular to the plane of the coil, which determines the flux linkage).`,
  "phys-ocra-h556-2022-p2::21(b)(iii)": `The gradient of the straight line of E₀ against sinθ is KI₀ANf, so
f = gradient/(KI₀AN)
f = 0.62 / (4.0 × 10⁻³ × 8.0 × 7.8 × 10⁻⁵ × 5000)
f = 0.62 / (1.248 × 10⁻²) = 49.7 Hz
For a product like this the percentage uncertainties add (N has no quoted uncertainty):
gradient: 0.03/0.62 = 4.8%
I₀: 0.2/8.0 = 2.5%
A: 0.1/7.8 = 1.3%
total percentage uncertainty = 4.8 + 2.5 + 1.3 = 8.6%
absolute uncertainty = 0.086 × 49.7 = 4.3 Hz
To 2 significant figures:
f = 50 ± 4 Hz`,
  "phys-ocra-h556-2022-p2::22(a)(i)1": `Capacitance C = ε₀A/d (for a parallel plate capacitor in vacuum). When separation doubles to 2d:
C_new = ε₀A/(2d) = C₀/2`,
  "phys-ocra-h556-2022-p2::22(a)(i)2": `Q remains constant (= Q₀). V = Q/C, so:
V_new = Q₀/(C₀/2) = 2Q₀/C₀ = 2V₀`,
  "phys-ocra-h556-2022-p2::22(a)(i)3": `Energy stored E = Q²/(2C) = Q₀²/(2 × C₀/2) = Q₀²/C₀ = 2 × (Q₀²/(2C₀)) = 2E₀`,
  "phys-ocra-h556-2022-p2::22(a)(ii)": `The oppositely charged plates attract each other. To increase the separation from d to 2d, an external force must do work against this attractive force between the plates. The work done by the external force is stored as electrical potential energy in the capacitor, increasing the energy stored. Equivalently, the electric field between the plates (which exerts an attractive force on the plates) must be opposed, requiring input of energy.`,
  "phys-ocra-h556-2022-p2::22(b)(i)": `The capacitor discharges according to V = V₀ e^(−t/RC). The p.d. is halved when V = V₀/2:
V₀/2 = V₀ e^(−T/RC)
1/2 = e^(−T/RC)
ln(1/2) = −T/RC
T/RC = ln2
T = RC ln2
Rearranging: T = (ln2)C × R
So T is linear in R, with gradient = C ln2. ✓`,
  "phys-ocra-h556-2022-p2::22(b)(ii)1": `Draw the best-fit straight line so that it passes through every error bar.
Taking a large triangle on that line, for example from (12.0 MΩ, 0.070 s) to (20.0 MΩ, 0.113 s):
gradient = (0.113 − 0.070)/((20.0 − 12.0) × 10⁶) = 0.043/(8.0 × 10⁶)
gradient = 5.4 × 10⁻⁹ s Ω⁻¹
From (b)(i) the gradient is C ln2, so
C = gradient/ln2 = 5.4 × 10⁻⁹/0.693
C = 7.8 × 10⁻⁹ F (7.8 nF)`,
  "phys-ocra-h556-2022-p2::22(b)(ii)2": `For a parallel-plate capacitor with the paper acting as the dielectric, C = εA/d, so ε = Cd/A.
C = 7.8 × 10⁻⁹ F, d = 8.0 × 10⁻⁵ m, A = 3.1 × 10⁻² m²
ε = (7.8 × 10⁻⁹ × 8.0 × 10⁻⁵)/(3.1 × 10⁻²)
ε = 6.24 × 10⁻¹³/3.1 × 10⁻²
ε = 2.0 × 10⁻¹¹ F m⁻¹`,
  "phys-ocra-h556-2022-p2::23(a)": `The collimator must be long and narrow to ensure that only gamma rays (photons) travelling in one specific direction (parallel to the axis of the collimator) can pass through. If the collimator were short or wide, gamma photons arriving at oblique angles would also pass through, reducing the spatial resolution of the image — the camera would not be able to pinpoint accurately where in the body the gamma photons originated.`,
  "phys-ocra-h556-2022-p2::23(b)": `The scintillator converts (absorbs) each incoming gamma-ray photon into a pulse of visible light photons. The gamma photon has too high a frequency to be detected directly by the photomultiplier tube, so the scintillator acts as a transducer, producing visible light that can then be detected.`,
  "phys-ocra-h556-2022-p2::23(c)": `The charge that flows during the pulse is
Q = It = 0.32 × 10⁻⁶ × 1.2 × 10⁻⁹ = 3.84 × 10⁻¹⁶ C
Each electron carries a charge of 1.60 × 10⁻¹⁹ C, so the number of electrons is
n = Q/e = 3.84 × 10⁻¹⁶ / 1.60 × 10⁻¹⁹
n = 2400`,
  "phys-ocra-h556-2022-p2::23(d)": `Diagnosing the function and blood flow of organs such as the thyroid gland, heart, kidneys, or lungs (e.g. thyroid scan, bone scan, or cardiac stress test).`,
  "phys-ocra-h556-2022-p2::24(a)": `In Compton scattering, an incoming X-ray photon interacts with a loosely bound (or free) electron in the material. The photon transfers some of its energy and momentum to the electron, which recoils. The photon is scattered at an angle with a lower frequency (longer wavelength) than the incident photon, since it has lost energy. The electron gains kinetic energy. The X-ray beam is attenuated because some photons are scattered out of the beam direction and some energy is transferred to electrons.`,
  "phys-ocra-h556-2022-p2::24(b)(i)": `The tissue is uniform between x = 0 and x = 1.0 cm, so the intensity falls exponentially there:
I = I₀e⁻ᵘˣ
Reading Fig. 24.2 at the two ends of this region: at x = 0, I₀ = 3.0 × 10³ W m⁻²; at x = 1.0 cm, I = 1.3 × 10³ W m⁻².
1.3 × 10³ = 3.0 × 10³ × e⁻ᵘ × ¹·⁰
μ × 1.0 = ln(3.0/1.3) = ln(2.31)
μ = 0.84 cm⁻¹`,
  "phys-ocra-h556-2022-p2::24(b)(ii)": `From Fig. 24.2 the intensity at a depth of x = 1.0 cm is I = 1.3 × 10³ W m⁻².
Intensity is the radiant power per unit area, so the energy delivered to an area A in a time t is E = I × A × t.
Here A = 1 cm² = 1.0 × 10⁻⁴ m² and E = 2.6 J:
2.6 = 1.3 × 10³ × 1.0 × 10⁻⁴ × t
2.6 = 0.13t
t = 20 s`,
  "phys-ocra-h556-2022-p2::24(b)(iii)": `Beyond x = 1.0 cm, the tissue has a larger attenuation coefficient μ₂ > μ₁. The intensity still decreases exponentially but with a steeper gradient (more rapid decrease). The curve on Fig. 24.2 should continue from where it left off at x = 1.0 cm, curving downward more steeply than the original exponential, maintaining a continuous join at x = 1.0 cm but with a smaller (more negative) gradient. It remains an exponential decay curve, but with a shorter 'half-thickness'.`,
  "phys-ocra-h556-2022-p3::1(a)": `g = GM/r², with M = 4.87 × 10²⁴ kg and r = 6050 km = 6.050 × 10⁶ m.
g = (6.67 × 10⁻¹¹ × 4.87 × 10²⁴) / (6.050 × 10⁶)²
g = 3.248 × 10¹⁴ / 3.660 × 10¹³
g = 8.87 N kg⁻¹ (to 3 significant figures)`,
  "phys-ocra-h556-2022-p3::1(b)(i)": `Probe B at the equator is carried round a circle whose radius is the radius of Venus, r = 6050 km = 6.050 × 10⁶ m, once every rotation period T = 5830 hours = 5830 × 3600 = 2.099 × 10⁷ s.
ω = 2π/T = 2π / (2.099 × 10⁷) = 2.99 × 10⁻⁷ rad s⁻¹
a = ω²r = (2.99 × 10⁻⁷)² × 6.050 × 10⁶
a = 5.42 × 10⁻⁷ m s⁻² (≈ 5.4 × 10⁻⁷ m s⁻²)`,
  "phys-ocra-h556-2022-p3::1(b)(ii)": `Upthrust = weight of atmosphere displaced by probe = ρ_atm × V × g
The density of Venus's atmosphere at the surface ≈ 65 kg m⁻³ (from the question paper data).
Upthrust = 65 × 1.7 × 8.87
= 65 × 15.08
= 980 N ≈ 980 N`,
  "phys-ocra-h556-2022-p3::1(b)(iii)": `Both probes are identical, so each has the same weight W = mg = 760 × 8.87 = 6740 N and each experiences the same upthrust U = 980 N from the atmosphere.

Probe A is at the north pole, on the axis of rotation, so it moves in a circle of essentially zero radius and needs no centripetal force. Its forces are therefore balanced:
R_A = W − U = 6740 − 980 = 5760 N

Probe B is on the equator, so it travels in a circle of radius 6.05 × 10⁶ m and there must be a resultant force on it directed towards the centre of Venus. Applying Newton's second law along that direction:
W − U − R_B = ma
R_B = W − U − ma = 5760 − (760 × 5.42 × 10⁻⁷) = 5760 − 4.1 × 10⁻⁴ N

Because some of the resultant of the weight and the upthrust on B is "used up" in providing the centripetal force, the surface has to push up on B slightly less hard than on A. Probe A therefore experiences the greater normal contact force, although the difference is only about 4 × 10⁻⁴ N and so would be impossible to measure in practice.`,
  "phys-ocra-h556-2022-p3::2(a)": `Set up the rod pivoted at one end (clamped or through a pin) so it can swing freely. Displace the rod by a small angle and release. Use a stopwatch to time the oscillations. To reduce uncertainty, time a large number of complete oscillations (e.g. 20 oscillations) and divide by the number to get the period T. Repeat the timing three times and take the mean value of T. A fiducial marker at the equilibrium position helps identify the exact moment the rod passes through equilibrium.`,
  "phys-ocra-h556-2022-p3::2(b)(i)": `f = (1/2π)√(3g/2L), so T = 1/f = 2π√(2L/3g)
T² = 4π² × (2L/3g) = (8π²/3g) × L
Therefore, plotting T² against L gives a straight line through the origin with gradient = 8π²/(3g). ✓`,
  "phys-ocra-h556-2022-p3::2(b)(ii)": `Gradient = 8π²/(3g)
g = 8π²/(3 × gradient) = 8π²/(3 × 2.64)
= 8 × 9.870 / 7.92
= 78.96 / 7.92
= 9.97 m s⁻² ≈ 9.97 m s⁻²`,
  "phys-ocra-h556-2022-p3::2(b)(iii)": `The worst-fit line is the steepest (or the shallowest) straight line that still passes through every error bar. For the steepest line, use a ruler to draw a single straight line from the bottom of the error bar on the first point, (0.080 m, 0.21 s²), to the top of the error bar on the last point, (0.200 m, 0.56 s²), checking as you draw that it passes inside all of the error bars in between. (The shallowest line, drawn from (0.080 m, 0.25 s²) to (0.200 m, 0.50 s²), is equally acceptable.) Label it clearly so that it is not confused with the line of best fit.`,
  "phys-ocra-h556-2022-p3::2(b)(iv)": `Find the gradient of the worst-fit line using a large triangle covering the whole range of L. For the steepest worst line, from (0.080 m, 0.21 s²) to (0.200 m, 0.56 s²):
gradient_worst = (0.56 − 0.21) / (0.200 − 0.080) = 0.35 / 0.120 = 2.92 s² m⁻¹

Use this gradient to find the worst value of g in the same way as in (b)(ii):
g_worst = 8π² / (3 × 2.92) = 78.96 / 8.76 = 9.01 m s⁻²

percentage uncertainty in g = |g_worst − g| / g × 100% = (9.97 − 9.01) / 9.97 × 100%
percentage uncertainty in g ≈ 10%

(Equivalently, because g is inversely proportional to the gradient, the percentage uncertainty in the gradient, (2.92 − 2.64)/2.64 × 100% ≈ 11%, gives the same answer to within the precision of the readings.)`,
  "phys-ocra-h556-2022-p3::2(b)(v)": `The student's value is g = 9.97 m s⁻² and the true value is 9.81 m s⁻².
Difference = |9.97 − 9.81| = 0.16 m s⁻²
Percentage difference = (0.16/9.81) × 100% = 1.6%
If the percentage uncertainty calculated in (b)(iv) is, say, 9%, then 1.6% < 9%, meaning the true value lies within the uncertainty range of the student's result. The experiment is therefore accurate — the result is consistent with the true value within experimental uncertainty.`,
  "phys-ocra-h556-2022-p3::3(a)": `In β⁺ decay, a proton decays to a neutron, a positron, and a neutrino:
¹₁p → ¹₀n + ⁰₁e + ⁰₀ν_e
Or in terms of a nuclide X decaying:
^A_Z X → ^A_(Z-1) Y + ⁰₁e⁺ + ⁰₀ν_e
The three particles produced are: a neutron (remains in the nucleus), a positron (β⁺ particle, charge +e), and an electron neutrino (ν_e).`,
  "phys-ocra-h556-2022-p3::3(b)": `Safety must come first. Each sealed source should be picked up only with long-handled tongs, never by hand, and clamped so that it points away from everyone in the room. Keep as far from the sources as the measurements allow, take them out of their lead-lined store only for as long as is needed, and return them as soon as the readings are finished.

Before testing anything, lock all three sources away and use the GM tube and counter to record the count over a fixed time, for example 60 s. This gives the background count rate, which must be subtracted from every reading taken afterwards so that only the count due to the source is used.

Now take each source in turn. Clamp it a fixed short distance from the GM tube and record the corrected count rate. Then place sheets of aluminium of increasing thickness between the source and the tube, recording the corrected count rate for each thickness. Two of the sources will be stopped by a few millimetres of aluminium: these are the beta emitters. The third still gives a substantial count rate through several millimetres of aluminium, and is only appreciably reduced by a thick sheet of lead: this is the gamma source. The same conclusion follows from moving the counter away from each source and recording how the count rate falls with distance, because gamma rays have much the longest range in air while the two beta sources have similar, much shorter ranges.

To tell the two beta sources apart, use the strong magnet to set up a magnetic field at right angles to the direction in which the particles travel. Gamma rays are uncharged and are not deflected at all, but beta particles are charged and so are deflected by the field. Move the GM tube to one side and then the other of the undeflected path to find which way each beam bends. Beta-minus particles are electrons and beta-plus particles are positrons, so they carry opposite charges and are deflected in opposite directions by the same field. Applying Fleming's left-hand rule (remembering that for the positrons the conventional current is in the direction the particles travel, and for the electrons it is in the opposite direction) predicts which way a positive beam should bend, so the source whose beam bends that way is the beta-plus emitter and the other is the beta-minus emitter.`,
  "phys-ocra-h556-2022-p3::4(a)": `The microwave background radiation (CMB) originated from the early universe, approximately 380 000 years after the Big Bang, at the epoch of recombination. Before this time, the universe was so hot and dense that matter was in the form of a plasma — electrons were not bound to nuclei. Photons were constantly scattered by free electrons and could not travel freely. When the universe cooled sufficiently (to about 3000 K), electrons combined with protons to form neutral hydrogen atoms. The universe became transparent to radiation for the first time. The photons that were released at this point have been travelling through the universe ever since. Due to the expansion of the universe, these photons have been redshifted from their original infrared/optical wavelengths to microwave wavelengths, giving the CMB we observe today.`,
  "phys-ocra-h556-2022-p3::4(b)(i)": `In the distant past the universe was much hotter. According to Wien's displacement law (λ_max T = constant), a higher temperature means the peak intensity is at a shorter wavelength. The spectrum would have the same black-body shape but shifted to the left (shorter wavelengths / higher frequencies), with the peak at a much smaller wavelength than 1.1 mm, and with a much higher intensity (since luminosity ∝ T⁴).`,
  "phys-ocra-h556-2022-p3::4(b)(ii)": `E = hc/λ = (6.63×10⁻³⁴ × 3.00×10⁸) / (1.1×10⁻³)
= 1.989×10⁻²⁵ / 1.1×10⁻³
= 1.81×10⁻²² J ≈ 1.8×10⁻²² J`,
  "phys-ocra-h556-2022-p3::4(b)(iii)": `The microwave background has intensity 3 × 10⁻⁶ W m⁻², and the back of the hand has area
A = 150 cm² = 150 × 10⁻⁴ m² = 1.5 × 10⁻² m²

Power incident on the hand = intensity × area = 3 × 10⁻⁶ × 1.5 × 10⁻² = 4.5 × 10⁻⁸ W

Each photon carries E = 1.8 × 10⁻²² J, from (ii).

number of photons per second = power / energy per photon = 4.5 × 10⁻⁸ / 1.8 × 10⁻²²
= 2.5 × 10¹⁴ s⁻¹`,
  "phys-ocra-h556-2022-p3::4(b)(iv)": `Take a cylindrical tank of top surface area A and depth h = 5.0 m, and let the intensity of the radiation be I = 3 × 10⁻⁶ W m⁻².

Energy absorbed in time t: E = IAt
Mass of water in the tank: m = ρV = ρAh

Since E = mcΔθ, IAt = ρAhcΔθ, and the area A cancels:
Δθ/t = I / (ρhc)
Δθ/t = 3 × 10⁻⁶ / (1000 × 5.0 × 4200) = 3 × 10⁻⁶ / 2.1 × 10⁷
Δθ/t = 1.4 × 10⁻¹³ °C s⁻¹ (about 1 × 10⁻¹³ °C s⁻¹)

A rise of only about 10⁻¹³ °C per second, whatever the area of the tank, shows that the microwave background is useless as an energy source.`,
  "phys-ocra-h556-2022-p3::5(a)(i)": `For a current carried by free electrons, I = nAvq, so at the maximum current
I_max = nAv_max e  and  v_max = I_max / (nAe)

nAe = 8.0 × 10²⁸ × 1.4 × 10⁻⁸ × 1.60 × 10⁻¹⁹
= 1.12 × 10²¹ × 1.60 × 10⁻¹⁹ = 1.79 × 10²

v_max = (20 × 10⁻³) / (8.0 × 10²⁸ × 1.4 × 10⁻⁸ × 1.60 × 10⁻¹⁹) = 0.020 / 179
v_max = 1.1 × 10⁻⁴ m s⁻¹ = 0.11 mm s⁻¹

This is about 0.1 mm s⁻¹, as required.`,
  "phys-ocra-h556-2022-p3::5(a)(ii)": `In SHM, v_max = Aω, where ω = 2πf = 2π × 11×10⁹ = 6.912×10¹⁰ rad s⁻¹.
A = v_max / ω = 1.12×10⁻⁴ / (6.912×10¹⁰)
= 1.62×10⁻¹⁵ m ≈ 1.6×10⁻¹⁵ m
(This is on the order of the size of a proton — the electrons oscillate with extremely tiny amplitude at microwave frequencies.)`,
  "phys-ocra-h556-2022-p3::5(a)(iii)": `In SHM, maximum acceleration a_max = Aω² = v_max × ω (since A = v_max/ω, so Aω² = v_max × ω). 
Since v_max = I_max/(nAq) and remains constant (maximum current is fixed), v_max is constant. Therefore A = v_max/ω = v_max/(2πf) — amplitude decreases as f increases. The maximum acceleration a_max = Aω² = v_max × ω = v_max × 2πf. Since v_max is constant and ω = 2πf increases with f, the maximum acceleration increases proportionally with frequency f.`,
  "phys-ocra-h556-2022-p3::5(b)(i)": `Why the pattern occurs

X and Y are coherent sources of the same frequency, so the waves arriving at the detector from the two transmitters keep a constant phase relationship and superpose. At a point on PQ where the path difference from X and from Y is a whole number of wavelengths, nλ, the two waves arrive exactly in phase (phase difference zero); they interfere constructively, the resultant amplitude is the sum of the two amplitudes, and the intensity is a maximum. At a point where the path difference is an odd number of half wavelengths, (n + ½)λ, the waves arrive in antiphase (phase difference π rad); they interfere destructively and the intensity is a minimum. As D is moved along PQ the path difference changes steadily, so maxima and minima are detected alternately.

The expected relationship between f and x

For two coherent sources separated by a distance a, with the detector line a distance D away, the separation of adjacent maxima is x = λD/a. The microwaves travel at the speed of light c, so λ = c/f and

x = cD / (af)

With a and D kept constant, c, D and a are all fixed, so x is inversely proportional to f. Doubling the frequency should halve the spacing of the maxima, and the product fx should have the same value at every frequency.

How to verify the relationship experimentally

Keep the separation a of the transmitters and the distance D to the line PQ fixed throughout. Set a frequency and measure it by connecting an oscilloscope to the transmitter (or to the detector) and reading the period of the trace. Move D slowly along PQ and mark the positions of the maxima; to reduce the uncertainty, measure the distance from the first to the eleventh maximum with a metre ruler and divide by ten to obtain x. Repeat for several different frequencies spread across the available range.

Then either calculate fx for each pair of readings and show that it is constant to within the experimental uncertainty, or plot a graph of x against 1/f (or of 1/x against f). A straight line through the origin confirms that x ∝ 1/f, and the gradient of the graph of x against 1/f equals cD/a.`,
  "phys-ocra-h556-2022-p3::5(b)(ii)": `As X is rotated about AB, the plane of polarisation of the microwaves it emits turns. Only the component of X's wave that oscillates vertically can be detected by D and can interfere with the vertically polarised wave from Y, and that component gets smaller as the angle of rotation increases. So between 0° and 90° the interference pattern is still seen but becomes less pronounced: the maxima become less intense and the minima become more intense.

At 90° the wave from X is horizontally polarised. Waves whose planes of polarisation are at right angles to each other cannot interfere, because only components oscillating in the same plane superpose. The interference pattern therefore disappears altogether and D records a constant (non-zero) intensity everywhere along PQ, due to Y alone.

As the rotation continues from 90° to 180° the vertical component of X's wave grows again, so the pattern reappears and the maxima grow stronger. At 180° the intensities of the maxima and minima are the same as they were at 0°, but the vertical component of X's wave has been inverted – it is now π rad out of phase with what it was originally – so the positions of the maxima and minima are interchanged compared with the original pattern.`,
  "phys-ocra-h556-2022-p3::6(a)": `The time constant τ of an RC circuit is defined as τ = RC. It is the time taken for the charge (or voltage) on the capacitor to fall to 1/e (approximately 37%) of its initial value during discharge through the resistor.`,
  "phys-ocra-h556-2022-p3::6(b)(i)": `From Fig. 6.2 the input is a square wave that repeats every 40 ms (it is at 3.0 V from 0 to 20 ms, at 0 V from 20 to 40 ms, and then repeats), so
T = 40 ms = 40 × 10⁻³ s

f = 1/T = 1 / (40 × 10⁻³)
f = 25 Hz`,
  "phys-ocra-h556-2022-p3::6(b)(ii)": `Use the discharging section that starts at t = 20 ms, where the charge is Q₀ = 8.0 μC.

During the discharge Q = Q₀e^(−t/CR), so after one time constant the charge has fallen to
Q₀/e = 8.0/e = 2.9 μC

Reading Fig. 6.3, the curve passes through Q = 2.9 μC at about t = 34 ms, so the time constant is
CR = 34 − 20 = 14 ms

(Check using the decay equation: the charge falls from 8.0 μC to 2.0 μC over the 20 ms between t = 20 ms and t = 40 ms, so 2.0 = 8.0e^(−20/CR), giving CR = 20/ln 4 = 14 ms.)

time constant = 14 ms`,
  "phys-ocra-h556-2022-p3::6(b)(iii)": `The current in the resistor is I = dQ/dt, which is the gradient of the graph, so the current is greatest where the graph is steepest – at the very start of a discharge, t = 20 ms (or t = 60 ms).

Draw a tangent to the curve at that point, keeping the tangent touching the curve with no daylight between them, and take a large triangle on the tangent. The tangent drawn at t = 20 ms starts at Q = 8.0 μC and reaches Q = 0 at about t = 34 ms, so

gradient = ΔQ/Δt = (0 − 8.0 × 10⁻⁶) / ((34 − 20) × 10⁻³) = −8.0 × 10⁻⁶ / 1.4 × 10⁻²

maximum current = 5.7 × 10⁻⁴ A (about 6 × 10⁻⁴ A; the minus sign simply shows that the capacitor is discharging)`,
  "phys-ocra-h556-2023-p1::16(a)(i)": `110 km/h must be converted to SI units (m/s).

v = 110 × 1000 / 3600 = 30.6 m s⁻¹ (to 3 s.f.)

Unit: m s⁻¹`,
  "phys-ocra-h556-2023-p1::16(a)(ii)": `time = distance / speed = 40 / 30.6 = 1.31 s ≈ 1.3 s`,
  "phys-ocra-h556-2023-p1::16(a)(iii)": `From the table, the thinking distance is the part of the stopping distance that is not braking:

thinking distance = 96 − 75 = 21 m  (equivalent to a thinking time of 21/31 = 0.69 s)

Keeping two markings between you and the vehicle in front means a gap of at least 2 × 40 = 80 m, and up to 3 × 40 = 120 m.

Comparing these with the manual's figures for 110 km/hr:
• The thinking distance of 21 m is much less than the 40 m spacing, so the driver has reacted before even one marking has been passed (0.69 s is well inside the 1.3 s it takes to cover one gap).
• The braking distance of 75 m is less than the 80 m minimum gap, and the full stopping distance of 96 m is less than 120 m.

So a driver who keeps two markings visible always has more road ahead than the distance needed to think and then brake to rest, and can stop before reaching the vehicle in front — which is why the 40 m spacing helps prevent collisions.`,
  "phys-ocra-h556-2023-p1::16(b)(i)": `First convert speed: v = 110 × 1000/3600 = 30.6 m s⁻¹

Using impulse-momentum theorem:
F = Δ(mv)/Δt = m(v − u)/t = 1600 × (0 − 30.6)/5.6
F = 1600 × 30.6 / 5.6 = 8743 N ≈ 8700 N (to 2 s.f.)

The average resultant force required is approximately 8700 N.`,
  "phys-ocra-h556-2023-p1::16(b)(ii)": `On an upward slope, there is a component of the vehicle's weight acting in the direction opposing motion (down the slope), in addition to the braking force. The resultant decelerating force is therefore larger than on a flat road. Since a larger net force decelerates the vehicle, the deceleration is greater and the distance required to stop is reduced. So the stopping distance decreases on an upward slope.`,
  "phys-ocra-h556-2023-p1::17(a)(i)": `The tension T acts along the rod, directed from the sandbag towards the pivot point at the top of the ride. The arrow labelled T should be drawn along the rod, pointing upward and inward (toward the pivot), acting on the sandbag.`,
  "phys-ocra-h556-2023-p1::17(a)(ii)": `The radius of the circle is the horizontal distance of the sandbag from the axis of rotation, which is the radius of the disc plus the horizontal offset of the rod.

Horizontal offset of the rod = 11.1 sin 35° = 6.37 m

Radius of the disc = 7.8/2 = 3.9 m

r = 6.37 + 3.9 = 10.27 m ≈ 10 m (as required)`,
  "phys-ocra-h556-2023-p1::17(a)(iii)": `The sandbag moves in a horizontal circle, so the vertical component of the tension supports the weight while the horizontal component provides the centripetal force.

Resolving vertically (no vertical acceleration):

T cos 35° = mg

T = mg / cos 35° = (12 × 9.81) / cos 35° = 117.7 / 0.8192

T = 143.7 N ≈ 140 N`,
  "phys-ocra-h556-2023-p1::17(a)(iv)": `The horizontal component of the tension provides the centripetal force:

T sin 35° = mω²r

ω = √(T sin 35° / mr)

Using T = 143.7 N from (a)(iii), m = 12 kg and r = 10.27 m from (a)(ii):

ω = √(143.7 × 0.5736 / (12 × 10.27)) = √(82.4 / 123.2) = √0.669

ω = 0.82 rad s⁻¹ ≈ 0.8 radians per second (as required)`,
  "phys-ocra-h556-2023-p1::17(b)(i)": `At the highest point, height = 17 m. Sandbag is released with zero vertical velocity (at the top of its circular path its velocity is horizontal).

Using s = ut + ½at²:
17 = 0 + ½ × 9.81 × t²
t² = 17 × 2 / 9.81 = 3.466
t = 1.86 s ≈ 1.9 s`,
  "phys-ocra-h556-2023-p1::17(b)(ii)": `At the moment of release the sandbag is moving horizontally with the tangential speed of the circular motion:

v = ωr = 0.82 × 10.27 = 8.4 m s⁻¹

There is no horizontal force (air resistance is neglected), so the horizontal velocity stays constant during the 1.86 s fall found in (b)(i):

s = vt = 8.4 × 1.86

s = 16 m (15.6 m)`,
  "phys-ocra-h556-2023-p1::17(b)(iii)": `The relevant difference is that a shoe is far lighter than the 12 kg seat and sandbag while having a broadly similar size, so the drag force on it is much more significant compared with its weight; air resistance was ignored in the calculation above.

Because of this drag the shoe is slowed horizontally as soon as it leaves the ride, so its horizontal speed is no longer the constant 8.4 m s⁻¹ used in (b)(ii) but falls steadily during the flight.

The horizontal displacement is therefore smaller than the 16 m calculated for the sandbag. (Note that the change of mass on its own would make no difference: ω and r are fixed by the ride and the time of fall is independent of mass, so it is the drag — not the lower mass by itself — that shortens the displacement.)`,
  "phys-ocra-h556-2023-p1::18": `Vertical drop method: g = 2h/t² = (2 × 1.20)/0.50² = 9.6 m s⁻².
Rolling ball method: the acceleration down the ramp is a = 2L/t² = (2 × 1.900)/0.90² = 4.69 m s⁻², and since a = g sin θ, g = 4.69/sin 30° = 9.4 m s⁻².

Uncertainties
Neither value is repeated, so there is no way of judging the random scatter and both are inherently uncertain. The lengths are the smallest source of uncertainty: a metre rule gives the drop height to about ±1 cm in 1.20 m (0.8%) and the ramp length to about ±1 mm in 1.900 m (0.05%).

The timing dominates both experiments. The stopclock reads to 0.01 s, but a hand-operated stopclock carries the experimenter's reaction time, so the realistic uncertainty in each time is about ±0.1 s. That is ±20% of the 0.50 s drop time but only ±11% of the 0.90 s roll time. Because g is calculated from t², these percentages double: about 40% for the drop and about 22% for the ramp.

The ramp has one extra term: the angle, measured with a protractor to perhaps ±1° or ±2°, and g depends on sin θ, so ±1° at 30° adds roughly a further 3%.

Adding the percentages gives about ±41% (≈ ±4 m s⁻²) for the vertical drop against about ±25% (≈ ±2 m s⁻²) for the rolling ball. The rolling ball method is therefore the less uncertain of the two, essentially because it stretches the same fixed reaction-time error over a longer time and a longer, more precisely measured distance. Against that, the ramp method suffers more from friction and from the fact that some of the energy goes into rotating the ball, which is a systematic effect that makes g come out too low and is not included in the uncertainty estimate.

Analysis of a full set of results
For each setting the student should repeat the timing several times, take a mean, and use half the range of the repeats as the uncertainty in t.

For the vertical drop, h = ½gt², so a graph of t² (y-axis) against h (x-axis) should be a straight line through the origin of gradient 2/g, giving g = 2/gradient (equivalently, plotting t² against 2h gives a gradient of 1/g).

For the ramp, L = ½(g sin θ)t², so t² = (2L/g) × 1/sin θ: a graph of t² (y-axis) against 1/sin θ (x-axis) is a straight line of gradient 2L/g, giving g = 2L/gradient.

In both cases error bars should be added and a worst-fit line drawn as well as the best-fit line; the uncertainty in g then follows from the difference between the best and worst gradients. Using a graph in this way averages out the random timing errors and shows up any systematic error as a non-zero intercept.`,
  "phys-ocra-h556-2023-p1::19(a)": `To find the centre of mass of a 2D shape:

Equipment: the shape (cut from card), a pin/nail, a clamp stand, a plumb line (string with small mass attached), a pencil.

Method: Suspend the shape freely from a pin through a hole near one edge; allow it to hang at rest. The centre of mass must lie vertically below the pivot. Hang the plumb line from the same pin and mark the line it makes across the shape. Repeat by suspending from a different hole near another edge and mark the plumb line again. The centre of mass is at the intersection of the two lines.`,
  "phys-ocra-h556-2023-p1::19(b)(i)": `As the bridge is raised from horizontal to vertical, its centre of mass swings from a point 6.3 m horizontally from the pivot (and 1.3 m below the platform, i.e. below the pivot) to a point 6.3 m vertically above the pivot.

Rise in height of the centre of mass:

Δh = 6.3 + 1.3 = 7.6 m

Work done against gravity:

W = weight × Δh = 120 × 10³ × 7.6 = 9.12 × 10⁵ J

Average power:

P = W/t = 9.12 × 10⁵ / 90

P = 10 100 W (about 10 kW)`,
  "phys-ocra-h556-2023-p1::19(b)(ii)": `The calculation assumed 100% efficiency and a constant load. In practice: the motor must overcome friction in the pivot and mechanical losses throughout the system; the bridge does not move at constant speed and may need to accelerate; wind may add an additional load; the motor must also have power available to stop the bridge safely at the end. A much larger maximum power ensures the motor can handle peak loads and unexpected resistive forces without stalling.`,
  "phys-ocra-h556-2023-p1::20(a)": `For n moles of ideal gas: pV = nRT

The mass of gas = nM (since M is molar mass).
Density ρ = mass/volume = nM/V.

From the ideal gas equation: V = nRT/p

Substituting:
ρ = nM/V = nM/(nRT/p) = nMp/(nRT) = Mp/(RT)

Therefore ρ = pM/RT  ✓`,
  "phys-ocra-h556-2023-p1::20(b)(i)": `Using ρ = pM/RT:
p = 1.0 × 10⁵ Pa, M = 0.029 kg mol⁻¹, T = 20 + 273 = 293 K, R = 8.31 J mol⁻¹ K⁻¹

ρ = (1.0 × 10⁵ × 0.029) / (8.31 × 293) = 2900 / 2434.8 = 1.19 kg m⁻³ ≈ 1.2 kg m⁻³  ✓`,
  "phys-ocra-h556-2023-p1::20(b)(ii)": `Weight of air displaced = ρ_air × V × g
= 1.2 × 12 000 × 9.81
= 141 264 N ≈ 1.4 × 10⁵ N`,
  "phys-ocra-h556-2023-p1::20(b)(iii)": `By Archimedes' principle, the upthrust on the airship equals the weight of fluid (air) displaced. For the airship to float stationary, the net force must be zero. The upward upthrust equals the weight of air displaced, and this must balance the total downward weight of the airship and its contents. Since the airship is in equilibrium (stationary), upthrust = weight of airship and contents = weight of displaced air.`,
  "phys-ocra-h556-2023-p1::20(b)(iv)": `If a higher pressure were used, the density of helium inside would increase (since ρ = pM/RT with higher p). The mass of helium in the gasbag would increase significantly. This greater mass of helium means more weight to support, reducing the net upthrust available to lift the payload (cabin and cargo). Additionally, a higher pressure would require the gasbag to be made from stronger, heavier material to withstand the pressure difference, further increasing weight. The risk of the gasbag bursting or leaking would also be greater.`,
  "phys-ocra-h556-2023-p1::20(c)": `Thrust = rate of change of momentum of air
= (mass per second) × velocity
= 7.8 × 45
= 351 N ≈ 350 N`,
  "phys-ocra-h556-2023-p1::20(d)": `At high altitude the air density is lower. Lower air density means the airship displaces less mass of air per unit volume, so the upthrust is smaller — however the airship's weight is unchanged. To remain aloft, the helium volume (and hence the buoyancy) must be maintained.

For the engine: thrust = (mass flow rate) × velocity = ρ_air × A × v_fan × v_relative. At higher altitude ρ_air is smaller. Even with the same fan speed, less mass of air is moved per second, so the thrust is less. However, because the air resistance on the airship is also lower at lower density (drag ∝ ρv²), the airship needs less thrust to achieve any given speed, and the reduced drag allows a higher maximum speed despite the lower thrust available.`,
  "phys-ocra-h556-2023-p1::21(a)(i)": `Check both sides have the same SI base units.

Left side: T² has units of s².

Right side: 2π²m/k. π is dimensionless.
[m] = kg; [k] = N m⁻¹ = kg m s⁻² m⁻¹ = kg s⁻²
[m/k] = kg / (kg s⁻²) = s²

So [2π²m/k] = s²  ✓

Both sides have units of s², so the equation is homogeneous.`,
  "phys-ocra-h556-2023-p1::21(a)(ii)": `Both springs stay in tension throughout, so at the equilibrium position each pulls the glider outwards with the same tension and the resultant force is zero.

Suppose the glider is now displaced a distance x to the right. The left-hand spring is stretched a further x, so its tension rises by kx and it pulls the glider to the left with a force (T₀ + kx). The right-hand spring is allowed to shorten by x, so its tension falls by kx and it pulls the glider to the right with a force (T₀ − kx).

Taking the direction towards the equilibrium position as positive, the resultant is

F = (T₀ + kx) − (T₀ − kx) = kx − (−kx) = 2kx

The equal and opposite tensions T₀ cancel, so the magnitude of the resultant force is F = 2kx, directed back towards the equilibrium position (which is why the motion is simple harmonic).`,
  "phys-ocra-h556-2023-p1::21(a)(iii)": `For SHM, the period is T = 2π√(m/(2k)) — it depends only on the mass m and the spring constant k, not on the amplitude (initial displacement).

Increasing the initial displacement does not change the period. The period remains the same. This is a fundamental property of SHM: isochronous oscillations, meaning the period is independent of amplitude.`,
  "phys-ocra-h556-2023-p1::21(b)(i)": `Error 1: The T and T² columns have no units in their headings. The first two columns are correctly headed m / kg and 20T / s, so these should be headed T / s and T² / s².

Error 2: The number of significant figures is not consistent down the columns and does not follow from the raw data. Every value of 20T is given to 3 significant figures, so each T should also be given to 3 significant figures; instead T runs 0.61, 0.68, 0.78, 0.88 (2 s.f.), then 0.945 (3 s.f.), and finally 1 for m = 0.700 kg, which is only 1 significant figure (it should be 1.00 s, with T² = 1.00 s²). One significant figure is never enough for data of this quality.`,
  "phys-ocra-h556-2023-p1::21(b)(ii)": `The first row of the table is m = 0.200 kg, T² = 0.372 s², so plot a point at (0.200, 0.372) — on the m axis a fifth of the way from 0 to 0.400, and on the T² axis just under 0.400 — marking it with a small sharp cross to within half a small square, in the same style as the points already plotted.

Then draw a single straight line of best fit with a ruler, extending it across the plotted range. Judge it so that the points are evenly scattered about it, with the same number above as below and the distances from the line balanced on each side. Do not force the line through the origin — these points sit slightly above a line through the origin, and the line drawn must be the best fit to the data as plotted, because its gradient is what gives k.`,
  "phys-ocra-h556-2023-p1::21(b)(iii)": `Rearranging T² = 2π²m/k into the form y = mx + c shows that the graph of T² against m has

gradient = 2π²/k,  so  k = 2π²/gradient

Take two widely separated points that lie on the line of best fit itself (not data points from the table), for example (0.200, 0.36) and (0.700, 1.01):

gradient = (1.01 − 0.36)/(0.700 − 0.200) = 0.65/0.500 = 1.30 s² kg⁻¹

k = 2π²/1.30 = 19.74/1.30

k = 15 N m⁻¹

(Any correctly drawn line gives a gradient of about 1.22 to 1.44 and hence k in the range 14 to 16 N m⁻¹.)`,
  "phys-ocra-h556-2023-p1::21(c)": `Both springs stay in tension, so if the initial displacement is x₀ and each spring has extension e at the equilibrium position, at maximum displacement one spring has extension (e + x₀) and the other (e − x₀).

The elastic potential energy stored in a spring is ½kx², which depends on the square of the extension. Because of that square, the energy gained by the spring that is stretched further is larger than the energy lost by the spring whose extension is reduced. Adding the two:

E = ½k(e + x₀)² + ½k(e − x₀)² = ke² + kx₀²

so the total energy stored at the extremes exceeds the value at the equilibrium position (ke²) by kx₀², and this excess grows as x₀². The total energy of the oscillation has therefore increased.

The kinetic energy is a maximum as the glider passes through the equilibrium position, where the stored elastic potential energy is at its minimum value of ke² — and that minimum is unchanged by the larger displacement. All of the extra energy kx₀² is therefore available as kinetic energy at that point, so the maximum kinetic energy increases.

The same conclusion follows from the SHM equations: ω depends only on k and m and so is unchanged, while the amplitude A has increased, so v_max = ωA is larger and the maximum kinetic energy ½mv_max² is greater.`,
  "phys-ocra-h556-2023-p1::22": `A star of about one solar mass starts its stable life on the main sequence, lying in the middle of the band that runs from the top left to the bottom right of the H-R diagram — a surface temperature of roughly 5000–6000 K and a luminosity of about one solar luminosity. (Remember that temperature increases to the left on an H-R diagram.) It stays there for billions of years while hydrogen fuses to helium in its core.

When the core hydrogen is exhausted, the core contracts and heats while hydrogen burns in a shell around it. The outer layers swell enormously and cool, so the luminosity rises while the surface temperature falls: the star leaves the main sequence and tracks up and to the right into the red giant region. Helium fusion then begins in the core.

Because the mass of the remnant core will be below the Chandrasekhar limit of about 1.4 solar masses, the star cannot become a neutron star. Once helium burning ends, the outer layers are thrown off as a planetary nebula, exposing the hot, dense core. The star drops almost vertically down and to the left on the diagram into the white dwarf region — very hot but very low luminosity — and then slowly cools and fades, moving to the right along the bottom of the diagram.

Using Fig. 22.2: the curve shows relative intensity against wavelength, so the wavelength at which the intensity peaks, λ_max, can be read from it. Wien's displacement law, λ_max T = 2.90 × 10⁻³ m K, then gives the surface temperature T = 2.90 × 10⁻³/λ_max. A short peak wavelength means a hot star and a long one a cool star, and the temperature fixes the horizontal coordinate of the star on the H-R diagram, which can be marked as a vertical line on Fig. 22.1.

Limitations: the spectrum gives only the temperature, so it places the star somewhere on that vertical line but says nothing about its luminosity, which is the vertical coordinate. Stars at the same temperature can be at completely different stages — a white dwarf, a main-sequence star and a hot supergiant can share a surface temperature — so the evolutionary stage cannot be identified without luminosity data, which needs the star's distance as well as its apparent brightness. In practice it can also be difficult to isolate the light of a single star, especially in another galaxy, and for a distant object the whole spectrum is red-shifted, so the shift must be corrected for before Wien's law is applied or the star will appear cooler than it is. Absorption and scattering by interstellar dust reddens the light in the same misleading way.`,
  "phys-ocra-h556-2023-p1::23(a)(i)": `The smallest parallax angle Hipparcos can resolve is its precision, 9.7 × 10⁻⁴ arcseconds, and the most distant measurable star is the one with that parallax.

Using d (parsec) = 1/p (arcsecond):

d = 1/(9.7 × 10⁻⁴) = 1030

d ≈ 1000 pc`,
  "phys-ocra-h556-2023-p1::23(a)(ii)": `The uncertainty in the measured parallax angle is the precision of the telescope, 9.7 × 10⁻⁴ arcseconds, and the measured angle for Polaris A is 7.5 × 10⁻³ arcseconds.

percentage uncertainty in p = (9.7 × 10⁻⁴)/(7.5 × 10⁻³) × 100% = 12.9%

Since d = 1/p, the percentage uncertainty in d is the same as the percentage uncertainty in p:

percentage uncertainty in d = 13%`,
  "phys-ocra-h556-2023-p1::23(b)(i)": `For an ideal gas the mean kinetic energy of a particle depends only on the absolute temperature:

E_k = (3/2)kT

where k is the Boltzmann constant, 1.38 × 10⁻²³ J K⁻¹, and T is the temperature of the star's atmosphere, 4.0 × 10⁶ K:

E_k = 1.5 × 1.38 × 10⁻²³ × 4.0 × 10⁶

E_k = 8.3 × 10⁻¹⁷ J ≈ 10⁻¹⁶ J (as required)

(The result does not depend on the mass of the nucleus — that only affects its speed.)`,
  "phys-ocra-h556-2023-p1::23(b)(ii)": `The nucleus reaches its maximum distance when all of its kinetic energy has been converted into gravitational potential energy, so at that point its kinetic energy is zero and the total energy is entirely potential. Total energy is conserved:

U_max = E_k + U_start = 8.3 × 10⁻¹⁷ + (−2.3 × 10⁻¹⁶)

U = −1.5 × 10⁻¹⁶ J

(The value is still negative, so the nucleus is still bound to the star.)`,
  "phys-ocra-h556-2023-p1::23(b)(iii)": `The gravitational potential energy of the nucleus at a distance r from the centre of the star is

U = −GMm/r,  so  r = −GMm/U

Using M = 1.1 × 10³¹ kg, m = 6.6 × 10⁻²⁷ kg, G = 6.67 × 10⁻¹¹ N m² kg⁻² and U = −1.5 × 10⁻¹⁶ J from (b)(ii):

r = (6.67 × 10⁻¹¹ × 1.1 × 10³¹ × 6.6 × 10⁻²⁷) / (1.5 × 10⁻¹⁶)
 = 4.84 × 10⁻⁶ / 1.5 × 10⁻¹⁶

r = 3.2 × 10¹⁰ m from the centre of the star

(That is only about 1.5 times the star's radius of 2.1 × 10¹⁰ m.)`,
  "phys-ocra-h556-2023-p1::23(b)(iv)": `The calculation in (iii) used the average kinetic energy from the Maxwell-Boltzmann distribution. In reality, gas particles have a range of speeds — the distribution has a high-speed tail. A small fraction of helium nuclei have kinetic energies far greater than the average (3/2 k_BT), enough to exceed the gravitational PE barrier and escape to much greater distances. This is analogous to evaporation — the fastest-moving particles escape even when the average energy is not sufficient.`,
  "phys-ocra-h556-2023-p2::16(a)": `A and D: diffraction. These are the dim regions towards the edges of the pattern, where the single-slit diffraction envelope has reduced the intensity almost to zero, so they may also be described as places where the light from the two slits arrives in antiphase and interferes destructively.

B and C: interference. B and C are bright fringes (maxima), produced where the waves from the two slits arrive in phase and interfere constructively, so the resultant amplitude — and hence the intensity — is a maximum.`,
  "phys-ocra-h556-2023-p2::16(b)": `Coherent waves have a constant phase difference (which may be zero) between them and have the same frequency (and wavelength). This means their relative phase relationship does not change with time.`,
  "phys-ocra-h556-2023-p2::16(c)": `B is a bright fringe, formed by constructive interference of the light arriving from the two slits.

The waves reaching B from the two slits have travelled different distances, and the path difference is a whole number of wavelengths, so the waves arrive in phase and reinforce one another.

B is the second bright fringe out from the central maximum C, so for B the path difference is 2λ, which corresponds to a phase difference of 4π rad (720°).`,
  "phys-ocra-h556-2023-p2::16(d)": `Fringe separation from the double-slit formula λ = ax/D:

x = λD/a = (640 × 10⁻⁹ × 4.0) / (1.00 × 10⁻⁵) = 0.256 m

B is the second maximum from the central maximum C, so the distance from C to B on the screen is

2x = 2 × 0.256 = 0.512 m

Hence

tan θ = 0.512 / 4.0 = 0.128
θ = tan⁻¹(0.128) = 7.3°

(Equivalently, using a sin θ = nλ with n = 2: sin θ = 2 × 640 × 10⁻⁹ / 1.00 × 10⁻⁵ = 0.128, giving θ = 7.4°.)

θ = 7.3°`,
  "phys-ocra-h556-2023-p2::17(a)": `Ultrasound is a longitudinal, mechanical pressure wave with a frequency above the upper limit of human hearing, which is 20 000 Hz (20 kHz). Ultrasound therefore has a frequency greater than 20 kHz. Like all sound waves it requires a medium through which to travel and travels as compressions and rarefactions.`,
  "phys-ocra-h556-2023-p2::17(b)": `Production of ultrasound: The transducer contains a piezoelectric crystal. When an alternating voltage at ultrasonic frequency is applied across the crystal, it vibrates at that frequency due to the inverse piezoelectric effect (applied electric field causes mechanical deformation). These vibrations are transmitted to the patient's skin as ultrasound pressure waves.

Receiving ultrasound: When the reflected ultrasound waves return and strike the piezoelectric crystal, the pressure variations cause the crystal to deform rhythmically. By the piezoelectric effect, this mechanical deformation generates an alternating voltage across the crystal, which is detected and processed electronically to form the image. The same crystal can therefore both emit and detect ultrasound.

Purpose of the gel: The acoustic impedance of air is very much lower than that of tissue. Without gel, at the boundary between the transducer and skin (separated by air), almost all the ultrasound would be reflected and very little transmitted into the body. The gel has an acoustic impedance much closer to that of tissue (and the transducer surface), so it fills the air gap and greatly reduces reflection at the transducer–skin interface, allowing efficient transmission of ultrasound into the patient.`,
  "phys-ocra-h556-2023-p2::17(c)(i)": `Region A is a fluid-filled cavity (such as the amniotic fluid surrounding the baby). Ultrasound is not reflected back from A because there is no significant acoustic impedance boundary within the fluid — the wave travels through the uniform liquid without encountering an interface where a change in acoustic impedance would cause reflection.`,
  "phys-ocra-h556-2023-p2::17(c)(ii)": `Region B is at a tissue–bone boundary (or a large impedance mismatch interface) while region C is at a softer tissue boundary (smaller impedance mismatch). The fraction of ultrasound reflected at any boundary is determined by the difference in acoustic impedances of the two media: a larger impedance mismatch produces a larger reflection coefficient. Bone has a much greater acoustic impedance than soft tissue, so the impedance mismatch at B is much greater than at C (soft tissue–soft tissue boundary). Therefore a much greater fraction of the incident ultrasound is reflected back from B than from C, giving a stronger (greater) signal at B.`,
  "phys-ocra-h556-2023-p2::17(d)": `Using the Doppler formula for moving reflector:
Δf = f_observed − f_emitted = 9.9987 MHz − 10.0000 MHz = −0.0013 MHz = −1300 Hz

|Δf| = 1300 Hz

Doppler formula (for a moving reflector with the transducer at angle θ to the vessel):
Δf = 2f₀ v cosθ / c

where f₀ = 10.0000 × 10⁶ Hz, c = 1600 m s⁻¹, θ = 50°

v = |Δf| × c / (2f₀ cosθ)
= 1300 × 1600 / (2 × 10.0000 × 10⁶ × cos50°)
= 2 080 000 / (2 × 10⁷ × 0.6428)
= 2.08 × 10⁶ / (1.2856 × 10⁷)
= 0.162 m s⁻¹ ≈ 0.16 m s⁻¹`,
  "phys-ocra-h556-2023-p2::18(a)": `The tube is open at both ends, so the fundamental has a displacement antinode at each open end and a single displacement node exactly half-way along the tube.

Sketch: inside the tube draw one smooth half-wavelength loop — a curve starting at maximum displacement at the left-hand open end, crossing the centre line (zero displacement) at the mid-point of the tube, and reaching maximum displacement again at the right-hand open end. Draw the mirror-image curve as a dashed line to show the other extreme of the oscillation. The whole tube therefore contains half a wavelength.`,
  "phys-ocra-h556-2023-p2::18(b)": `For a tube open at both ends the fundamental fits half a wavelength into the tube, so

λ₀ = 2L = 2 × 0.300 = 0.600 m

f₀ = v/λ₀ = 340 / 0.600 = 567 Hz

f₀ = 567 Hz`,
  "phys-ocra-h556-2023-p2::18(c)": `A tube open at both ends supports all harmonics, so the next standing wave is the second harmonic, for which a whole wavelength fits into the tube:

λ₁ = L = 0.300 m

f₁ = v/λ₁ = 340 / 0.300 = 1133 Hz

f₁ = 1.13 × 10³ Hz (i.e. 2f₀)`,
  "phys-ocra-h556-2023-p2::19(a)": `The experiment is electron diffraction through a thin graphite (carbon) film.

Apparatus (labelled diagram description): An electron gun (cathode, anode with high voltage ~5 kV) fires a beam of electrons. The beam passes through a thin polycrystalline graphite film mounted on a mesh inside an evacuated glass tube. A fluorescent screen at the far end of the tube detects the electrons.

Method: Electrons are accelerated through the potential difference in the electron gun, gaining kinetic energy. They strike the graphite film, where the regular atomic lattice acts as a diffraction grating. The diffracted electrons hit the fluorescent screen, producing a pattern of concentric rings of alternating light and dark.`,
  "phys-ocra-h556-2023-p2::19(b)": `The pattern of concentric bright and dark rings is produced by diffraction and interference of electron waves passing through the regular crystal lattice of graphite.

The bright rings occur where electrons from different atomic planes in the crystal lattice arrive at the screen having travelled path lengths that differ by a whole number of de Broglie wavelengths — constructive interference produces high electron intensity (bright rings).

The dark rings occur where the path difference is a half-integer multiple of the wavelength — destructive interference produces zero (or low) electron intensity.

This evidence demonstrates wave-particle duality: electrons, which have mass and charge and behave as particles, also exhibit wave-like behaviour (diffraction and interference). Their de Broglie wavelength is comparable to the interatomic spacing in graphite (~10⁻¹⁰ m), which is why diffraction is observable.`,
  "phys-ocra-h556-2023-p2::19(c)(i)": `Work done on electrons:
W = QV = eV = 1.60 × 10⁻¹⁹ × 5000 = 8.0 × 10⁻¹⁶ J`,
  "phys-ocra-h556-2023-p2::19(c)(ii)": `The work done equals the kinetic energy gained:
½mv² = eV
v = √(2eV/m) = √(2 × 8.0 × 10⁻¹⁶ / 9.11 × 10⁻³¹)
= √(1.756 × 10¹⁵) = 4.19 × 10⁷ m s⁻¹

Momentum p = mv = 9.11 × 10⁻³¹ × 4.19 × 10⁷ = 3.817 × 10⁻²³ kg m s⁻¹

de Broglie wavelength:
λ = h/p = 6.63 × 10⁻³⁴ / 3.817 × 10⁻²³ = 1.74 × 10⁻¹¹ m ≈ 1.7 × 10⁻¹¹ m`,
  "phys-ocra-h556-2023-p2::19(c)(iii)": `Noticeable diffraction only occurs when the gap (or spacing) through which the waves pass is of about the same size as the wavelength of the waves.

The de Broglie wavelength of the electrons is 1.7 × 10⁻¹¹ m, so the spacing between the graphite atoms must be of about this size:

spacing ≈ 1.7 × 10⁻¹¹ m (i.e. of the order of 10⁻¹¹ m)`,
  "phys-ocra-h556-2023-p2::20(a)": `Circuit diagram to draw:

- A 6.0 V d.c. supply (cell/battery symbol).
- A two-way switch connected to the positive terminal of the supply: in one position it connects the supply into the circuit (charging); in the other position it disconnects the supply and connects the capacitor directly across the same resistor (discharging).
- The 10 kΩ resistor in series with the 1.0 µF capacitor, so that the charging current and the discharging current both pass through this resistor.
- A voltmeter connected in parallel with (directly across) the capacitor.

No component labels are required, but the circuit must show the supply in series with the resistor and capacitor, the voltmeter across the capacitor, and a switch (or pair of switches) that allows the capacitor to be discharged through the same resistor without moving any components.`,
  "phys-ocra-h556-2023-p2::20(b)": `When the capacitor is fully charged the p.d. across it equals the supply p.d. of 6.0 V.

Q = VC = 6.0 × 1.0 × 10⁻⁶ = 6.0 × 10⁻⁶ C

Q = 6.0 × 10⁻⁶ C (6.0 µC)`,
  "phys-ocra-h556-2023-p2::20(c)": `The time constant of the circuit is

τ = CR = 1.0 × 10⁻⁶ × 10 × 10³ = 0.010 s

τ is the time taken for the p.d. across the capacitor to fall to 1/e (about 37%) of its initial value, so in only 0.010 s the p.d. has already dropped from 6.0 V to about 2.2 V, and after about 5τ = 0.05 s the capacitor is essentially fully discharged.

(Equivalently, using V = V₀e^(−t/CR): 0.6 = 6.0e^(−t/0.01) gives t = 0.023 s for the p.d. to fall to just 10% of its starting value.)

These times are a few hundredths of a second, which is far shorter than a human reaction time (roughly 0.2 s), so a stopwatch could not be started, read and stopped quickly enough to record how the p.d. varies during the charging or discharging.`,
  "phys-ocra-h556-2023-p2::20(d)": `Use a datalogger (or data logger with a voltage sensor) connected across the capacitor in place of the voltmeter. The datalogger automatically records voltage at very short, regular time intervals (e.g. every 0.01 s), giving many accurate data points throughout the charging process. The data can then be plotted and analysed on a computer.`,
  "phys-ocra-h556-2023-p2::20(e)(i)": `For discharge, V = V₀e^(−t/CR), with V₀ = 6.0 V, V = 4.12 V and CR = 1.0 × 10⁻⁶ × 10 × 10³ = 0.010 s.

4.12 = 6.0 e^(−t/0.010)
e^(−t/0.010) = 4.12/6.0 = 0.6867
t/0.010 = −ln(0.6867) = 0.3759
t = 0.3759 × 0.010 = 3.76 × 10⁻³ s

t = 3.76 × 10⁻³ s`,
  "phys-ocra-h556-2023-p2::20(e)(ii)": `Energy stored by a capacitor is E = ½CV², so the energy lost as the p.d. falls from 6.0 V to 4.12 V is

ΔE = ½CV₁² − ½CV₂² = ½ × 1.0 × 10⁻⁶ × (6.0² − 4.12²)
   = ½ × 1.0 × 10⁻⁶ × (36 − 16.97)
   = 9.5 × 10⁻⁶ J

This energy is lost in the time found in (e)(i), t = 3.76 × 10⁻³ s, so

average rate of energy loss = ΔE/t = 9.5 × 10⁻⁶ / 3.76 × 10⁻³ = 2.53 × 10⁻³ J s⁻¹

average rate at which energy is lost = 2.53 × 10⁻³ J s⁻¹`,
  "phys-ocra-h556-2023-p2::21(a)": `The upper label, pointing to the vertical rods inside the core, is: (nuclear) fuel rods — these contain the uranium (uranium oxide) fuel.

The lower label, pointing to the material filling the core around the rods, is: moderator (for example graphite or heavy water) — the material that surrounds the fuel rods and slows the fast neutrons. (A correctly named coolant, such as carbon dioxide or water, is equally acceptable for this label.)`,
  "phys-ocra-h556-2023-p2::21(b)": `Inducing fission: A slow (thermal) neutron is absorbed by a U-235 nucleus, making it highly unstable. It then undergoes fission, splitting into two smaller nuclei (fission fragments) and releasing 2 or 3 fast neutrons plus energy. For example: ²³⁵₉₂U + ¹₀n → ¹⁴¹₅₆Ba + ⁹²₃₆Kr + 3¹₀n

Controlling the chain reaction: The fast neutrons released must be slowed down (moderated) by the moderator before they can induce further fissions. The control rods (boron/cadmium) absorb neutrons — inserting them deeper reduces the rate of fission; withdrawing them allows more neutrons to cause fission. By adjusting the control rods, the chain reaction is kept at a steady, controlled rate (k=1, critical).

Energy release calculation:
Mass defect: Δm = (mass of U-235 + mass of neutron) − (mass of Ba-141 + mass of Kr-92 + 3×mass of neutron)
= (235.04395 + 1.00867) − (140.91440 + 91.92617 + 3 × 1.00867) u
= 236.05262 − (140.91440 + 91.92617 + 3.02601) u
= 236.05262 − 235.86658 u
= 0.18604 u

Energy released = 0.18604 × 931.5 MeV = 173.3 MeV ≈ 173 MeV per fission

This is an enormous amount of energy per event — about 50 million times more than a typical chemical reaction (which releases a few eV). This is because in nuclear reactions the binding energy of the nucleus is involved (strong nuclear force), whereas chemical reactions involve only electron energy levels.`,
  "phys-ocra-h556-2023-p2::21(c)": `Advantages of fusion over fission:
- Fuel availability: Deuterium can be extracted from sea water (practically limitless supply); tritium can be bred from lithium, also abundant. Uranium-235 is rare and must be mined and enriched.
- Energy yield: Fusion releases over 7 times more energy per kg of fuel than fission of uranium, making it far more energy-dense.
- Waste: Fusion produces no long-lived radioactive waste — the main product is helium (inert) and some neutron activation of reactor components, which has a much shorter half-life than fission products.
- Safety: No risk of runaway chain reaction; the plasma conditions required for fusion are so extreme that any containment failure stops the reaction immediately.

Disadvantages of fusion:
- Technological challenge: Fusion requires temperatures of ~100 million K to overcome Coulomb repulsion between nuclei. No material can contain such a plasma — magnetic confinement (tokamak) or inertial confinement must be used, and these technologies have not yet achieved net energy gain at commercial scale.
- Engineering: The intense neutron flux damages reactor materials and activates them; materials science challenges remain unsolved.
- Not yet available: Fusion is not yet a commercially viable energy source; fission reactors exist and provide electricity today.

Fission disadvantages: long-lived radioactive waste, risk of meltdown, limited uranium-235 supply, concerns about proliferation.`,
  "phys-ocra-h556-2023-p2::22(a)": `F-18 (fluorine-18) undergoes β⁺ decay:

¹⁸₉F → ¹⁸₈O + ⁰₊₁e + ⁰₀ν_e

(A positron is emitted along with a neutrino; the daughter nucleus is oxygen-18.)`,
  "phys-ocra-h556-2023-p2::22(b)": `In annihilation, the rest mass energy of the electron and positron is converted entirely to two gamma photons (by conservation of momentum, two photons must be produced moving in opposite directions).

Energy of each photon = rest mass energy of one electron:
E = m_e c² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 8.199 × 10⁻¹⁴ J

Using E = hc/λ:
λ = hc/E = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) / (8.199 × 10⁻¹⁴)
= 1.989 × 10⁻²⁵ / 8.199 × 10⁻¹⁴
= 2.43 × 10⁻¹² m ≈ 2.4 × 10⁻¹² m`,
  "phys-ocra-h556-2023-p2::22(c)": `X-rays are produced when fast-moving electrons are rapidly decelerated (Bremsstrahlung radiation) as they interact with matter, or when electrons make transitions between inner electron shells (characteristic X-rays) — in both cases, energy from electronic transitions or deceleration is emitted as photons.

Gamma rays are produced by nuclear transitions — when an excited nucleus (formed after radioactive decay, such as after alpha or beta emission) drops to a lower energy state, the energy difference is emitted as a gamma-ray photon. Gamma rays originate from within the nucleus, not from electron transitions.`,
  "phys-ocra-h556-2023-p2::22(d)": `A half-life of 109.7 minutes is short, which means the activity of the F-18 tracer is high but falls away quickly.

Advantage for the patient: because the tracer decays rapidly, it is present in the body for only a few hours, so the patient's total exposure to ionising radiation is kept as low as possible while still giving a strong enough signal for a clear PET image.

Disadvantage for the radiographers: the same rapid decay means the activity falls noticeably during the procedure, so they have only a short time in which to inject the tracer and complete the scan and diagnosis. The F-18 also cannot be stored or transported far — it must be produced in a cyclotron on or near the site immediately before use, and handling such a high-activity source increases the radiographers' own exposure.`,
  "phys-ocra-h556-2023-p2::23(a)(i)": `From the table:
For 1 mm: intensity = 122 W m⁻², ln(122) = 4.80
For 2 mm: intensity = 46.5 W m⁻², ln(46.5) = 3.84`,
  "phys-ocra-h556-2023-p2::23(a)(ii)": `Plot the two new points on the graph:
(1 mm, 4.80) and (2 mm, 3.84)
These should be added to the existing three points at (3 mm, 2.88), (4 mm, 1.92), (5 mm, 0.960).`,
  "phys-ocra-h556-2023-p2::23(a)(iii)": `Draw a straight line of best fit through all five data points, minimising the total distance of points from the line. The line should have a negative gradient (ln(I) decreases as thickness increases) and should be extended to the y-axis to find the intercept.`,
  "phys-ocra-h556-2023-p2::23(b)(i)": `The exponential absorption law: I = I₀ e^(−μx)

Taking the natural log of both sides:
ln(I) = ln(I₀) − μx

This is in the form y = c + mx, where:
y = ln(I), x = thickness, gradient m = −μ (negative), y-intercept c = ln(I₀).

A graph of ln(I) against x is therefore a straight line with negative gradient −μ.`,
  "phys-ocra-h556-2023-p2::23(b)(ii)": `From the graph, the y-intercept (where the best-fit line meets the y-axis at x = 0) gives ln(I₀).

Reading from the graph (using the five data points, which show a very regular spacing of ~0.96 per mm):
At x = 0: ln(I₀) ≈ 4.80 + 0.96 = 5.76
I₀ = e^5.76 = 317 W m⁻² ≈ 320 W m⁻²

(Accept any value consistent with the best-fit line extended to x = 0.)`,
  "phys-ocra-h556-2023-p2::23(b)(iii)": `The gradient of the best-fit line = −μ.

Using two well-separated points on the line, e.g. (1 mm, 4.80) and (5 mm, 0.960):
Gradient = (0.960 − 4.80)/(5 − 1) = (−3.84)/4 = −0.96 mm⁻¹

Therefore μ = 0.96 mm⁻¹`,
  "phys-ocra-h556-2023-p2::23(c)(i)": `Using voltage divider formula: V_out = V_supply × R₂/(R₁ + R₂)

With 1 mm jelly (R₂ = 100 Ω):
V_out = 5 × 100/(5000 + 100) = 500/5100 = 0.0980 V

With 5 mm jelly (R₂ = 8000 Ω):
V_out = 5 × 8000/(5000 + 8000) = 40000/13000 = 3.077 V

Output voltage range = 3.077 − 0.0980 = 2.98 V ≈ 3.0 V`,
  "phys-ocra-h556-2023-p2::23(c)(ii)": `Two ways to increase the output voltage range:
1. Reduce the value of R₁ (the fixed resistor): a smaller R₁ means a greater fraction of the supply voltage appears across R₂ at all settings, increasing V_out at all light levels and widening the range.
2. Increase the supply voltage V_supply: since V_out is directly proportional to V_supply, a higher supply voltage proportionally increases V_out at all settings, widening the output range.`,
  "phys-ocra-h556-2023-p2::23(c)(iii)": `When light intensity increases (thinner jelly or more light reaching R₂), the resistance of R₂ (the light-dependent component) decreases. A smaller R₂ means a smaller fraction of the supply voltage is dropped across R₂, so V_out decreases. Conversely, when light intensity decreases, R₂ increases and V_out increases. The circuit therefore gives an output voltage that decreases with increasing light intensity.`,
  "phys-ocra-h556-2023-p3::1(a)(i)": `The maximum acceleration occurs at the point in the orbit where the gravitational force (and hence centripetal acceleration = GM/r²) is greatest, i.e. where the distance from Mars is smallest. This is the periapsis (closest approach point). Mark X at the point on the elliptical orbit closest to Mars (the planet is at one focus of the ellipse, so X is at the end of the orbit nearest Mars).`,
  "phys-ocra-h556-2023-p3::1(a)(ii)": `Kepler's 1st law states that every planet (or satellite) moves in an ellipse with the central body at one focus. MAVEN's orbit around Mars is an ellipse, with Mars located at one of the two foci of the ellipse. The orbit is not circular (the altitude varies between about 150 km and 6200 km above the Martian surface), consistent with an elliptical orbit.`,
  "phys-ocra-h556-2023-p3::1(b)(i)": `Kepler's 3rd law states that T² ∝ r³, so T²/r³ should have the same value for every orbit around Mars.

MAVEN: T² = 4.5² = 20.25 h², r³ = 6500³ = 2.746 × 10¹¹ km³ → T²/r³ = 7.4 × 10⁻¹¹ h² km⁻³

Phobos: T² = 7.7² = 59.29 h², r³ = 9400³ = 8.305 × 10¹¹ km³ → T²/r³ = 7.1 × 10⁻¹¹ h² km⁻³

Deimos: T² = 30² = 900 h², r³ = 23 000³ = 1.217 × 10¹³ km³ → T²/r³ = 7.4 × 10⁻¹¹ h² km⁻³

Areostationary: T² = 25² = 625 h², r³ = 20 000³ = 8.00 × 10¹² km³ → T²/r³ = 7.8 × 10⁻¹¹ h² km⁻³

All four values of T²/r³ are the same to within a few per cent, so T²/r³ is constant and the data are consistent with Kepler's 3rd law.`,
  "phys-ocra-h556-2023-p3::1(b)(ii)": `Reason 1: MAVEN's mission is to study the Martian atmosphere at various altitudes. An areostationary orbit is at a fixed high altitude (20,000 km), which would prevent MAVEN from passing through the upper atmosphere at low altitudes where measurements are needed. An elliptical orbit with a low periapsis allows MAVEN to dip into the atmosphere.

Reason 2: An areostationary orbit is only above the Martian equator, so the satellite always observes the same region of Mars. MAVEN needs to study the entire planet (global coverage); an elliptical inclined orbit provides coverage of different latitudes and longitudes.`,
  "phys-ocra-h556-2023-p3::2(a)(i)": `The student used a micrometer screw gauge (or digital micrometer) to measure the diameter of the wire. The student measured at five different positions along the wire and/or in different orientations (to account for non-circularity), recording each reading in the table.`,
  "phys-ocra-h556-2023-p3::2(a)(ii)": `Calculating the value of diameter:
The student identified 0.495 mm as an anomalous result (it is significantly different from the other four values). Excluding this outlier, the remaining four values are: 0.460, 0.450, 0.455, 0.455 mm.
Mean = (0.460 + 0.450 + 0.455 + 0.455)/4 = 1.820/4 = 0.455 mm ✓

Calculating the uncertainty:
The range of the remaining four values = 0.460 − 0.450 = 0.010 mm.
Half-range (as uncertainty) = 0.010/2 = 0.005 mm ✓

So d = 0.455 ± 0.005 mm.`,
  "phys-ocra-h556-2023-p3::2(b)(i)": `The resistance of the wire of length L and cross-sectional area A = πd²/4 is:
R_wire = ρL/A = ρL/(πd²/4) = 4ρL/(πd²)

Applying Kirchhoff's voltage law around the circuit:
ε = I(R_wire + r) = I × (4ρL/(πd²) + r)

Dividing both sides by Iε:
1/I = (4ρL/(πd²ε)) + r/ε

Rearranging:
1/I = (4ρ/(πd²ε)) × L + r/ε  ✓

This is of the form y = mx + c, where y = 1/I, x = L, gradient m = 4ρ/(πd²ε), intercept c = r/ε.`,
  "phys-ocra-h556-2023-p3::2(b)(ii)1": `Take two widely separated points on the best-fit (solid) line, for example (0, 0.40 A⁻¹) and (0.60 m, 3.40 A⁻¹):

gradient = Δ(1/I)/ΔL = (3.40 − 0.40) / (0.60 − 0) = 3.00/0.60 = 5.0 A⁻¹ m⁻¹

Comparing 1/I = (4ρ/(πεd²))L + r/ε with y = mx + c, the gradient is

m = 4ρ/(πεd²)   so   ρ = m πεd²/4

ρ = 5.0 × π × 1.45 × (0.455 × 10⁻³)² / 4
  = 5.0 × π × 1.45 × 2.070 × 10⁻⁷ / 4
  = 4.715 × 10⁻⁶ / 4
  = 1.2 × 10⁻⁶ Ω m

ρ = 1.2 × 10⁻⁶ Ω m`,
  "phys-ocra-h556-2023-p3::2(b)(ii)2": `The intercept of the graph is c = r/ε, so r = (y-intercept) × ε.

The best-fit line cuts the 1/I axis at 0.40 A⁻¹, so

r = 0.40 × 1.45 = 0.58 Ω

For the uncertainty, use the worst-fit (dashed) line, which cuts the axis at 0.73 A⁻¹, together with the largest value of the e.m.f., ε_max = 1.45 + 0.05 = 1.50 V:

r_max = 0.73 × 1.50 = 1.1 Ω

absolute uncertainty = r_max − r = 1.1 − 0.58 = 0.5 Ω

r = 0.6 ± 0.5 Ω`,
  "phys-ocra-h556-2023-p3::3(a)(i)": `A neutron star forms at the end of the life of a massive star (typically greater than about 8 solar masses). When the star's core has exhausted its nuclear fuel, the outward radiation pressure can no longer support the core against gravity. The core collapses rapidly under gravity — this collapse is so energetic that it triggers a supernova explosion of the outer layers. During the collapse, the enormous pressure forces electrons to combine with protons (inverse beta decay: p + e⁻ → n + ν_e), converting virtually all the matter to neutrons. The collapse halts when neutron degeneracy pressure becomes sufficient to resist further compression, leaving a dense, compact neutron star.`,
  "phys-ocra-h556-2023-p3::3(a)(ii)": `A neutron star is extremely dense — its density is of the order of 10¹⁷ kg m⁻³, comparable with the density of an atomic nucleus.

(Any one other correct characteristic would also do, for example that it has an extremely strong gravitational field, that it is supported against further collapse by neutron degeneracy pressure, or that no fusion takes place in it.)`,
  "phys-ocra-h556-2023-p3::3(b)": `Density of neutron star:
ρ_NS = M/V = (2 × 10³⁰) / (4/3 × π × (10⁴)³)
= 2 × 10³⁰ / (4.189 × 10¹²)
= 4.8 × 10¹⁷ kg m⁻³

Density of a nucleon (modelled as a sphere of radius 1 fm = 10⁻¹⁵ m):
Mass of nucleon ≈ 1.67 × 10⁻²⁷ kg
V_nucleon = 4/3 × π × (10⁻¹⁵)³ = 4.189 × 10⁻⁴⁵ m³
ρ_nucleon = 1.67 × 10⁻²⁷ / 4.189 × 10⁻⁴⁵ = 3.99 × 10¹⁷ kg m⁻³ ≈ 4 × 10¹⁷ kg m⁻³

Both values are approximately 4–5 × 10¹⁷ kg m⁻³, confirming that the average density of a neutron star is similar to the density of an atomic nucleus. ✓`,
  "phys-ocra-h556-2023-p3::3(c)(i)": `The energy received is the area between the curve and the time axis, since E = ∫P dt.

On this graph one large square is 1.0 × 10⁻³ s wide and 1.0 × 10⁻²² W high, so each large square represents

1.0 × 10⁻³ × 1.0 × 10⁻²² = 1.0 × 10⁻²⁵ J

Counting the large squares under the curve (counting squares that are more than half filled and ignoring those less than half filled) gives about 11 large squares.

total energy received = 11 × 1.0 × 10⁻²⁵ = 1.1 × 10⁻²⁴ J`,
  "phys-ocra-h556-2023-p3::3(c)(ii)": `Convert the distance to metres: 1 pc = 3.1 × 10¹⁶ m, so

d = 300 × 3.1 × 10¹⁶ = 9.3 × 10¹⁸ m

If the pulsar radiates equally in all directions, by the time the radiation reaches the Earth it is spread over the surface of a sphere of radius d:

A_sphere = 4πd² = 4π × (9.3 × 10¹⁸)² = 1.09 × 10³⁹ m²

The telescope collects only the fraction of this that falls on its 3000 m² surface, so

ratio of areas = 1.09 × 10³⁹ / 3000 = 3.6 × 10³⁵

total energy emitted = ratio × energy received = 3.6 × 10³⁵ × 1.1 × 10⁻²⁴

energy emitted = 4.0 × 10¹¹ J`,
  "phys-ocra-h556-2023-p3::4(a)": `At terminal velocity, the object has zero acceleration (constant velocity). This occurs because the drag force (air resistance) has increased to equal the weight of the object. The net force on the object is zero. By Newton's 1st law, a zero net force means no acceleration, so the object continues to fall at a constant (terminal) velocity. As the object first starts falling it accelerates due to its weight; as speed increases, drag increases (drag ∝ v or v²) until drag equals weight and terminal velocity is reached.`,
  "phys-ocra-h556-2023-p3::4(b)(i)": `Terminal velocity formula: v = 2gr²(ρ_s − ρ_f)/(9η)

For rain drops: they are large water droplets, so r is relatively large (e.g. 0.5–2 mm). Since v ∝ r², larger r gives much larger terminal velocity, so rain drops fall quickly to the ground.

For mist droplets: these are very small water droplets, with r much smaller (e.g. r ~ 1–10 μm). Since v ∝ r², the terminal velocity is extremely small (v ∝ r² means if r is 100× smaller, v is 10,000× smaller). The droplets fall so slowly that they appear to 'float' — upward air currents and Brownian motion can keep them suspended.`,
  "phys-ocra-h556-2023-p3::4(b)(ii)": `Aim: To verify the expression v = 2gr²(ρ_s − ρ_f)/(9η) by measuring the terminal velocity v of solid spheres of different known radii r falling through a liquid.

Apparatus: Measuring cylinder or tall glass tube filled with sunflower oil (η ≈ 50 × 10⁻³ Pa s, ρ_f = 920 kg m⁻³); steel spheres of various diameters (measured with a micrometer); ruler; stopwatch; set square to mark timing lines on the tube.

Method: Release a sphere from the surface of the oil. Allow it to reach terminal velocity (the velocity becomes constant — check by timing over equal intervals). Measure v by timing the sphere over a fixed distance (e.g. 200 mm) in the middle of the tube using the marked lines; v = distance/time. Repeat for spheres of several different radii r. Plot a graph of v against r² — this should be a straight line through the origin with gradient = 2g(ρ_s − ρ_f)/(9η). Compare the experimental gradient to the theoretical value to verify the expression.

Estimate lowest terminal velocity for steel sphere (ρ_s = 7800 kg m⁻³), d = 1 mm so r = 5 × 10⁻⁴ m, in sunflower oil:
v = 2 × 9.81 × (5 × 10⁻⁴)² × (7800 − 920) / (9 × 50 × 10⁻³)
= 2 × 9.81 × 2.5 × 10⁻⁷ × 6880 / (0.45)
= 2 × 9.81 × 1.72 × 10⁻³ / 0.45
= 3.376 × 10⁻² / 0.45
= 0.075 m s⁻¹ = 7.5 cm s⁻¹

This is measurable with a stopwatch over a 200 mm drop (time ~2.7 s), so the experiment is feasible.`,
  "phys-ocra-h556-2023-p3::5(a)(i)": `Energy stored by a capacitor network: W = ½CV²

400 × 10⁶ = ½ × C × (24 × 10³)²

C = 2 × 400 × 10⁶ / (24 × 10³)² = 8.00 × 10⁸ / 5.76 × 10⁸

C = 1.4 F`,
  "phys-ocra-h556-2023-p3::5(a)(ii)": `In a parallel combination, the same voltage V is applied across all capacitors. The total charge stored Q_total = C_total × V = nC × V (n times the charge on one). In a series combination the total capacitance would be C/n, which is much smaller, and the stored energy (E = ½CV²) would be much less. Parallel connection maximises the total capacitance and hence the total energy stored E = ½C_total V², which is needed to power the lasers. Therefore the capacitors are connected in parallel.`,
  "phys-ocra-h556-2023-p3::5(b)": `The network stores 400 MJ and this must all be delivered in less than 1 ms, so the power needed is

P = E/t = 400 × 10⁶ / 1 × 10⁻³ = 4.0 × 10¹¹ W (400 GW)

A large power station generates only about 1 GW, so the lasers would need the entire output of roughly 400 power stations at once — far more than any mains supply could deliver.

(Equivalently, a 1 GW power station supplying the 400 MJ directly would take t = 400 × 10⁶ / 1 × 10⁹ = 0.40 s, which is 400 times longer than the 1 ms allowed.)

The capacitors get round this because they can be charged slowly from the mains over a long period and then discharged in under a millisecond, giving the enormous peak power required.`,
  "phys-ocra-h556-2023-p3::5(c)": `Mass defect of one reaction:

Δm = (2.014102 + 3.016049) − (4.002603 + 1.008665) = 5.030151 − 5.011268 = 0.018883 u

In kilograms: Δm = 0.018883 × 1.661 × 10⁻²⁷ = 3.14 × 10⁻²⁹ kg

Energy released per fusion reaction:

E = Δmc² = 3.14 × 10⁻²⁹ × (3.00 × 10⁸)² = 2.82 × 10⁻¹² J

The energy stored in the capacitor network is 400 MJ, so the number of reactions needed is

N = 400 × 10⁶ / 2.82 × 10⁻¹²

number of fusion reactions = 1.4 × 10²⁰`,
  "phys-ocra-h556-2023-p3::6(a)": `The heater is supplied at ε = 12 V and dissipates 40 W, so using P = V²/R:

R = V²/P = 12² / 40 = 144/40

R = 3.6 Ω

(Equivalently, I = P/V = 40/12 = 3.33 A, then R = V/I = 12/3.33 = 3.6 Ω.)`,
  "phys-ocra-h556-2023-p3::6(b)(i)": `The specific latent heat of fusion is the energy required to change the state of unit mass of a substance from solid to liquid (melting) at constant temperature, without any change in temperature. It is defined as L = Q/m, where Q is the energy supplied to melt a mass m of substance.`,
  "phys-ocra-h556-2023-p3::6(b)(ii)": `The maximum mass is melted when all the energy supplied by the heater goes into melting PLA that is already at its melting point.

Energy supplied in one minute: E = Pt = 40 × 60 = 2400 J

This energy melts a mass m where E = mL:

m = Pt/L = 2400 / (9.4 × 10⁴) = 2.553 × 10⁻²

m = 2.6 × 10⁻² kg (about 26 g)`,
  "phys-ocra-h556-2023-p3::6(b)(iii)": `The calculation in (ii) assumed all heater power was used solely to melt PLA at its melting point. In practice: the PLA enters the heater at room temperature (20°C) and must first be heated from 20°C to the melting point of 160°C — this requires additional energy (mcΔT), so less energy is available for melting. Also, the heater loses heat to the surroundings by conduction, convection and radiation — not all electrical energy goes into the PLA. The printing mechanism itself requires time to move and deposit material, meaning the process cannot be continuous. All these factors reduce the effective melting rate below the theoretical maximum.`,
  "phys-ocra-h556-2023-p3::6(b)(iv)": `The temperature-time graph of PLA from A (20°C) to B (120°C) should show:

1. An initial rising section (positive gradient): the solid PLA heats up from 20°C as energy is supplied by the heater — temperature increases approximately linearly with time (constant specific heat capacity of solid PLA).

2. A horizontal plateau at 160°C (the melting point): temperature remains constant while the PLA melts (latent heat of fusion is absorbed at constant temperature). This plateau continues until all the PLA has melted.

3. A rising section again: liquid PLA heats above 160°C.

4. After being deposited and cooling: the PLA cools and solidifies. A further horizontal plateau at 160°C (solidification, releasing latent heat of fusion at constant temperature) followed by cooling from 160°C down to the final temperature of 120°C (point B).

(Note: points A and B are marked on Fig. 6.1 as 20°C and 120°C respectively; the curve must show the melting plateau at 160°C.)`,
  "phys-ocra-h556-2023-p3::6(c)(i)": `High-energy X-ray photons (MeV range) interact with matter by pair production: a single photon with energy greater than 2m_e c² = 2 × 0.511 MeV = 1.022 MeV can spontaneously convert into an electron–positron pair in the electric field near an atomic nucleus. The photon's energy must exceed the rest mass energy of both particles (1.022 MeV), with any excess going to the kinetic energy of the electron and positron. This process can only occur near a heavy nucleus (to conserve momentum). The created electron and positron travel through the tissue depositing energy (increasing the absorbed dose) before the positron annihilates with another electron.`,
  "phys-ocra-h556-2023-p3::6(c)(ii)": `How CAT scans work: In a Computerised Axial Tomography (CAT/CT) scan, a narrow beam of X-rays is rotated around the patient at many angles. Detectors on the opposite side measure the transmitted X-ray intensity; different tissues absorb X-rays to different degrees (bone absorbs more than soft tissue). A computer reconstructs a 3D image of the internal structure from the attenuation data at many angles using back-projection algorithms. The scan provides detailed 3D anatomical information.

How PET scans work: In Positron Emission Tomography, the patient is injected with a radiotracer (e.g. F-18 labelled glucose). The tracer accumulates in metabolically active regions. When F-18 decays by β⁺ emission, the positron travels a short distance and annihilates with an electron, producing two 511 keV gamma rays travelling in exactly opposite directions. Detectors surrounding the patient detect these coincident gamma pairs, allowing the reconstruction of the 3D distribution of the tracer — showing metabolic activity rather than anatomy.

Advantages and disadvantages of having a scan to produce a bolus:

Advantages: A CAT or PET scan gives a precise 3D map of the patient's body shape and internal anatomy, allowing a bolus to be 3D-printed that fits perfectly — ensuring the maximum radiation dose is accurately targeted to the skin cancer. This improves treatment efficacy and reduces dose to surrounding healthy tissue. The scan is taken only once and the bolus can be reused for multiple treatment sessions.

Disadvantages: Both CAT and PET scans expose the patient to ionising radiation (X-rays for CAT; gamma rays from the radiotracer for PET), which itself carries a small risk of inducing cancer — adding to the radiation burden of the patient. PET scans additionally require injection of a radiotracer, which is invasive. The scans are expensive and require specialist equipment. The time delay between the scan and bolus manufacture must be considered if the patient's body shape changes (e.g. due to weight change or tumour response to treatment), potentially making the bolus less accurate.`,
  "phys-ocra-h556-2024-p1::16(a)(i)": `The graph starts at v = 0 m s⁻¹ at t = 0 and increases with a decreasing gradient (curve becoming less steep). It then levels off at a horizontal plateau at v = 30 m s⁻¹. The value 30 m s⁻¹ should be marked on the vertical axis. The shape is concave down (like a square-root curve), rising steeply at first then flattening out as terminal velocity is reached.`,
  "phys-ocra-h556-2024-p1::16(a)(ii)": `As the car accelerates down the slope, its speed increases. The resistive drag force F = kv² therefore increases as speed increases. The net (resultant) force acting on the car equals the component of weight down the slope minus the drag force. As the drag force grows, the net force decreases, so the acceleration decreases. Eventually, when the drag force equals the component of weight down the slope, the net force is zero and the acceleration is zero. The car therefore reaches a constant maximum speed (terminal velocity).`,
  "phys-ocra-h556-2024-p1::16(a)(iii)": `At the maximum speed the car is no longer accelerating, so the resultant force on it is zero: the total resistive force must equal the component of the car's weight acting down the slope.

Component of weight down the slope = W sin 5° = 9300 × sin 5° = 810 N

At the maximum speed v = 30 m s⁻¹ the resistive force F = kv² is equal to this, so

k = F ÷ v² = 810 ÷ 30² = 810 ÷ 900 = 0.90

k = 0.90 N s² m⁻², which is about 1 as required.`,
  "phys-ocra-h556-2024-p1::16(b)": `On a straight, level track the car travels at its maximum speed when the driving force from the engine is equal to the total resistive force F = kv².

Power delivered = driving force × speed:
P = Fv = (kv²)v = kv³

so v = (P ÷ k)^(1/3)

With P = 75 kW = 7.5 × 10⁴ W and k = 0.90 N s² m⁻² from (a)(iii):

v³ = 75 000 ÷ 0.90 = 8.3 × 10⁴ m³ s⁻³
v = (8.3 × 10⁴)^(1/3) = 44 m s⁻¹

maximum speed = 44 m s⁻¹ (using the rounded value k = 1 gives 42 m s⁻¹).`,
  "phys-ocra-h556-2024-p1::16(c)": `At maximum speed, power = kv³, so v_max = (P/k)^(1/3). If power is doubled: v_new = (2P/k)^(1/3) = 2^(1/3) × (P/k)^(1/3) = 2^(1/3) × v_max ≈ 1.26 × v_max. Since the speed is proportional to the cube root of power, doubling the power only multiplies the maximum speed by ∛2 ≈ 1.26, an increase of about 26%, not 100%. Therefore the maximum speed is not doubled.`,
  "phys-ocra-h556-2024-p1::17(a)": `Newton's second law states that the net (resultant) force acting on a body is proportional to the rate of change of momentum of the body, and that this change of momentum takes place in the direction of the net force.`,
  "phys-ocra-h556-2024-p1::17(b)(i)": `The airflow is diverted 30° below the horizontal at 50 m s⁻¹.

Horizontal component: v_x = 50 cos 30° = 50 × 0.866 = 43.3 m s⁻¹ (in original direction of flow)
Vertical component: v_y = 50 sin 30° = 50 × 0.500 = 25.0 m s⁻¹ (downward)`,
  "phys-ocra-h556-2024-p1::17(b)(ii)": `The airflow exerts a force on the model because the air's momentum changes as it flows around the model. By Newton's second law, the rate of change of momentum of the air equals the force the model exerts on the air. By Newton's third law, the model experiences an equal and opposite force. Since the air is deflected downward, the model exerts a downward force on the air, so the air exerts an upward (lift) force on the model.`,
  "phys-ocra-h556-2024-p1::17(b)(iii)": `Initial horizontal momentum of air per second = 35 × 50 = 1750 kg m s⁻¹
Final horizontal momentum per second = 35 × 43.3 = 1515.5 kg m s⁻¹
Change in horizontal momentum per second = 1750 − 1515.5 = 234.5 N (horizontal force on air, backwards)

Initial vertical momentum per second = 0
Final vertical momentum per second = 35 × 25.0 = 875 kg m s⁻¹ (downward)
Change in vertical momentum per second = 875 N (downward force on air)

By Newton's third law, the vertical force on the model (lift) = 875 N upward.

F = Δp/Δt = 35 × 50 × sin 30° = 35 × 25 = 875 N`,
  "phys-ocra-h556-2024-p1::18(a)(i)": `When F = 6.0 N, h = 0.81 m. The natural (unloaded) length corresponds to h₀ = 1.80 m.
Extension x = 1.80 − 0.81 = 0.99 m ≈ 0.99 m`,
  "phys-ocra-h556-2024-p1::18(a)(ii)": `Plot the missing point at x = 0.99 m, F = 6.0 N, marking it with a neat cross to within half a small square.

Then draw two smooth curves through the points — not ruled straight lines joining point to point.

Loading curve: starts at the origin and passes through the points taken as the masses were added (x = 0.00, 0.20, 0.24, 0.29, 0.35, 0.45 and 0.99 m). It rises steeply from the origin to about (0.45 m, 5.0 N) and then becomes much shallower as the extension increases to 0.99 m at 6.0 N.

Unloading curve: passes through the points taken as the masses were removed (x = 0.67, 0.53, 0.50, 0.46, 0.35 and 0.05 m), starting from the same point at 6.0 N and ending at x = 0.05 m when F = 0, so it does not return to the origin. For any given force the extension is larger than on the loading curve, so this curve lies below (to the right of) the loading curve, enclosing a hysteresis loop.

Label the upper curve "loading" and the lower curve "unloading" (or put arrows on each curve showing the direction in which the readings were taken).`,
  "phys-ocra-h556-2024-p1::18(a)(iii)": `Hooke's law requires that extension is directly proportional to the applied force (F ∝ x). The loading curve is not a straight line through the origin — at low forces (F = 1 to 3 N) the curve may be approximately linear, but at higher forces (F = 5 to 6 N) the extension increases much more rapidly, indicating non-linear behaviour. Furthermore, the loading and unloading curves are different (hysteresis), which is inconsistent with Hooke's law. Therefore Hooke's law cannot be applied to the cord over the full range measured.`,
  "phys-ocra-h556-2024-p1::18(a)(iv)1": `The joule (J). (The area under an F–x graph has units of N × m = J.)`,
  "phys-ocra-h556-2024-p1::18(a)(iv)2": `The area between the two curves is the energy transferred to the rubber during a loading–unloading cycle that is not given back when the rubber relaxes; it appears as an increase in the internal (thermal) energy of the rubber, which therefore warms up slightly each time it is used.

This matters for the planned use because the rubber mat is there to absorb the energy of a heavy object that is dropped on it. The larger this area, the more of the object's kinetic energy is absorbed and dissipated by the rubber instead of being returned to the object, so the object rebounds far less. Because the object is brought to rest over a longer distance and its energy is absorbed, the force exerted on the object, and hence the force exerted on the floor, is smaller, so both the object and the floor are less likely to be damaged.`,
  "phys-ocra-h556-2024-p1::18(b)": `1. The pulley is not frictionless. Some of the weight of the masses is used to overcome friction at the pulley, so the tension in the cord is no longer equal to the weight hung on the other side. Every value of F is then systematically too large, which shifts the whole graph.

2. The masses now hang from the pulley on a rope or string, and this is not perfectly inextensible. As the load is increased the rope stretches as well, so part of the measured change in h is not extension of the rubber cord, making the values of x too large.`,
  "phys-ocra-h556-2024-p1::19": `To determine the wavelength λ of a monochromatic laser pointer using a diffraction grating:

Setup: Direct the laser beam perpendicularly at the diffraction grating. Set up a screen at a measured distance D from the grating (at least 1 m). The grating has a known number of lines per mm, N, so the grating spacing d = 1/N mm = 1/(N × 10³) m.

Data collection: Observe the diffraction maxima on the screen. Measure the distance y_n from the central maximum to each nth-order maximum on both sides (average to reduce error). Calculate the angle θ_n using tan θ_n = y_n / D. Use the grating equation: nλ = d sin θ_n.

Graphical method: Rearrange to sin θ_n = (λ/d) × n. Plot sin θ_n on the y-axis against order number n on the x-axis. Draw a straight line of best fit through the origin. The gradient = λ/d, so λ = gradient × d.

Improving accuracy:
- Use a large distance D (e.g. 2 m or more) to make y_n larger and reduce the percentage uncertainty in the angle.
- Measure the position of the nth-order maximum on both sides of the central maximum and average the two y values.
- Use higher orders of diffraction (n = 2, 3) where available to extend the range of the graph.
- Take multiple readings and calculate a mean.
- Ensure the laser is perpendicular to the grating (zero-order maximum is at same height as the laser).
- Darken the room to make the maxima easier to locate precisely.`,
  "phys-ocra-h556-2024-p1::20(a)(i)": `The internal energy of an ideal gas is the sum of the random kinetic energies of all the molecules/particles in the gas. (There is no potential energy contribution since ideal gas molecules have no intermolecular forces between them.)`,
  "phys-ocra-h556-2024-p1::20(a)(ii)": `From the kinetic theory equation: pV = ⅓ Nm⟨c²⟩, so p = ⅓ (N/V)m⟨c²⟩.
From the ideal gas equation: pV = NkT, so p = NkT/V.

Equating: NkT/V = ⅓ (N/V)m⟨c²⟩
kT = ⅓ m⟨c²⟩
½ m⟨c²⟩ = (3/2)kT

Since ½m⟨c²⟩ is the average kinetic energy of one particle, and (3/2)kT depends only on absolute temperature T (with k and 3/2 being constants), the average kinetic energy is directly proportional to the absolute temperature T.`,
  "phys-ocra-h556-2024-p1::20(b)(i)": `The mean square speed ⟨c²⟩ = (310² + 370² + 440² + 550²) / 4
= (96 100 + 136 900 + 193 600 + 302 500) / 4
= 729 100 / 4
= 182 275 m² s⁻²

c_rms = √182 275 = 427 m s⁻¹ ≈ 430 m s⁻¹ (as required)`,
  "phys-ocra-h556-2024-p1::20(b)(ii)": `Using ½M_m c_rms² = (3/2)RT, where M_m is the molar mass:
M_m = 3RT / c_rms²
= (3 × 8.31 × 290) / (430²)
= 7230.9 / 184 900
= 0.03911 kg mol⁻¹
≈ 0.039 kg mol⁻¹ (39 g mol⁻¹)

(This is consistent with argon, molar mass ≈ 40 g mol⁻¹.)`,
  "phys-ocra-h556-2024-p1::20(c)(i)": `When the filament is switched on, electrical energy is converted to thermal energy in the filament, causing its temperature to rise. As the temperature of the filament increases, it emits electromagnetic radiation (infrared and visible light) at an increasing rate, as the power emitted by a black body is proportional to T⁴ (Stefan–Boltzmann law). At 2400 K, the rate of energy emission (and conduction/convection losses to the surrounding gas) equals the rate of electrical energy input. At this point, energy input equals energy output, so there is no net energy gain and the temperature remains constant at 2400 K. The filament reaches thermal equilibrium at this temperature.`,
  "phys-ocra-h556-2024-p1::20(c)(ii)": `Using the ideal gas law at constant volume (sealed lamp): p₁/T₁ = p₂/T₂

p₁/290 = 120 × 10³/2400
p₁ = (120 × 10³ × 290) / 2400
p₁ = 34 800 000 / 2400
p₁ = 14 500 Pa = 1.45 × 10⁴ Pa`,
  "phys-ocra-h556-2024-p1::21(a)(i)": `Wien's displacement law states λ_max T = 2.90 × 10⁻³ m K. From Fig. 21.1, the peak wavelength of the spectrum of Nu Persei is read off the graph. If λ_max ≈ 460 nm = 4.60 × 10⁻⁷ m:
T = 2.90 × 10⁻³ / 4.60 × 10⁻⁷ = 6304 K ≈ 6300 K (as required).`,
  "phys-ocra-h556-2024-p1::21(a)(ii)": `Treat Nu Persei as a sphere radiating as a black body, so its luminosity is given by the Stefan–Boltzmann law L = 4πr²σT⁴.

Rearranging: r = √(L ÷ (4πσT⁴))

With L = 2.3 × 10²⁹ W, σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴ and T = 6300 K:

6300⁴ = 1.58 × 10¹⁵ K⁴
4π × 5.67 × 10⁻⁸ × 1.58 × 10¹⁵ = 1.12 × 10⁹

r = √(2.3 × 10²⁹ ÷ 1.12 × 10⁹) = √(2.05 × 10²⁰)

radius = 1.4 × 10¹⁰ m`,
  "phys-ocra-h556-2024-p1::21(b)(i)": `Power collected by sensor = 7.0 × 10⁻¹⁵ W.
Efficiency = 11% = 0.11.
Total power arriving at sensor area = 7.0 × 10⁻¹⁵ / 0.11 = 6.36 × 10⁻¹⁴ W.
Area of sensor = 1.0 × 10⁻⁴ m².
Radiant power per unit area = 6.36 × 10⁻¹⁴ / 1.0 × 10⁻⁴ = 6.36 × 10⁻¹⁰ W m⁻² ≈ 6 × 10⁻¹⁰ W m⁻² (as required).`,
  "phys-ocra-h556-2024-p1::21(b)(ii)": `By the time it reaches Earth the radiation is spread evenly over a sphere whose radius r is the distance to Nu Persei, so the radiant power per unit area (intensity) at Earth is

I = L ÷ 4πr²

Rearranging: r = √(L ÷ (4πI))

With L = 2.3 × 10²⁹ W and I = 6.4 × 10⁻¹⁰ W m⁻² from (b)(i):

4π × 6.4 × 10⁻¹⁰ = 8.0 × 10⁻⁹
r² = 2.3 × 10²⁹ ÷ 8.0 × 10⁻⁹ = 2.9 × 10³⁷ m²
r = 5.4 × 10¹⁸ m

One light year = 9.5 × 10¹⁵ m, so

distance = 5.4 × 10¹⁸ ÷ 9.5 × 10¹⁵ = 5.6 × 10²

distance ≈ 560 light years`,
  "phys-ocra-h556-2024-p1::21(c)": `The luminosity used in (b)(ii) was not measured directly — it was read off the HR diagram using the surface temperature of 6300 K, and that is where most of the uncertainty comes from.

At 6300 K the main sequence on Fig. 21.2 is a broad band of points rather than a single line. Reading the band vertically at 6300 K gives lg(L/L☉) of roughly 0 to 1, so the luminosity could be anywhere between about L☉ and about 10 L☉ — a spread of a factor of ten.

Because r = √(L ÷ 4πI), the distance depends on the square root of the luminosity, so the percentage uncertainty in the distance is only half the percentage uncertainty in the luminosity. Even so, a factor of ten in L still gives a factor of about √10 ≈ 3 in the distance.

In addition, there is no guarantee that Nu Persei lies on the main sequence at all; a star at 6300 K could be a giant lying well above the band, which would make its luminosity, and therefore the calculated distance, much larger. The value found in (b)(ii) is therefore only an order-of-magnitude estimate.`,
  "phys-ocra-h556-2024-p1::22(a)(i)": `One condition: the orbit must be in the equatorial plane of the Earth (directly above the equator), and the satellite must orbit in the same direction as the Earth's rotation (west to east) with an orbital period of exactly 24 hours.`,
  "phys-ocra-h556-2024-p1::22(a)(ii)": `For a circular orbit, gravitational force provides centripetal force:
GMm/r² = mω²r
GM = ω²r³
r³ = GM/ω²

Period T = 24 hours = 24 × 3600 = 86 400 s
ω = 2π/T = 2π/86 400 = 7.272 × 10⁻⁵ rad s⁻¹

r³ = (6.67 × 10⁻¹¹ × 6.0 × 10²⁴) / (7.272 × 10⁻⁵)²
= (4.002 × 10¹⁴) / (5.288 × 10⁻⁹)
= 7.569 × 10²²
r = (7.569 × 10²²)^(1/3)
= 4.23 × 10⁷ m (42 300 km)`,
  "phys-ocra-h556-2024-p1::22(b)(i)": `For a satellite in circular orbit of radius r around a planet of mass M:
Gravitational force = centripetal force:
GMm/r² = mv²/r
So mv² = GMm/r
Kinetic energy: E_k = ½mv² = GMm/(2r)

Gravitational potential energy: E_p = mV_g = m(−GM/r) = −GMm/r

Therefore E_k = GMm/(2r) = ½ × GMm/r = ½ |E_p|
So kinetic energy = ½ × magnitude of gravitational potential energy. (QED)`,
  "phys-ocra-h556-2024-p1::22(b)(ii)": `Energy needed = change in total mechanical energy from surface to orbit.

At Earth's surface:
Gravitational PE per unit mass = V_g(surface) = −63 MJ kg⁻¹
KE per unit mass at surface = 0 (launched from rest)
Total energy per unit mass at surface = −63 MJ kg⁻¹

In orbit:
V_g(orbit) = −56 MJ kg⁻¹
Using E_k = ½|E_p| = ½ × 56 = 28 MJ kg⁻¹
Total energy per unit mass in orbit = −56 + 28 = −28 MJ kg⁻¹

Energy required per kg = −28 − (−63) = 35 MJ kg⁻¹
For satellite of mass 1.0 kg: Energy required = 35 MJ

Since 35 MJ > 30 MJ, the satellite must gain more than 30 MJ. (Shown.)`,
  "phys-ocra-h556-2024-p1::22(c)": `From (b)(ii), the satellite needs 35 MJ to reach orbit from rest at the surface.

Advantage of equatorial launch (rotation of Earth):
KE from Earth's rotation at equator = ½mv² = ½ × 1.0 × 460² = 105 800 J ≈ 0.106 MJ
This is only 0.106/35 = 0.3% of the required energy — a very small contribution.

Advantage of aircraft launch:
At altitude 10 000 m, aircraft has:
- KE: ½ × 1.0 × 230² = 26 450 J ≈ 0.026 MJ
- Reduced energy needed (satellite already 10 km higher): change in V_g ≈ g × h = 9.81 × 10 000 = 98 100 J ≈ 0.098 MJ
- Total advantage ≈ 0.026 + 0.098 ≈ 0.124 MJ

Evaluation:
Advantage: Aircraft launch gives a small energy saving (~0.12 MJ = 0.3% of 35 MJ) and can be done from anywhere without a fixed ground launch site, offering more flexibility. It avoids the need for a fixed equatorial launch site. A smaller rocket is needed, reducing cost.

Limitation: The energy savings are very small (less than 0.5% of the total energy needed), so the rocket must still provide over 34.9 MJ. The aircraft itself consumes fuel carrying the rocket. There are safety concerns about launching a rocket from an aircraft. The rocket also needs to be designed for air launch. The Earth's rotation benefit (0.106 MJ) is similarly very small. Neither strategy provides a significant energy saving — the dominant energy requirement (35 MJ) is from climbing against gravity and gaining orbital speed.`,
  "phys-ocra-h556-2024-p1::23(a)": `The photon carries away the energy lost by the electron as it falls from level X to level Y.

ΔE = E_X − E_Y = (−0.58 × 10⁻¹⁹) − (−5.42 × 10⁻¹⁹) = 4.84 × 10⁻¹⁹ J

Using E = hf = hc/λ and rearranging for the wavelength:

λ = hc ÷ ΔE
= (6.63 × 10⁻³⁴ × 3.00 × 10⁸) ÷ (4.84 × 10⁻¹⁹)
= 1.989 × 10⁻²⁵ ÷ 4.84 × 10⁻¹⁹
= 4.11 × 10⁻⁷ m

λ = 411 nm, i.e. about 410 nm as required.`,
  "phys-ocra-h556-2024-p1::23(b)(i)": `The dark lines are absorption lines. The continuous spectrum of light from the hot stars at the centre of the galaxy passes through the cooler outer atmosphere of the stars (and gas clouds). Electrons in atoms in this cooler gas absorb photons of specific wavelengths, causing them to jump to higher energy levels. These specific wavelengths are therefore removed from the spectrum, producing dark absorption lines at those wavelengths. The pattern of dark lines is characteristic of the chemical elements present.`,
  "phys-ocra-h556-2024-p1::23(b)(ii)": `The transition X→Y produces a rest wavelength λ₀ = 410 nm.
The observed wavelength is λ = 432 nm.
Redshift z = (λ − λ₀)/λ₀ = (432 − 410)/410 = 22/410 = 0.0537

Using the Doppler formula for recession velocity (v << c):
v = zc = 0.0537 × 3.00 × 10⁸ = 1.61 × 10⁷ m s⁻¹ ≈ 1.6 × 10⁷ m s⁻¹`,
  "phys-ocra-h556-2024-p1::23(b)(iii)": `The Big Bang theory.`,
  "phys-ocra-h556-2024-p2::16(a)": `The voltmeter has been connected in series in the circuit. The student should move the voltmeter so that it is connected in parallel with (across) the thermistor, leaving the ammeter in series with the thermistor so that it still measures the current through it.`,
  "phys-ocra-h556-2024-p2::16(b)(i)": `Plot the remaining data points on the graph: (50, 1.51), (60, 2.10), (70, 2.80), (80, 3.66), (90, 4.76). Each point should be plotted as a small cross or dot at the correct coordinates.`,
  "phys-ocra-h556-2024-p2::16(b)(ii)": `Draw a smooth curve of best fit through all the plotted points. The curve is exponential in shape — it curves upward with increasing gradient from bottom-left to top-right, passing through or close to all the data points. The line should be smooth, not ruled between points.`,
  "phys-ocra-h556-2024-p2::16(c)": `As temperature increases, the current increases (from the graph). Since the voltage is constant at 3.00 V, and R = V/I:

At 30 °C: R = 3.00/0.75 × 10⁻³ = 4000 Ω
At 90 °C: R = 3.00/4.76 × 10⁻³ = 630 Ω

As temperature increases, resistance decreases significantly (from ~4000 Ω to ~630 Ω). This is the behaviour of a Negative Temperature Coefficient (NTC) thermistor — resistance decreases as temperature increases. Therefore the student used an NTC thermistor.`,
  "phys-ocra-h556-2024-p2::16(d)": `Circuit 1: V_out is taken directly across the thermistor. Since there are no other components, V_out = 3.00 V at all temperatures (the full supply voltage). The output does not change with temperature, so Circuit 1 is not suitable as a temperature-sensing circuit.

Circuit 2: The thermistor and 10 kΩ fixed resistor form a potential divider. V_out = V_supply × R_thermistor / (R_thermistor + 10 kΩ).

At 30 °C: R_thermistor ≈ 4000 Ω, V_out = 3.00 × 4000/14000 = 0.86 V
At 90 °C: R_thermistor ≈ 630 Ω, V_out = 3.00 × 630/10630 = 0.18 V

As temperature increases, V_out decreases. This is suitable for a heating system: when the milk is cool (low T), V_out is high, which could trigger the heater to turn on. When the milk is warm (high T), V_out is low, turning the heater off. Circuit 2 is therefore suitable for the heating system as V_out responds to temperature changes.`,
  "phys-ocra-h556-2024-p2::17(a)": `At P1, the two loudspeakers X and Y are equidistant, so the path difference is zero. The waves from X and Y arrive in phase and interfere constructively, producing a loud sound (maximum). As the microphone moves from P1 to P3, the path difference increases. At P2, the path difference equals half a wavelength, so the waves arrive in antiphase and interfere destructively, producing a quiet sound (minimum). This pattern of alternating loud and quiet results from the superposition (interference) of the two coherent wave sources.`,
  "phys-ocra-h556-2024-p2::17(b)": `P1 and P3 are adjacent maxima and the minimum P2 lies halfway between them, so the distance P1 to P2 is half the separation of adjacent maxima.

Separation of adjacent maxima, x = 2 × 1.25 = 2.50 m

Using the two-source interference formula λ = ax/D, with slit (loudspeaker) separation a = 70.0 cm = 0.700 m and D = 4.00 m:

λ = (0.700 × 2.50) ÷ 4.00 = 0.4375 m

Then, using v = fλ:

f = v ÷ λ = 340 ÷ 0.4375 = 777 Hz

frequency ≈ 780 Hz`,
  "phys-ocra-h556-2024-p2::17(c)": `At positions where constructive interference previously occurred (e.g. at P1), the two waves still arrive in phase, but now Y has amplitude 2A and X has amplitude A. The combined amplitude = 2A + A = 3A (constructive). At positions of destructive interference, the signals partially cancel: amplitude = 2A − A = A (not zero). The microphone will therefore observe that maxima are louder than before (larger amplitude), the minima are no longer silent (there is a minimum amplitude of A rather than zero), and there is no longer complete cancellation. The pattern still alternates between louder and quieter regions, but the minima have a non-zero signal.`,
  "phys-ocra-h556-2024-p2::17(d)(i)": `Intensity is the power transmitted per unit area perpendicular to the direction of wave propagation. It is measured in watts per square metre (W m⁻²). Intensity is proportional to the square of the amplitude of the wave.`,
  "phys-ocra-h556-2024-p2::17(d)(ii)": `Original situation at P1: both speakers have amplitude A, and at P1 (constructive interference) the resultant amplitude = A + A = 2A.
Intensity at P1 (original): I ∝ (2A)² = 4A²

New situation: speaker Y has amplitude 2A, speaker X has amplitude A. At P1 (constructive), resultant amplitude = 2A + A = 3A.
Intensity at P1 (new): I' ∝ (3A)² = 9A²

Factor by which intensity is larger = 9A²/4A² = 9/4 = 2.25

The intensity at P1 in (c) is 2.25 times larger than the original intensity at P1.`,
  "phys-ocra-h556-2024-p2::18(a)": `Circuit diagram (labelled): a low-voltage a.c. supply (or signal generator) connected across the primary coil, which is wound on the iron core; on the same core a secondary coil, connected in a loop containing an a.c. ammeter in series with a fixed load resistor. Label the number of turns on each coil (N_p and N_s), the core, the a.c. supply and the ammeter. An a.c. supply is essential, because only a changing current gives a changing flux linkage and so an induced e.m.f. in the secondary.

Method: Wind a primary coil with a small, fixed number of turns (for example N_p = 20) and connect it to the a.c. supply. Wind a secondary coil on the same core, counting the turns as they are wound; because the transformer is to be a step-up transformer, N_s must be larger than N_p, so start with about 40 turns. Switch on and record the output current I_s shown by the a.c. ammeter and the number of secondary turns N_s. Add more turns to the secondary (for example in steps of 20, up to about 200 turns) and record I_s each time, obtaining at least six pairs of readings. Throughout the experiment keep the input a.c. voltage, the number of primary turns, the core and the load resistor unchanged, and switch off between readings so that the coils do not heat up and change resistance.

Analysis: For an ideal transformer V_s / V_p = N_s / N_p, and since energy is conserved V_p I_p = V_s I_s. Combining these gives I_s = I_p N_p / N_s. With V_p, N_p and the load kept constant, this predicts that I_s is inversely proportional to N_s, i.e. I_s ∝ 1 / N_s.

To test this, plot 1 / I_s on the vertical axis against N_s on the horizontal axis (or equivalently I_s against 1 / N_s). If the relationship holds, the points lie on a straight line passing through the origin.

Alternatively, plot lg I_s against lg N_s. Since I_s = constant × N_s^n gives lg I_s = lg(constant) + n lg N_s, the graph is a straight line whose gradient is n; a gradient of −1 confirms that I_s ∝ 1 / N_s.`,
  "phys-ocra-h556-2024-p2::18(b)(i)": `Faraday's law states that the induced e.m.f. in a conductor is directly proportional to (equal to) the rate of change of magnetic flux linkage through that conductor. (EMF = −dNΦ/dt, where NΦ is the flux linkage.)`,
  "phys-ocra-h556-2024-p2::18(b)(ii)": `Using the transformer turns ratio: V_s/V_p = N_s/N_p
N_s = N_p × V_s/V_p = 920 × 5.0/230 = 920/46 = 20 turns (as required).`,
  "phys-ocra-h556-2024-p2::18(b)(iii)": `Using Faraday's law for the secondary coil:
EMF = −N_s × ΔΦ/Δt
So ΔΦ = EMF × Δt / N_s

Output voltage = 3.4 V, N_s = 20, Δt = 1.2 ms = 1.2 × 10⁻³ s

ΔΦ = 3.4 × 1.2 × 10⁻³ / 20
= 4.08 × 10⁻³ / 20
= 2.04 × 10⁻⁴ Wb
≈ 2.0 × 10⁻⁴ Wb

Unit: weber (Wb) (or T m², or V s)`,
  "phys-ocra-h556-2024-p2::19(a)": `Energy of one light photon:
E_light = hc / λ = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) ÷ (510 × 10⁻⁹) = 3.90 × 10⁻¹⁹ J

Energy of one X-ray photon:
E_X-ray = 32 keV = 32 × 10³ × 1.60 × 10⁻¹⁹ = 5.12 × 10⁻¹⁵ J

Only 15% of the X-ray photon's energy is converted into light by the crystal, so

number of light photons = (E_X-ray ÷ E_light) × 0.15
= (5.12 × 10⁻¹⁵ ÷ 3.90 × 10⁻¹⁹) × 0.15
= 13 128 × 0.15
= 1969

So each X-ray photon produces about 2000 light photons, as required.`,
  "phys-ocra-h556-2024-p2::19(b)(i)": `The work function is the minimum energy required to remove a photoelectron from the surface of the photocathode material. It is the minimum energy needed to liberate an electron from the metal surface.`,
  "phys-ocra-h556-2024-p2::19(b)(ii)": `From (a), each light photon of wavelength 510 nm has energy

E = hc / λ = (6.63 × 10⁻³⁴ × 3.00 × 10⁸) ÷ (510 × 10⁻⁹) = 3.90 × 10⁻¹⁹ J

Work function φ = 2.3 eV = 2.3 × 1.60 × 10⁻¹⁹ = 3.68 × 10⁻¹⁹ J

Using Einstein's photoelectric equation, KE_max = hf − φ:

KE_max = 3.90 × 10⁻¹⁹ − 3.68 × 10⁻¹⁹ = 2.2 × 10⁻²⁰ J

(equivalently 2.44 − 2.3 = 0.14 eV)`,
  "phys-ocra-h556-2024-p2::19(b)(iii)": `From (a), each X-ray photon produces ~2000 light photons.
12 X-ray photons per minute → 12 × 2000 = 24 000 light photons per minute.
Each light photon produces one photoelectron (given all photons produce photoelectrons).
Number of electrons per second = 24 000 / 60 = 400 electrons per second.
Current I = number of electrons per second × charge per electron
I = 400 × 1.60 × 10⁻¹⁹ = 6.4 × 10⁻¹⁷ A`,
  "phys-ocra-h556-2024-p2::19(b)(iv)": `That the X-ray photons arrive at a steady rate throughout the minute (one every 5 s), so that the current is continuous rather than a series of short pulses.`,
  "phys-ocra-h556-2024-p2::20(a)": `The nuclear binding energy of a nucleus is the energy required to completely separate all the nucleons (protons and neutrons) in the nucleus from each other, dispersing them to infinity. Equivalently, it is the energy released when the nucleons combine from an unbound state to form the nucleus. It equals the mass defect multiplied by c².`,
  "phys-ocra-h556-2024-p2::20(b)": `¹₁H (a single proton) has no neutrons and no nuclear binding — it consists of a single nucleon and cannot be split into smaller nucleons. Therefore it has zero binding energy per nucleon and cannot be plotted on a binding energy per nucleon graph. (The concept of nuclear binding energy only applies to nuclei with more than one nucleon.)`,
  "phys-ocra-h556-2024-p2::20(c)(i)": `On the binding energy per nucleon graph, nuclei with low mass numbers (such as hydrogen isotopes) lie on the left-hand side where the curve has a steep positive gradient. When two light nuclei fuse, the product nucleus has a higher binding energy per nucleon than the reactants. This means the product is more tightly bound, and energy is released equal to the increase in total binding energy. Fusion of light nuclei therefore releases energy. (For heavy nuclei, fission releases energy instead as they move to higher binding energy per nucleon by splitting.)`,
  "phys-ocra-h556-2024-p2::20(c)(ii)": `From the binding energy per nucleon diagram:
- ²₁H (deuterium): binding energy per nucleon ≈ 1.1 MeV, A = 2, total BE ≈ 2.2 MeV
- ³₁H (tritium): binding energy per nucleon ≈ 2.8 MeV, A = 3, total BE ≈ 8.4 MeV
- ⁴₂He: binding energy per nucleon ≈ 7.1 MeV, A = 4, total BE ≈ 28.4 MeV
- ¹₀n: BE = 0

Energy released = BE(products) − BE(reactants)
= (28.4 + 0) − (2.2 + 8.4) MeV
= 28.4 − 10.6 = 17.8 MeV

17.8 MeV × 1.60 × 10⁻¹³ J/MeV = 2.85 × 10⁻¹² J ≈ 3 × 10⁻¹² J (as required).`,
  "phys-ocra-h556-2024-p2::20(c)(iii)": `The Sun's power output comes from the mass it loses each second, using E = Δmc²:

energy released per second = 4.3 × 10⁹ × (3.00 × 10⁸)² = 4.3 × 10⁹ × 9.00 × 10¹⁶ = 3.87 × 10²⁶ J s⁻¹

From (c)(ii), each fusion event releases 2.85 × 10⁻¹² J (17.8 MeV).

number of fusion events per second = 3.87 × 10²⁶ ÷ 2.85 × 10⁻¹²
= 1.4 × 10³⁸ s⁻¹`,
  "phys-ocra-h556-2024-p2::20(d)(i)": `Conservation of charge: left side has 1 + 1 = +2. Right side: ²₁H has charge +1; ⁰₊₁e⁺ has charge +1. So right side already has charge +2 from these two. The missing particle must have charge 0 (zero charge).`,
  "phys-ocra-h556-2024-p2::20(d)(ii)": `The missing particle is a neutrino (electron neutrino, νₑ). (It is a lepton with zero charge, which balances lepton number: left side has 0 leptons, right side has 1 positron (lepton number −1) so the neutrino has lepton number +1.)`,
  "phys-ocra-h556-2024-p2::20(d)(iii)": `Each proton (¹₁H nucleus) consists of 2 up quarks and 1 down quark.
Two protons at the start: 2 × (2u + 1d) = 4 up quarks + 2 down quarks.
Total number of up quarks at the start = 4.`,
  "phys-ocra-h556-2024-p2::20(e)": `In β⁻ decay, a down quark changes to an up quark:
d → u + e⁻ + ν̄ₑ

For tritium decay: ³₁H → ³₂He + e⁻ + ν̄ₑ
In terms of quarks: one down quark becomes an up quark:
d → u + e⁻ + ν̄ₑ`,
  "phys-ocra-h556-2024-p2::21(a)(i)": `A tracer is a radioactive substance (radioisotope) that is introduced into the body (usually injected) and is designed to be taken up by specific organs or tissues. The radiation emitted by the tracer is detected outside the body to produce an image or to monitor the function of the organ. The tracer allows doctors to diagnose medical conditions without surgery.`,
  "phys-ocra-h556-2024-p2::21(a)(ii)": `Advantage 1: Gamma radiation is highly penetrating and can pass through the body tissue to be detected outside the body by a gamma camera, allowing imaging without surgery.

Advantage 2: Gamma radiation does not cause as much ionisation damage to body tissue as alpha or beta radiation (lower ionising power), so the risk of tissue damage is reduced. (Also: gamma emitters do not irradiate tissues near the injection site as heavily as alpha/beta emitters.)`,
  "phys-ocra-h556-2024-p2::21(b)(i)": `Activity A = λN, where λ = ln2/t½

t½ = 6.01 hours = 6.01 × 3600 = 21 636 s
λ = ln 2 / 21 636 = 0.6931 / 21 636 = 3.203 × 10⁻⁵ s⁻¹

A = 900 MBq = 900 × 10⁶ = 9.00 × 10⁸ Bq

N = A/λ = 9.00 × 10⁸ / 3.203 × 10⁻⁵ = 2.81 × 10¹³
N ≈ 2.8 × 10¹³ nuclei`,
  "phys-ocra-h556-2024-p2::21(b)(ii)": `A = A₀ e^(−λt)
We want A/A₀ = 3.0% = 0.030
0.030 = e^(−λt)
ln(0.030) = −λt
−3.507 = −3.203 × 10⁻⁵ × t
t = 3.507 / 3.203 × 10⁻⁵ = 1.095 × 10⁵ s

Convert to hours: t = 1.095 × 10⁵ / 3600 = 30.4 hours ≈ 30 hours

Alternatively: A/A₀ = (1/2)^(t/t½), so 0.030 = (0.5)^(t/6.01)
t/6.01 = log(0.030)/log(0.5) = (−1.523)/(−0.3010) = 5.06
t = 5.06 × 6.01 = 30.4 hours ≈ 30 hours`,
  "phys-ocra-h556-2024-p2::21(c)": `The half-life of ⁹⁹₄₃Tc is over 200 000 years, which means it decays extremely slowly. The activity (decay rate) from the small amount present in the body will be negligibly small — far too low to cause significant ionising radiation dose to the patient. Furthermore, 50% of it passes out of the body relatively quickly, and the amount initially present is very small (only a few nanograms). The dose received is therefore negligible compared to natural background radiation.`,
  "phys-ocra-h556-2024-p2::21(d)": `Method
Use a Geiger–Müller tube connected to a counter (or ratemeter), with a stopwatch for timing, and a clamp and stand to hold the tube.

Before bringing the source out, measure the background radiation: with no source nearby, record the number of counts for one minute, and repeat over at least three minutes so that a reliable mean background count per minute is obtained.

Take the source from its lead-lined box using tongs, holding it at arm's length and pointing it away from the body, and clamp it a short fixed distance in front of the GM tube. Neither the source nor the tube is moved for the rest of the experiment. Record the number of counts in exactly one minute, timed with the stopwatch, and then return the source to the lead-lined box. Repeat this once every hour for six hours.

For each reading, subtract the mean background count per minute from the measured count per minute to obtain the corrected count rate, then take its natural logarithm and plot ln(corrected count rate / minute) against time in hours.

Determining the half-life
The corrected count rate is proportional to the activity, and A = A₀e^(−λt), so ln A = ln A₀ − λt. The graph is therefore a straight line of gradient −λ.

Taking two widely separated points on the line of best fit, the value falls from 7.81 at t = 0 to 7.51 at t = 6.0 hours:

gradient = (7.51 − 7.81) ÷ (6.0 − 0) = −0.050 hour⁻¹
so λ = 0.050 hour⁻¹

t½ = ln 2 ÷ λ = 0.693 ÷ 0.050 = 13.9 hours

The half-life is therefore about 14 hours (about 8.3 × 10² minutes, or 5.0 × 10⁴ s).`,
  "phys-ocra-h556-2024-p2::22(a)(i)": `Draw at least four straight, vertical, equally spaced parallel lines in the space between the two horizontal capacitor plates, with at least one of them touching both the upper plate and the lower plate. Put an arrowhead on each line pointing vertically downwards, from the positive upper plate towards the negative lower plate. Equally spaced parallel lines represent the uniform field of an ideal parallel-plate capacitor.`,
  "phys-ocra-h556-2024-p2::22(a)(ii)": `A real thunder cloud is not a pair of flat parallel plates: the top and the bottom of the cloud are uneven and are not parallel to each other, and the charge on them is not spread out uniformly. The field between them is therefore non-uniform, so the actual field lines would not all be straight, vertical and equally spaced — they would be closer together where the charged regions are closer together or where the charge density is greater, and they would spread out at the edges of the cloud.`,
  "phys-ocra-h556-2024-p2::22(a)(iii)": `V = E × d = 4.0 × 10⁵ × 3.2 × 10³ = 1.28 × 10⁹ V ≈ 1 × 10⁹ V (as required).`,
  "phys-ocra-h556-2024-p2::22(a)(iv)": `C = ε₀A/d, where A is the plate area (circular plates).
Radius = 24/2 = 12 km = 12 000 m
A = πr² = π × (12 000)² = π × 1.44 × 10⁸ = 4.52 × 10⁸ m²
d = 3.2 × 10³ m
C = (8.85 × 10⁻¹² × 4.52 × 10⁸) / (3.2 × 10³)
= (4.00 × 10⁻³) / (3.2 × 10³)
= 1.25 × 10⁻⁶ F ≈ 1.3 μF`,
  "phys-ocra-h556-2024-p2::22(a)(v)": `Q = CV = 1.25 × 10⁻⁶ × 1.28 × 10⁹ = 1600 C ≈ 1.6 × 10³ C`,
  "phys-ocra-h556-2024-p2::22(b)(i)": `Using V = kQ/r = Q/(4πε₀r), where the cloud acts as a point charge:
Q = 155 C, r = 2.0 km = 2.0 × 10³ m
V = Q/(4πε₀r) = (155) / (4π × 8.85 × 10⁻¹² × 2.0 × 10³)
= 155 / (2.228 × 10⁻⁷)
= 6.96 × 10⁸ V ≈ 7.0 × 10⁸ V`,
  "phys-ocra-h556-2024-p2::22(b)(ii)": `The strike lasts 25 ms and the cloud discharges completely (155 C).
Charge reaching ground per second = 155 / (25 × 10⁻³) = 6200 C s⁻¹ = 6200 A

Charge in 1.0 ms = 6200 × 1.0 × 10⁻³ = 6.2 C

Number of electrons = Q/e = 6.2 / (1.60 × 10⁻¹⁹) = 3.875 × 10¹⁹ ≈ 3.9 × 10¹⁹ electrons`,
  "phys-ocra-h556-2024-p3::1(a)": `A standard flute acts as an open pipe at both ends (both the embouchure hole and the far end are effectively open). For an open pipe, the fundamental frequency has a wavelength λ = 2L, where L is the length of the pipe.

The lowest note on a standard flute is C4 (middle C) at approximately 262 Hz. Using v = fλ:
v_sound = 340 m s⁻¹ (at room temperature)
λ = v/f = 340/262 = 1.298 m
L = λ/2 = 1.298/2 = 0.649 m ≈ 0.65 m (as required).

(Speed of sound in air at ~20°C ≈ 340 m s⁻¹; f = 262 Hz gives L ≈ 0.65 m.)`,
  "phys-ocra-h556-2024-p3::1(b)(i)": `Assumption 1: The collisions between gas molecules and the walls of the container are perfectly elastic (no energy lost in collisions).
Assumption 2: The volume of the gas molecules themselves is negligible compared to the volume of the container (molecules are treated as point masses).`,
  "phys-ocra-h556-2024-p3::1(b)(ii)": `For helium: γ = 1.67 and M = 4.00 g mol⁻¹ = 4.00 × 10⁻³ kg mol⁻¹. The temperature is T = −10 °C = 263 K, and R = 8.31 J mol⁻¹ K⁻¹.

v = √(γRT/M) = √(1.67 × 8.31 × 263 / 4.00 × 10⁻³) = √(9.12 × 10⁵) = 955 m s⁻¹

The flute itself is unchanged, so the lowest note still corresponds to the fundamental of a pipe open at both ends, with λ = 2L = 2 × 0.65 = 1.30 m.

f = v/λ = 955 / 1.30 = 735 Hz ≈ 730 Hz (2 s.f.)

The lowest frequency inside the chamber is about 730 Hz — much higher than 262 Hz because sound travels far faster in helium (small molar mass).`,
  "phys-ocra-h556-2024-p3::2(a)": `The N capacitors are in parallel, so the total capacitance is C_total = NC. The N resistors are in series, so the total resistance is R_total = NR. The time constant of the discharge circuit is therefore

τ = R_total × C_total = NR × NC = N²RC

When switch X is opened the capacitors discharge through the resistors, and the current (the ammeter reading) decays exponentially:

I = I₀e^(−t/τ)

T is defined as the time for the reading to fall to half its initial value, so

I₀/2 = I₀e^(−T/τ)  →  ½ = e^(−T/N²RC)

Taking natural logarithms of both sides:

ln ½ = −T/(N²RC), and since ln ½ = −ln 2, this gives ln 2 = T/(N²RC)

Therefore T = (ln 2)N²RC, as required.`,
  "phys-ocra-h556-2024-p3::2(b)": `Data are precise when repeated readings are closely clustered about their mean — that is, when the spread (range) of the repeats is small compared with the value being measured. Judged on that basis the students' claim is largely justified, and it can be supported with numbers from their own table.

For N = 1 the three readings 14.7, 14.1 and 14.3 s have a range of only 0.6 s, an uncertainty of ±0.3 s on a mean of 14.4 s, i.e. about 2%. For N = 6 the range is 512.7 − 499.5 = 13.2 s, i.e. ±6.6 s on a mean of 504.2 s, which is only about 1.3%. For N = 3 and N = 4 the spreads are smaller still (1.4 s and 1.6 s, well under 1%).

The one weak set is N = 5, where 345.6 s lies well below 356.1 and 354.3 s: the range is 10.5 s (±5.3 s, about 1.5%), so that repeat is noticeably less consistent than the others and might be an anomaly worth repeating.

So overall the repeats do agree to within about 1–2%, which supports the statement — but precision says nothing about accuracy, so close agreement does not prove the values of T are correct.`,
  "phys-ocra-h556-2024-p3::2(c)": `For N = 1: mean T = (14.7 + 14.1 + 14.3)/3 = 43.1/3 = 14.4 s

For N = 2: mean T = (50.3 + 49.6 + 50.1)/3 = 150.0/3 = 50.0 s

Both means are written to 1 decimal place, the same precision as the individual readings.`,
  "phys-ocra-h556-2024-p3::2(d)(i)": `The x-axis (N²) is already drawn and scaled from 0 to 40; the y-axis is blank, so it has to be completed first.

Label the y-axis "T / s" and give it a scale that fits the largest value (504.2 s) while filling the grid: mark 100, 200, 300, 400 and 500 s every two large squares from the origin, i.e. 50 s per large square (0 to 600 s).

Then plot the six results as (N², mean T):
(1, 14.4), (4, 50.0), (9, 126.0), (16, 224.9), (25, 352.0) and (36, 504.2).

Each point should be a small, sharp cross (or a dot in a circle) placed to within half a small square of the correct position. No error bars are needed.`,
  "phys-ocra-h556-2024-p3::2(d)(ii)": `Draw a straight line of best fit through the plotted points, passing as close as possible to all points, with roughly equal numbers of points above and below the line. The line should pass through or near the origin (since T = 0 when N = 0).`,
  "phys-ocra-h556-2024-p3::2(d)(iii)": `Draw a large gradient triangle on the best-fit line, using at least half the length of the line (Δx of at least 17.5 on the N² axis), and take the coordinates from the line itself, not from the plotted data points.

The line passes essentially through the origin, so taking the points (0, 0) and (36, 504) that lie on it:

gradient = ΔT/Δ(N²) = (504 − 0)/(36 − 0) = 14 s

gradient ≈ 14 s (any value between about 13 and 15 s from a correctly drawn line).`,
  "phys-ocra-h556-2024-p3::2(d)(iv)": `Comparing T = (ln 2)N²RC with y = mx shows that the gradient of the T against N² graph is

gradient = (ln 2)RC,  so  R = gradient/(C ln 2)

With gradient = 14 s and C = 1000 μF = 1.000 × 10⁻³ F:

R = 14 / (1.000 × 10⁻³ × 0.693) = 2.0 × 10⁴ Ω = 20 kΩ

The only uncertainty quoted is the ±5% in C, and R ∝ 1/C, so the percentage uncertainty in R is also 5%:

ΔR = 0.05 × 20 = 1 kΩ

R = 20 ± 1 kΩ

(The uncertainty is given to the same number of decimal places as R.)`,
  "phys-ocra-h556-2024-p3::2(e)(i)": `Systematic error.`,
  "phys-ocra-h556-2024-p3::2(e)(ii)": `Two 470 μF capacitors in parallel give a combined capacitance of 940 μF, not 1000 μF. The capacitance used for N = 6 was less than expected (940 μF instead of 1000 μF). Since T = (ln 2)N²RC, a smaller C gives a smaller T for N = 6. This means the gradient of the T vs N² graph is slightly smaller than it should be (one data point is too low), leading to a calculated value of R that is smaller than the true value of R.`,
  "phys-ocra-h556-2024-p3::3(a)": `By Newton's third law, when the rocket engine expels hot gas backwards (exerts a force on the gas in the backward direction), the gas exerts an equal and opposite force (thrust) on the rocket in the forward direction. By Newton's first law, before ignition the rocket is stationary (resultant force = 0). Once the engine fires, there is a resultant forward force on the rocket. By Newton's second law (F = ma), this resultant force causes the rocket to accelerate in the forward (upward) direction. Between t = 0 and t = 50 s, the thrust from the engine exceeds the weight of the rocket plus air resistance, so there is a net upward force and the rocket accelerates upward.`,
  "phys-ocra-h556-2024-p3::3(b)": `At B the rocket's velocity is 3.1 km s⁻¹ = 3100 m s⁻¹ at 75° to the horizontal, so its vertical component is

v_B = 3100 sin 75° = 2994 m s⁻¹

Stage 1 — A to B (powered flight, 0 to 50 s)
Assumptions: the thrust and the mass of the rocket stay constant, so the acceleration is uniform, and the rocket climbs along the straight line A to B. Taking vertical motion with u = 0, v = 2994 m s⁻¹ and t = 50 s:

s₁ = ½(u + v)t = ½ × 2994 × 50 = 7.49 × 10⁴ m ≈ 74.9 km

Stage 2 — B to C (unpowered ascent)
Assumptions: air resistance is negligible at this altitude, so the only force is the rocket's weight; the horizontal component of velocity (3100 cos 75° = 802 m s⁻¹) is unchanged and does not affect the vertical motion; at C the vertical velocity is zero. With u = 2994 m s⁻¹, v = 0 and a = −9.81 m s⁻²:

v² = u² + 2as  →  s₂ = 2994²/(2 × 9.81) = 4.57 × 10⁵ m ≈ 457 km

Total vertical displacement:

H = s₁ + s₂ = 74.9 + 457 ≈ 5.3 × 10² km (about 530 km)

Evaluating the assumption that g = 9.81 m s⁻² throughout
Outside the Earth the gravitational field strength obeys g ∝ 1/r², where r is measured from the Earth's centre. At A, r_A = 6400 km; at C, r_C = 6400 + 530 = 6930 km. Hence

g_C/g_A = r_A²/r_C² = (6400/6930)² = 0.85

so g_C ≈ 0.85 × 9.81 ≈ 8.3 m s⁻² — a fall of about 15% between A and C.

A 15% change is far from negligible, so taking g as a constant 9.81 m s⁻² over the whole flight is a poor assumption. Because the true value of g falls steadily as the rocket climbs, the deceleration during stage 2 is on average smaller than 9.81 m s⁻², so the rocket would actually coast higher than calculated: the value of about 530 km is an underestimate of the real maximum height. The calculation is still useful as a first estimate, but a more reliable treatment would use energy conservation with the 1/r gravitational potential rather than the suvat equations.`,
  "phys-ocra-h556-2024-p3::4(a)": `To determine the spring constant k experimentally:
1. Suspend the spring vertically from a clamp and stand.
2. Attach a mass hanger to the lower end and measure the initial length (natural length) of the spring with a ruler.
3. Add known masses (e.g. 100 g increments) and measure the new length each time. Record the extension x = new length − natural length.
4. Record the applied force F = mg for each mass.
5. Plot a graph of F (y-axis) against x (x-axis).
6. Draw a straight line of best fit. The gradient of this line equals k (in N m⁻¹).
7. Only use the linear portion of the graph (Hooke's law region) to find the gradient.`,
  "phys-ocra-h556-2024-p3::4(b)(i)": `The spring is already stretched by 3.2 cm at P, where the spring force balances the weight, so the extra force provided by F is what stretches it the further

d = 8.5 − 3.2 = 5.3 cm

At the instant F is removed, the weight is still balanced by the spring force due to the first 3.2 cm of extension, so the resultant (upward) force on the block is the spring force due to the extra 5.3 cm:

F_resultant = kd = 0.62 × 5.30 = 3.3 N

(Equivalently: resultant force = 0.62 × 8.50 − 0.20 × 9.81 = 5.27 − 1.96 = 3.3 N.)

a = F/m = 3.3/0.20 = 17 m s⁻²

The initial acceleration is about 17 m s⁻², directed upwards.`,
  "phys-ocra-h556-2024-p3::4(b)(ii)": `For a mass on a spring the restoring force is F = kx, so a = −(k/m)x. Comparing this with the defining equation of simple harmonic motion, a = −ω²x, gives ω² = k/m.

The force constant in SI units is k = 0.62 N cm⁻¹ = 62 N m⁻¹, and m = 0.20 kg:

ω = √(k/m) = √(62/0.20) = √310 = 17.6 rad s⁻¹

f = ω/2π = 17.6/6.283 = 2.8 Hz

(The same result follows from the answer to (b)(i): ω² = a/x = 16.5/0.053 = 311 s⁻², giving f = 2.8 Hz.)

The frequency of the motion is 2.8 Hz.`,
  "phys-ocra-h556-2024-p3::4(c)(i)": `As magnet M (attached to the vibration generator) oscillates in and out of coil Y, the magnetic flux through coil Y changes. By Faraday's law, this induces an alternating EMF in coil Y. Since coil Y is connected to coil X by wires, this EMF drives an alternating current through the circuit (coils X and Y connected in series). This alternating current in coil X produces a changing magnetic field inside X. By Faraday's/Lenz's law, the changing magnetic flux through coil X exerts a force on magnet L inside it. Since the current alternates at the driving frequency, the force on L alternates, causing L to oscillate. The spring-mass system with L therefore experiences a periodic driving force and oscillates.`,
  "phys-ocra-h556-2024-p3::4(c)(ii)": `As the frequency of the vibration generator is varied from 0.5 Hz to 5.0 Hz:

Amplitude: The amplitude of L's oscillations will be small at low frequencies (e.g. 0.5 Hz), will increase as the driving frequency approaches the natural frequency of the spring-mass system (2.5 Hz), reaching a maximum at resonance (driving frequency ≈ 2.5 Hz). Above 2.5 Hz, the amplitude will decrease again, becoming small at 5.0 Hz. This produces a resonance peak in the amplitude-frequency graph, with the peak at approximately 2.5 Hz.

Frequency: The frequency of L's oscillations always equals the driving frequency (the forced frequency), not its natural frequency. So as the generator frequency increases from 0.5 to 5.0 Hz, the frequency of L's oscillations also increases from 0.5 to 5.0 Hz throughout.

(A diagram would show an amplitude vs driving frequency curve with a sharp peak at ~2.5 Hz.)`,
  "phys-ocra-h556-2024-p3::5(a)(i)": `The internal resistance of a cell is the resistance within the cell itself, due to the materials making up the electrodes and electrolyte. It causes a voltage drop (lost volts) inside the cell when current flows, so the terminal voltage is less than the e.m.f.`,
  "phys-ocra-h556-2024-p3::5(a)(ii)": `The e.m.f. (electromotive force) of a cell is the energy transferred (work done) by the cell per unit charge that flows around the complete circuit. It is measured in volts (J C⁻¹). It equals the terminal voltage only when no current flows.`,
  "phys-ocra-h556-2024-p3::5(b)": `The lamp and the internal resistance are in series, so

ε = V + Ir, i.e. 5.6 = V + 1.2I

Rearranging gives the load line for the cell:

I = (5.6 − V)/1.2 = 4.7 − 0.83V

Draw this straight line on the same axes as the I–V characteristic of B: it runs from (V = 0, I = 4.7 A) down to (V = 5.6 V, I = 0). The operating point of the circuit is where this line crosses the lamp's characteristic, because only there do the lamp and the cell carry the same current at the same p.d.

Reading off the intersection gives V ≈ 2.2 V and

I = 2.8 A

(Check: 2.8 × 1.2 = 3.4 V of lost volts, and 5.6 − 3.4 = 2.2 V across the lamp, which matches the characteristic.)`,
  "phys-ocra-h556-2024-p3::5(c)": `The student should use the thermistor as the external resistance (since its resistance ~0.1 Ω is similar to the internal resistance ~0.1 Ω, which will make the effect of internal resistance significant and measurable).

Circuit: Connect the thermistor in series with the ammeter and the cell. Connect the voltmeter across the thermistor (= terminal voltage V).

Data collection: Change the resistance of the thermistor by changing its temperature (e.g. using a water bath at different temperatures). For each temperature, record the current I (from ammeter) and terminal voltage V (from voltmeter). Collect at least 6 pairs of (I, V) values.

Analysis: Use ε = V + Ir → V = ε − Ir. Plot V (y-axis) against I (x-axis). The graph should be a straight line:
- y-intercept = ε (e.m.f.)
- gradient = −r (negative of internal resistance)

Determining uncertainties:
- Draw lines of maximum and minimum gradient through the error bars on the graph.
- Uncertainty in ε = range of y-intercepts of the two extreme lines / 2.
- Uncertainty in r = range of gradients of the two extreme lines / 2.
- State percentage uncertainties for each.

(Note: The thermistor resistance changes with temperature, which allows variation of I without a standard variable resistor — essential since none is available.)`,
  "phys-ocra-h556-2024-p3::6(a)": `The electric force on a charge in a uniform field is F = EQ, and the proton carries a charge Q = +1.60 × 10⁻¹⁹ C:

F = EQ = 0.90 × 1.60 × 10⁻¹⁹ = 1.4 × 10⁻¹⁹ N

This is about 10⁻¹⁹ N, as required. It is constant in both magnitude and direction (vertically upwards, since the field is upwards and the proton is positive) because the field is uniform and the force does not depend on the proton's velocity.`,
  "phys-ocra-h556-2024-p3::6(b)(i)": `The magnetic force on the proton is F = Bqv, where v is the speed of the proton. At X and Y, the electric force is the same (constant E field, constant q), but the proton has different speeds at X and Y because it has been accelerated by the electric field between X and Y. Since the magnetic force depends on the speed (F = Bqv), and the speed is different at X and Y, the magnetic force has a different magnitude at the two points.`,
  "phys-ocra-h556-2024-p3::6(b)(ii)": `First find the speed at X from the magnetic force, F = BQv:

v = F/(BQ) = 5.6 × 10⁻¹⁹ / (5.0 × 10⁻⁵ × 1.60 × 10⁻¹⁹) = 7.0 × 10⁴ m s⁻¹

At X the proton moves horizontally to the right, so the magnetic force (BQv) is vertically downwards while the constant electric force of 1.4 × 10⁻¹⁹ N is vertically upwards. Both are perpendicular to the velocity, so the resultant force is also perpendicular to the velocity and acts as the centripetal force:

F_R = (5.6 − 1.4) × 10⁻¹⁹ = 4.2 × 10⁻¹⁹ N (downwards)

Using F_R = mv²/r with the proton mass m = 1.67 × 10⁻²⁷ kg:

r = mv²/F_R = (1.67 × 10⁻²⁷ × (7.0 × 10⁴)²) / (4.2 × 10⁻¹⁹)
 = 8.2 × 10⁻¹⁸ / 4.2 × 10⁻¹⁹

r = 20 m`,
  "phys-ocra-h556-2024-p3::6(b)(iii)1": `At Y the proton is moving vertically downwards, so the magnetic force (always perpendicular to the velocity) is horizontal and has magnitude 3.9 × 10⁻¹⁹ N, while the electric force is vertical (upwards) with the constant magnitude 1.4 × 10⁻¹⁹ N found in (a).

The two forces are at right angles, so the magnitude of the resultant is found with Pythagoras:

|F| = √[(3.9 × 10⁻¹⁹)² + (1.4 × 10⁻¹⁹)²] = √(15.2 + 1.96) × 10⁻¹⁹ = √17.2 × 10⁻¹⁹

|F| = 4.1 × 10⁻¹⁹ N`,
  "phys-ocra-h556-2024-p3::6(b)(iii)2": `At Y, the resultant force is not directed purely perpendicular to the velocity of the proton. The magnetic force (Bqv) is always perpendicular to the velocity, but the electric force (qE) is always in a fixed direction (along the field lines), which is not necessarily perpendicular to the velocity at Y. Since the proton's velocity direction at Y has changed (it has been deflected by the combined fields between X and Y), the electric force component along the direction of motion is non-zero at Y. This means the electric force does work on the proton at Y, changing its kinetic energy (speed). Since the speed is changing, the motion cannot be equivalent to uniform circular motion (which requires constant speed). Therefore the motion at Y is not instantaneously equivalent to circular motion at constant speed.`,
  "phys-ocrb-h557-2022-p1::31(a)": `The equipotential lines are equally spaced: every 1 m rise in height corresponds to the same change in gravitational potential, 1.6 J kg⁻¹. Since the gravitational field strength is the potential gradient, g = ΔV_grav/Δh, equal potential steps for equal steps in height mean that g has the same value everywhere in the region shown — the field is uniform on this scale.`,
  "phys-ocrb-h557-2022-p1::31(b)": `Assumptions: the gravitational field strength stays constant over the whole flight (the height reached is very small compared with the radius of the Moon), and there is no air resistance.
From the diagram the potential rises by 1.6 J kg⁻¹ for each 1 m of height, so g = 1.6 N kg⁻¹.
At the highest point the vertical velocity is zero, so using v² = u² − 2gh with v = 0:
h = u²/2g = 20.0²/(2 × 1.6) = 400/3.2 = 125 m.`,
  "phys-ocrb-h557-2022-p1::32(a)": `On Fig. 32.2, above the narrower slit, draw at least three wavefronts. They must have exactly the same spacing as the plane waves arriving from below, and the same spacing as the wavefronts in Fig. 32.1, because passing through the slit does not change the wavelength.
Each wavefront should be a symmetrical arc centred on the slit. Because the slit is narrower the waves spread out more than in Fig. 32.1: the arcs should be curved along almost their whole length (approaching semicircles) rather than being flat across the middle, and each should extend noticeably further sideways beyond the dashed lines than the corresponding wavefront in Fig. 32.1.`,
  "phys-ocrb-h557-2022-p1::32(b)": `Each narrow slit acts as a source of secondary wavelets (Huygens' principle). For the direction shown by the arrow, the path difference between waves from adjacent slits is exactly one wavelength. Therefore waves from all slits arrive at the screen in phase with one another — they interfere constructively. This produces a bright line (maximum intensity) in that direction. The wavefronts from neighbouring slits, having a path difference of λ, add up coherently in that direction.`,
  "phys-ocrb-h557-2022-p1::33": `Relativistic principle: the invariance of the speed of light — the radar pulse travels at 3.00 × 10⁸ m s⁻¹ on the way out and at the same speed on the way back, whatever the motion of the spacecraft.
The journey time is for the round trip, so the distance to the spacecraft is half of c × (journey time). Between the two pulses the round-trip time increases by 3335.586 − 3335.564 = 0.022 s, so the spacecraft has moved further away by
½ × 0.022 × 3.00 × 10⁸ = 3.3 × 10⁶ m.
That extra distance is covered in the 1800.00 s between the pulses, so
v = 3.3 × 10⁶ / 1800.00 = 1.83 × 10³ m s⁻¹ (about 1830 m s⁻¹).`,
  "phys-ocrb-h557-2022-p1::34(a)": `Shaded area: the area under a graph of charge against p.d. is the sum of VΔQ, which is the work done in moving charge onto the capacitor — that is, the energy transferred to the capacitor. The shaded strip runs from V = 0.4 V to V = 1.2 V, where the charge rises from 1.7 mC to 5.0 mC, so it represents the energy stored as the p.d. is raised from 0.4 V to 1.2 V. Using E = ½QV at each end:
E = ½ × 5.0 × 10⁻³ × 1.2 − ½ × 1.7 × 10⁻³ × 0.4 = 3.0 × 10⁻³ − 0.34 × 10⁻³ = 2.7 × 10⁻³ J.
Gradient: the gradient of the line is Q/V, and capacitance is defined by C = Q/V, so the gradient of this graph is the capacitance of the capacitor. The line is straight and passes through the origin, showing that C is constant; here C = 5.0 × 10⁻³/1.2 ≈ 4.2 × 10⁻³ F.`,
  "phys-ocrb-h557-2022-p1::34(b)": `The equation ΔQ = −(Q/RC)Δt gives the small change in charge ΔQ on the capacitor in a short time interval Δt. The method is as follows:

1. Start with the initial charge Q₀ at t = 0.
2. Calculate ΔQ = −(Q/RC)Δt using the current value of Q.
3. Update: Q_new = Q + ΔQ (the charge decreases because ΔQ is negative).
4. Increment time: t_new = t + Δt.
5. Repeat steps 2–4 using Q_new as the new value of Q.

By repeating this process many times with a small Δt, the charge at any time t can be built up iteratively. The smaller Δt is chosen, the more accurate the result, as the approximation that Q is constant within each interval becomes better. The graph of Q against t will trace out an exponential decay, approximating Q = Q₀ e^(−t/RC).`,
  "phys-ocrb-h557-2022-p1::35(a)": `Method: if E ∝ 1/r² then the product E × r² must be the same for every row of the table. Working it out for each pair of values:
r = 0.20 m: Er² = 5.6 × 10⁵ × 0.20² = 2.24 × 10⁴
r = 0.30 m: Er² = 2.5 × 10⁵ × 0.30² = 2.25 × 10⁴
r = 0.40 m: Er² = 1.4 × 10⁵ × 0.40² = 2.24 × 10⁴
The three values are the same to within the precision of the data, so Er² = constant, i.e. E = constant/r² and the field strength is inversely proportional to the square of the distance from the centre of the charge.`,
  "phys-ocrb-h557-2022-p1::35(b)": `Electric field strength E ∝ 1/r², so E falls off rapidly with distance. Electric potential V ∝ 1/r, so V falls off more gradually. This is because V is related to E by V = ∫E dr; integrating 1/r² gives 1/r, which decreases more slowly.

Arithmetical example: If r doubles (say from 1 m to 2 m), E decreases by a factor of 4 (from E to E/4), whereas V decreases by only a factor of 2 (from V to V/2). So the potential drops to half its value while the field drops to a quarter of its value over the same distance change. This means V decreases more gradually than E with increasing distance.`,
  "phys-ocrb-h557-2022-p1::36(a)": `From the diagrams, light travels in medium 1 at speed c₁ and in medium 2 at speed c₂. In time t, the wavefront in medium 1 travels a distance c₁t = AB sin i (where AB is the length along the boundary) and in medium 2 travels c₂t = AB sin r. Therefore:

sin i / sin r = c₁t / c₂t = c₁ / c₂

Hence sin i / sin r = c₁ / c₂. □`,
  "phys-ocrb-h557-2022-p1::36(b)": `Apply Snell's law at each interface, noting that as light passes from air into glass and then from glass into water, the relevant refractive indices apply. Using sin i / sin r = c₁/c₂ and noting that at each boundary the ratio of sines equals the ratio of speeds:

For the air–glass interface: sin 30° / sin r_g = c_air / c_glass = 3.00×10⁸ / 1.99×10⁸
sin r_g = sin 30° × (1.99/3.00) = 0.500 × 0.6633 = 0.3317
r_g = 19.4°

For the glass–water interface, using the angle in glass as the new angle of incidence:
sin r_g / sin r_w = c_glass / c_water = 1.99×10⁸ / 2.26×10⁸
sin r_w = sin r_g × (2.26/1.99) = 0.3317 × 1.136 = 0.3768
r_w = arcsin(0.3768) ≈ 22.1° ≈ 22°`,
  "phys-ocrb-h557-2022-p1::36(c)(i)": `A monochromatic (single-wavelength) light source is used because the refractive index of glass varies with wavelength (dispersion). Using a single wavelength ensures a unique, well-defined refractive index is measured, so the relationship sin i / sin r = n is unambiguous and the measurements are not blurred by dispersion.`,
  "phys-ocrb-h557-2022-p1::36(c)(ii)": `The angle of incidence is set by the student before the ray is sent into the block and is measured directly against a drawn normal, so it is known quite precisely. The angle of refraction is not measured directly: the path of the ray inside the block has to be constructed afterwards by joining the point where the ray enters to the point where the emergent ray leaves the block. Locating those points and drawing the line between them introduces extra uncertainty (thick pencil lines, small errors in marking the emergent ray), so r — and therefore sin r — carries a bigger uncertainty than the pre-set angle i.`,
  "phys-ocrb-h557-2022-p1::36(c)(iii)": `A constant uncertainty in angle (e.g. ±0.5°) does not translate to a constant uncertainty in the sine. The uncertainty in sin θ is approximately Δ(sin θ) ≈ cos θ × Δθ (in radians). Since cos θ varies with angle — it is large near θ = 0° (cos 0° = 1) and small near θ = 90° (cos 90° = 0) — the uncertainty in the sine changes with angle. Therefore a constant angular uncertainty gives a smaller uncertainty in sin θ at large angles and a larger uncertainty at small angles. The uncertainty in sin θ is not constant, so assuming a constant uncertainty in the sines is unlikely to be correct.`,
  "phys-ocrb-h557-2022-p1::36(c)(iv)": `Method: the graph is sin i against sin r, so its gradient is the refractive index. As well as the best-fit line, draw the steepest line and the shallowest line that still pass through all of the range bars, and find the gradient of each using readings taken at least a third of the way along the line.
The steepest such line has a gradient of about 1.80 and the shallowest about 1.30. The uncertainty in the refractive index is half the spread of these extreme gradients: (1.80 − 1.30)/2 = 0.25, which is quoted to one significant figure as 0.3.
Refractive index of the glass block = 1.5 ± 0.3.`,
  "phys-ocrb-h557-2022-p1::37(a)(i)": `Converting acceleration: 1.9 km h⁻¹ s⁻¹ = 1900 m / 3600 s per second = 0.5278 m s⁻²
Top speed: 300 km h⁻¹ = 300000/3600 = 83.33 m s⁻¹

Using v = u + at with u = 0:
t = v/a = 83.33 / 0.5278 ≈ 158 s ≈ 160 s ✓`,
  "phys-ocrb-h557-2022-p1::37(a)(ii)": `Work done during acceleration = change in kinetic energy (ignoring friction as stated):
Ek = ½mv² = ½ × 7.15×10⁵ × (83.33)² = ½ × 7.15×10⁵ × 6944 = 2.483×10⁹ J

Average power = Ek / t = 2.483×10⁹ / 158 ≈ 1.57×10⁷ W ≈ 1.6×10⁷ W (2 s.f.)`,
  "phys-ocrb-h557-2022-p1::37(b)(i)": `v = 300 km h⁻¹ = 83.33 m s⁻¹
F_D = ½ × C_D × A × ρ × v² = ½ × 1.5 × 13.5 × 1.2 × (83.33)²
= ½ × 1.5 × 13.5 × 1.2 × 6944
= ½ × 168 750 = 84 375 N

Power = F_D × v = 84 375 × 83.33 ≈ 7.03×10⁶ W ≈ 7.0×10⁶ W (2 s.f.)`,
  "phys-ocrb-h557-2022-p1::37(b)(ii)": `Estimate of passenger mass: Average mass per passenger ≈ 70 kg (must state estimate clearly)
Total passenger mass = 1300 × 70 = 91 000 kg = 9.1×10⁴ kg
Total mass (full) = 7.15×10⁵ + 9.1×10⁴ = 8.06×10⁵ kg

Acceleration of full train:
From F = ma with the same driving force F = m_empty × a_empty = 7.15×10⁵ × 0.5278 = 3.77×10⁵ N
a_full = F / m_full = 3.77×10⁵ / 8.06×10⁵ ≈ 0.468 m s⁻² = 1.68 km h⁻¹ s⁻¹

This is about 11–12% less than 1.9 km h⁻¹ s⁻¹, so the train accelerates noticeably more slowly when full.

Effect on power to maintain 300 km/h against drag:
The drag force F_D = ½C_D A ρ v² depends on v and the cross-sectional area A. The passengers do not significantly change A (they are inside the train), so the drag force at 300 km/h is unchanged. Therefore the power required to overcome air drag is the same (≈7.0 MW) whether the train is full or empty.

Passing through a narrow tunnel:
In a narrow tunnel, the air cannot flow freely around the train; it is forced through the gap between train and tunnel walls. This reduces the effective area available for airflow, greatly increasing the aerodynamic resistance (ram effect / piston effect). The drag force increases substantially, so a much greater power is required to maintain 300 km/h. The closer the tunnel walls are to the train (smaller gap), the larger this additional drag.`,
  "phys-ocrb-h557-2022-p1::38(a)": `Procedure to determine absolute zero:
1. Set up the capillary tube vertically in the water bath with the sealed end at the bottom and the liquid index trapping a column of air above the seal.
2. Measure the length L of the trapped air column using the rule alongside the tube.
3. Record the temperature T (in °C) using the thermometer in the water bath.
4. Heat (or cool) the water bath to different temperatures and record L at each temperature.
5. Plot a graph of L against T (°C). Since pressure is constant (column of air is open via the index), V ∝ T (K), so L ∝ T (K). The graph is linear.
6. Extrapolate the straight line back to L = 0. The temperature at which L = 0 is absolute zero in degrees Celsius.

Why constant bore is necessary: The volume of trapped gas V = A × L, where A is the cross-sectional area of the bore. If A is constant throughout, then V ∝ L and the length is a direct measure of volume. If A varies, L would not be proportional to V, invalidating the method.

Sources of uncertainty and how to reduce them:
- Reading the position of the liquid index against the rule: use a set square to avoid parallax errors; take multiple readings.
- Temperature not being uniform throughout the tube: stir the water bath frequently and allow time to reach thermal equilibrium before recording.
- The index itself occupying a length of tube: keep the index as short as possible.

Why trapped air will not give an accurate value of absolute zero: Air is not an ideal gas. At very low temperatures, air starts to liquify (oxygen liquifies at 90 K, nitrogen at 77 K), so the gas-law extrapolation breaks down before absolute zero is reached. Even above these temperatures, intermolecular forces cause deviations from ideal gas behaviour, so the straight line will curve and the extrapolated intercept will not be exactly 0 K.`,
  "phys-ocrb-h557-2022-p1::38(b)(i)": `Using the ideal gas law: pV = nRT
V = L × A = L × 5.0×10⁻³ m²
p = 1.0×10⁵ Pa, n = 0.24 mol, T = 298 K, R = 8.31 J mol⁻¹ K⁻¹

V = nRT/p = (0.24 × 8.31 × 298) / (1.0×10⁵)
= (594.3) / (1.0×10⁵)
= 5.943×10⁻³ m³

L = V / A = 5.943×10⁻³ / 5.0×10⁻³ = 1.189 m ≈ 1.2 m ✓

Reasoning: At constant (atmospheric) pressure, the ideal gas equation pV = nRT gives the volume directly. Dividing by the cross-sectional area gives the length of the column.`,
  "phys-ocrb-h557-2022-p1::38(b)(ii)": `In the kinetic model the gas particles are in continuous random motion, and each collision with the underside of the disc reverses a particle's momentum. The rate of change of momentum of all the particles striking unit area is the pressure the gas exerts on the disc; the air above pushes down on the disc in exactly the same way.
When the gas is heated its particles gain kinetic energy and move faster, so each collision with the disc produces a larger momentum change and the collisions also happen more often. The upward force on the underside of the disc therefore becomes greater than the downward force from the atmosphere, and the disc is pushed upwards.
As the disc rises the same number of particles occupy a greater volume, so they strike the disc less frequently. The disc keeps moving up until the rate of change of momentum per unit area on the two sides of the disc is equal again, which is at a greater length L.`,
  "phys-ocrb-h557-2022-p1::38(b)(iii)": `The pressure is unchanged at 1.0 × 10⁵ Pa and the new volume is V = 5.0 × 10⁻³ × 1.8 = 9.0 × 10⁻³ m³, so
pV = 1.0 × 10⁵ × 9.0 × 10⁻³ = 900 J.
From the kinetic model pV = ⅓Nm⟨c²⟩, where N = 0.24 × 6.02 × 10²³ = 1.45 × 10²³ particles and m = 6.6 × 10⁻²⁶ kg, so Nm = 9.5 × 10⁻³ kg.
⟨c²⟩ = 3pV/(Nm) = 3 × 900 / 9.5 × 10⁻³ = 2.83 × 10⁵ m² s⁻²
r.m.s. speed = √(2.83 × 10⁵) = 532 m s⁻¹ ≈ 5.3 × 10² m s⁻¹.`,
  "phys-ocrb-h557-2022-p1::39(a)": `The binding energy of a nucleus is the energy that must be supplied to completely separate all the nucleons (protons and neutrons) in the nucleus into free, unbound particles at rest at infinity. Equivalently, it is the energy released when the nucleus is assembled from its constituent free nucleons.

Calculation: The mass of the individual unbound protons and neutrons (Z × m_p + N × m_n) is greater than the actual mass of the nucleus (mass deficit = Δm). Using Einstein's mass–energy equivalence: binding energy = Δm × c² = (Z·m_p + N·m_n − m_nucleus) × c².`,
  "phys-ocrb-h557-2022-p1::39(b)(i)": `Read the binding energy per nucleon of each fission product from Fig. 39.1 and multiply by the nucleon number to get the total binding energy:
¹³⁷₅₄Xe: about −8.4 MeV per nucleon, so 137 × (−8.4) = −1151 MeV
⁹⁴₃₈Sr: about −8.6 MeV per nucleon, so 94 × (−8.6) = −808 MeV
The three neutrons are released free, so they contribute no binding energy.
Total binding energy of the products = −1151 + (−808) = −1959 MeV, compared with −1778 MeV for the ²³⁴₉₂U nucleus.
The products are more tightly bound than the uranium nucleus, and the difference in binding energy is released:
energy released = −1778 − (−1959) = 181 MeV, i.e. about 200 MeV.`,
  "phys-ocrb-h557-2022-p1::39(b)(ii)": `Energy released per fission ≈ 200 MeV = 200 × 10⁶ × 1.60×10⁻¹⁹ J = 3.20×10⁻¹¹ J

Total energy needed in one year:
E = P × t = 1400×10⁶ × 3.2×10⁷ = 4.48×10¹⁶ J

Number of fissions required:
N_fissions = E / E_per_fission = 4.48×10¹⁶ / 3.20×10⁻¹¹ = 1.40×10²⁷

Mass of ²³⁴U:
m = N_fissions × m_atom = 1.40×10²⁷ × 3.89×10⁻²⁵ = 545 kg ≈ 540 kg (2 s.f.)`,
  "phys-ocrb-h557-2022-p1::39(c)": `Energy needed per second = 1400 MJ = 1.4×10⁹ J
Energy per fission = 3.20×10⁻¹¹ J (from above)
Number of ²³⁴U nuclei needed = 1.4×10⁹ / 3.20×10⁻¹¹ = 4.375×10¹⁹

These ²³⁴U nuclei must come from decay of ²³³Pa. The decay rate ΔN/Δt = λN gives the number of ²³³Pa that decay per second:
λ = ln2 / t½ = 0.693 / 1600 = 4.33×10⁻⁴ s⁻¹

For ΔN/Δt = 4.375×10¹⁹ s⁻¹ (need 4.375×10¹⁹ decays per second):
N(Pa) = (ΔN/Δt) / λ = 4.375×10¹⁹ / 4.33×10⁻⁴ = 1.010×10²³

Mass of ²³³Pa = N × m_atom = 1.010×10²³ × 3.87×10⁻²⁵ = 3.91×10⁻² kg ≈ 39 g

This is a minimum value because: not every ²³³Pa nucleus that decays will produce a ²³⁴U nucleus that undergoes fission in time (some may not be irradiated by neutrons), and losses occur at every stage of the reaction chain. In practice, more ²³³Pa is required to account for these inefficiencies.`,
  "phys-ocrb-h557-2022-p1::40(a)": `Wave-like properties: The electrons form a diffraction pattern (alternating bright and dark fringes/bands) when passed through the two gaps. Diffraction and interference are wave phenomena — the pattern can only be explained if the electrons behave as waves that spread out and superpose, producing constructive and destructive interference.

Particle-like properties: Individual electrons arrive at the detector as discrete, localised events — each electron produces a single spot (flash) at one position. The pattern builds up statistically from many individual particle arrivals, not as a continuous wave. This shows electrons behave as particles when detected.`,
  "phys-ocrb-h557-2022-p1::40(b)(i)": `At each point the two phasors have already been drawn head to tail. The resultant is the single arrow that closes the triangle: draw a straight line from the tail of the first phasor (the dot marking A, and likewise the dot marking B) to the arrowhead at the far end of the second phasor, and put an arrowhead on that end so the resultant points away from the dot.
At A the two phasors are turned through only a small angle from one another, so the resultant is long — about 25 mm on the scale of the diagram. At B the second phasor is turned much further round, so more of the two phasors cancels and the resultant is shorter — about 19 mm.`,
  "phys-ocrb-h557-2022-p1::40(b)(ii)": `Measure the resultant phasors drawn in (b)(i): the resultant amplitude at A is about 25 mm and at B about 19 mm.
The probability is proportional to the square of the resultant amplitude, so
relative probability = (25/19)² = 1.7.
An electron is about 1.7 times more likely to arrive at A than at B.`,
  "phys-ocrb-h557-2022-p1::40(c)(i)": `de Broglie wavelength:
λ = h / p = 6.63×10⁻³⁴ / 1.2×10⁻²² = 5.525×10⁻¹² m ≈ 5.5×10⁻¹² m

Angle to first order maximum using the double-gap diffraction condition:
d sin θ = λ (for first order, m = 1), where d = 1.0×10⁻⁶ m
sin θ = λ / d = 5.525×10⁻¹² / 1.0×10⁻⁶ = 5.525×10⁻⁶
θ = arcsin(5.525×10⁻⁶) ≈ 5.5×10⁻⁶ rad ≈ 3.2×10⁻⁴ degrees

(The angle is extremely small, consistent with the very short de Broglie wavelength compared to the slit separation.)`,
  "phys-ocrb-h557-2022-p1::40(c)(ii)": `Rest energy of an electron: E₀ = mₑc² = 9.11 × 10⁻³¹ × (3.00 × 10⁸)² = 8.2 × 10⁻¹⁴ J = 8.2 × 10⁻¹⁴/1.6 × 10⁻¹³ = 0.51 MeV.
Accelerating through 50 kV gives the electron 50 keV of kinetic energy, so its total energy is E₀ + 50 keV and the Lorentz factor is
γ = total energy/rest energy = 1 + 50 keV/0.51 MeV = 1 + 0.098 = 1.098.
Since γ = 1/√(1 − v²/c²),
v = c√(1 − 1/γ²) = 3.00 × 10⁸ × √(1 − 1/1.098²) = 3.00 × 10⁸ × √(1 − 0.829) = 3.00 × 10⁸ × 0.413
v = 1.24 × 10⁸ m s⁻¹ (1.23 × 10⁸ m s⁻¹ if γ is rounded to 1.097), which is about 1.2 × 10⁸ m s⁻¹ as required.`,
  "phys-ocrb-h557-2022-p2::1(a)": `At terminal velocity, the acceleration is zero. By Newton's second law, the net force on the drop must be zero. The weight W acts downward. Since upthrust is ignored, the only upward force is the drag D. For the forces to balance (net force = zero), D must be equal in magnitude and opposite in direction to W.`,
  "phys-ocrb-h557-2022-p2::1(b)": `First find the radius of the drop from its mass:
m = ρ × V = ρ × (4/3)πr³
1.8×10⁻¹⁵ = 8.7×10² × (4/3)π r³
r³ = 1.8×10⁻¹⁵ / (8.7×10² × 4.189) = 1.8×10⁻¹⁵ / 3644 = 4.94×10⁻¹⁹
r = (4.94×10⁻¹⁹)^(1/3) = 7.91×10⁻⁷ m

At terminal velocity, D = W = mg = 1.8×10⁻¹⁵ × 9.81 = 1.766×10⁻¹⁴ N
Using D = 6πη r v:
v = D / (6πη r) = 1.766×10⁻¹⁴ / (6π × 1.8×10⁻⁵ × 7.91×10⁻⁷)
= 1.766×10⁻¹⁴ / (2.686×10⁻¹⁰)
= 6.57×10⁻⁵ m s⁻¹ ≈ 7×10⁻⁵ m s⁻¹ ✓`,
  "phys-ocrb-h557-2022-p2::1(c)(i)": `Draw six straight vertical lines running the full gap from the +V plate at the top to the 0 V plate at the bottom, equally spaced across the width of the figure with at least three lines on each side of the oil drop. Put an arrowhead on each line pointing downwards, i.e. from the positive plate towards the 0 V plate, since the field points from high to low potential. Equal spacing and parallel, straight lines show that the field is uniform (slight curvature at the edges of the plates is acceptable).`,
  "phys-ocrb-h557-2022-p2::1(c)(ii)": `For the drop to be stationary, the electric force upward must equal the weight downward:
qE = mg
E = V/d = 200 / 5.4×10⁻³ = 3.704×10⁴ V m⁻¹
mg = 1.8×10⁻¹⁵ × 9.81 = 1.766×10⁻¹⁴ N
q = mg / E = 1.766×10⁻¹⁴ / 3.704×10⁴ = 4.77×10⁻¹⁹ C ≈ 4.8×10⁻¹⁹ C

(This corresponds to 3 × 1.6×10⁻¹⁹ C = 3 elementary charges.)`,
  "phys-ocrb-h557-2022-p2::1(c)(iii)": `If charge were not quantised, the drops would have picked up any amount of charge and the measured values would have been spread continuously over a range. Instead every drop carried a whole-number multiple of about 1.6 × 10⁻¹⁹ C, which shows that charge comes in discrete packets of this size — a fundamental quantity of charge.

In the modern model, hadrons such as protons and neutrons are made of quarks, and quarks carry fractional charges of magnitude ⅓e and ⅔e, i.e. about 5.3 × 10⁻²⁰ C and 1.1 × 10⁻¹⁹ C. So the smallest quantity of charge a particle can possess may be a third of 1.6 × 10⁻¹⁹ C rather than 1.6 × 10⁻¹⁹ C itself. Millikan’s experiment could not detect this because quarks are confined inside hadrons and are never found in isolation.`,
  "phys-ocrb-h557-2022-p2::2(a)(i)": `Iron is used in the core because it is a ferromagnetic material with high magnetic permeability. This means it greatly enhances the magnetic flux through the coil — it concentrates and channels the magnetic field lines, increasing the rate of change of flux linkage through the coil and therefore increasing the induced emf.

Laminating the core improves performance by reducing eddy current losses. When the magnetic flux changes, it induces circulating currents (eddy currents) in the conducting iron core. These eddy currents dissipate energy as heat, reducing efficiency. The laminations (thin layers of iron separated by insulating material) are oriented parallel to the flux but perpendicular to the direction that eddy currents would flow, greatly increasing the electrical resistance of any eddy current path. This reduces the magnitude of eddy currents and hence reduces energy losses, so more of the mechanical energy is converted to electrical energy.`,
  "phys-ocrb-h557-2022-p2::2(a)(ii)": `Permeance is analogous to electrical conductance (1/resistance). To increase permeance (reduce magnetic 'resistance'), one should reduce the length of the magnetic circuit or increase its cross-sectional area (analogous to reducing resistance by shortening or widening a conductor).

Suggested change: Increase the cross-sectional area of the iron core (make it thicker/wider). This provides a larger cross-section for magnetic flux to flow through, reducing the magnetic reluctance and increasing the permeance — just as a thicker wire has lower electrical resistance and higher conductance.`,
  "phys-ocrb-h557-2022-p2::2(b)(i)": `The emf induced across the coil is ε = N dΦ/dt, and Φ = BA, so ε = NA × (rate of change of B).

The maximum emf therefore occurs where the flux density is changing fastest, which on Fig. 2.2 is where the curve is steepest — where the line crosses the time axis. Draw a tangent to the curve at one of these crossing points and find its gradient; this gives the greatest rate of change of flux density, in T s⁻¹.

Multiply that maximum gradient by the cross-sectional area of the iron core inside the coil (1.5 × 10⁻⁴ m²) to obtain the maximum rate of change of magnetic flux, in Wb s⁻¹. Then multiply this by the number of turns, 220, because each turn has the same changing flux through it and the emfs of the turns add. The result is an estimate of the maximum emf across the coil.`,
  "phys-ocrb-h557-2022-p2::2(b)(ii)": `From Fig. 2.2 the flux density is sinusoidal with maximum value B_max = 0.16 T, and successive maxima occur at t = 0 and t = 17.5 ms, so the period is T = 17.5 ms = 1.75 × 10⁻² s and the frequency is
f = 1/T = 1/(1.75 × 10⁻²) = 57.1 Hz

Maximum flux through the core:
φ_max = B_max A = 0.16 × 1.5 × 10⁻⁴ = 2.4 × 10⁻⁵ Wb

The emf across one turn is ε = 2πf φ_max sin 2πft, which has maximum value 2πf φ_max (when sin 2πft = 1):
ε_max (per turn) = 2π × 57.1 × 2.4 × 10⁻⁵ = 8.6 × 10⁻³ V

The 220 turns are in series, so the maximum emf across the whole coil is
ε_max = N × 2πf φ_max = 220 × 8.6 × 10⁻³ = 1.9 V`,
  "phys-ocrb-h557-2022-p2::3(a)(i)": `The unstrained gauge resistance is 310 Ω. The student needs to choose a series resistor that is of similar magnitude to the gauge resistance so that the potential divider output is sensitive to small changes in gauge resistance — if the series resistor is much larger or smaller than the gauge, the voltage across it changes very little when the gauge resistance changes slightly.

470 Ω is the best choice because it is closest to the gauge resistance (310 Ω) among the options. This gives a roughly equal split of voltage across each component, maximising the sensitivity of the output voltage to small changes in the gauge resistance. A 100 Ω resistor would give most of the voltage across the gauge, and a 2000 Ω resistor would give most of the voltage across itself, both reducing sensitivity. 470 Ω provides the best compromise and highest sensitivity.`,
  "phys-ocrb-h557-2022-p2::3(a)(ii)": `Using the potential divider formula — the voltmeter reads the p.d. across the 470 Ω resistor:
V_R = V_supply × R / (R + R_gauge) = 6.00 × 470 / (470 + 310)
= 6.00 × 470 / 780
= 6.00 × 0.6026
= 3.615 V ≈ 3.6 V ✓`,
  "phys-ocrb-h557-2022-p2::3(a)(iii)": `Rearranging the potential divider formula for the gauge resistance:
V_R = V × R / (R + R_gauge)
3.57 = 6.00 × 470 / (470 + R_gauge)
470 + R_gauge = 6.00 × 470 / 3.57 = 2820 / 3.57 = 790.0
R_gauge = 790.0 − 470 = 320 Ω`,
  "phys-ocrb-h557-2022-p2::3(b)": `Unstrained resistance of each gauge:
R₀ = ρL₀/A₀ = (4.83 × 10⁻⁷ × 0.118)/(1.84 × 10⁻¹⁰) = 309.8 Ω

The volume of wire is constant, so if the length changes by a factor (1 + ε) the cross-sectional area changes by 1/(1 + ε) and
R = ρL/A = R₀(1 + ε)²

Gauge 1 (stretched, ε = +0.01): L = 0.118 × 1.01 = 0.11918 m, A = 1.84 × 10⁻¹⁰/1.01 = 1.822 × 10⁻¹⁰ m²
R₁ = (4.83 × 10⁻⁷ × 0.11918)/(1.822 × 10⁻¹⁰) = 316 Ω  (= 1.02 × R₀)

Gauge 2 (compressed, ε = −0.01): L = 0.118 × 0.99 = 0.11682 m, A = 1.84 × 10⁻¹⁰/0.99 = 1.859 × 10⁻¹⁰ m²
R₂ = (4.83 × 10⁻⁷ × 0.11682)/(1.859 × 10⁻¹⁰) = 304 Ω  (= 0.98 × R₀)

The voltmeter is across gauge 2, so by the potential divider equation:
V = 6.00 × R₂/(R₁ + R₂) = 6.00 × 303/(316 + 303) = 6.00 × 303/619
V = 2.94 V`,
  "phys-ocrb-h557-2022-p2::4(a)(i)": `When current flows in the wire, the magnetic field exerts a force on the wire (the motor effect: F = BIL). By Newton's Third Law, if the magnet exerts a force on the current-carrying wire, the wire must exert an equal and opposite force on the magnet. The magnet is attached to or resting on the balance, so the force on the magnet is transmitted to the balance, changing its reading. The force on the wire is upward (or downward), and the equal and opposite reaction force on the magnet (and balance) is downward (or upward), changing the balance reading. This pair of forces — wire on magnet and magnet on wire — is the Newton's Third Law pair.`,
  "phys-ocrb-h557-2022-p2::4(a)(ii)": `Force on wire: F = BIL
Δm = 1.4 g = 1.4×10⁻³ kg, so ΔF = Δm × g = 1.4×10⁻³ × 9.81 = 1.373×10⁻² N
I = 3.1 A, L = 0.040 m
B = F / (IL) = 1.373×10⁻² / (3.1 × 0.040) = 1.373×10⁻² / 0.124 = 0.111 T ≈ 0.11 T (2 s.f.)`,
  "phys-ocrb-h557-2022-p2::4(a)(iii)": `The force on the wire is F = BIL, and it appears on the balance as a change in reading Δm, where Δm × g = BIL. Rearranging, Δm = (BL/g) I, so a graph of balance reading against current is a straight line through the origin whose gradient is
gradient = Δm/ΔI = BL/g
Therefore the field strength is found from
B = gradient × g/L = gradient × (9.8 N kg⁻¹ / 0.040 m)
(with the balance readings converted to kilograms).

Taking the gradient of a best-fit line is more reliable than averaging several separate estimates of B because the line is fixed by all of the data points at once, so it gives a weighted mean that smooths out the random error in individual readings. Anomalous points can be seen as points lying off the line and left out when the line is drawn, whereas an outlier would still pull the mean of individual estimates of B. The straight line through the origin also confirms that the balance reading really is proportional to the current.`,
  "phys-ocrb-h557-2022-p2::4(b)(i)": `The alternating current reverses direction at 50 Hz, so the current direction reverses 100 times per second (every 0.01 s). The force F = BIL on the wire reverses direction with each reversal of current (since B is constant from the Earth's field). Each complete cycle of current (0.02 s) produces one complete oscillation of the wire (force up then down then up…). Therefore the wire is driven to oscillate at the same frequency as the AC supply: 50 Hz.`,
  "phys-ocrb-h557-2022-p2::4(b)(ii)": `The wire behaves as a stretched string and can form standing waves. The fundamental mode of vibration (first harmonic) for a wire fixed at both ends has a wavelength λ = 2L = 2 × 0.90 = 1.80 m.

The speed of transverse waves: c = √(T/μ) = √(37 / 0.0046) = √(8043) = 89.7 m s⁻¹

Frequency of fundamental: f = c / λ = 89.7 / 1.80 = 49.8 Hz ≈ 50 Hz

When the tension is 37 N, the natural frequency of the fundamental mode exactly equals the driving frequency of 50 Hz. This is resonance — the driving force is in phase with the oscillation, so energy is transferred most efficiently to the wire each cycle. The amplitude of oscillation builds up to a maximum because the driving frequency matches the wire's natural frequency. At any other tension, the natural frequency would differ from 50 Hz and the amplitude would be smaller.`,
  "phys-ocrb-h557-2022-p2::5(a)": `For a satellite of mass m in circular orbit of radius r around a planet of mass M, period T:

Centripetal force = gravitational force:
mv²/r = GMm/r²   →   v² = GM/r

But orbital speed v = 2πr/T, so v² = 4π²r²/T²

Substituting:
4π²r²/T² = GM/r
T² = (4π²/GM) × r³

This matches Kepler's third law: T² = kr³ where k = 4π²/(GM). □`,
  "phys-ocrb-h557-2022-p2::5(b)": `Using T² = (4π²/GM) r³ → M = 4π²r³/(GT²)

For Ganymede: r = 1.07×10⁹ m, T = 6.18×10⁵ s, G = 6.67×10⁻¹¹ N m² kg⁻²

M = 4π² × (1.07×10⁹)³ / (6.67×10⁻¹¹ × (6.18×10⁵)²)
= 4π² × 1.225×10²⁷ / (6.67×10⁻¹¹ × 3.819×10¹¹)
= 4.832×10²⁸ / 25.47
= 1.897×10²⁷ kg ≈ 2×10²⁷ kg ✓`,
  "phys-ocrb-h557-2022-p2::5(c)(i)": `As the spacecraft moves closer to Jupiter, it moves deeper into Jupiter's gravitational field and loses gravitational potential energy (GPE becomes more negative). By conservation of energy (no motors used), this decrease in GPE is converted into an increase in kinetic energy. Since KE = ½mv², an increase in KE means the spacecraft moves faster. Conversely, as it moves away from Jupiter its KE decreases (converts back to GPE) and it slows down. Total mechanical energy (KE + GPE) is conserved throughout the orbit.`,
  "phys-ocrb-h557-2022-p2::5(c)(ii)": `Energy per unit mass is conserved, because the motors are off:
total energy/kg = ½v² − GM/r

Using M = 2 × 10²⁷ kg from part (b) and G = 6.67 × 10⁻¹¹ N m² kg⁻², so GM = 1.33 × 10¹⁷ N m² kg⁻¹.

At closest approach (r = 7.4 × 10⁷ m, v = 5.8 × 10⁴ m s⁻¹):
½v² = ½ × (5.8 × 10⁴)² = 1.682 × 10⁹ J kg⁻¹
−GM/r = −(1.33 × 10¹⁷)/(7.4 × 10⁷) = −1.803 × 10⁹ J kg⁻¹
total energy/kg = 1.682 × 10⁹ − 1.803 × 10⁹ = −1.21 × 10⁸ J kg⁻¹

At the furthest point (r = 1.0 × 10⁹ m):
p.e./kg = −GM/r = −(1.33 × 10¹⁷)/(1.0 × 10⁹) = −1.33 × 10⁸ J kg⁻¹

So the kinetic energy per kilogram there is
½v² = −1.21 × 10⁸ − (−1.33 × 10⁸) = 1.2 × 10⁷ J kg⁻¹
v = √(2 × 1.2 × 10⁷) = 4.9 × 10³ m s⁻¹

speed ≈ 4900 m s⁻¹`,
  "phys-ocrb-h557-2022-p2::5(d)": `Before entering orbit, the spacecraft was travelling on a hyperbolic or parabolic trajectory approaching Jupiter, with a speed greater than Jupiter's escape velocity at that distance. At this speed, gravity alone would not cause it to follow a closed orbit — it would swing past Jupiter and continue into space.

To enter a stable (closed elliptical) orbit, the spacecraft must reduce its speed so that its kinetic energy is low enough to be bound gravitationally to Jupiter. The motors were fired to decelerate the spacecraft (retro-burn), reducing its total mechanical energy so that it became negative (bound orbit). Without this deceleration, Jupiter's gravity would still be attractive but insufficient to hold the spacecraft in a closed orbit — it would escape. The burn effectively slows the craft so that it can be captured into orbit.`,
  "phys-ocrb-h557-2022-p2::6(a)(i)": `The amplitude of the displacement is constant — the graph shows that the peaks and troughs of the displacement–time curve all have the same magnitude throughout. In an undamped oscillation, there is no energy dissipation, so the amplitude remains constant. If the oscillator were damped, the amplitude would decrease over time.`,
  "phys-ocrb-h557-2022-p2::6(a)(ii)": `The velocity is 90° (a quarter period) ahead of the displacement in phase. Draw a sinusoidal curve of the same period but shifted a quarter period to the left (or equivalently, a cosine if the displacement is a sine). The maximum velocity occurs when displacement is zero (equilibrium), and velocity is zero at maximum displacement. The amplitude of the velocity curve can be estimated as ωA (where ω = 2πf and A is the displacement amplitude), but may be drawn to the same scale for clarity. Label it 'v'.`,
  "phys-ocrb-h557-2022-p2::6(a)(iii)": `The acceleration is 180° (half a period) out of phase with the displacement — it is an inverted version of the displacement curve. This follows from a = −ω²x: acceleration is proportional to displacement but in the opposite direction. When displacement is maximum positive, acceleration is maximum negative, and vice versa. Draw a sinusoidal curve of the same period but inverted (flipped vertically) compared to the displacement curve. Label it 'a'.`,
  "phys-ocrb-h557-2022-p2::6(b)(i)": `Using the average velocity (v_new + v_old)/2 over the time interval Δt gives a better estimate of the distance traveled than using either velocity alone. During the interval Δt, the velocity changes continuously from v_old to v_new. Using the average of these two values is the trapezium rule approximation, which is more accurate than using just the initial or final velocity. This follows from the kinematic principle that for uniformly changing velocity, displacement = average velocity × time.`,
  "phys-ocrb-h557-2022-p2::6(b)(ii)": `At t = 0.10 s: x = 0.1155 m, v_old = −0.180 m s⁻¹ (from row 2)

a = −kx/m = −(18 × 0.1155)/0.60 = −2.079/0.60 = −3.465 m s⁻²
Δv = a × Δt = −3.465 × 0.05 = −0.1733 m s⁻¹
v_new = v_old + Δv = −0.180 + (−0.1733) = −0.3533 m s⁻¹ ≈ −0.353 m s⁻¹
Δx = ((v_new + v_old)/2) × Δt = ((−0.3533 + (−0.180))/2) × 0.05 = (−0.2667) × 0.05 = −0.01333 m
x_new = x + Δx = 0.1155 + (−0.01333) = 0.1022 m ≈ 0.102 m`,
  "phys-ocrb-h557-2022-p2::6(b)(iii)": `From the graph: the model starts at the maximum displacement, x = 0.12 m at t = 0, and the curve first crosses the time axis at t = 0.325 s. That crossing is a quarter of a cycle, so
T = 4 × 0.325 = 1.30 s  and  f = 1/T = 0.77 Hz

From the equation for a mass–spring oscillator:
T = 2π√(m/k) = 2π√(0.60/18) = 2π × 0.183 = 1.15 s
f = 1/1.15 = 0.87 Hz

frequency from the graph = 0.77 Hz; frequency from the equation = 0.87 Hz.

The modelled frequency is about 12% lower than the true value. Part of the difference is measurement: only a quarter of a cycle is shown, the graph has no minor gridlines, and a small error in reading the zero crossing is multiplied by four when T is found. The rest is a fault in the model itself: the acceleration is held constant at its value at the start of each 0.05 s interval, so while the mass is moving back towards equilibrium the model uses an acceleration that is too large in magnitude at the start and it also leaves the oscillator stationary for the whole of the first interval. These approximations stretch out the modelled cycle and so give too low a frequency; using a much smaller Δt would bring the model closer to 0.87 Hz.`,
  "phys-ocrb-h557-2022-p2::6(c)": `Method and reasoning: for a mass–spring oscillator the total energy is E = ½kA², so E ∝ A². If the energy really does increase by the same constant factor during every oscillation, then the ratio of the squares of the amplitudes of successive peaks must be the same for every pair of consecutive peaks. So I read off the height of successive peaks from Fig. 6.5 and test whether (Aₙ₊₁/Aₙ)² is constant.

Reading the four clearest successive peaks:
A₁ ≈ 0.95 m, A₂ ≈ 1.5 m, A₃ ≈ 2.35 m, A₄ ≈ 3.6 m

Ratios of energies:
E₂/E₁ = (1.5/0.95)² = 2.5
E₃/E₂ = (2.35/1.5)² = 2.5
E₄/E₃ = (3.6/2.35)² = 2.3

Conclusion: the three ratios are the same to within the precision with which the peaks can be read from the graph (about 2.4 each time), so the data support the student’s suggestion — the model multiplies the energy of the oscillator by a constant factor of roughly 2.4 every cycle, which is why the amplitude grows steadily rather than staying constant.`,
  "phys-ocrb-h557-2022-p2::7": `Using random walk statistics: the number of steps N needed to achieve a net displacement d when each step has length Δx is given by:
d = Δx √N → N = (d/Δx)²

N = (3.5×10⁸ / 1.2×10⁻⁴)² = (2.917×10¹²)² = 8.51×10²⁴ steps

Total distance travelled = N × Δx = 8.51×10²⁴ × 1.2×10⁻⁴ = 1.021×10²¹ m

Time taken = total distance / speed of light:
t = 1.021×10²¹ / 3.00×10⁸ = 3.40×10¹² s

Convert to years: t = 3.40×10¹² / 3.2×10⁷ = 1.06×10⁵ years ≈ 100 000 years ✓`,
  "phys-ocrb-h557-2022-p2::8(a)": `Mechanism: High-energy charged particles (electrons and protons) from the solar wind are guided by the Earth's magnetic field and spiral down toward the poles. These particles collide with atoms and molecules in the upper atmosphere (mainly oxygen and nitrogen), transferring energy to them and exciting their electrons to higher energy levels. When the excited electrons fall back to lower energy levels, they release the energy as photons of light — this is the aurora.

Energy of photon (λ = 558 nm = 558×10⁻⁹ m):
E = hf = hc/λ = (6.63×10⁻³⁴ × 3.00×10⁸) / (558×10⁻⁹)
= 1.989×10⁻²⁵ / 5.58×10⁻⁷
= 3.56×10⁻¹⁹ J ≈ 3.6×10⁻¹⁹ J`,
  "phys-ocrb-h557-2022-p2::8(b)(i)": `For a charged particle moving perpendicular to a magnetic field, the magnetic force provides the centripetal force:
qvB = mv²/r → r = mv/(qB)

m_e = 9.11×10⁻³¹ kg, v = 5.0×10⁵ m s⁻¹, q = 1.60×10⁻¹⁹ C, B = 40×10⁻⁶ T

r = (9.11×10⁻³¹ × 5.0×10⁵) / (1.60×10⁻¹⁹ × 40×10⁻⁶)
= (4.555×10⁻²⁵) / (6.40×10⁻²⁴)
= 0.0712 m ≈ 0.07 m ≈ 7 cm ✓`,
  "phys-ocrb-h557-2022-p2::8(b)(ii)": `Resolve the velocity of 5.0 × 10⁵ m s⁻¹ into a component along the field (which gives the steady advance down the field line) and a component perpendicular to the field (which gives the circular motion):
vertical (along field) component = 5.0 × 10⁵ cos 25° = 4.5 × 10⁵ m s⁻¹
horizontal (perpendicular) component = 5.0 × 10⁵ sin 25° = 2.1 × 10⁵ m s⁻¹

The perpendicular component carries the electron once round a circle of radius r = 0.029 m, so the time for one full rotation is
t = 2πr/v_perpendicular = (2π × 0.029)/(2.1 × 10⁵) = 8.7 × 10⁻⁷ s

During that time the electron advances along the field line at the constant vertical component of velocity, so
d = v_vertical × t = 4.5 × 10⁵ × 8.7 × 10⁻⁷ = 0.39 m`,
  "phys-ocrb-h557-2022-p2::8(b)(iii)": `As the electron moves nearer to the pole, the magnetic field strengthens. A stronger field increases the magnetic force on the electron, causing the radius of the circular component of its spiral to decrease (r = mv_⊥/qB, so r decreases as B increases). The spiral becomes tighter (smaller radius). The parallel velocity component v_∥ is gradually reduced as the increasing field reflects the particle (magnetic mirror effect), potentially reversing it before it reaches the dense atmosphere.

If the electron does penetrate the atmosphere, it collides with atmospheric particles, transferring energy to them and causing excitation and ionisation. This causes the electron to lose kinetic energy, reducing both components of velocity. The aurora light is produced in this process. The electron slows, the spiral tightens further, and eventually the electron stops or is reflected back.`,
  "phys-ocrb-h557-2022-p2::9": `Energy needed to bring two protons to within 10⁻¹⁴ m of each other (work done against the Coulomb repulsion):
E = e²/(4πε₀r) = (1.6 × 10⁻¹⁹)²/(4π × 8.85 × 10⁻¹² × 1.0 × 10⁻¹⁴) = 2.3 × 10⁻¹⁴ J

Average random energy of a proton at the core temperature of 1.5 × 10⁷ K:
kT = 1.38 × 10⁻²³ × 1.5 × 10⁷ = 2.1 × 10⁻¹⁶ J  (⅔ of the mean kinetic energy ³⁄₂kT = 3.1 × 10⁻¹⁶ J)

Two protons approaching each other bring, on average, 2kT = 4.2 × 10⁻¹⁶ J to the collision. This is about 55 times smaller than the 2.3 × 10⁻¹⁴ J needed, so on average protons in the core come nowhere near having enough kinetic energy to fuse: a pair with only the average energy gets no closer than about 5.5 × 10⁻¹³ m, fifty times too far apart.

Fusion can only happen for the rare pairs in the high-energy tail of the distribution, and the fraction of pairs with at least the required energy is given by the Boltzmann factor:
f_B = e^(−E/2kT) = e^(−54.8) = 1.7 × 10⁻²⁴

So only about two collisions in every 10²⁴ involve enough energy. To see whether this can account for the observed rate, estimate the number of protons in the Sun:
N = M/m_p = (2 × 10³⁰)/(1.67 × 10⁻²⁷) = 1.2 × 10⁵⁷ protons
Even if every proton had one chance to react each second, the number fusing per second would be only
N × f_B = 1.2 × 10⁵⁷ × 1.7 × 10⁻²⁴ ≈ 2 × 10³³ s⁻¹

This is about 10⁵ times smaller than the observed 3.7 × 10³⁸ protons fusing each second; you would need a star of some 10⁵ solar masses to supply that rate on this argument. The Boltzmann factor alone therefore cannot explain the Sun’s output, which is why quantum tunnelling through the Coulomb barrier — protons fusing without ever acquiring the classical 2.3 × 10⁻¹⁴ J — has to be invoked.`,
  "phys-ocrb-h557-2022-p2::10(a)": `Intensity follows an inverse-square law: I ∝ 1/r²
I₁r₁² = I₂r₂²
I₂ = I₁ × (r₁/r₂)² = 1400 × (1.5×10¹¹ / 1.4×10¹⁰)²
= 1400 × (10.714)²
= 1400 × 114.8
= 1.607×10⁵ W m⁻² ≈ 1.6×10⁵ W m⁻²`,
  "phys-ocrb-h557-2022-p2::10(b)": `Stefan's Law: I = σT⁴ (for a perfect black body at thermal equilibrium absorbing all incident radiation and re-radiating the same power per unit area)

T = (I/σ)^(1/4) = (1.607×10⁵ / 5.67×10⁻⁸)^(1/4)
= (2.834×10¹²)^(1/4)
= (2.834×10¹²)^0.25

(2.834×10¹²)^(1/2) = 1.684×10⁶
(1.684×10⁶)^(1/2) = 1297 K ≈ 1300 K`,
  "phys-ocrb-h557-2022-p2::10(c)": `Solar missions like the Parker Solar Probe have importance beyond scientific discovery because the Sun drives space weather — events such as solar flares and coronal mass ejections that can severely disrupt technology on Earth and in space. Understanding the Sun's behaviour enables better prediction of these events, allowing protection of satellites (communications, GPS, weather), electrical power grids, and aircraft systems that would otherwise be damaged or destroyed by intense solar particle events and magnetic storms. Improved forecasting from solar research protects critical infrastructure, economic activity, and potentially human lives (e.g. astronaut safety, airline routes over polar regions).`,
  "phys-ocrb-h557-2022-p3::1(a)": `Polarisation is a property of transverse waves in which the oscillations are restricted to a single plane (the plane of polarisation) containing the direction of propagation. In an unpolarised wave the oscillations occur in all planes perpendicular to the direction of travel; polarisation limits these to one plane.

All electromagnetic waves can be polarised because they are transverse waves — the electric (and magnetic) field vectors oscillate perpendicular to the direction of propagation. This perpendicular oscillation can be restricted to a single plane by a polarising filter, unlike longitudinal waves (where oscillations are parallel to propagation) which cannot be polarised.`,
  "phys-ocrb-h557-2022-p3::1(b)": `Look at the reflected light through the filter and slowly rotate the filter about the line of sight through a complete turn.
If the reflected light is polarised, the brightness seen through the filter changes gradually as the filter is rotated: it is a maximum when the transmission axis of the filter is parallel to the plane in which the light is oscillating, and a minimum (dark, or at least much dimmer) when the axis is perpendicular to that plane. The angle between the position of maximum intensity and the position of minimum intensity is 90°.
If, instead, the brightness stays the same for every orientation of the filter, the reflected light is not polarised.`,
  "phys-ocrb-h557-2022-p3::1(c)(i)": `To measure the angle of rotation of the grille:
1. Mark the initial (vertical) position of the grille clearly on the stand or a protractor fixed to it, noting it as 0°.
2. Attach a protractor scale (or use a circular protractor) centred on the rotation axis of the grille, so that the angle can be read directly as the grille is rotated.
3. Rotate the grille to each desired angle and read the angle from the protractor before taking the receiver reading.

Alternatively, use a pointer fixed to the grille that sweeps over a fixed circular protractor scale, so the angle of rotation can be read to the nearest degree.`,
  "phys-ocrb-h557-2022-p3::1(c)(ii)": `The voltage at the receiver is proportional to the intensity of the microwaves, so if intensity ∝ cos²θ then V = k cos²θ and the quantity V ÷ cos²θ must come out the same for every point on the graph.
Reading three widely spaced points from Fig. 1.2 (avoiding the angles where V = 0, because cos²θ = 0 there too):
θ = 60°, V = 0.8 mV: cos²60° = 0.25, so V ÷ cos²θ = 0.8 ÷ 0.25 = 3.2 mV
θ = 100°, V = 0.1 mV: cos²100° = 0.030, so V ÷ cos²θ = 0.1 ÷ 0.030 = 3.3 mV
θ = 125°, V = 1.1 mV: cos²125° = 0.329, so V ÷ cos²θ = 1.1 ÷ 0.329 = 3.3 mV
The three values, 3.2, 3.3 and 3.3 mV, are the same to within the precision with which the graph can be read, and they agree with the maximum voltage of 3.3 mV at θ = 0°, which is the value k should take. The investigation therefore does support the relationship intensity ∝ cos²θ.`,
  "phys-ocrb-h557-2022-p3::2(a)(i)": `A variable that must be controlled is the temperature of the gas. Temperature affects the pressure and volume of the gas (ideal gas law: pV = nRT), so if temperature changes during the experiment, it would alter the relationship being investigated (between pressure and volume at constant temperature — Boyle's Law). The temperature must remain constant throughout.`,
  "phys-ocrb-h557-2022-p3::2(a)(ii)": `The reading at 79 mm² lies well away from the cluster formed by all the others, so it is an outlier and is left out. That leaves 14 readings: one at 84, four at 85, one at 86, three at 87, two at 88, one at 90 and two at 91 mm².
sum = 84 + 4(85) + 86 + 3(87) + 2(88) + 90 + 2(91) = 1219 mm²
mean = 1219 ÷ 14 = 87.07 mm² = 87 mm² (2 s.f.)
uncertainty = ½ × range = ½(91 − 84) = 3.5 mm²
percentage uncertainty = (3.5 ÷ 87.07) × 100 = 4.0% = 4% (1 s.f.)
Mean cross-sectional area = 87 mm² ± 4%.`,
  "phys-ocrb-h557-2022-p3::2(a)(iii)": `A realistic estimate is about ±3 mm (anywhere between ±2 mm and ±5 mm is reasonable) — much larger than the ±0.5 mm the millimetre scale of the rule might suggest.
The limit is not the scale of the rule but how well the ends of the gas column can be located. The rule has to be held alongside the tube rather than against the gas itself, so the readings suffer from parallax; the boundary between the gas and the oil is a curved meniscus, so there is no sharp point to read to; and the reading is taken through the curved glass wall of the tube, which distorts the apparent position. Both the top and the bottom of the column have to be read, so these effects combine and the overall uncertainty in h is a few millimetres.`,
  "phys-ocrb-h557-2022-p3::2(b)": `Absolute pressure = excess pressure + atmospheric pressure
= 255 kPa + 101 kPa = 356 kPa = 356×10³ Pa

1/absolute pressure = 1/(356×10³) = 2.809×10⁻⁶ Pa⁻¹ ≈ 2.81×10⁻⁶ Pa⁻¹

Unit: Pa⁻¹ (or equivalently kPa⁻¹ if pressure kept in kPa: 1/356 = 2.81×10⁻³ kPa⁻¹)`,
  "phys-ocrb-h557-2022-p3::2(c)": `Presentation of the graph
• The y-axis carries no unit: it should read '1 / absolute pressure / 10⁻⁶ Pa⁻¹', otherwise the numbers 4, 8, 12 and 16 are meaningless.
• The y-axis scale is too compressed. All the values lie between 2.8 and 9.0, so the points occupy only the bottom half of the grid; a scale running from 0 to 10 (or a suppressed zero) would spread them over more than half the grid and make them easier to plot and read.
• The x-axis scale is awkward (0.06 m spread over an odd number of centimetres), so intermediate heights are hard to plot accurately; a scale such as 0.02 m per two large squares would be much easier to use.
• The points are drawn as blobs; fine crosses should be used so that each point can be placed and read to within half a small square.
• Error bars should be added to show the uncertainty in h (a few mm, from (a)(iii)) and in 1/p.
• The line of best fit is too steep: it passes below the first three points and cuts below the last one, instead of having a balanced scatter of points either side.
• Anomalous point: the third point (h = 0.250 m, 1/p = 5.90 × 10⁻⁶ Pa⁻¹) is anomalous — its neighbours at 0.200 m and 0.300 m are 3.85 and 6.06 × 10⁻⁶ Pa⁻¹, so this reading is far too high for the trend and should be ignored when the line is drawn.

Physical significance of the gradient
For an ideal gas, pV = nRT. The gas column is a cylinder of cross-sectional area A and height h, so V = Ah and
pAh = nRT, which rearranges to 1/p = [A/(nRT)] h
So a graph of 1/p against h should be a straight line through the origin whose gradient is A/(nRT). The gradient therefore measures the cross-sectional area of the tube divided by the product nRT, and it stays constant throughout the experiment only because the amount of gas and its temperature are held constant — which is exactly what Boyle's law requires.

Assumptions
The gas behaves ideally: the molecules themselves occupy a negligible fraction of the volume, there are no forces between them except during collisions, and the collisions are perfectly elastic and take a negligible time. It is also assumed that the temperature stays constant at 298 K, that no gas leaks or dissolves in the oil, and that the tube has a uniform cross-section A.

Estimating n
gradient = A/(nRT), so n = A ÷ (RT × gradient)
Taking A = 87.1 mm² = 87.1 × 10⁻⁶ m² from (a)(ii), T = 298 K, R = 8.31 J mol⁻¹ K⁻¹ and the gradient as 25 × 10⁻⁶ in SI units (Pa⁻¹ m⁻¹, i.e. N⁻¹ m):
n = 87.1 × 10⁻⁶ ÷ (8.31 × 298 × 25 × 10⁻⁶) = 87.1 × 10⁻⁶ ÷ 6.19 × 10⁻² = 1.4 × 10⁻³ mol
So the tube contains about 1.4 × 10⁻³ mol of gas, which is roughly 8 × 10²⁰ molecules.`,
  "phys-ocrb-h557-2022-p3::3(a)": `The decay constant λ represents the probability that a given nucleus will decay per unit time. It is a constant characteristic of a particular radioisotope — a larger λ means a more unstable isotope that decays more rapidly.

The negative sign in the equation ΔN/Δt = −λN indicates that the number of nuclei N is decreasing over time (the sample is losing nuclei as they decay). Since λ and N are both positive, without the negative sign the rate would be positive (increasing N), which is unphysical. The minus sign correctly shows that the number of radioactive nuclei decreases as decay proceeds.`,
  "phys-ocrb-h557-2022-p3::3(b)(i)": `With λ = 0.4 s⁻¹ and Δt = 1 s, every row has ΔN = λNΔt = 0.4N, and the number remaining is N − ΔN = 0.6N; that value becomes N in the next row.
t = 2 s: N = 1800, ΔN = 0.4 × 1800 × 1 = 720, N − ΔN = 1800 − 720 = 1080
t = 3 s: N = 1080, ΔN = 0.4 × 1080 × 1 = 432, N − ΔN = 1080 − 432 = 648
t = 4 s: N = 648, ΔN = 0.4 × 648 × 1 = 259 (259.2), N − ΔN = 648 − 259 = 389 (388.8)`,
  "phys-ocrb-h557-2022-p3::3(b)(ii)": `Each value in the last column of Table 3.1 is the number of nuclei left at the end of that interval, so it is plotted at the following second. The three points still missing are therefore
(3 s, 1080), (4 s, 648) and (5 s, 389).
Plot each one to within half a small square. They continue the falling curve already begun, each value being 0.6 of the one before.`,
  "phys-ocrb-h557-2022-p3::3(b)(iii)": `The activity is the gradient of the graph. In each row the model produces a fixed number of decays, ΔN = λNΔt, spread over the interval Δt, so each section of the graph is a straight line whose gradient ΔN/Δt is the activity: the activity is taken to be constant throughout an interval and then steps down to a new constant value for the next one.`,
  "phys-ocrb-h557-2022-p3::3(b)(iv)": `With Δt = 0.5 s the number of nuclei is recalculated twice as often, so twice as many points are obtained in the same total time and the graph is a smoother curve rather than a series of long straight steps.
It is also more realistic. In a real sample the activity falls continuously, whereas the model holds the rate of decay fixed for the whole of each interval; halving the interval means the value of N used in each step stays much closer to the true, continuously changing value, so the modelled curve follows the true exponential decay more closely.`,
  "phys-ocrb-h557-2022-p3::3(c)(i)": `10-second counting intervals are suitable because:

1. The half-life of protactinium-234 is about 72 seconds. A 10-second interval is sufficiently short compared to the half-life that the count rate does not change significantly within one interval, making each count rate measurement a reasonable snapshot of the activity at that time. If the interval were too long (e.g. comparable to the half-life), the count rate would change substantially during the count, making it hard to assign a time to each measurement.

2. 10-second intervals are long enough to accumulate a statistically significant number of counts (reducing random fluctuation/percentage uncertainty in each count), while still allowing enough data points over a few minutes to map out the exponential decay adequately. A shorter interval would give too few counts per interval and large statistical uncertainty.`,
  "phys-ocrb-h557-2022-p3::3(c)(ii)": `For exponential decay the count rate is R = R₀e^(−λt), so taking natural logs, ln R = ln R₀ − λt. A graph of ln(count rate) against t is therefore a straight line of gradient −λ.
Take two points on the line of best fit that are far apart — the whole length of the line — for example (0 s, 4.38) and (140 s, 3.04):
gradient = Δ(ln count rate)/Δt = (3.04 − 4.38)/(140 − 0) = −1.34/140 = −9.6 × 10⁻³ s⁻¹
decay constant λ = −gradient = 9.6 × 10⁻³ s⁻¹
half-life t½ = ln2 / λ = 0.693 / (9.6 × 10⁻³) = 72 s
Half-life ≈ 72 s.`,
  "phys-ocrb-h557-2022-p3::4(a)(i)": `Experimental technique for reliable data:
- Clamp one end of the rubber band firmly to a stand and clamp so it hangs vertically.
- Attach a known mass hanger to the free end and measure the extension from the natural length using a ruler with a set square to avoid parallax errors.
- Record the force (F = mg) and corresponding extension for a range of masses, adding masses in small increments.
- Take repeat readings (load and unload) for each mass to check for hysteresis and identify any anomalous results; use the mean.
- Measure the natural length before and after loading to check for permanent deformation.

Minimising uncertainties:
- Use a fiducial marker (pin or marker at the lower end of the band) to read extension consistently against the ruler.
- Ensure the band hangs freely, not touching the stand.
- Allow the band to settle at each load before measuring.

Minimising risks:
- Use a tray or cushion below the masses to catch them if they fall.
- Wear eye protection in case the band snaps under high load.

Greatest source of uncertainty: the measurement of extension, because the rubber band may oscillate or the natural length marker is hard to read precisely (especially when the band stretches non-uniformly).`,
  "phys-ocrb-h557-2022-p3::4(a)(ii)": `The graph is not a straight line, so the rubber band does not obey Hooke's law, although the extension does increase throughout as the force is increased and the deformation stays elastic. The stiffness at any point is the gradient ΔF/Δx, and it changes three times across the range shown.

From 0 to about 5 cm the band is comparatively stiff: 3 N produces only 5 cm of extension, a gradient of about 0.6 N cm⁻¹.
From about 5 cm to about 15 cm the graph is much shallower: the next 3 N produces 10 cm of extension, a gradient of only about 0.3 N cm⁻¹, so the band is far less stiff here and stretches very easily.
Beyond about 15 cm the graph steepens again: the last 2 N produces only about 3 cm more extension, a gradient of about 0.7 N cm⁻¹, so the band becomes stiff again — stiffer even than at the start.

This pattern follows from the structure of rubber. Rubber is a polymer: it is made of very long chain molecules of many repeated units. In an unstretched band these chains are coiled up and tangled together, pointing in random directions, and they are joined here and there to neighbouring chains by cross-links (sulphur atoms introduced by vulcanisation).

In the first, steep section the applied force has to drag the tangled chains past one another and break or distort the cross-links and the weak bonds between neighbouring chains, so a fairly large force gives only a small extension.
In the shallow middle section the chains are free to uncoil and straighten out and to slide over one another, so a large extension is obtained for only a small extra force.
In the final, steep section almost all the chains have been pulled straight and lined up along the direction of the force. Any further extension now has to come from stretching the strong covalent C–C bonds along the chains themselves, so a large force produces only a very small extension and the band becomes very stiff; increasing the force much further would break the band.

A labelled sketch of tangled chains, then straightened chains, then chains with their bonds being stretched, drawn against the three sections of the graph, shows the same argument.`,
  "phys-ocrb-h557-2022-p3::4(b)(i)": `There are two candidate lines that stay inside every error bar — the steepest and the shallowest — and the steepest is the one whose gradient differs most from the best-fit value, so that is the line to draw.
Using a ruler, draw a single thin straight line from the left-hand end of the error bar on the top point, (0.0035 m, 40 N), down to (0.0005 m, 0 N), so that it passes through the right-hand ends of the error bars on the lowest points. Check as you draw that it stays within every error bar on the graph.
(The shallowest possible line would run from (0.0045 m, 40 N) to (−0.0005 m, 0 N), but its gradient differs from the best-fit gradient by less than the steepest line's does.)`,
  "phys-ocrb-h557-2022-p3::4(b)(ii)": `E = stress ÷ strain = (F/A) ÷ (x/L) = (F/x) × (L/A) = gradient × L ÷ A
A = πd²/4 = π(0.5 × 10⁻³)² / 4 = 1.96 × 10⁻⁷ m²
E = (10 100 × 4) ÷ (1.96 × 10⁻⁷) = 40 400 ÷ 1.96 × 10⁻⁷ = 2.1 × 10¹¹ Pa = 210 GPa
Uncertainty: the steepest line drawn in (i) runs from (0.0005 m, 0 N) to (0.0035 m, 40 N), so its gradient is
40 ÷ (0.0035 − 0.0005) = 40 ÷ 0.0030 = 1.33 × 10⁴ N m⁻¹
percentage difference from the best-fit gradient = (13 300 − 10 100) ÷ 10 100 × 100 = 32%
E is directly proportional to the gradient, so the absolute uncertainty in E is 0.32 × 210 GPa = 67 GPa.
Young modulus = (2.1 ± 0.7) × 10¹¹ Pa, i.e. 210 ± 67 GPa.`,
  "phys-ocrb-h557-2022-p3::4(c)(i)": `Resolution = 0.5 mm / 50 = 0.01 mm

Unit: mm (or equivalently 0.01 mm = 10 μm, but mm is conventional for micrometers)`,
  "phys-ocrb-h557-2022-p3::4(c)(ii)": `Measure the diameter several times at different places along the length of the wire, and at each place turn the wire through 90° and measure again, in case the cross-section is not perfectly circular. Add the readings and divide by the number of readings to obtain the mean diameter.
The uncertainty is then ± half the range of the readings, i.e. ½(largest reading − smallest reading). If half the range works out smaller than the resolution of the micrometer, quote the uncertainty as ± the resolution, ±0.01 mm, instead.`,
  "phys-ocrb-h557-2022-p3::4(c)(iii)": `A = πd²/4 = π × (0.35 × 10⁻³)² ÷ 4 = π × 1.225 × 10⁻⁷ ÷ 4 = 9.6 × 10⁻⁸ m²
percentage uncertainty in d = (0.02 ÷ 0.35) × 100 = 5.7%
A depends on d², so the percentage uncertainty in A is 2 × 5.7% = 11.4%
absolute uncertainty in A = 0.114 × 9.62 × 10⁻⁸ = 1.1 × 10⁻⁸ m²
Cross-sectional area = (9.6 ± 1.1) × 10⁻⁸ m².`,
  "phys-ocrb-h557-2023-p1::31(a)": `In a polarised wave, the oscillations (of the electric field, or of the displacement) occur in only one plane, which contains the direction of propagation. In an unpolarised wave, the oscillations occur in all planes perpendicular to the direction of propagation simultaneously (i.e. the plane of oscillation is random/constantly changing).`,
  "phys-ocrb-h557-2023-p1::31(b)": `Hold a polarising filter in the path of the reflected light and rotate it through 360°. If the intensity of the transmitted light varies (increases and decreases) as the filter is rotated — going through a maximum and a minimum — then the reflected light is (at least partially) polarised. If the intensity remains constant throughout the rotation, the light is unpolarised.`,
  "phys-ocrb-h557-2023-p1::32(a)(i)": `Number of bits = 1280 × 720 × 24 = 22 118 400 bits ≈ 2.2 × 10⁷ bits.`,
  "phys-ocrb-h557-2023-p1::32(a)(ii)": `Duration of recording = 40 min × 60 s min⁻¹ = 2400 s. Total number of images = 30 × 2400 = 72 000. Total file size = 0.74 Gbytes = 0.74 × 10⁹ × 8 bits = 5.92 × 10⁹ bits. Average bits per image = 5.92 × 10⁹ / 72 000 ≈ 82 222 bits ≈ 82 kbits. This confirms the suggested value of about 82 kbits.`,
  "phys-ocrb-h557-2023-p1::32(b)": `1. Every image from the second camera contains many more pixels and so many more bits, so even after compression the files are much bigger and a much greater rate of data transmission (more bandwidth) is needed to stream the lesson, as well as much more memory to hold the recording.

2. Not every student will have a home broadband connection fast enough, or a large enough data allowance, to keep up with that higher data rate, so the video would keep freezing or jumping during the lesson — and the extra resolution is not needed anyway for students to see the teacher and the board clearly.`,
  "phys-ocrb-h557-2023-p1::33(a)": `All the work done on the electron by the accelerating p.d. becomes kinetic energy:

eV = ½mv²

eV = 1.6 × 10⁻¹⁹ × 5000 = 8.0 × 10⁻¹⁶ J

v = √(2eV/m) = √(2 × 8.0 × 10⁻¹⁶ / 9.1 × 10⁻³¹) = √(1.76 × 10¹⁵)

velocity = 4.2 × 10⁷ m s⁻¹`,
  "phys-ocrb-h557-2023-p1::33(b)": `The relativistic kinetic energy is given by EK = (γ − 1)m₀c². EK = (1.7 − 1) × 8.2 × 10⁻¹⁴ = 0.7 × 8.2 × 10⁻¹⁴ = 5.74 × 10⁻¹⁴ J. The work done by the accelerating potential difference equals the kinetic energy gained: eV = EK. V = EK / e = 5.74 × 10⁻¹⁴ / 1.6 × 10⁻¹⁹ = 3.59 × 10⁵ V ≈ 3.6 × 10⁵ V.`,
  "phys-ocrb-h557-2023-p1::33(c)": `Particles must be accelerated to very high energies so that they have a very short de Broglie wavelength (λ = h/p). For the particle to resolve (or probe) the structure of a nucleus, the wavelength must be comparable to or smaller than the nuclear size (~10⁻¹⁵ m). Higher energy gives greater momentum and hence smaller wavelength, allowing finer nuclear structures to be investigated.`,
  "phys-ocrb-h557-2023-p1::34(a)": `Reading from the graph, the p.d. across the filament when the current is 2.5 A is 4.0 V.

R = V/I = 4.0 / 2.5

R = 1.6 Ω, as required.`,
  "phys-ocrb-h557-2023-p1::34(b)": `Conductivity σ = 1/(ρ), and resistance R = ρL/A, so ρ = RA/L, giving σ = L/(RA). The ratio of conductivities equals the ratio of resistances (same wire, same dimensions): σ₁/σ₂ = R₂/R₁. σ at 1.6 Ω = σ at 0.93 Ω × (0.93/1.6) = 1.8 × 10⁷ × (0.93/1.6) = 1.8 × 10⁷ × 0.58125 = 1.05 × 10⁷ S m⁻¹ ≈ 1.0 × 10⁷ S m⁻¹.`,
  "phys-ocrb-h557-2023-p1::34(c)": `As the current through the filament increases, the filament heats up to a higher temperature. In a metal, conductivity decreases with increasing temperature because the positive metal ions vibrate with greater amplitude at higher temperatures. This increases the frequency of collisions between the conduction electrons and the lattice ions, reducing the mean drift velocity of electrons for a given field, and therefore reducing the conductivity.`,
  "phys-ocrb-h557-2023-p1::35(a)": `At point A, the total energy is conserved. The alpha particle gains electric potential energy equal to the kinetic energy lost. KE lost = 8.0 × 10⁻¹³ − 4.0 × 10⁻¹³ = 4.0 × 10⁻¹³ J. This equals the electric potential energy gained: EPE = kQ₁Q₂/r. r = kQ₁Q₂/EPE = (8.99 × 10⁹ × 3.2 × 10⁻¹⁹ × 1.3 × 10⁻¹⁷) / (4.0 × 10⁻¹³). Numerator = 8.99 × 10⁹ × 4.16 × 10⁻³⁶ = 3.74 × 10⁻²⁶ J m. r = 3.74 × 10⁻²⁶ / 4.0 × 10⁻¹³ = 9.35 × 10⁻¹⁴ m ≈ 9.4 × 10⁻¹⁴ m.`,
  "phys-ocrb-h557-2023-p1::35(b)": `The electrostatic (Coulomb) force on the alpha particle is given by F = kQ₁Q₂/r². At point A, the alpha particle is at its closest approach to the gold nucleus, so r is at its minimum value. Since F ∝ 1/r², the force is greatest when r is smallest. Therefore the electrostatic repulsive force is greatest at A, and since F = ma with constant mass, the acceleration is greatest at A.`,
  "phys-ocrb-h557-2023-p1::36(a)": `Gravitational potential V = −GM/R. V = −(6.67 × 10⁻¹¹ × 7.3 × 10²²) / (1.7 × 10⁶). Numerator = 6.67 × 10⁻¹¹ × 7.3 × 10²² = 4.87 × 10¹² J m kg⁻¹. V = −4.87 × 10¹² / 1.7 × 10⁶ = −2.86 × 10⁶ J kg⁻¹ ≈ −2.9 × 10⁶ J kg⁻¹. (Confirmed.)`,
  "phys-ocrb-h557-2023-p1::36(b)(i)": `For a projectile to just escape from the Moon's surface, its initial kinetic energy must equal the magnitude of its gravitational potential energy at the surface (since potential energy at infinity = 0). ½mv² = m|V| where V = −2.9 × 10⁶ J kg⁻¹. v = √(2 × 2.9 × 10⁶) = √(5.8 × 10⁶) = 2408 m s⁻¹ ≈ 2.4 × 10³ m s⁻¹. (Confirmed.)`,
  "phys-ocrb-h557-2023-p1::36(b)(ii)": `The Earth exerts a gravitational attractive force on the projectile throughout its journey. As the projectile moves away from the Moon toward the Earth, there is a point (the L1 Lagrange point) where the gravitational pull of the Earth on the projectile exceeds that of the Moon. Beyond this point, the Earth's gravity accelerates the projectile toward Earth. Therefore, the projectile does not need to have enough initial kinetic energy to reach infinity; it only needs enough to reach the point where Earth's gravitational field takes over and pulls it the rest of the way. This requires less initial velocity than the escape velocity from the Moon.`,
  "phys-ocrb-h557-2023-p1::36(c)": `Rotations per second: the projectile goes once round a circle of radius 20 m in each rotation, so

v = 2πr/T, giving T = 2πr/v = (2π × 20) / 1900 = 0.066 s

f = 1/T = 15 rotations per second (15 Hz)

The stress in the arm is the tension needed to keep the projectile moving in its circle divided by the cross-sectional area of the arm: stress = F/A, where F = mv²/r. The mass of the projectile and the release speed of 1900 m s⁻¹ are both fixed, so there are two things that can be changed.

Change 1 — make the arm longer. Since F = mv²/r, doubling the length of the arm from 20 m to 40 m at the same release speed halves the force the arm has to supply, and so halves the stress on its cross-section. It also halves the rotation rate needed, because f = v/2πr, so the machine turns more slowly for the same launch speed. The drawback is that a longer arm is itself more massive, and the arm's own mass must also be whirled round, which adds to the tension near the axle; a long arm is also more likely to bend.

Change 2 — make the cross-section of the arm larger. Stress = F/A, so for the same tension, doubling the cross-sectional area halves the stress. This is simple and leaves the launch speed and rotation rate unchanged. The drawback is again extra mass: a thicker arm is heavier, and the extra weight of the arm has to be supported by the arm itself, so the stress does not fall quite in proportion to the increase in area. (A related option would be to use a strong material of lower density so that the arm is less massive, although a less dense material may bend more easily.)

Which is better: lengthening the arm is the better method. Increasing the cross-section only spreads the same force over more material, and part of that benefit is cancelled because the thicker arm is heavier and adds to the tension it must carry. Lengthening the arm actually reduces the force required, because F = mv²/r, and it lowers the rotation rate at the same time, so the stress falls for two reasons at once. Provided the arm is designed to be stiff enough not to bend, a longer arm therefore gives the greater reduction in stress.`,
  "phys-ocrb-h557-2023-p1::37(a)(i)": `The LDR and the 10.0 kΩ fixed resistor are in series across the 6.0 V supply, so the p.d.s across them must add up to 6.0 V.

From Fig. 37.2, at an illuminance of 200 lux the p.d. across the fixed resistor is 3.5 V.

So the p.d. across the LDR = 6.0 − 3.5 = 2.5 V.

The same current passes through both components, so their resistances are in the same ratio as the p.d.s across them:

R_LDR = (2.5 / 3.5) × 10.0 × 10³ = 7.1 × 10³ Ω

The resistance of the LDR is therefore about 7 kΩ, as required.

(Equivalently, the current is I = 3.5 / (10.0 × 10³) = 3.5 × 10⁻⁴ A, so R_LDR = 2.5 / (3.5 × 10⁻⁴) = 7.1 kΩ.)`,
  "phys-ocrb-h557-2023-p1::37(a)(ii)": `The sensitivity of the sensor is the gradient of the output p.d. against illuminance graph at that illuminance, so draw a tangent to the curve at 200 lux (where the p.d. is 3.50 V) and find its gradient.

Taking two widely separated points on the tangent, for example (150 lux, 3.00 V) and (250 lux, 3.95 V):

sensitivity = ΔV / Δ(illuminance) = (3.95 − 3.00) / (250 − 150) = 0.95 / 100

sensitivity = 0.01 V / lux (to 1 s.f.)`,
  "phys-ocrb-h557-2023-p1::37(a)(iii)": `If the fall were exponential, then adding a fixed number of extra sheets would always reduce the illuminance by the same fraction — in particular, the number of sheets needed to halve the illuminance would be the same wherever you start.

Taking three pairs of values from Fig. 37.3:

400 lux at 4 sheets; 200 lux at 16 sheets; 100 lux at 32 sheets.

Halving the illuminance from 400 lux to 200 lux takes 16 − 4 = 12 sheets.
Halving it again from 200 lux to 100 lux takes 32 − 16 = 16 sheets.

The number of sheets needed to halve the illuminance is not constant — it takes more sheets the second time — so the illuminance does not fall exponentially as the number of sheets increases.`,
  "phys-ocrb-h557-2023-p1::37(b)(i)": `Set up the GM tube at a fixed distance from the lead absorber, and place the gamma source on the other side of the lead. Measure the background count rate with no source present and record it. Then measure the count rate (corrected for background) with no lead absorber (x = 0) to obtain I₀. Add lead absorbers of known, measured thickness x (using vernier callipers to measure thickness accurately) one at a time and record the count rate I for each thickness. Each count should be taken over a long enough time (e.g. 60–120 seconds) to reduce statistical uncertainty. Plot a graph of ln I against x; if the relationship is exponential, this gives a straight line of gradient −μ, from which the absorption coefficient μ can be determined.`,
  "phys-ocrb-h557-2023-p1::37(b)(ii)": `I = I₀ e⁻ᵘˣ with I/I₀ = 0.15 and x = 3.2 cm.

0.15 = e^(−μ × 3.2)

ln(0.15) = −μ × 3.2

−1.897 = −3.2μ

μ = 1.897 / 3.2

absorption coefficient = 0.59 cm⁻¹`,
  "phys-ocrb-h557-2023-p1::38(a)": `Procedure. Clamp one end of the wire firmly to the bench between wooden blocks with the G-clamp, run the wire horizontally along the bench and over the pulley at the far end, and hang a mass hanger on the free end so that the wire is pulled straight under a small initial tension. Use a micrometer screw gauge to measure the diameter d of the wire at several places along its length and in different orientations, take the mean and work out the cross-sectional area A = πd²/4. Attach a small marker (a fiducial mark, such as a flag of tape) to the wire alongside the millimetre ruler and measure the original length L of wire between the clamped end and the marker with a metre rule. Record the starting position of the marker against the ruler. Now add slotted masses one at a time in equal steps, recording the added weight F = mg and the new position of the marker each time; the extension x is the distance the marker has moved from its starting position. Keep within the elastic region and check that the wire returns to its original length when the load is removed. Wear eye protection and put a padded box or tray of sand under the masses in case the wire breaks.

Analysis. Plot force F on the y-axis against extension x on the x-axis; the points should lie on a straight line through the origin. Draw the best-fit line and find its gradient F/x. Since E = stress/strain = (F/A) ÷ (x/L),

E = gradient × L / A

so multiplying the gradient by the original length and dividing by the cross-sectional area gives the Young Modulus.

Sources of uncertainty and how to estimate them. (1) The diameter of the wire. The micrometer reads only to ±0.01 mm and the wire may not be perfectly round or uniform, so the uncertainty is estimated as half the range of the several readings taken along the wire. Because A depends on d², this percentage uncertainty is doubled when it is carried into E, and on a thin wire it is usually the largest contribution. (2) The extension. It is only a few millimetres and is read from a millimetre ruler against the marker, so each of the two position readings is uncertain by about ±0.5 mm (the resolution of the ruler); repeating the loading and comparing the readings gives a check on the spread. The original length and the weights of the slotted masses contribute as well — the masses can be weighed on a balance and a mean value used.

Estimating the uncertainty in E. Put error bars for the extension on each point of the force–extension graph, then draw the steepest and the shallowest 'worst-fit' lines that still pass through all the error bars. Half the difference between the maximum and minimum gradients gives the uncertainty in the gradient. Express that as a percentage, then add it to the percentage uncertainty in the original length and to twice the percentage uncertainty in the diameter; applying the total percentage uncertainty to the calculated value of E gives the absolute uncertainty in the Young Modulus.`,
  "phys-ocrb-h557-2023-p1::38(b)(i)": `Strain at yield = yield stress / Young Modulus = 3.5 × 10⁸ / 2.8 × 10¹¹ = 1.25 × 10⁻³. Extension = strain × original length = 1.25 × 10⁻³ × 1.4 = 1.75 × 10⁻³ m ≈ 1.8 × 10⁻³ m (1.8 mm).`,
  "phys-ocrb-h557-2023-p1::38(b)(ii)": `Energy stored = ½ × F × ΔL = ½ × stress × A × extension = ½ × σ × A × ΔL. Alternatively, energy stored = ½ × (stress) × (strain) × volume = ½ × σ × ε × (A × L₀). = ½ × 3.5 × 10⁸ × 1.25 × 10⁻³ × (0.52 × 10⁻⁶ × 1.4) = ½ × 3.5 × 10⁸ × 1.25 × 10⁻³ × 7.28 × 10⁻⁷ = ½ × 3.185 × 10⁻¹ = 0.159 J ≈ 0.16 J.`,
  "phys-ocrb-h557-2023-p1::38(b)(iii)": `Yield strain: Yield strain = yield stress / Young Modulus. Since both the yield stress and Young Modulus are properties of the material (not the dimensions), and both remain the same for the same material, the yield strain is unchanged. Yield strain = 1.25 × 10⁻³ (same as before). Energy stored at yielding: E = ½ × σ × ε × volume = ½ × σ × ε × A × L. Since the new length is 2L₀ (doubled), the volume is doubled. Therefore the energy stored at the yielding point is doubled (E_new = 2 × 0.16 J = 0.32 J).`,
  "phys-ocrb-h557-2023-p1::38(b)(iv)": `Long cables are used because a longer cable stores more elastic potential energy before reaching its yield stress (as shown in (b)(iii), energy stored ∝ length for the same material and cross-section). When a sudden jerk or surge in tension occurs (e.g. if a wave causes the tug to lurch), a longer cable stretches by a greater extension before the force reaches a dangerous level, acting as a shock absorber. This prevents sudden impulsive forces from being transmitted directly to the rig, reducing the risk of the cable snapping or the rig being damaged.`,
  "phys-ocrb-h557-2023-p1::39(a)": `The gravitational potential energy released by contraction from infinity to radius R is approximately: E_grav = GM²/R. E_grav = (6.67 × 10⁻¹¹ × (2.0 × 10³⁰)²) / (7.0 × 10⁸) = (6.67 × 10⁻¹¹ × 4.0 × 10⁶⁰) / (7.0 × 10⁸) = 2.668 × 10⁵⁰ / 7.0 × 10⁸ = 3.81 × 10⁴¹ J. Lifetime = E/L = 3.81 × 10⁴¹ / 3.9 × 10²⁶ = 9.77 × 10¹⁴ s. In years: 9.77 × 10¹⁴ / (3.15 × 10⁷) ≈ 3.1 × 10⁷ years ≈ 3 × 10⁷ years.`,
  "phys-ocrb-h557-2023-p1::39(b)(i)": `Before reaction: Two protons (¹₁H), each with 2 up quarks and 1 down quark. Total up quarks = 2 × 2 = 4. Total down quarks = 2 × 1 = 2. After reaction: ²₁H (deuterium: 1 proton + 1 neutron = 2 up + 1 down + 1 up + 2 down = 3 up + 3 down), ⁰₊₁e (positron: not made of quarks, 0 quarks), ⁰₀ν (neutrino: 0 quarks). Total up quarks after = 3. Total down quarks after = 3. (A proton has uud; a neutron has udd; the deuterium nucleus has 1p + 1n: 2u + 1d + 1u + 2d = 3u + 3d. One up quark has converted to a down quark via the weak interaction.)`,
  "phys-ocrb-h557-2023-p1::39(b)(ii)": `Lepton number before: Two protons are not leptons (lepton number = 0). Total lepton number before = 0. Lepton number after: The positron (e⁺) has lepton number −1. The electron neutrino (νₑ) has lepton number +1. Deuterium is not a lepton (lepton number = 0). Total lepton number after = −1 + 1 + 0 = 0. Since lepton number before (0) equals lepton number after (0), lepton number is conserved.`,
  "phys-ocrb-h557-2023-p1::39(c)(i)": `From Fig. 39.1 (binding energy per nucleon graph), read off the binding energy per nucleon for each nucleus: ²₁H ≈ 1.1 MeV/nucleon; ³₂He ≈ 2.6 MeV/nucleon; ⁴₂He ≈ 7.1 MeV/nucleon; ¹₁H = 0 (proton, no binding energy). The three-stage process overall converts 4 protons into one ⁴₂He nucleus (plus 2 positrons and 2 neutrinos and 2 gamma photons, but considering just the nuclear binding energy change): Energy released = (total binding energy of products) − (total binding energy of reactants). For the overall reaction 4¹H → ⁴He: BE of ⁴He = 4 × 7.1 MeV = 28.4 MeV. BE of reactants (4 protons) = 0. Total energy ≈ 28.4 MeV = 28.4 × 1.6 × 10⁻¹³ J = 4.54 × 10⁻¹² J ≈ 5 × 10⁻¹² J. (Confirmed.)`,
  "phys-ocrb-h557-2023-p1::39(c)(ii)": `Each complete three-stage cycle releases approximately 5 × 10⁻¹² J. Number of fusion reaction cycles per second = L / energy per cycle = 3.9 × 10²⁶ / 5 × 10⁻¹² = 7.8 × 10³⁷ cycles per second ≈ 8 × 10³⁷ s⁻¹.`,
  "phys-ocrb-h557-2023-p1::39(c)(iii)": `Using E = mc²: rate of mass conversion = L/c² = 3.9 × 10²⁶ / (3.0 × 10⁸)² = 3.9 × 10²⁶ / 9.0 × 10¹⁶ = 4.33 × 10⁹ kg s⁻¹ ≈ 4.3 × 10⁹ kg s⁻¹.`,
  "phys-ocrb-h557-2023-p1::39(c)(iv)": `From (c)(iii) the Sun converts mass to energy at 4.3 × 10⁹ kg s⁻¹.

Mass lost in one year = 4.3 × 10⁹ × 3.15 × 10⁷ = 1.4 × 10¹⁷ kg, which is (1.4 × 10¹⁷ / 2.0 × 10³⁰) × 100 = 7 × 10⁻¹² % of the Sun's mass each year.

Mass converted in 4.5 billion years = 1.4 × 10¹⁷ × 4.5 × 10⁹ = 6.1 × 10²⁶ kg

percentage of solar mass converted to energy = (6.1 × 10²⁶ / 2.0 × 10³⁰) × 100 = 0.031 %

Explanation: gravitational contraction could have kept the Sun shining for only about 31 million years (part (a)), but the Earth is about 4.5 billion years old and the Sun has been shining throughout that time, so the contraction model gives far too short a lifetime and cannot be the source of the Sun's energy. Fusion easily lasts long enough: in the whole 4.5 billion years it has converted only 0.031% of the Sun's mass into energy, so there is plenty of mass left for the Sun to keep shining for billions of years yet.`,
  "phys-ocrb-h557-2023-p1::40(a)": `Draw a curve that is the potential energy curve turned upside down: it starts at zero on the displacement axis at −A, rises smoothly to a maximum at zero displacement, and falls back to zero at +A, with the same shape as the potential energy curve reflected in a horizontal line.

The maximum height of this curve at the centre must be the same as the height the potential energy curve reaches at −A and +A, so that at every displacement the two curves add up to the same constant total energy (the two curves therefore cross midway between the centre and each end). Label the new curve 'kinetic energy'.`,
  "phys-ocrb-h557-2023-p1::40(b)": `The oscillator is released from maximum displacement A = 0.050 m at t = 0, so x = A cos(2πft). At t = 0.25 s: x = 0.050 × cos(2π × 0.80 × 0.25) = 0.050 × cos(0.4π) = 0.050 × cos(72°) = 0.050 × 0.309 = 0.01545 m. v = ±2πf√(A² − x²) = ±2π × 0.80 × √((0.050)² − (0.01545)²) = ±5.027 × √(0.002500 − 0.000239) = ±5.027 × √(0.002261) = ±5.027 × 0.04755 = ±0.239 m s⁻¹ ≈ ±0.24 m s⁻¹. (The magnitude is 0.24 m s⁻¹; the sign depends on the direction of motion at that instant.)`,
  "phys-ocrb-h557-2023-p1::40(c)(i)": `Treating the molecule as a mass on a spring,

f = (1/2π)√(k/m) = (1/2π)√(520 / 1.7 × 10⁻²⁷)

520 / 1.7 × 10⁻²⁷ = 3.06 × 10²⁹ s⁻²

√(3.06 × 10²⁹) = 5.53 × 10¹⁴ s⁻¹

f = 5.53 × 10¹⁴ / 6.28

f = 8.8 × 10¹³ Hz`,
  "phys-ocrb-h557-2023-p1::40(c)(ii)": `The hydrogen chloride molecule only absorbs and emits photons of specific (discrete) frequencies. Each photon absorbed carries energy E = hf, and this energy is absorbed by the oscillating molecule to increase its amplitude of oscillation. Since only certain photon energies (corresponding to the resonant frequency f = 8.8 × 10¹³ Hz and its harmonics) can be absorbed, the energy of the oscillator can only increase in discrete steps (quanta). This means the amplitude of oscillation is quantised — only certain discrete amplitudes are allowed, corresponding to the allowed energy levels of the quantum oscillator. The molecule cannot oscillate with arbitrary amplitude; each allowed energy state has a specific amplitude given by E = ½kA².`,
  "phys-ocrb-h557-2023-p2::1(a)(i)": `The Boltzmann factor is e^(−E/kT). Here E = 1.2 × 10⁻¹⁹ J, k = 1.38 × 10⁻²³ J K⁻¹ and T = 310 K.
E/kT = 1.2 × 10⁻¹⁹ / (1.38 × 10⁻²³ × 310) = 1.2 × 10⁻¹⁹ / 4.28 × 10⁻²¹ = 28.0
Boltzmann factor = e⁻²⁸˙⁰ = 6.6 × 10⁻¹³.`,
  "phys-ocrb-h557-2023-p2::1(a)(ii)": `Each particle is making very large numbers of collisions every second, and in any one collision it can gain energy as well as lose it, so the energy of an individual particle is constantly changing. A particle that happens to gain energy in several successive collisions can end up with far more energy than the average. It is this build-up of energy through a run of favourable collisions that occasionally lifts one particle above the 1.2 × 10⁻¹⁹ J needed, allowing it to react, even though the mean energy of the particles is very much smaller than this.`,
  "phys-ocrb-h557-2023-p2::1(b)(i)": `The Boltzmann factor gives the fraction (proportion) of particles that have energy greater than or equal to the activation energy E_a at temperature T. A larger Boltzmann factor means a greater proportion of particles have sufficient energy to react. When an enzyme is present, it lowers the activation energy E_a of the reaction. This increases the exponent (−E_a / k_BT becomes less negative), so e^(−E_a/k_BT) becomes much larger. A larger Boltzmann factor means a much greater fraction of particles have enough energy to undergo the reaction at any given moment. Therefore, the rate of successful collisions (and hence the rate of the digestion reaction) increases significantly.`,
  "phys-ocrb-h557-2023-p2::1(b)(ii)": `The Boltzmann factor is e^(−E/kT), so 6.7 × 10⁻⁷ = e^(−E/(1.38 × 10⁻²³ × 310)).
Taking natural logarithms of both sides: ln(6.7 × 10⁻⁷) = −E/(1.38 × 10⁻²³ × 310), so −14.22 = −E/(4.28 × 10⁻²¹).
E = 14.22 × 4.28 × 10⁻²¹ = 6.1 × 10⁻²⁰ J.`,
  "phys-ocrb-h557-2023-p2::2(a)(i)": `Vertical component of velocity: v_y = 30 × sin40° = 30 × 0.6428 = 19.28 m s⁻¹. At maximum height, vertical velocity = 0. Using v² = u² − 2gh: 0 = (19.28)² − 2 × 9.81 × h. h = (19.28)² / (2 × 9.81) = 371.7 / 19.62 = 18.95 m ≈ 19 m. Since 19 m < 20 m, the highest point reached is less than 20 m above the cannon. (Confirmed.)`,
  "phys-ocrb-h557-2023-p2::2(a)(ii)": `Resolve the launch velocity: horizontal component = 30 cos 40° = 23.0 m s⁻¹, vertical component = 30 sin 40° = 19.3 m s⁻¹.
Time to reach the highest point: t₁ = 19.3/9.8 = 1.97 s, at a height of 19.0 m (from (a)(i)).
The shirt then falls from 19.0 m to the spectators at 10 m, a drop of 9.0 m: 9.0 = ½ × 9.8 × t₂², so t₂ = √(2 × 9.0/9.8) = 1.36 s.
Total time in the air = 1.97 + 1.36 = 3.33 s.
The horizontal velocity is constant, so x = 23.0 × 3.33 = 77 m (76 m if unrounded values are carried through).`,
  "phys-ocrb-h557-2023-p2::2(b)": `The shirt starts from rest and reaches 30 m s⁻¹ over the length of the barrel (1.4 m). Using work-energy theorem: Work done by net force = change in KE. F_avg × d = ½mv². F_avg = mv² / (2d) = (0.50 × 30²) / (2 × 1.4) = (0.50 × 900) / 2.8 = 450 / 2.8 = 160.7 N ≈ 160 N.`,
  "phys-ocrb-h557-2023-p2::2(c)": `Area of cross-section of barrel: A = π r² = π × (0.05)² = π × 0.0025 = 7.854 × 10⁻³ m². Initial force = excess pressure × area = 4.0 × 10⁴ × 7.854 × 10⁻³ = 314 N ≈ 310 N. This is greater than the average force (160 N) because as the gas expands along the barrel, its pressure decreases (following Boyle's Law: PV = constant, so P decreases as V increases). The force on the shirt is proportional to the gas pressure. At the moment of release, the gas is at its highest pressure, giving the maximum force. As the shirt accelerates along the barrel, the gas expands, the pressure falls, and so the force decreases. The average force over the whole barrel is therefore less than the initial maximum force.`,
  "phys-ocrb-h557-2023-p2::3(a)": `Graph of P vs V (Fig. 3.2a): For an isothermal process (constant temperature), PV = constant. The graph is a hyperbola — a curve that decreases steeply at low V and approaches the axes asymptotically. As V increases, P decreases in a non-linear (hyperbolic) fashion. The curve does not touch either axis.

Graph of P vs 1/V (Fig. 3.2b): Since PV = constant, P = constant × (1/V). A graph of P against 1/V is a straight line through the origin with a positive gradient equal to nRT (the constant). Both graphs must show curves/lines consistent with Boyle's Law.`,
  "phys-ocrb-h557-2023-p2::3(b)": `Using the kinetic theory result: P = ⅓ρ<c²>, so <c²> = 3P/ρ. Alternatively, using: ½m<c²> = (3/2)k_BT. c_rms = √(3k_BT/m) = √(3 × 1.38 × 10⁻²³ × 298 / 6.6 × 10⁻²⁶). Numerator = 3 × 1.38 × 10⁻²³ × 298 = 1.233 × 10⁻²⁰ J. c_rms = √(1.233 × 10⁻²⁰ / 6.6 × 10⁻²⁶) = √(1.868 × 10⁵) = 432 m s⁻¹ ≈ 430 m s⁻¹. (Confirmed.)`,
  "phys-ocrb-h557-2023-p2::3(c)(i)": `In an elastic collision between the atom (mass m, velocity u = +430 m s⁻¹) and the piston (mass M >> m, velocity V = −1.5 m s⁻¹ toward the atom), the relative velocity of approach equals the relative velocity of separation. Relative velocity of approach = u − V = 430 − (−1.5) = 431.5 m s⁻¹. In an elastic collision, the relative velocity of separation = −(relative velocity of approach). Since M >> m, the piston is effectively unchanged in velocity after the collision. Velocity of atom after = V − (u − V) = 2V − u = 2(−1.5) − 430 = −3 − 430 = −433 m s⁻¹. The atom now moves at −433 m s⁻¹ (in the opposite direction), which confirms the stated value.`,
  "phys-ocrb-h557-2023-p2::3(c)(ii)": `If the gas is compressed more quickly, the piston moves inward with a greater speed. Each time a gas atom collides with the moving piston, it gains more kinetic energy (as shown in (c)(i) — the faster the piston moves, the greater the increase in speed of the reflected atom). Therefore the average kinetic energy of the gas atoms increases more rapidly, meaning the temperature of the gas rises. Since PV = nRT and T increases during faster compression, the final pressure for a given volume is higher than it would be for slow (isothermal) compression. On the P–V graph (Fig. 3.2a), the curve for fast compression lies above the isothermal curve (the gas reaches a higher pressure at the same volume). On the P vs 1/V graph (Fig. 3.2b), the line has a steeper gradient (greater nRT constant) than the isothermal line.`,
  "phys-ocrb-h557-2023-p2::4(a)": `Both speakers are driven by the same signal generator, so they emit coherent sound waves of the same frequency and similar amplitude which travel towards each other along the line between them. Where the two waves meet they superpose. At points where they always arrive in phase the displacements add and an antinode of maximum amplitude is formed; halfway between these, where they always arrive in antiphase (180° out of phase), they cancel and a node of minimum amplitude is formed. Because the pattern of nodes and antinodes stays in the same place it is a standing wave.
It is observed by moving the microphone slowly along the line between the speakers: the amplitude of the trace on the oscilloscope rises to a maximum at each antinode and falls to a minimum at each node, with adjacent nodes half a wavelength apart.`,
  "phys-ocrb-h557-2023-p2::4(b)(i)": `Nodes are separated by λ/2. λ/2 = 5.60 cm, so λ = 11.2 cm = 0.112 m. v = fλ = 3.00 × 10³ × 0.112 = 336 m s⁻¹.`,
  "phys-ocrb-h557-2023-p2::4(b)(ii)": `If only the distance between two adjacent nodes is measured, the uncertainty in that single measurement (e.g. ±1 mm) constitutes a large percentage of the small distance (~5.6 cm). By measuring the total distance across several nodes (e.g. n node spacings), the actual distance measured is n times larger, while the absolute uncertainty in the measurement remains roughly the same (still ±1 mm from reading the ruler). The percentage uncertainty in the distance therefore decreases by a factor of n. Since λ/2 = total distance / n, the percentage uncertainty in λ/2 (and hence in v = fλ) is reduced. The student's reasoning is that spreading the measurement over a greater distance reduces the fractional (percentage) uncertainty, leading to a more precise and accurate result.`,
  "phys-ocrb-h557-2023-p2::4(c)(i)": `For the lowest standing wave mode (fundamental) in a box of length L, the standing wave has one half-wavelength fitting in the box: L = λ/2, so λ = 2L = 2 × 2.4 × 10⁻¹⁰ = 4.8 × 10⁻¹⁰ m. Using de Broglie: p = h/λ = 6.63 × 10⁻³⁴ / 4.8 × 10⁻¹⁰ = 1.38 × 10⁻²⁴ kg m s⁻¹ ≈ 1.4 × 10⁻²⁴ kg m s⁻¹. (Confirmed.)`,
  "phys-ocrb-h557-2023-p2::4(c)(ii)": `EK = p²/(2m) = (1.38 × 10⁻²⁴)² / (2 × 9.11 × 10⁻³¹). Numerator = 1.904 × 10⁻⁴⁸. Denominator = 1.822 × 10⁻³⁰. EK = 1.904 × 10⁻⁴⁸ / 1.822 × 10⁻³⁰ = 1.045 × 10⁻¹⁸ J ≈ 1.0 × 10⁻¹⁸ J.`,
  "phys-ocrb-h557-2023-p2::4(c)(iii)": `Electric potential energy of electron at distance r = 1.2 × 10⁻¹⁰ m from proton: EP = −ke²/r = −(8.99 × 10⁹ × (1.60 × 10⁻¹⁹)²) / (1.2 × 10⁻¹⁰). Numerator = 8.99 × 10⁹ × 2.56 × 10⁻³⁸ = 2.301 × 10⁻²⁸ J m. EP = −2.301 × 10⁻²⁸ / 1.2 × 10⁻¹⁰ = −1.918 × 10⁻¹⁸ J ≈ −1.9 × 10⁻¹⁸ J.`,
  "phys-ocrb-h557-2023-p2::4(c)(iv)": `Total energy = kinetic + potential = 1.0 × 10⁻¹⁸ + (−1.9 × 10⁻¹⁸) = −9.0 × 10⁻¹⁹ J.
The total energy is negative — the magnitude of the (negative) potential energy is greater than the kinetic energy — so the electron is bound and would not escape from the proton at this distance.
If the atom were squeezed to a smaller size the standing wave would have a shorter wavelength, so the momentum and hence the kinetic energy would rise as 1/L², while the magnitude of the potential energy only rises as 1/L. The total energy therefore becomes less negative as the box is made smaller, and the minimum possible size of the atom is the length at which the total energy has risen to zero (kinetic energy equal in magnitude to the potential energy); at any smaller size the electron would no longer be bound. Equating the two expressions and solving for L gives an estimate of the minimum diameter of a hydrogen atom.`,
  "phys-ocrb-h557-2023-p2::5(a)(i)": `The graph shows the ionisation density (ion pairs per mm) along the track of the alpha particle. The total number of ion pairs is represented by the area under the graph (ionisation density vs distance). If the area under the curve is approximately 240 000 ion pairs, this total area corresponds to the total ionisation along the entire track, confirming the stated number of ion pairs.`,
  "phys-ocrb-h557-2023-p2::5(a)(ii)": `Total number of ion pairs ≈ 240 000. Energy per ion pair = 30 eV. Total energy of alpha particle = 240 000 × 30 = 7 200 000 eV = 7.2 MeV. The reasoning: the alpha particle loses all its kinetic energy by creating ion pairs along its track, so the initial kinetic energy equals the total number of ion pairs multiplied by the energy required per ion pair.`,
  "phys-ocrb-h557-2023-p2::5(a)(iii)": `Beta particles are much lighter than alpha particles (mass of electron ≈ 1/7400 of alpha particle mass). For the same initial kinetic energy, beta particles travel at much higher speeds. Beta particles also carry a single charge (−e) compared to the double charge (2e) of alpha particles. The rate of ionisation (energy loss per unit distance, stopping power) is much lower for beta particles because: (1) they have smaller charge so the Coulomb interaction with electrons is weaker; (2) they travel faster so spend less time near each air molecule. Therefore beta particles create fewer ion pairs per unit length and travel much farther in air before losing all their energy compared to alpha particles of the same initial energy.`,
  "phys-ocrb-h557-2023-p2::5(b)(i)": `Conservation of momentum: initial momentum = 0 (radium at rest). After decay: m_α v_α = m_Rn v_Rn (in opposite directions). v_Rn / v_α = m_α / m_Rn = 4 / 220. Kinetic energy of alpha: EK_α = ½m_α v_α². Kinetic energy of Rn: EK_Rn = ½m_Rn v_Rn² = ½m_Rn (m_α v_α / m_Rn)² = ½(m_α² v_α²)/m_Rn = EK_α × (m_α/m_Rn). Total KE = EK_α + EK_Rn = EK_α (1 + m_α/m_Rn) = EK_α(1 + 4/220) = EK_α × 224/220. So EK_α / Total KE = 220/224 = 0.982 = 98.2%. The alpha particle carries approximately 98% of the kinetic energy released in the decay.`,
  "phys-ocrb-h557-2023-p2::5(b)(ii)": `Tissue is far denser than air (990 kg m⁻³ compared with about 1.2 kg m⁻³), so its atoms are much more closely packed. The alpha particle therefore makes many more ionising interactions in each millimetre it travels, loses its kinetic energy over a much shorter distance and stops after about 0.1 mm instead of the 70 mm it travels in air.`,
  "phys-ocrb-h557-2023-p2::5(b)(iii)": `Step 1 — Calculate the energy of the alpha particle. Mass defect Δm = m_Ra − m_Rn − m_α = 223.97191 − 219.96420 − 4.00150 = 0.00621 u. Energy released = Δm × 931.5 MeV/u = 0.00621 × 931.5 = 5.785 MeV = 5.785 × 10⁶ × 1.6 × 10⁻¹⁹ = 9.26 × 10⁻¹³ J. From (b)(i), the alpha particle carries 98.2% of this energy: EK_α = 0.982 × 9.26 × 10⁻¹³ = 9.09 × 10⁻¹³ J ≈ 9.1 × 10⁻¹³ J.

Step 2 — Calculate the effective dose over 2 hours. Activity = 18 kBq = 18 000 disintegrations per second. Duration = 2 hours = 7200 s. Number of decays = 18 000 × 7200 = 1.296 × 10⁸. Each decay produces one alpha particle, so energy absorbed by tissue = 1.296 × 10⁸ × 9.09 × 10⁻¹³ = 1.178 × 10⁻⁴ J. Absorbed dose = energy / mass = 1.178 × 10⁻⁴ / 0.004 = 2.945 × 10⁻² Gy = 0.0295 Gy. Effective dose = absorbed dose × quality factor = 0.0295 × 20 = 0.59 Sv.

Assumptions: (1) All the alpha particle energy is absorbed within the tissue of mass 0.004 kg — this is reasonable because the range of alpha particles in tissue is ~0.1 mm, so all energy is deposited locally within the target cells. (2) The activity is assumed constant over the 2 hours — this is reasonable because 2 hours is much shorter than the half-life of radium-224 (T½ = 3.6 days), so negligible decay of the source occurs during this period. (3) The radon daughter nucleus is assumed to escape the tissue (or its energy is not counted) — this may not be entirely valid but the alpha contributes ~98% of the energy.`,
  "phys-ocrb-h557-2023-p2::6(a)(i)": `The wavefronts shown to the left of the lens are straight (plane) parallel lines. Plane wavefronts indicate that the source of the waves is very far away (effectively at infinity), because waves from a point source become plane waves when the source is an infinite distance away. The flat, parallel wavefronts show zero curvature, corresponding to an object at infinite distance.`,
  "phys-ocrb-h557-2023-p2::6(a)(ii)": `To the right of the lens draw a set of arcs that are all centred on the point P, so that each arc curves round P with its concave side facing P (i.e. the waves are converging on P). The arcs should be evenly spaced, with the same spacing as the plane wavefronts arriving at the lens, and each successive arc should be shorter as they close in on P, where they converge to a point.`,
  "phys-ocrb-h557-2023-p2::6(a)(iii)": `Using the lens equation with curvatures: curvature of incident wave + power of lens = curvature of outgoing wave. The incident wave is plane (from infinity), so incident curvature = 0. Outgoing curvature = 0 + 1.8 D = 1.8 D. Distance to focal point = 1/curvature = 1/1.8 = 0.556 m ≈ 0.56 m. The lens adds +1.8 D of curvature to the wavefront; since the incoming wavefront has zero curvature (plane wave from infinity), the outgoing curvature is 1.8 D, corresponding to a focal length (distance to P) of 1/1.8 ≈ 0.56 m.`,
  "phys-ocrb-h557-2023-p2::6(b)(i)": `For wavelength 410 nm: n = c_air / c_glass = 3.00 × 10⁸ / 1.81 × 10⁸ = 1.657 ≈ 1.66. For wavelength 710 nm: n = 1.62, so c_glass = c_air / n = 3.00 × 10⁸ / 1.62 = 1.852 × 10⁸ m s⁻¹ ≈ 1.85 × 10⁸ m s⁻¹. Completed table: 410 nm | 1.81 × 10⁸ m s⁻¹ | 1.66; 710 nm | 1.85 × 10⁸ m s⁻¹ | 1.62.`,
  "phys-ocrb-h557-2023-p2::6(b)(ii)": `The power of a lens depends on its refractive index: a higher refractive index causes greater bending (refraction) of light at each surface. Since shorter wavelength light (e.g. blue/violet) travels more slowly in glass (lower v, higher n = c/v), the lens has a higher refractive index for shorter wavelengths. A higher refractive index gives a larger deviation at each lens surface and hence a shorter focal length (greater power P = 1/f). Consequently, the power of the lens is greater for shorter wavelength (blue) light, meaning blue light is brought to focus at a shorter distance from the lens than red light. This causes chromatic aberration: different colours focus at different positions along the optical axis.`,
  "phys-ocrb-h557-2023-p2::6(c)(i)": `The image is formed on the retina, so the image distance is v = 2.0 cm, and the object is at the near point, u = 25 cm.
Linear magnification m = v/u = 2.0/25 = 0.080.
Height of image = 0.080 × 4 mm = 0.32 mm = 3.2 × 10⁻⁴ m.`,
  "phys-ocrb-h557-2023-p2::6(c)(ii)": `The image must always be focused on the retina, 2.0 cm from the lens.
To focus an object placed at 25 cm the eye needs a total power of 1/0.25 + 1/0.020 = 4.0 + 50.0 = +54.0 D.
A person whose near point is 50 cm can produce at most 1/0.50 + 1/0.020 = 2.0 + 50.0 = +52.0 D.
The spectacle lens must supply the difference: 54.0 − 52.0 = +2.0 D, i.e. a converging lens of focal length 0.50 m.`,
  "phys-ocrb-h557-2023-p2::6(d)": `For a more powerful (high-power) spectacle lens, a large degree of bending of light is required. A higher refractive index (n = 1.70 for high-index glass) achieves the required power with less curvature (less curved surfaces) than a lower-index material. Flatter surfaces are thinner, making the lens lighter and more aesthetically acceptable despite the glass being denser. The resulting thin lens also reduces distortion and aberration. For lower power lenses (less bending required), the surfaces are already relatively flat for any material, so the greater density of glass (3.2 × 10³ kg m⁻³) would make the lens unnecessarily heavy without providing optical benefit. Polycarbonate has a density of only 1.2 × 10³ kg m⁻³ — nearly three times lighter — so for low-power lenses, polycarbonate gives a much lighter, thinner, and more comfortable lens with adequate optical performance, making it preferable.`,
  "phys-ocrb-h557-2023-p2::7(a)(i)": `Fig. 7 shows the flux repeating every 0.020 s, so the period is T = 0.020 s and the rotation frequency is f = 1/T = 50 Hz.
The e.m.f. is ε = maximum flux linkage × 2πf sin(2πft), which is greatest when sin(2πft) = 1, so ε₀ = maximum flux linkage × 2πf.
Maximum flux linkage = ε₀/(2πf) = 24.0/(2π × 50) = 24.0/314 = 0.076 Wb turns.`,
  "phys-ocrb-h557-2023-p2::7(a)(ii)": `Flux linkage NΦ = NBA, where A = (0.12)² = 0.0144 m², N = 400. NΦ_max = NBA = 0.0764 Wb (from (i)). B = NΦ_max / (NA) = 0.0764 / (400 × 0.0144) = 0.0764 / 5.76 = 0.01326 T ≈ 0.013 T = 13 mT.`,
  "phys-ocrb-h557-2023-p2::7(b)": `Modification 1: increase the number of turns on the coil. The flux linkage is NΦ, so for the same flux and the same rotation frequency the maximum flux linkage is increased in proportion to N, and since ε₀ = maximum flux linkage × 2πf the induced e.m.f. increases in the same proportion.
Modification 2: increase the cross-sectional area of the coil and core. The flux through the coil is Φ = BA, so a larger area carries more flux; the maximum flux linkage NBA is therefore larger and, by Faraday's law ε = −d(NΦ)/dt, the rate of change of flux linkage and so the induced e.m.f. is greater even though the frequency of rotation is unchanged.`,
  "phys-ocrb-h557-2023-p2::8(a)": `Consider a cylinder of air of cross-sectional area A and length v·t (swept out in time t) moving with wind velocity v. Volume of air = Avt. Mass of air = ρAvt. Kinetic energy of this air = ½mv² = ½(ρAvt)v² = ½ρAv³t. Power = energy/time = ½ρAv³t/t = ½ρAv³. Therefore P = ½ρAv³. (This derivation shows that the power available from wind is proportional to the cube of the wind speed and proportional to the swept area.)`,
  "phys-ocrb-h557-2023-p2::8(b)": `We need to find the wind speed at 10 m height (v₁₀) that produces a total electrical output power of 900 MW.

Step 1: Find the total mechanical wind power needed at turbine height. Electrical output = 900 MW = 9.0 × 10⁸ W. Efficiency = 43% = 0.43. Total wind power intercepted by all turbines = 9.0 × 10⁸ / 0.43 = 2.093 × 10⁹ W.

Step 2: Power per turbine = 2.093 × 10⁹ / 85 = 2.462 × 10⁷ W.

Step 3: Swept area of each turbine = π(d/2)² = π × (60)² = π × 3600 = 11 310 m².

Step 4: Find wind speed at turbine height (90 m) using P = ½ρAv³. 2.462 × 10⁷ = ½ × 1.2 × 11 310 × v³ = 6786 v³. v³ = 2.462 × 10⁷ / 6786 = 3628. v = ∛3628 = 15.38 m s⁻¹ at hub height 90 m.

Step 5: Use the wind shear power law to find v at 10 m. The standard wind profile equation is v(h) = v_ref × (h/h_ref)^α where α ≈ 1/7 (Hellmann exponent for open terrain). v₁₀ = 15.38 × (10/90)^(1/7) = 15.38 × (0.1111)^(0.143) = 15.38 × 0.726 = 11.2 m s⁻¹ ≈ 11 m s⁻¹.

The method: first back-calculate the required wind power at hub height from the output and efficiency, then use P = ½ρAv³ to find hub-height wind speed, then apply the wind shear law to find the equivalent speed at 10 m reference height.`,
  "phys-ocrb-h557-2023-p2::9(a)": `The water loses gravitational potential energy at a rate ṁgh = 55 × 9.81 × 195 = 1.05 × 10⁵ W.
The output power of the turbine is 94.5 kW = 9.45 × 10⁴ W.
Efficiency = useful output power / input power = 9.45 × 10⁴ / 1.05 × 10⁵ = 0.90, i.e. 90%.`,
  "phys-ocrb-h557-2023-p2::9(b)(i)": `Volume flow rate Q = 55 × 10⁻³ m³ s⁻¹. Cross-sectional area A = 7.9 × 10⁻³ m². Velocity v = Q/A = 55 × 10⁻³ / 7.9 × 10⁻³ = 6.96 m s⁻¹ ≈ 7 m s⁻¹. (Confirmed.)`,
  "phys-ocrb-h557-2023-p2::9(b)(ii)": `Force = rate of change of momentum. Mass flow rate ṁ = ρ × Q = 1000 × 55 × 10⁻³ = 55 kg s⁻¹. The water's horizontal velocity reduces to zero on hitting the surface. Force = ṁ × Δv = 55 × (7 − 0) = 385 N ≈ 390 N.`,
  "phys-ocrb-h557-2023-p2::9(b)(iii)": `The vane moves away from the nozzle at 3.5 m s⁻¹ while the jet travels at 7.0 m s⁻¹, so relative to the vane the water arrives at 7.0 − 3.5 = 3.5 m s⁻¹ — half the jet speed, which is the condition for maximum power.
The mass of water arriving each second is still ṁ = ρQ = 1000 × 55 × 10⁻³ = 55 kg s⁻¹, and its horizontal velocity relative to the vane is reduced to zero, so the force is F = ṁ × 3.5 = 55 × 3.5 = 192.5 N, half the value found in (b)(ii).
Power transferred = F × (velocity of the vane) = 192.5 × 3.5 = 674 W ≈ 6.7 × 10² W.`,
  "phys-ocrb-h557-2023-p2::9(b)(iv)": `The Pelton turbine vane is designed as a curved, cup-like 'bucket' shape. When the water jet strikes the curved vane, it is deflected so that it leaves the vane moving backwards (nearly 180° deflection in the frame of the vane). This design increases the change in momentum (Δp) of the water compared to a flat vane where the water just stops. By redirecting the water back in the direction it came from (in the vane's reference frame), the rate of change of momentum — and hence the force on the vane and the power extracted — is doubled compared to a flat vane that simply stops the water. The water is therefore more efficiently decelerated, transferring more kinetic energy to the turbine for the same jet velocity and flow rate.`,
  "phys-ocrb-h557-2023-p3::1(a)(i)": `The two blank cells are in the 10.0 kΩ and 13.3 kΩ rows. Using I = V/R, and working in mV and kΩ so that the current comes out directly in µA:
R = 10.0 kΩ: I = 738 / 10.0 = 73.8 µA (≈ 74 µA)
R = 13.3 kΩ: I = 765 / 13.3 = 57.5 µA (≈ 58 µA)
Completed rows: 10.0 kΩ | 738 mV | 73.8 µA and 13.3 kΩ | 765 mV | 57.5 µA.`,
  "phys-ocrb-h557-2023-p3::1(a)(ii)": `Plot the two currents found in (a)(i) against their potential differences: (74 µA, 738 mV) and (58 µA, 765 mV). Mark each with a fine cross or dot no larger than half a small square — they fall between the (101, 666) and (47, 784) points that are already plotted. Then use a ruler to draw a single straight line of best fit through all six points, with roughly equal numbers of points above and below it, covering the whole range of the data from about I = 40 µA to I = 164 µA. Do not draw a kinked or 'hairy' line and do not join the points dot-to-dot. Drawn correctly, the line cuts the potential-difference axis at about 890 mV and reaches V = 500 mV at about I = 181 µA.`,
  "phys-ocrb-h557-2023-p3::1(a)(iii)": `Take two widely separated points that lie on the line of best fit (not raw data points), for example (40 µA, 806 mV) and (160 µA, 546 mV):
gradient = ΔV/ΔI = (546 − 806) / (160 − 40) = −260 mV / 120 µA = −2.17 mV µA⁻¹
In SI units: −2.17 × 10⁻³ V ÷ 10⁻⁶ A = −2.17 × 10³ Ω.
For a cell with internal resistance, ε = V + Ir, which rearranges to V = ε − Ir = (−r)I + ε. Comparing with y = mx + c, a graph of V against I is a straight line whose gradient is −r (and whose intercept is the emf, ε ≈ 0.89 V).
So r = −gradient = 2.17 × 10³ Ω ≈ 2200 Ω (2.2 kΩ).`,
  "phys-ocrb-h557-2023-p3::1(a)(iv)": `The lamp needs a current I = P/V = 0.45 / 1.5 = 0.30 A. Two lemon cells in series cannot supply anything like this. Their combined emf is 2ε ≈ 1.8 V but their combined internal resistance is 2r ≈ 2 × 2.2 kΩ = 4.4 kΩ, so even with the terminals short-circuited the largest possible current is 2ε/2r = 1.8 / 4400 ≈ 4 × 10⁻⁴ A, i.e. less than 1 mA — roughly a thousand times smaller than the 0.30 A the lamp requires.
The same point can be made with resistances: at its working point the lamp's resistance is R = V²/P = 1.5² / 0.45 = 5.0 Ω. This is tiny compared with the 4.4 kΩ internal resistance of the two lemons, so almost the whole emf would be lost inside the cells and the pd across the lamp would be only a few millivolts. The lamp would not light.`,
  "phys-ocrb-h557-2023-p3::1(b)": `One lemon cell: ε = V + Ir, so V = ε − rI. A graph of V against I is a straight line of gradient −r with y-intercept ε, reaching V = 0 at I = ε/r.

Two lemons in series: the emfs add and so do the internal resistances, giving 2ε = V + 2I_s r, i.e. V = 2ε − 2rI_s. The gradient is −2r, twice as steep as for one lemon, and the y-intercept is 2ε, twice as large. The same current flows through both cells and through the load. Setting V = 0 gives I = 2ε/2r = ε/r, exactly the same x-intercept as for a single lemon. For any given current the lost volts are 2Ir instead of Ir, so a larger proportion of the emf is lost inside the cells.

Two lemons in parallel: each cell still has emf ε, so the combination has emf ε. The load current I_p divides equally between the two identical cells, so each carries I_p/2. Applying the emf equation to one cell: ε = V + (I_p/2)r, which can be written ε = V + I_p(r/2) — i.e. the two internal resistances behave as one resistance r/2 (two equal resistors in parallel give r×r/(r+r) = r/2). Rearranging, V = ε − (r/2)I_p. The gradient is therefore −r/2, half as steep as for one lemon, while the y-intercept is ε, the same as for one lemon. Setting V = 0 gives I = 2ε/r, twice the x-intercept of a single lemon, so the parallel pair can deliver twice the maximum current. For the same load current the lost volts are halved, so a smaller proportion of the emf is lost internally.

Sketch (three straight lines on the same V–I axes, each labelled):
• one lemon — starts at ε (about 0.89 V) on the V-axis, gradient −r, meets the I-axis at about 0.4 mA;
• two in series — starts at 2ε (about 1.8 V), the steepest line, gradient −2r, meets the I-axis at the same current (about 0.4 mA) as the single lemon;
• two in parallel — starts at the same intercept ε as the single lemon, the shallowest line, gradient −r/2, meets the I-axis at about 0.8 mA, twice as far out.

In summary, connecting the lemons in series doubles the pd available on open circuit but also doubles the internal resistance, so the line falls away twice as quickly; connecting them in parallel leaves the open-circuit pd unchanged but halves the internal resistance, so the pd falls away only half as quickly and twice the current can be drawn.`,
  "phys-ocrb-h557-2023-p3::2(a)(i)": `There are 15 readings on the dot-plot. Their sum is
1.42 + 1.44 + 1.46 + 1.47 + 2(1.48) + 1.49 + 3(1.50) + 1.51 + 2(1.52) + 1.53 + 1.54 = 22.36 V
mean = 22.36 / 15 = 1.4907 = 1.49 V (3 s.f.)
absolute uncertainty = ½ × range = ½(1.54 − 1.42) = ½ × 0.12 = 0.06 V
Mean striking voltage = 1.49 ± 0.06 V. (All 15 readings are used; none is discarded as an outlier when finding the mean.)`,
  "phys-ocrb-h557-2023-p3::2(a)(ii)": `One significant cause of uncertainty: The striking voltage (the voltage at which the LED just begins to emit visible light) is difficult to determine precisely because the transition from off to on is gradual — the LED dims gradually as the voltage is reduced, rather than switching off sharply. This makes the exact striking voltage subjective and dependent on the observer's judgement. Method to reduce this uncertainty: Use a light-dependent resistor (LDR) or photodiode connected to a sensitive meter or datalogger to detect the onset of light emission objectively, rather than relying on visual observation. Alternatively, take many repeat readings and calculate the mean to reduce random error.`,
  "phys-ocrb-h557-2023-p3::2(b)(i)": `The uncertainty from (a)(i) is ±0.06 V. On the striking-voltage axis one small square is 0.02 V, so each error bar must extend 3 small squares above and 3 small squares below its point (6 small squares long in total). Draw such a vertical bar on every one of the five plotted points — for example the point at (1.53 × 10⁶ m⁻¹, 0.80 V) gets a bar from 0.74 V to 0.86 V, and the point at (2.33 × 10⁶ m⁻¹, 1.49 V) gets one from 1.43 V to 1.55 V.
Then use a ruler to draw the steepest straight line that still passes through every error bar: it runs from the bottom of the error bar on the bottom-left point, (1.53 × 10⁶ m⁻¹, 0.74 V), to the top of the error bar on the top-right point, (2.33 × 10⁶ m⁻¹, 1.55 V). Check as you draw that it also passes inside the three error bars in between.`,
  "phys-ocrb-h557-2023-p3::2(b)(ii)": `Take two points from the steepest line drawn in (b)(i), namely its ends:
(1.53 × 10⁶ m⁻¹, 0.74 V) and (2.33 × 10⁶ m⁻¹, 1.55 V)
steepest gradient = ΔV / Δ(1/λ) = (1.55 − 0.74) / [(2.33 − 1.53) × 10⁶] = 0.81 / (0.80 × 10⁶) = 1.01 × 10⁻⁶ V m = 10.1 × 10⁻⁷ V m
absolute uncertainty in the gradient = steepest gradient − best-fit gradient = (10.1 − 8.90) × 10⁻⁷ = 1.2 × 10⁻⁷ V m
So the gradient is (8.9 ± 1.2) × 10⁻⁷ V m, i.e. an absolute uncertainty of ±1.2 × 10⁻⁷ V m.`,
  "phys-ocrb-h557-2023-p3::2(c)(i)": `The energy of a photon: E = hf = hc/λ. The minimum energy needed for an electron to be excited (striking voltage V_s): eV_s = hc/λ. Rearranging: V_s = (hc/e) × (1/λ). A graph of V_s against 1/λ has gradient = hc/e. Therefore: hc/e = gradient, which gives h = gradient × e / c. (This is the required result.)`,
  "phys-ocrb-h557-2023-p3::2(c)(ii)": `h = gradient × e/c = (8.90 × 10⁻⁷ × 1.60 × 10⁻¹⁹) / (3.00 × 10⁸)
= 1.424 × 10⁻²⁵ / 3.00 × 10⁸ = 4.75 × 10⁻³⁴ J s
Uncertainty: e and c are known constants, so the percentage uncertainty in h is the same as the percentage uncertainty in the gradient found in (b)(ii):
1.2 × 10⁻⁷ / 8.90 × 10⁻⁷ = 0.13, i.e. 13%
absolute uncertainty in h = 0.13 × 4.75 × 10⁻³⁴ = 0.6 × 10⁻³⁴ J s
(The same answer comes from the steepest line: h_max = 10.1 × 10⁻⁷ × 1.60 × 10⁻¹⁹ / 3.00 × 10⁸ = 5.4 × 10⁻³⁴ J s, and 5.4 × 10⁻³⁴ − 4.75 × 10⁻³⁴ ≈ 0.6 × 10⁻³⁴ J s.)
Planck constant = (4.7 ± 0.6) × 10⁻³⁴ J s.`,
  "phys-ocrb-h557-2023-p3::3(a)": `Circuit diagram: Connect the variable power supply in series with the capacitor (of unknown capacitance C) and a switch S₁. Connect the 4.7 kΩ resistor in parallel with the capacitor, with a second switch S₂ in series with the resistor (or in the discharge loop). The multimeter is set to DC voltage and connected in parallel with the capacitor to measure V_C.

Procedure: First, close S₁ (and open S₂) to charge the capacitor to the desired voltage (e.g. 7.0 V to 12 V from the power supply). Check the multimeter reads the desired voltage. Then, simultaneously open S₁ and close S₂ to allow the capacitor to discharge through the resistor. Start the stopwatch at the moment S₂ is closed. Record the potential difference V shown on the multimeter at regular time intervals (every 10 s). Continue until V is too small to measure accurately. Record V and corresponding time t in a table.`,
  "phys-ocrb-h557-2023-p3::3(b)(i)": `Complete ln V column: at t = 20 s, ln(2.97) = 1.088 ≈ 1.09; at t = 30 s, ln(1.98) = 0.683 ≈ 0.68. Mathematical test for exponential decay: For V = V₀ e^(−t/RC), taking natural logs: ln V = ln V₀ − t/(RC). So ln V should be a linear function of t (a straight line with negative gradient). Check that ln V decreases linearly with t: ln V values: 1.946, 1.513, 1.088, 0.683, 0.300, −0.062. Differences between successive values (Δt = 10 s): 1.946 − 1.513 = 0.433; 1.513 − 1.088 = 0.425; 1.088 − 0.683 = 0.405; 0.683 − 0.300 = 0.383; 0.300 − (−0.062) = 0.362. The differences are approximately constant (around 0.4 per 10 s interval), consistent with a linear decrease in ln V with time, confirming exponential decay.`,
  "phys-ocrb-h557-2023-p3::3(b)(ii)": `The time constant τ = RC is the time for V to fall to 1/e of its initial value, i.e. to V₀/e = 7.00/e = 7.00/2.718 = 2.575 V. From the data, V ≈ 2.97 V at t = 20 s and V ≈ 1.98 V at t = 30 s. By interpolation, V = 2.575 V occurs between t = 20 s and t = 30 s. Alternatively, from the graph of ln V vs t, the gradient = −1/τ. Using two points: gradient ≈ (−0.062 − 1.946)/(50 − 0) = −2.008/50 = −0.04016 s⁻¹. τ = 1/0.04016 = 24.9 s ≈ 25 s. (Confirmed.)`,
  "phys-ocrb-h557-2023-p3::3(b)(iii)": `τ = RC = 25 s. C = τ/R = 25 / (4.7 × 10³) = 25 / 4700 = 5.32 × 10⁻³ F ≈ 5.3 × 10⁻³ F = 5.3 mF.`,
  "phys-ocrb-h557-2023-p3::3(c)(i)": `Energy stored in capacitor: E = ½CV². Since V = V₀ e^(−t/RC) = V₀ e^(−t/τ): E = ½C(V₀ e^(−t/τ))² = ½CV₀² × e^(−2t/τ) = E₀ e^(−2t/τ) where E₀ = ½CV₀². At t = 5τ: E = E₀ e^(−2 × 5τ/τ) = E₀ e^(−10). e^(−10) = 4.54 × 10⁻⁵ ≈ 4.5 × 10⁻⁵. Therefore E = 4.5 × 10⁻⁵ E₀. (Confirmed.)`,
  "phys-ocrb-h557-2023-p3::3(c)(ii)": `After a time of 5τ the energy left in the capacitor is only 4.5 × 10⁻⁵ of the energy it started with (about 0.005%), and the pd has fallen to less than 1% of V₀. The rule of thumb therefore gives an engineer a quick estimate of how long to wait before the charge, pd and stored energy remaining in the capacitor are negligible — for example before it is safe to handle the circuit, or before the capacitor can be treated as empty at the start of the next charging cycle.`,
  "phys-ocrb-h557-2023-p3::4(a)(i)": `Flux linkage NΦ = NBA, where N = 10, B = 5.0 × 10⁻³ T, A = π r² = π × (0.020)² = π × 4 × 10⁻⁴ = 1.2566 × 10⁻³ m². NΦ = 10 × 5.0 × 10⁻³ × 1.2566 × 10⁻³ = 10 × 6.283 × 10⁻⁶ = 6.283 × 10⁻⁵ Wb ≈ 6.3 × 10⁻⁵ Wb. (Confirmed.)`,
  "phys-ocrb-h557-2023-p3::4(a)(ii)": `The oscilloscope trace shows a sinusoidal (AC) waveform. This shape arises because as the coil rotates at constant angular velocity ω, the flux linkage through the coil varies sinusoidally: NΦ = NBAcosθ = NBAcos(ωt). By Faraday's law, the induced e.m.f. is ε = −d(NΦ)/dt = NBAω sin(ωt). Since sin(ωt) varies sinusoidally with time, the induced e.m.f. also varies sinusoidally, producing the sinusoidal trace seen on the oscilloscope. The amplitude of the e.m.f. is constant because the coil rotates at a constant rate (ω = constant, B = constant, N and A are constant).`,
  "phys-ocrb-h557-2023-p3::4(a)(iii)": `From Fig. 4.3, one complete cycle of the trace (peak to the next peak) occupies 8 horizontal divisions.
T = 8 × 0.625 = 5.0 s
f = 1/T = 1/5.0 = 0.20 Hz
ω = 2πf = 2π × 0.20 = 0.4π = 1.26 rad s⁻¹
Angular frequency ω = 1.26 rad s⁻¹ (2 s.f.).`,
  "phys-ocrb-h557-2023-p3::4(a)(iv)": `As the coil rotates, the angle θ between the normal to the plane of the coil and the magnetic field lines changes at a constant rate: θ = ωt (starting from θ = 0 when the normal is parallel to B). The magnetic flux through the coil at any instant is Φ = B × A × cos θ (the component of B perpendicular to the coil plane, multiplied by the area). Substituting θ = ωt: Φ = BA cos(ωt). Therefore the flux in the coil is given by Φ = BA cos ωt. (This result follows directly from the definition of magnetic flux: Φ = BA cosθ, with θ = ωt.)`,
  "phys-ocrb-h557-2023-p3::4(b)(i)": `When the number of turns is doubled to 20 (everything else unchanged), the maximum flux linkage doubles: NΦ_max = 20 × BA = 2 × 6.3 × 10⁻⁵ = 1.26 × 10⁻⁴ Wb. The maximum e.m.f. also doubles: ε₀_new = 2ε₀_old. The frequency (and hence period) of the trace is unchanged (same ω). On Fig. 4.5, draw a sinusoidal trace with the same period (same horizontal wavelength) as the original, but with double the amplitude (double the peak-to-peak height). The trace should have the same phase as the original.`,
  "phys-ocrb-h557-2023-p3::4(b)(ii)": `The induced emf is ε = −d(NΦ)/dt, so its size at t = 0.23 s is the gradient of the flux-linkage–time graph at that instant. The flux linkage is passing through zero there, so the curve is at its steepest.
Draw a tangent to the curve at the point (0.23 s, 0) and read two points off the tangent, for example (0.17 s, +8.0 × 10⁻⁶ Wb) and (0.29 s, −8.0 × 10⁻⁶ Wb):
gradient = Δ(NΦ)/Δt = (−8.0 × 10⁻⁶ − 8.0 × 10⁻⁶) / (0.29 − 0.17) = −16 × 10⁻⁶ / 0.12 = −1.3 × 10⁻⁴ Wb s⁻¹
emf = −d(NΦ)/dt = 1.3 × 10⁻⁴ V (about 0.13 mV).
Check: the peak flux linkage is 12.5 × 10⁻⁶ Wb and the first peak-to-trough interval is about 0.27 s, so T ≈ 0.54 s and ω ≈ 2π/0.54 ≈ 11.6 rad s⁻¹, giving ε_max = NΦ_max ω ≈ 12.5 × 10⁻⁶ × 11.6 ≈ 1.4 × 10⁻⁴ V, which agrees.`,
  "phys-ocrb-h557-2023-p3::4(b)(iii)": `How the suggestion can be tested
The peak emf produced in any one cycle is ε₀ = NΦ₀ω, where NΦ₀ is the amplitude of the flux linkage in that cycle and ω = 2π/T is the angular velocity of the coil. The peak emf can therefore be found in two equivalent ways from Fig. 4.6: directly, as the maximum gradient of the curve (the gradient where it crosses the time axis), or indirectly from the amplitude and the period of that cycle. If the peak emf really falls by the same fraction each cycle, then the ratio of the peak emfs of one cycle to the next must come out the same for every pair of cycles. So I need the same measurement taken at equivalent points in all three cycles, and then the ratios between successive values.

Readings taken from Fig. 4.6
The peaks are at t = 0.10 s, 0.70 s and 1.62 s and the troughs at t = 0.37 s, 1.11 s and 2.24 s. Every peak reaches +12.5 × 10⁻⁶ Wb and every trough −12.5 × 10⁻⁶ Wb, so the amplitude of the flux linkage stays constant at NΦ₀ = 12.5 × 10⁻⁶ Wb; it is only the period that changes as the coil slows down.
Taking the peak-to-trough interval of each cycle, which is half a period:
cycle 1: 0.37 − 0.10 = 0.27 s, so T₁ = 0.54 s
cycle 2: 1.11 − 0.70 = 0.41 s, so T₂ = 0.82 s
cycle 3: 2.24 − 1.62 = 0.62 s, so T₃ = 1.24 s

Carrying out the test
ω₁ = 2π/0.54 = 11.6 rad s⁻¹, ω₂ = 2π/0.82 = 7.66 rad s⁻¹, ω₃ = 2π/1.24 = 5.07 rad s⁻¹
ε₁ = 12.5 × 10⁻⁶ × 11.6 = 1.45 × 10⁻⁴ V
ε₂ = 12.5 × 10⁻⁶ × 7.66 = 9.6 × 10⁻⁵ V
ε₃ = 12.5 × 10⁻⁶ × 5.07 = 6.3 × 10⁻⁵ V
Ratios of successive peak emfs: ε₂/ε₁ = 9.6/14.5 = 0.66 and ε₃/ε₂ = 6.3/9.6 = 0.66.
Because the amplitude is the same in every cycle this is identical to comparing the periods: T₁/T₂ = 0.54/0.82 = 0.66 and T₂/T₃ = 0.82/1.24 = 0.66. The value of ε₁ also agrees with the 1.3 × 10⁻⁴ V obtained from the maximum gradient of the graph at t = 0.23 s in (b)(ii), which confirms the method.

Conclusion
The two ratios are the same, 0.66 in each case, so the data support the suggestion: the peak emf falls by the same fraction (about one third is lost, leaving about 66%) in every cycle. This is what is expected if the resistive torque slowing the coil is proportional to its angular velocity, since ω, and hence the peak emf, then decays exponentially. The test is limited by the fact that only three cycles are shown and the peak and trough times can only be read to about ±0.02 s, giving the ratios an uncertainty of roughly ±5%; a trace covering more cycles would make the conclusion firmer.`,
  "phys-ocrb-h557-2024-p1::31(a)": `The alternating current in the primary coil produces a continuously changing magnetic field around the primary coil. This changing magnetic field passes through the iron core and links with the secondary coil. By Faraday's law of electromagnetic induction, the changing magnetic flux through the secondary coil induces an alternating e.m.f. in the secondary coil. Because the flux is alternating (continuously changing direction and magnitude), the induced e.m.f. is also alternating, which drives an alternating current in any circuit connected to the secondary coil.`,
  "phys-ocrb-h557-2024-p1::31(b)": `Secondary current: V_s = 50 V, R = 800 Ω, so I_s = V_s / R = 50 / 800 = 0.0625 A ≈ 0.063 A.

Primary current: Using the transformer power equation (assuming 100% efficiency): V_p × I_p = V_s × I_s, so I_p = (V_s × I_s) / V_p = (50 × 0.0625) / 20 = 3.125 / 20 = 0.156 A ≈ 0.16 A.

Primary current = 0.16 A; Secondary current = 0.063 A.`,
  "phys-ocrb-h557-2024-p1::32(a)": `Reading Fig. 32.1 at each sampling time and rounding to the nearest millivolt:

Time 4 ms: signal level 1 mV, digitised 001
Time 5 ms: signal level 0 mV, digitised 000
Time 6 ms: signal level 1 mV, digitised 001

On Fig. 32.2, add the three points (4 ms, 1 mV), (5 ms, 0 mV) and (6 ms, 1 mV) to the four already plotted. The reconstructed signal is then drawn as a staircase through all seven points: each sampled level is held constant for the whole millisecond until the next sample is taken, giving steps at 2, 4, 5, 4, 1, 0 and 1 mV.`,
  "phys-ocrb-h557-2024-p1::32(b)": `Two separate things go wrong.

First, the sampling rate is too low. The signal in Fig. 32.3 contains a rapid oscillation with a period of only about 0.5 ms, i.e. a frequency of about 2 kHz, but the students take only one sample every millisecond (1 kHz). The sampling rate is therefore less than twice the highest frequency present in the signal: there is less than one sample per cycle, so whole oscillations happen between consecutive samples and are lost completely.

Second, there are not enough quantisation levels. The levels are 1 mV apart, but much of the detail in this signal consists of variations of only a few tenths of a millivolt between one peak and the next. Those differences are smaller than the spacing of the levels, so they are rounded away and cannot be recovered.

For both reasons the reconstructed signal cannot follow the original.`,
  "phys-ocrb-h557-2024-p1::33(a)": `Using s = ½at²: a = 2s / t² = (2 × 0.75) / (0.41)² = 1.50 / 0.1681 = 8.9 m s⁻² (2 s.f.).`,
  "phys-ocrb-h557-2024-p1::33(b)": `From s = ½gt², rearranging gives t² = (2/g)s. This is a linear equation of the form t² = (2/g)s, so a graph of t² against s gives a straight line through the origin with gradient = 2/g. The acceleration due to gravity is therefore found from g = 2 / gradient, where the gradient is measured from the best-fit straight line drawn through the plotted points.`,
  "phys-ocrb-h557-2024-p1::34(a)": `Frequencies: one complete cycle of signal 1 occupies 2 divisions, so its period is 2 × 50 = 100 ms and f₁ = 1/0.100 = 10 Hz. One complete cycle of signal 2 occupies 1 division, so its period is 50 ms and f₂ = 1/0.050 = 20 Hz. The frequency of signal 1 is therefore half the frequency of signal 2.

Amplitudes: signal 1 rises 3 divisions from the centre line to its peak, so its peak potential difference is 3 × 0.2 = 0.6 V. Signal 2 rises only 1 division, so its peak potential difference is 1 × 0.2 = 0.2 V. The peak potential difference of signal 1 is three times that of signal 2.`,
  "phys-ocrb-h557-2024-p1::34(b)": `On Fig. 34.3 the resistor trace rises 3 squares from the centre line to its peak, and the peak p.d. across the resistor is 6 V, so one square on the vertical scale represents 2 V. One complete cycle of the resistor trace occupies 6 squares horizontally.

Draw a smooth sine curve, by eye, for the p.d. across X with:
• an amplitude of 2 squares, since its peak value is 4 V – two thirds of the height of the resistor trace;
• exactly the same period as the resistor trace, one cycle every 6 squares, drawn right across the grid (at least three quarters of a cycle must be shown);
• its whole trace shifted sideways by a quarter of a cycle, which is about 1.5 squares, relative to the resistor trace – either to the left (leading) or to the right (lagging), since a phase difference of π/2 either way fits the description.

So where the resistor trace has its positive peak, the new curve should be crossing the centre line, and its own peak should lie 1.5 squares before (or after) that point.`,
  "phys-ocrb-h557-2024-p1::35(a)": `The Boltzmann factor is e^(−E/kT), where E is the energy needed to break one H–H bond, so at T = 1000 K

e^(−E/kT) = 1.64 × 10⁻²³
E = −kT ln(1.64 × 10⁻²³) = −(1.38 × 10⁻²³ × 1000) × (−52.46)
E = 7.24 × 10⁻¹⁹ J for one molecule

One mole contains N_A = 6.02 × 10²³ molecules, each with one H–H bond, so

energy per mole = 7.24 × 10⁻¹⁹ × 6.02 × 10²³
energy = 4.36 × 10⁵ J (about 436 kJ mol⁻¹)`,
  "phys-ocrb-h557-2024-p1::35(b)": `The molecules do not all have the same energy. Their energies are spread over a wide distribution about the mean, so even at 300 K, where the average energy is well below the bond energy, a small fraction of molecules at any instant have far more than the average.

The gas also contains an enormous number of molecules, and each one makes a very large number of collisions every second. Energy is shared out at random in these collisions, so a molecule can gain energy in one collision after another until it has more than enough to break an H–H bond. Because the number of collisions per second is so large, the tiny fraction that reach the bond-breaking energy still amounts to a great many molecules every second, and the reaction proceeds at a reasonable rate.`,
  "phys-ocrb-h557-2024-p1::36(a)(i)": `Fig. 36.1 is a straight line through the origin, so the wire obeys Hooke's law and the stiffness is the gradient of the load–extension line.

Using a large triangle from the origin to a point near the top of the line, a load of 29 N produces an extension of 15.2 × 10⁻⁴ m:

k = F/x = 29 / (15.2 × 10⁻⁴)
k = 1.9 × 10⁴ N m⁻¹`,
  "phys-ocrb-h557-2024-p1::36(a)(ii)": `The load on the wire is 10 N, so the suspended mass is
m = F/g = 10/9.81 = 1.02 kg

and the stiffness of the wire from (i) is k = 1.9 × 10⁴ N m⁻¹.

For a mass oscillating on a spring-like support,
T = 2π√(m/k) = 2π√((10/9.81)/(1.9 × 10⁴))
= 2π√(5.37 × 10⁻⁵) = 2π × 7.33 × 10⁻³

T = 4.6 × 10⁻² s`,
  "phys-ocrb-h557-2024-p1::36(a)(iii)": `The wire oscillations are simple harmonic because the wire obeys Hooke's law throughout the range of oscillation: the restoring force is directly proportional to the displacement from equilibrium (F = –kx), which is the definition of SHM. The rubber strip does not obey Hooke's law — from Fig. 36.2 the force–extension graph is non-linear (the rubber becomes stiffer at larger extensions). Therefore the restoring force is not proportional to displacement, so the oscillations of the rubber strip are not simple harmonic.`,
  "phys-ocrb-h557-2024-p1::36(b)": `Structure of a metal alloy. A metal consists of positive ions packed in a regular three-dimensional lattice, held together by a sea of delocalised electrons, so the bonding is strong in every direction. In an alloy, some sites in the lattice are occupied by atoms of a different size, and these impurity atoms distort the regular planes of ions. They act as obstacles that prevent whole planes of ions from sliding over one another, so the alloy cannot deform plastically to any great extent: it is very stiff, and it is brittle rather than ductile.

Structure of a polymer such as rubber. Rubber is built from very long chain molecules, each a long sequence of repeated monomer units, with occasional cross-links between neighbouring chains. When the strip is not under tension the chains are curled up and tangled together, so the strip is far shorter than the stretched-out length of its chains. The bonds along each chain are strong covalent bonds, but very little force is needed simply to uncoil and untangle a chain, and the chains coil up again when the load is removed, so the deformation is elastic.

Shape of Fig. 36.1. Because the planes of ions in the alloy cannot slip, loading the wire can only pull the planes slightly further apart. For these small displacements the increase in the separation of the planes is proportional to the force applied, so the extension is proportional to the load and the graph is a straight line through the origin, with a steep gradient because the metallic bonds are stiff. The line stays straight all the way to 16 × 10⁻⁴ m, where the force becomes large enough to pull the planes of ions apart completely and the wire fractures – there is no curved, plastic region first, which is what makes the alloy brittle.

Shape of Fig. 36.2. For the rubber the graph is a curve, not a straight line, because the extension is not produced in the same way. Over the middle of the range the line is comparatively shallow: here the load is doing little more than straightening and untangling the coiled chains, so a small increase in load produces a relatively large extension and the stiffness is low. Once the chains have been pulled straight and aligned along the direction of the load, any further extension has to stretch the strong covalent bonds within the chains themselves, so a much larger increase in load is needed for the same extra extension and the curve turns sharply upwards at the largest extensions. The rubber therefore has a stiffness that changes with extension, which is why its graph is curved, while the alloy's is straight.`,
  "phys-ocrb-h557-2024-p1::37(a)": `Both strings are fixed at the same two kinds of end and oscillate in the same mode at the same frequency, so the length of the vibrating section is proportional to the wavelength:

L₂/L₁ = λ₂/λ₁ = v₂/v₁  (because f is the same for both)

The strings have the same tension T, and v = √(T/μ), so

v₂/v₁ = √(μ₁/μ₂)

The strings are made of the same material, so the mass per unit length is proportional to the cross-sectional area and hence to the square of the diameter: μ ∝ d². Therefore

v₂/v₁ = √(d₁²/d₂²) = d₁/d₂ = 1/1.4 = 0.714

L₂ = 0.714 × L₁ = 0.714 × 0.18
length = 0.13 m`,
  "phys-ocrb-h557-2024-p1::37(b)(i)": `At the first resonance, the air column contains a quarter wavelength: L = λ/4, so λ = 4L.
Assumption: the end correction C is negligibly small (C ≈ 0), so L ≈ 17.0 cm = 0.170 m.
λ = 4 × 0.170 = 0.680 m
v = fλ = 440 × 0.680 = 299 m s⁻¹ ≈ 300 m s⁻¹ ✓

Assumption stated: the end correction at the open end of the tube is assumed to be zero.`,
  "phys-ocrb-h557-2024-p1::37(b)(ii)": `Draw a large triangle on the line of best fit, using more than half the range of L. The line passes through the points (0.17 m, 0.00228 s) and (0.31 m, 0.00392 s):

gradient = (0.00392 − 0.00228)/(0.31 − 0.17) = 0.00164/0.14 = 0.0117 s m⁻¹

The gradient is 4/v, so

v = 4/gradient = 4/0.0117
v = 3.4 × 10² m s⁻¹ (about 340 m s⁻¹)`,
  "phys-ocrb-h557-2024-p1::37(b)(iii)": `At resonance in a closed tube with one open end, there is a node at the closed (water) end and an antinode at the open end. The simplest resonance (fundamental) corresponds to a quarter wavelength fitting in the tube: L + C = λ/4, where C is the end correction.
Rearranging: λ = 4(L + C).
Since v = fλ: v = f × 4(L + C), so 1/f = 4(L + C)/v = (4/v)L + 4C/v.
This is a linear equation in L with gradient 4/v and intercept 4C/v. Therefore the gradient of the 1/f against L graph equals 4/v.`,
  "phys-ocrb-h557-2024-p1::37(b)(iv)": `There are several real advantages. A signal generator and loudspeaker produce a note of constant amplitude that continues for as long as it is needed, whereas the note from a struck tuning fork dies away within a few seconds; this gives far more time to raise the tube slowly and judge the length at which the sound is loudest, so L at resonance can be found more precisely. The note from a loudspeaker can also be made much louder than that from a tuning fork, so the resonance peak stands out more clearly and is easier to identify. In addition, the frequency of a signal generator can be set anywhere in a continuous range, rather than to the handful of values available from a set of forks, so many more points can be plotted and the line of best fit – and hence the gradient and v – is better defined.

Against this, a tuning fork has its frequency stamped on it and is accurate, whereas the frequency indicated on a signal generator dial may itself be in error, so the uncertainty in f could be larger unless the frequency is checked with an oscilloscope or frequency meter. Provided that check is made, the loudspeaker method does give the more reliable determination of the speed of sound.`,
  "phys-ocrb-h557-2024-p1::38(a)(i)": `The nitrogen is compressed at constant temperature, so Boyle's law applies, and because the volume is the cross-sectional area times the length, the volume is proportional to l:

p₁l₁ = p₂l₂
p₂ = p₁l₁/l₂ = 170 × 10.0/3.0 = 567 kPa

The rise in pressure is produced by the extra force on the piston, which is the weight of the person:

mg = (p₂ − p₁) × A = (567 − 170) × 10³ × 15.0 × 10⁻⁴
mg = 397 × 10³ × 1.50 × 10⁻³ = 596 N

m = 596/9.81 = 60.7 kg

which is about 61 kg, as required.`,
  "phys-ocrb-h557-2024-p1::38(a)(ii)": `The same person is sitting on the chair, so the force on the piston is unchanged and the pressure of the trapped nitrogen is the same as before. The gas is therefore warmed at constant pressure, and since its volume is proportional to the length of the cylinder, l/T is constant:

l₁/T₁ = l₂/T₂, with T₁ = 18 + 273 = 291 K and T₂ = 30 + 273 = 303 K

3.0/291 = l₂/303
l₂ = 3.0 × 303/291 = 3.12 cm

length of cylinder = 0.031 m`,
  "phys-ocrb-h557-2024-p1::38(b)(i)": `Read the graph at 30 °C: the measured volume there is 61 cm³.

The gas syringe measures to the nearest 1 cm³, so the uncertainty in the volume is 1 cm³:
percentage uncertainty in volume = (1/61) × 100% = 1.6%

The thermometer measures to the nearest 1 °C, so the uncertainty in the temperature is 1 °C:
percentage uncertainty in temperature = (1/30) × 100% = 3.3%`,
  "phys-ocrb-h557-2024-p1::38(b)(ii)": `For a fixed mass of gas at constant pressure the volume is proportional to the absolute temperature, so the straight line of V against the Celsius temperature θ reaches V = 0 at absolute zero. Extrapolating the line of best fit back to V = 0 therefore gives a value for absolute zero.

Use a large triangle on the line of best fit, taking two widely separated points on it, (30 °C, 61.4 cm³) and (80 °C, 71.9 cm³):

gradient = (71.9 − 61.4)/(80 − 30) = 10.5/50 = 0.21 cm³ °C⁻¹

Intercept on the volume axis: c = 61.4 − (0.21 × 30) = 55 cm³, so the equation of the line is
V = 0.21θ + 55

Putting V = 0 and solving for θ:
θ = −55/0.21

absolute zero of temperature = −260 °C (compared with the accepted value of −273 °C)`,
  "phys-ocrb-h557-2024-p1::39(a)": `Unstable nucleus: A nucleus is unstable when the combination of neutrons and protons in the nucleus results in a configuration that has excess energy compared to a more stable arrangement. The nuclear forces and electrostatic repulsion are not balanced in a way that gives minimum energy, so the nucleus has a tendency to decay by emitting a particle or gamma radiation to reach a more stable (lower energy) state.

Random process: Radioactive decay is random in the sense that it is impossible to predict which particular nucleus in a sample will decay next, or exactly when any individual nucleus will decay. Each nucleus has a fixed, constant probability of decaying per unit time, regardless of the age of the nucleus or external conditions (temperature, pressure, chemical state).`,
  "phys-ocrb-h557-2024-p1::39(b)": `Both nuclides emit alpha particles, and alpha particles are very strongly ionising, so they do a great deal of damage to living cells over the very short distance they travel.

The alpha particles from the thorium in the rod, however, are very unlikely ever to reach living tissue. They have a range of only a few centimetres in air and do not have enough energy to penetrate even the dead outer layer of the skin. The thorium is locked in a solid rod that the welder picks up only occasionally, and wearing gloves and an apron prevents any thorium dust from contaminating the skin. The hazard from the thorium is therefore small.

The radon-220 is far more dangerous because it is a gas. It escapes from the rod, mixes with the air in the workshop and can be breathed in, and gloves and an apron give no protection against that; a mask will not stop it either unless it is airtight. Once radon is inside the lungs there is nothing to absorb the alpha particles before they reach tissue, so they deposit their energy directly in sensitive lung cells.

Two things reduce the radon risk: its half-life is only 55 s, so much of it decays before it can be inhaled, and because radon is produced from thorium with a half-life of 1.4 × 10¹⁰ years, the rate at which it is made is extremely small. Even so, the risk of internal irradiation from inhaled radon is the more serious of the two, especially in a poorly ventilated workshop.`,
  "phys-ocrb-h557-2024-p1::39(c)(i)": `The rate of emission of alpha particles equals the activity A = λN, where N is the number of radon-220 atoms present and λ is the decay constant. Since each alpha particle causes a fixed average amount of ionisation in the chamber, the ionisation current is proportional to the activity, which is proportional to N. Therefore the ionisation current is proportional to the number of radon-220 atoms remaining.`,
  "phys-ocrb-h557-2024-p1::39(c)(ii)": `Completing the table:
Time 140 s: ln(0.13 × 10⁻¹²) = ln(1.3 × 10⁻¹³) = ln(1.3) + ln(10⁻¹³) = 0.262 − 29.934 = −29.67 (approximately −29.67)
Time 160 s: ln(0.10 × 10⁻¹²) = ln(1.0 × 10⁻¹³) = 0 − 29.934 = −29.93 (approximately −29.93)

Plotting ln(I) against time: the points should form a straight line (since I = I₀e^(−λt), so ln(I) = ln(I₀) − λt). Plot all data points including the two completed values and draw a line of best fit.

To find the half-life: the gradient of the line = −λ.
Using two points on the best-fit line, e.g. at t = 0, ln(I) = −27.81 and at t = 160 s, ln(I) = −29.93:
gradient = (−29.93 − (−27.81)) / (160 − 0) = −2.12 / 160 = −0.01325 s⁻¹
λ = 0.01325 s⁻¹
t₁/₂ = ln2 / λ = 0.693 / 0.01325 = 52 s ≈ 52 s.

The graph gives a value closer to 55 s than the student's method because the graph uses all the data points to find the best-fit line, averaging out random experimental errors. The student's method uses only two readings and is therefore more susceptible to random errors in individual measurements. The graphical method is more reliable because it is based on the overall trend of all data.`,
  "phys-ocrb-h557-2024-p1::40(a)(i)": `Electrons are accelerated through a potential difference of V. Using energy conservation:
eV = ½mv²
v = √(2eV/m) = √(2 × 1.60 × 10⁻¹⁹ × 1000 / 9.11 × 10⁻³¹)
= √(3.20 × 10⁻¹⁶ / 9.11 × 10⁻³¹)
= √(3.513 × 10¹⁴)
= 1.87 × 10⁷ m s⁻¹ ≈ 1.9 × 10⁷ m s⁻¹ ✓

(Accelerating voltage assumed to be 1.0 kV = 1000 V from context.)`,
  "phys-ocrb-h557-2024-p1::40(a)(ii)": `The magnetic field is at right angles to the velocity of the electrons, so the magnetic force BQv on each electron is always perpendicular to its velocity. It therefore acts as a centripetal force and the beam follows a circular path (an arc of a circle) while it is in the field region.

The field is directed into the page and the electrons travel across the page. Applying Fleming's left-hand rule, remembering that the conventional current is in the opposite direction to the motion of the electrons, the force on the beam is towards the bottom of the page, so the beam is deflected towards the bottom of the page.

For the radius of the arc:
Bev = mv²/r, so r = mv/(Be)
r = (9.11 × 10⁻³¹ × 1.9 × 10⁷) / (20 × 10⁻³ × 1.60 × 10⁻¹⁹)
r = 1.73 × 10⁻²³ / 3.2 × 10⁻²¹

r = 5.4 × 10⁻³ m

The radius is only about 5 mm, so the beam curves very sharply, and it leaves the field region travelling along the tangent to the arc at the point where it emerges.`,
  "phys-ocrb-h557-2024-p1::40(b)": `For the beam to continue in a straight line, the electric force on each electron must balance the magnetic force on it:

Ee = Bev, so E = Bv

The field between two parallel plates a distance d apart is E = V/d, so

V = Bvd = 0.020 × 1.9 × 10⁷ × 0.040

potential difference = 1.5 × 10⁴ V (15 000 V)`,
  "phys-ocrb-h557-2024-p1::40(c)": `The plates and the magnetic field act as a velocity selector: the beam goes straight through when the electric force balances the magnetic force, so

qE = qvB, giving v = E/B

The field between the plates is
E = V/d = 120/0.040 = 3000 V m⁻¹

so the speed of the ions is
v = E/B = 3000/0.020 = 1.5 × 10⁵ m s⁻¹

Each ion was accelerated from rest through 1.0 kV, so the work done on it, qV, all becomes kinetic energy:

½mv² = qV = 1000q
q/m = v²/(2 × 1000) = (1.5 × 10⁵)²/2000 = 2.25 × 10¹⁰/2000

q/m = 1.1 × 10⁷ C kg⁻¹ (1.125 × 10⁷ C kg⁻¹)`,
  "phys-ocrb-h557-2024-p2::1(a)(i)": `On the parasail the rope pulls back towards the boat, at 32° to the horizontal, so the tension has a downward vertical component.

vertical component = T sin 32° = 550 × sin 32° = 550 × 0.5299

vertical component = 291 N (directed downwards, towards the boat)`,
  "phys-ocrb-h557-2024-p2::1(a)(ii)": `The parasailor and sail travel at constant velocity, so the vertical forces on them are balanced.

The rope pulls them downwards with the 291 N found in (a)(i), and their weight of 870 N also acts downwards, so the upward force must balance both:

vertical upwards force = 870 + 291 = 1160 N (3 s.f.)`,
  "phys-ocrb-h557-2024-p2::1(a)(iii)": `Horizontal component of the tension:

F = T cos 32° = 550 × cos 32° = 466 N

Reasoning: the parasailor moves at constant horizontal velocity, so there is no acceleration and therefore no resultant horizontal force. The drag force on the parasailor and sail must therefore be equal in magnitude to the 466 N horizontal pull of the rope, and the power needed is the rate at which work is done against that drag.

power = Fv = 466 × 5.8 = 2700 W (2.7 kW)`,
  "phys-ocrb-h557-2024-p2::1(b)": `Extension of the rope:
Cross-sectional area: A = π(d/2)² = π(0.006)² = π × 3.6 × 10⁻⁵ = 1.131 × 10⁻⁴ m²
Young modulus: E = stress/strain = (F/A)/(ΔL/L)
ΔL = FL/(EA) = (550 × 240) / (13.2 × 10⁹ × 1.131 × 10⁻⁴)
= 132 000 / (1.493 × 10⁶)
= 0.0884 m ≈ 0.088 m (8.8 cm)`,
  "phys-ocrb-h557-2024-p2::1(c)": `When the parasail moves at a greater constant horizontal velocity, the air drag on the sail increases (drag is proportional to v²). For the parasailor and sail to remain in equilibrium at the higher speed, a greater horizontal component of tension is required to balance the increased drag. Therefore the tension in the rope will increase above 550 N.`,
  "phys-ocrb-h557-2024-p2::2(a)": `Best-fit line: draw one straight ruled line through the eight points, starting from the origin (0.0, 0.0) and passing close to the highest point at (0.80, 1.27), with roughly equal numbers of points lying just above and just below it.

Gradient: take two points on the line separated by more than half the range of the data, for example (0.10, 0.17) and (0.80, 1.27):

gradient = (1.27 − 0.17) / (0.80 − 0.10) = 1.10 / 0.70

gradient = 1.6 V m⁻¹ (2 s.f.)`,
  "phys-ocrb-h557-2024-p2::2(b)": `For a length L of the nichrome wire, V = IR and R = ρL/A, so V = (Iρ/A)L. The gradient of the p.d.–L graph is therefore Iρ/A, and

ρ = gradient × A / I

Cross-sectional area: A = π(d/2)² = π × (2.6 × 10⁻⁴)² = 2.12 × 10⁻⁷ m²

ρ = 1.6 × 2.12 × 10⁻⁷ / 0.29

ρ = 1.17 × 10⁻⁶ Ω m`,
  "phys-ocrb-h557-2024-p2::2(c)": `Percentage uncertainty in the diameter = (0.1 × 10⁻⁴ / 5.2 × 10⁻⁴) × 100 = 1.9%

The area depends on d², so the percentage uncertainty in A = 2 × 1.9 = 3.8%

Percentage uncertainty in the current = (0.01 / 0.29) × 100 = 3.4%

Since ρ = gradient × A / I, these percentage uncertainties add:

total percentage uncertainty = 3.8 + 3.4 = 7.3%

absolute uncertainty = 0.073 × 1.17 × 10⁻⁶ = ± 0.09 × 10⁻⁶ Ω m

so ρ = (1.17 ± 0.09) × 10⁻⁶ Ω m.`,
  "phys-ocrb-h557-2024-p2::2(d)": `With the current no longer controlled it is larger at the shorter lengths, so more power is dissipated in the wire and the wire runs hotter for the short lengths than for the long ones.

The resistivity of a metal increases with temperature, so the resistance of a given length of the wire is larger than it would have been at the controlled current, and a larger p.d. is recorded for that length.

The extra p.d. is greatest at the short lengths and negligible at the long ones, so the points at small L are lifted above the original straight line. The graph is no longer a straight line through the origin: it rises steeply at first and then bends over, becoming a curve of (slightly) decreasing gradient.`,
  "phys-ocrb-h557-2024-p2::3(a)": `At the equilibrium position the upward force from the spring balances the weight of the mass:

kx = mg

x = mg / k = (0.25 × 9.81) / 23.0 = 2.4525 / 23.0

x = 0.107 m, which is about 0.11 m as required.`,
  "phys-ocrb-h557-2024-p2::3(b)(i)": `Fig. 3.1 is a straight line. The resultant force is zero at the equilibrium extension of about 0.107 m; for smaller extensions the resultant force is positive (downwards) and for larger extensions it is negative (upwards). So the graph shows that the resultant force is proportional to the displacement from the equilibrium position and is always directed back towards it, i.e. F ∝ −s.

Since F = ma, the acceleration is also proportional to the negative of the displacement from equilibrium, a ∝ −s, and that is the defining condition for simple harmonic motion. The line stays straight for displacements of at least 0.11 m on either side of the equilibrium position, so the mass will oscillate with simple harmonic motion for any amplitude up to about 0.11 m — including the 0.03 m amplitude used here.`,
  "phys-ocrb-h557-2024-p2::3(b)(ii)": `For oscillations with amplitude greater than 0.11 m, the mass moves upward by more than the equilibrium extension, meaning the spring would be compressed or would become slack (zero extension). Once the spring goes slack, there is no spring force, only gravity. The restoring force is no longer proportional to displacement — it cannot follow F = −kx beyond this point. Since the force–displacement relationship is no longer linear, the motion is not SHM.`,
  "phys-ocrb-h557-2024-p2::3(c)": `frequency = 1.5 Hz

Reasoning: the amplitude is greatest at resonance, which occurs when the driving frequency of the vibration generator is equal to the natural frequency of the mass–spring system, because energy is then transferred to the oscillator most readily.

Natural frequency of the system:

f₀ = (1/2π)√(k/m) = (1/2π)√(23.0 / 0.25) = (1/2π)√92.0 = 9.59 / 6.28

f₀ = 1.5 Hz

This lies inside the 0.1 Hz to 3.0 Hz range of the generator, so the greatest amplitude will be seen at a driving frequency of about 1.5 Hz.`,
  "phys-ocrb-h557-2024-p2::3(d)": `Treating the hydrogen atom as a mass on the end of a spring of spring constant 550 N m⁻¹, the natural frequency of vibration of the molecule is

f₀ = (1/2π)√(k/m) = (1/2π)√(550 / 1.7 × 10⁻²⁷) = (1/2π)√(3.24 × 10²⁹) = (1/2π) × 5.69 × 10¹⁴

f₀ = 9.1 × 10¹³ Hz

The frequency of infrared radiation of wavelength 3.3 × 10⁻⁶ m is

f = c/λ = 3.0 × 10⁸ / 3.3 × 10⁻⁶ = 9.1 × 10¹³ Hz

The two frequencies are equal, so this radiation drives the molecule at its natural frequency and the molecule resonates. Energy is transferred to the oscillating molecule far more readily at resonance than at any other frequency, so infrared of this wavelength is absorbed much more strongly than other wavelengths.`,
  "phys-ocrb-h557-2024-p2::4(a)": `At points where the path difference from the two (or multiple) slits is a whole number of wavelengths (nλ, where n = 0, 1, 2, ...), the waves arrive in phase. Waves that are in phase interfere constructively, meaning the amplitudes add together, producing a bright spot (maximum intensity). Between these maxima, the path difference is not a whole number of wavelengths, so the waves are not in phase and interfere partially or completely destructively, producing dark regions. This alternating pattern of constructive interference (bright dots) and destructive interference produces a series of bright dots across the screen.`,
  "phys-ocrb-h557-2024-p2::4(b)(i)": `Grating spacing: d = 1 / (300 × 10³ m⁻¹) = 1/300 000 = 3.333 × 10⁻⁶ m
Using the grating equation: d sin θ = nλ
For n = 3: sin θ = 3λ/d = (3 × 175 × 10⁻⁹) / (3.333 × 10⁻⁶)
= (5.25 × 10⁻⁷) / (3.333 × 10⁻⁶) = 0.1575
θ = arcsin(0.1575) = 9.06° ≈ 9.1°`,
  "phys-ocrb-h557-2024-p2::4(b)(ii)": `For the maximum order: sin θ ≤ 1, so nλ/d ≤ 1, giving n ≤ d/λ.
n_max = d/λ = (3.333 × 10⁻⁶) / (175 × 10⁻⁹) = 19.05
Since n must be a whole number, n_max = 19.
The highest order of maximum produced is the 19th order.`,
  "phys-ocrb-h557-2024-p2::4(b)(iii)": `Work function: φ = 4.3 eV = 4.3 × 1.60 × 10⁻¹⁹ = 6.88 × 10⁻¹⁹ J
Frequency: f = c/λ = (3.00 × 10⁸) / (175 × 10⁻⁹) = 1.714 × 10¹⁵ Hz
Photon energy: hf = 6.63 × 10⁻³⁴ × 1.714 × 10¹⁵ = 1.136 × 10⁻¹⁸ J
E_k(max) = hf − φ = 1.136 × 10⁻¹⁸ − 6.88 × 10⁻¹⁹
= 1.136 × 10⁻¹⁸ − 0.688 × 10⁻¹⁸
= 4.48 × 10⁻¹⁹ J ≈ 4.5 × 10⁻¹⁹ J

In eV: E_k(max) = hf/e − φ/e = (1.136 × 10⁻¹⁸)/(1.60 × 10⁻¹⁹) − 4.3 = 7.10 − 4.3 = 2.8 eV`,
  "phys-ocrb-h557-2024-p2::4(b)(iv)": `Explanation using photon model: Light consists of photons, each carrying a discrete energy E = hf. One photon interacts with one electron; the photon's energy is transferred entirely to the electron. The kinetic energy of the ejected electron equals the photon energy minus the work function: E_k = hf − φ. Since each photon has the same energy (determined only by frequency f, not intensity), all ejected electrons have the same maximum kinetic energy regardless of intensity. Increasing intensity means more photons per unit time but each photon still has the same energy hf, so the maximum kinetic energy of ejected electrons remains unchanged.

Effect of increasing intensity: Increasing the intensity increases the number of photons hitting the surface per second. Since each photon can eject one electron (provided hf > φ), more photons result in more electrons being ejected per second — the photocurrent increases. However, the maximum kinetic energy of each individual ejected electron remains the same, because E_k(max) depends only on frequency, not on the number of photons.`,
  "phys-ocrb-h557-2024-p2::4(c)": `A wave-only model cannot explain the ejection of the electrons. In that model the energy arriving is spread continuously over the whole zinc surface, so an electron would have to accumulate energy gradually and the energy it gained would depend on the intensity of the light and on how long the surface was illuminated. Light of low intensity would then still eject electrons after a delay, and the maximum kinetic energy would increase with intensity — neither of which happens, and the existence of a threshold frequency cannot be explained at all.

A particle-only model cannot explain how the light gets to the zinc in the first place. Classical particles travel in straight lines and do not diffract or superpose, so a stream of particles passing through the grating could not be redistributed into a set of maxima, and there would be no third order maximum at which to place the zinc surface.

The phasor model accounts for both. Light is delivered in photons, but the chance of a photon arriving at a particular point is found by adding the phasors for every possible path from the source to that point. At the angle of the third order maximum the phasors for the paths through successive slits arrive in phase and add to give a large resultant amplitude, while at other angles they curl round and cancel. The probability of a photon arriving is proportional to the square of the resultant phasor amplitude, so photons do arrive in large numbers at the position of the zinc surface. Each of those photons still carries a single quantum of energy hf, which is larger than the work function of zinc, so one photon can be absorbed by one electron and eject it. Diffraction and photoemission are then explained by the same model.`,
  "phys-ocrb-h557-2024-p2::5(a)": `An alpha particle with a smaller aiming error x passes closer to the nucleus than the particle shown in Fig. 5.1. At a smaller aiming error, the alpha particle approaches the nucleus more closely, so it experiences a stronger Coulomb repulsive force (since F ∝ 1/r²). The impulse (change in momentum) delivered by the repulsive force is greater, deflecting the alpha particle through a larger angle. Therefore, the deflection angle for a smaller aiming error is greater than θ. In the limiting case of x = 0, the alpha particle travels directly towards the nucleus and is deflected through 180°.`,
  "phys-ocrb-h557-2024-p2::5(b)(i)": `At the distance of nearest approach r₀, all the kinetic energy of the alpha particle has been converted to electrical potential energy:
E_k = k × q₁q₂ / r₀
r₀ = k × q₁q₂ / E_k

Charge of alpha particle: q_α = 2e = 2 × 1.60 × 10⁻¹⁹ = 3.20 × 10⁻¹⁹ C
Charge of silver nucleus (Z = 47): q_Ag = 47e = 47 × 1.60 × 10⁻¹⁹ = 7.52 × 10⁻¹⁸ C
E_k = 4.5 MeV = 4.5 × 10⁶ × 1.60 × 10⁻¹⁹ = 7.20 × 10⁻¹³ J
k = 1/(4πε₀) = 8.99 × 10⁹ N m² C⁻²

r₀ = (8.99 × 10⁹ × 3.20 × 10⁻¹⁹ × 7.52 × 10⁻¹⁸) / (7.20 × 10⁻¹³)
= (8.99 × 10⁹ × 2.406 × 10⁻³⁶) / (7.20 × 10⁻¹³)
= (2.163 × 10⁻²⁶) / (7.20 × 10⁻¹³)
= 3.00 × 10⁻¹⁴ m ≈ 3.0 × 10⁻¹⁴ m`,
  "phys-ocrb-h557-2024-p2::5(b)(ii)": `The calculation assumes that the alpha particle is brought to rest purely by the electrostatic repulsion of the nucleus, so 3.0 × 10⁻¹⁴ m is simply the closest that a 4.5 MeV alpha particle gets — it need not have touched the nuclear surface at all. An alpha particle of higher energy would get closer still before stopping, showing that the nucleus is smaller than this. The value therefore only sets an upper limit on the radius of the silver nucleus.`,
  "phys-ocrb-h557-2024-p2::5(c)": `Distance of closest approach: alpha particles are positively charged, like the nucleus, so they are repelled by it and are stopped by the Coulomb barrier while still outside the nucleus. Electrons carry the opposite charge, so they are attracted by the nucleus rather than repelled by it, and they feel no strong nuclear force either. There is no electrostatic barrier to turn them back, so electrons of high enough energy can reach the nucleus and probe its size directly.

Relativistic factor: the total energy of each electron is its 250 MeV of kinetic energy plus its rest energy of 0.511 MeV, so

γ = E_total / E_rest = 250.511 / 0.511 = 490

Since γ = 1/√(1 − v²/c²),

v = c√(1 − 1/γ²) = c√(1 − 1/490²) = 0.999998c = 3.0 × 10⁸ m s⁻¹ (to 2 s.f.)

A gamma factor of 490 therefore means the electrons are travelling at very nearly the speed of light.

de Broglie wavelength: using p = E/c with E = 250 MeV = 250 × 1.6 × 10⁻¹³ = 4.0 × 10⁻¹¹ J,

p = 4.0 × 10⁻¹¹ / 3.0 × 10⁸ = 1.33 × 10⁻¹⁹ kg m s⁻¹

λ = h/p = 6.63 × 10⁻³⁴ / 1.33 × 10⁻¹⁹ = 5.0 × 10⁻¹⁵ m

This wavelength is comparable with the size of a nucleus, which is why these electrons are diffracted by nuclei.

Diameter of the nucleus: in Fig. 5.2 the experimental curve dips well below the Rutherford curve, and the diffraction minimum lies at about θ = 22°. Using sin θ = 1.22λ/d,

d = 1.22λ / sin θ = (1.22 × 5.0 × 10⁻¹⁵) / sin 22° = 6.1 × 10⁻¹⁵ / 0.375

d = 1.6 × 10⁻¹⁴ m

so the nucleus has a diameter of about 1.6 × 10⁻¹⁴ m (a radius of roughly 8 × 10⁻¹⁵ m). Unlike the alpha-particle result this is a measurement of the nuclear size itself rather than an upper limit.`,
  "phys-ocrb-h557-2024-p2::5(d)(i)": `The nucleon shown in Fig. 5.3 contains two up (u) quarks and one down (d) quark. This quark combination (uud) has charge = 2/3 + 2/3 − 1/3 = +1, which is the charge of a proton. The nucleon shown is a proton.`,
  "phys-ocrb-h557-2024-p2::5(d)(ii)": `In the collision the electron transfers energy to the quarks inside the nucleon, and that energy appears as the jet of new particles. Part of it becomes the rest energy (mass) of the newly created particles and the remainder becomes their kinetic energy. Energy is conserved overall, and the energy given to the new particles can only have come from the electron, so the electron leaves the collision with less kinetic energy than it had before.`,
  "phys-ocrb-h557-2024-p2::6(a)(i)": `In beta-minus decay, a neutron converts to a proton, emitting a beta-minus particle (electron, ⁰₋₁e) and an antineutrino. Balancing the equation:
²³⁴₉₀Th → ²³⁴₉₁Pa + ⁰₋₁e + X
Mass number: 234 = 234 + 0 + 0 ✓
Atomic number: 90 = 91 + (−1) + 0 ✓
X must have zero mass number and zero charge, so X is an electron antineutrino: ν̄_e (antineutrino).`,
  "phys-ocrb-h557-2024-p2::6(a)(ii)": `Mass defect:
Δm = mass of thorium − mass of protactinium − mass of electron
= 233.9940 − 233.9934 − 0.00055
= 0.00005 u
Δm in kg = 0.00005 × 1.661 × 10⁻²⁷ = 8.305 × 10⁻³² kg
Energy released: E = Δmc² = 8.305 × 10⁻³² × (3.00 × 10⁸)²
= 8.305 × 10⁻³² × 9.00 × 10¹⁶
= 7.47 × 10⁻¹⁵ J ≈ 7.5 × 10⁻¹⁵ J`,
  "phys-ocrb-h557-2024-p2::6(a)(iii)": `The energy calculated in (a)(ii) is the maximum energy of the beta-minus particle because beta-minus decay also produces an antineutrino (X = ν̄_e). The total energy released (7.5 × 10⁻¹⁵ J) is shared between the beta-minus particle and the antineutrino. The electron only has the maximum kinetic energy when the antineutrino carries zero kinetic energy, which occurs only in a small fraction of decays. In general, the energy is shared between the electron and the antineutrino in a continuous spectrum, so the electron's energy is usually less than the maximum.`,
  "phys-ocrb-h557-2024-p2::6(b)(i)": `Activity A = λN, so N = A/λ.
Decay constant: λ = ln2 / t₁/₂
t₁/₂ = 4.51 × 10⁹ years = 4.51 × 10⁹ × 365.25 × 24 × 3600 s = 4.51 × 10⁹ × 3.156 × 10⁷ = 1.423 × 10¹⁷ s
λ = 0.693 / 1.423 × 10¹⁷ = 4.87 × 10⁻¹⁸ s⁻¹
N = A/λ = 9.6 / (4.87 × 10⁻¹⁸) = 1.97 × 10¹⁸ ≈ 2.0 × 10¹⁸ nuclei`,
  "phys-ocrb-h557-2024-p2::6(b)(ii)": `One third of the original nuclei decay: N_decayed = N₀/3, so N_remaining = N₀ − N₀/3 = 2N₀/3.
Using N = N₀e^(−λt):
2N₀/3 = N₀e^(−λt)
2/3 = e^(−λt)
ln(2/3) = −λt
−0.4055 = −λt
t = 0.4055 / λ = 0.4055 / (4.87 × 10⁻¹⁸) = 8.33 × 10¹⁶ s
Converting to years: t = 8.33 × 10¹⁶ / 3.156 × 10⁷ = 2.64 × 10⁹ years ≈ 2.6 × 10⁹ years`,
  "phys-ocrb-h557-2024-p2::6(c)(i)": `The reaction shows that one neutron absorbed by a U-235 nucleus produces, among the fission products, 3 neutrons. These 3 neutrons can each go on to be absorbed by other U-235 nuclei, each producing 3 more fission events and 9 neutrons. Provided a sufficient proportion of these neutrons cause further fissions (rather than being absorbed by non-fissile materials or escaping), the number of fissions grows exponentially — this is a chain reaction. For a sustained (critical) chain reaction, on average exactly one neutron from each fission must go on to cause another fission.`,
  "phys-ocrb-h557-2024-p2::6(c)(ii)": `To produce a steady power of 2.5 MW, the rate of fission of Pu-239 must be constant.
Rate of fissions needed: rate = P / E_per_fission = 2.5 × 10⁶ / 3.3 × 10⁻¹² = 7.576 × 10¹⁷ fissions s⁻¹.

Reasoning: The plutonium is produced by the decay of Np-239. For a steady state, the rate of production of Pu-239 (= rate of decay of Np-239) must equal the rate of fission of Pu-239 (assuming all Pu produced immediately fissions, which is the minimum mass condition).
Rate of decay of Np-239 = λ_Np × N_Np = rate of fission required = 7.576 × 10¹⁷ s⁻¹.
N_Np = rate / λ_Np = 7.576 × 10¹⁷ / 3.4 × 10⁻⁶ = 2.228 × 10²³ atoms.
Mass of Np-239: m = N_Np × m_atom = 2.228 × 10²³ × 3.97 × 10⁻²⁵ = 8.84 × 10⁻² kg ≈ 88 g.`,
  "phys-ocrb-h557-2024-p2::7(a)": `The wavelengths plotted on the x-axis cover an enormous range, from the very short wavelengths of gamma rays to the long wavelengths of radio waves — many powers of ten. A logarithmic scale compresses that range so that the whole electromagnetic spectrum fits on one axis and detail can still be seen at both ends; on a linear scale everything shorter than visible light would be crushed into the first fraction of a millimetre of the axis.

It makes the data harder to interpret because equal distances along the axis no longer represent equal changes in wavelength — each equal step multiplies the wavelength by ten rather than adding a fixed amount. Equal ranges of wavelength therefore have very different widths in different parts of the scale, and intermediate values have to be worked out rather than simply read off.`,
  "phys-ocrb-h557-2024-p2::7(b)": `The proportion absorbed per kilometre depends on the density of the atmosphere being crossed. The air near the ground is far denser than the air at the top of the atmosphere, so there are many more atoms in each kilometre of path; the chance of a gamma photon interacting with a particle in that kilometre is correspondingly greater, so the fraction absorbed per km increases steadily as the rays descend and is not the same all the way down.

The energy (and hence frequency or wavelength) of the gamma rays also matters: higher energy gamma rays have more energy to transfer in collisions and are scattered and absorbed differently from lower energy ones, so gamma rays of different energies are absorbed at different rates per kilometre.`,
  "phys-ocrb-h557-2024-p2::8(a)": `The Rayleigh criterion gives the angular resolution limit:
θ = 1.22λ/D = 1.22 × 2000 × 10⁻⁹ / 6.5
= 1.22 × 2.00 × 10⁻⁶ / 6.5
= 2.44 × 10⁻⁶ / 6.5
= 3.75 × 10⁻⁷ rad ≈ 0.4 μrad ✓`,
  "phys-ocrb-h557-2024-p2::8(b)(i)": `image resolution = angular width / number of pixels = 0.60 × 10⁻³ / 4121

image resolution = 1.5 × 10⁻⁷ rad pixel⁻¹ (0.15 μrad per pixel)

Suggestion: the telescope's resolution limit is 1.22λ/D, which is proportional to wavelength. The camera also works at wavelengths much shorter than 2000 nm, and at those shorter wavelengths the resolution limit is smaller than the 0.4 μrad calculated in (a). The pixels must be small enough to resolve that finer detail; if each pixel covered more than the resolution limit the sharpness of the image would be set by the detector rather than by the optics, and detail the telescope can actually resolve would be thrown away.`,
  "phys-ocrb-h557-2024-p2::8(b)(ii)": `Recession speed from the redshift:

z = Δλ/λ = (668 − 657) / 657 = 11 / 657 = 0.0167

v = zc = 0.0167 × 3.0 × 10⁸ = 5.0 × 10⁶ m s⁻¹

Distance from Hubble's law. First convert the Hubble constant to SI units:

H₀ = 73 × 10³ / (3.1 × 10²²) = 2.4 × 10⁻¹⁸ s⁻¹

d = v / H₀ = 5.0 × 10⁶ / 2.4 × 10⁻¹⁸ = 2.1 × 10²⁴ m

d = 2.1 × 10²⁴ / 9.5 × 10¹⁵ = 2.2 × 10⁸ light years, i.e. about 223 million light years.

Width of the main section. The whole image in Fig. 8 spans 0.60 mrad, and the line AB is a little over half of the image width, about 0.32 mrad. For such a small angle,

width = θ × d = 0.32 × 10⁻³ × 2.23 × 10⁸

width = 7.2 × 10⁴ light years, so the main section of the galaxy is roughly 72 000 light years across.

Comment on possible causes of error: the largest uncertainty is in the Hubble constant itself. The accepted value has changed considerably over the years, and measurements made in different ways still disagree by several per cent, so the distance — and therefore the width, which is proportional to it — carries the same percentage error. The Hubble 'constant' also need not have had the same value throughout the 220 million years the light has been travelling. On top of that, the angular separation AB has to be measured by eye from the image: A and B mark a diffuse edge rather than a sharp one, and the image itself is only resolved to 0.15 μrad per pixel, so the 0.32 mrad reading could easily be a few per cent out. Any motion of the galaxy of its own, in addition to the expansion of the universe, would also alter the measured redshift and hence the calculated distance.`,
  "phys-ocrb-h557-2024-p2::9": `The total energy of the satellite is constant, so the sum of its gravitational potential energy and its kinetic energy is the same at every point of the orbit. Working per kilogram of satellite:

At the furthest point, r = 1.5 × 10⁸ m and v = 1.1 × 10³ m s⁻¹:

E/m = −GM/r + ½v² = −(6.67 × 10⁻¹¹ × 6.0 × 10²⁴) / (1.5 × 10⁸) + ½ × (1.1 × 10³)²

= −2.668 × 10⁶ + 6.05 × 10⁵ = −2.063 × 10⁶ J kg⁻¹

At the nearest approach, r = 1.6 × 10⁷ m, the total energy per kilogram is unchanged:

−(6.67 × 10⁻¹¹ × 6.0 × 10²⁴) / (1.6 × 10⁷) + ½v² = −2.063 × 10⁶

−2.501 × 10⁷ + ½v² = −2.063 × 10⁶

½v² = 2.295 × 10⁷

v² = 4.59 × 10⁷

speed = 6.8 × 10³ m s⁻¹`,
  "phys-ocrb-h557-2024-p2::10(a)": `L2 lies beyond the Earth on the Sun–Earth line, so its distance from the Sun is

r_Sun = 1.5 × 10¹¹ + 1.5 × 10⁹ = 1.515 × 10¹¹ m

At L2 both the Sun and the Earth lie on the same side, so their fields point in the same direction and their magnitudes add.

Field due to the Sun:

g_Sun = −GM_Sun / r² = −(6.67 × 10⁻¹¹ × 2.0 × 10³⁰) / (1.515 × 10¹¹)² = −5.81 × 10⁻³ N kg⁻¹

Field due to the Earth:

g_Earth = −GM_Earth / r² = −(6.67 × 10⁻¹¹ × 6.0 × 10²⁴) / (1.5 × 10⁹)² = −1.8 × 10⁻⁴ N kg⁻¹

Resultant field strength:

g = −5.81 × 10⁻³ + (−1.8 × 10⁻⁴) = −5.99 × 10⁻³ N kg⁻¹

The negative sign shows that the resultant field of 5.99 × 10⁻³ N kg⁻¹ is directed inwards, towards the Sun.`,
  "phys-ocrb-h557-2024-p2::10(b)(i)": `The resultant field strength at L2 provides the centripetal acceleration for circular motion round the Sun at radius r = 1.515 × 10¹¹ m:

g = v²/r = 4π²r / T² = 5.99 × 10⁻³ N kg⁻¹

T² = 4π²r / g = (4π² × 1.515 × 10¹¹) / (5.99 × 10⁻³) = 5.98 × 10¹² / 5.99 × 10⁻³ = 9.98 × 10¹⁴ s²

T = 3.16 × 10⁷ s, which is about 3.2 × 10⁷ s as required — the same as the Earth's orbital period of one year, which is why the JWST stays at L2 as the Earth moves round the Sun.`,
  "phys-ocrb-h557-2024-p2::10(b)(ii)": `Mass of the Moon = 0.01 × 6.0 × 10²⁴ = 6.0 × 10²² kg.

The Moon orbits the Earth at 3.8 × 10⁸ m while L2 is 1.5 × 10⁹ m from the Earth, so as the Moon goes round each month its distance from L2 varies between about 1.5 × 10⁹ − 3.8 × 10⁸ = 1.1 × 10⁹ m and 1.5 × 10⁹ + 3.8 × 10⁸ = 1.9 × 10⁹ m, and sometimes the Moon lies on the Sun–Earth–L2 line and sometimes well off it.

At its closest the Moon's field at L2 is largest:

g_Moon = (6.67 × 10⁻¹¹ × 6.0 × 10²²) / (1.12 × 10⁹)² = 3.2 × 10⁻⁶ N kg⁻¹

That is only about 0.05% of the 5.99 × 10⁻³ N kg⁻¹ already there: the maximum total field becomes 6.0 × 10⁻³ N kg⁻¹ and the orbital speed stays at 3.0 × 10⁴ m s⁻¹ to 2 s.f.

So the Moon has only a very small effect and does not stop the JWST orbiting L2. Its effect is not quite zero, though: because its distance from L2 and its direction both change through the month, the resultant field at L2 varies slightly and periodically, and this varying field slowly disturbs the telescope's path around L2, so small corrections have to be made.`,
  "phys-ocrb-h557-2024-p3::1(a)": `Put a few drops of water (or of oil) into the hole before pushing the thermometer in. The liquid fills the air gap between the thermometer bulb and the aluminium, so heat passes readily from the block to the bulb and the thermometer records the block's temperature rather than lagging behind it.`,
  "phys-ocrb-h557-2024-p3::1(b)(i)": `For each data point on Fig. 1.2, draw a vertical bar (error bar) extending ±1.0°C above and below the plotted point. Each bar should be centred on the data point and have a total length corresponding to 2.0°C on the temperature axis scale.`,
  "phys-ocrb-h557-2024-p3::1(b)(ii)": `Draw the two extreme ruled straight lines that still pass inside every one of the eleven uncertainty bars, each extended right across the grid from t = 0 to t = 10 minutes.

Maximum-gradient (steepest) line: since the temperature is rising, the steepest acceptable line starts at the bottom of an early bar and finishes at the top of a later bar — draw it through (0 min, 19 °C) and (8 min, 33 °C).

Minimum-gradient (shallowest) line: this one starts at the top of an early bar and finishes at the bottom of a later bar — draw it through (2 min, 23 °C) and (10 min, 35 °C).

Both lines must be thin and ruled, and must still pass through every uncertainty bar.`,
  "phys-ocrb-h557-2024-p3::1(b)(iii)": `Steepest line — read two widely separated points on it: (0 min, 19.0 °C) and (8 min, 33.0 °C)

gradient = (33.0 − 19.0)/(8 − 0) = 1.75 °C min⁻¹ = 1.75/60 = 0.0292 °C s⁻¹

Shallowest line — (2 min, 23.0 °C) and (10 min, 35.0 °C)

gradient = (35.0 − 23.0)/(10 − 2) = 1.50 °C min⁻¹ = 1.50/60 = 0.0250 °C s⁻¹

mean rate = ½(0.0292 + 0.0250) = 0.0271 °C s⁻¹
uncertainty = ½(0.0292 − 0.0250) = 0.0021 °C s⁻¹
percentage uncertainty = (0.0021/0.0271) × 100 = 7.7 %

rate of temperature rise = 0.027 °C s⁻¹ ± 7.7 %`,
  "phys-ocrb-h557-2024-p3::1(c)(i)": `The energy needed to raise the temperature of the block by Δθ is

E = mcΔθ

and the heater delivers that energy in time t at a rate

P = E/t

Substituting the first expression into the second:

P = mcΔθ/t

Rearranging for Δθ/t, which is exactly the gradient of the temperature–time graph:

gradient = Δθ/t = P/(mc)

which is the required result.`,
  "phys-ocrb-h557-2024-p3::1(c)(ii)": `Power supplied to the heater:

P = IV = 3.76 × 9.6 = 36.1 W

From gradient = P/(mc), with the mean gradient 0.0271 °C s⁻¹ from part (b)(iii):

c = P/(m × gradient) = 36.1/(1.00 × 0.0271) = 1330 J kg⁻¹ K⁻¹

Percentage uncertainties, added because c is a product/quotient of the quantities:
pd 2 % and current 0.9 %, so power 2.9 %
mass (0.01/1.00) × 100 = 1 %
gradient 7.7 % (from part (b)(iii))
total = 2.9 + 1 + 7.7 = 11.6 %

absolute uncertainty = 0.116 × 1330 = 150 J kg⁻¹ K⁻¹

specific thermal capacity = 1330 ± 150 J kg⁻¹ K⁻¹`,
  "phys-ocrb-h557-2024-p3::1(d)": `The experimental value, about 1330 J kg⁻¹ K⁻¹, is much higher than the textbook value of 900 J kg⁻¹ K⁻¹ — the difference of more than 400 J kg⁻¹ K⁻¹ is far larger than the ±150 J kg⁻¹ K⁻¹ uncertainty, so it cannot be explained by the uncertainties alone.

The main reason is that not all of the electrical energy supplied by the heater goes into warming the aluminium. The block is not insulated, so energy is transferred to the surroundings from its surfaces and through the bench while the heating is going on. The block therefore warms more slowly than it would if all the power reached it, the measured gradient is too small, and since c = P/(m × gradient) a gradient that is too small makes the calculated value of c too large.`,
  "phys-ocrb-h557-2024-p3::2(a)": `Conductance G = I/V = 7.5 × 10⁻³ / 0.65 = 0.01154 S

Percentage uncertainty in I: 0.02/7.5 × 100 = 0.267%
Percentage uncertainty in V: 0.02/0.65 × 100 = 3.08%
Total percentage uncertainty in G = 0.267% + 3.08% = 3.35% ≈ 3.3%
Absolute uncertainty = 3.35% × 0.01154 = ±3.9 × 10⁻⁴ S ≈ ±4 × 10⁻⁴ S

G = (1.15 ± 0.04) × 10⁻² S`,
  "phys-ocrb-h557-2024-p3::2(b)": `Vary the potential difference. Set the variable d.c. supply to a series of different emfs and, at each setting, record the voltmeter reading (the pd across the diode) and the ammeter reading (the current through it); plot these pairs as the I–V graph. Reverse the supply connections to obtain the reverse-bias points.

Use small increments of pd, and take many more readings close to the threshold pd (around 0.6–0.7 V), because that is where the current changes most rapidly and the interesting part of the curve lies; larger steps are adequate well away from it.

The fixed resistor protects the circuit. Once the threshold pd is exceeded the resistance of the diode becomes very small, so without the resistor the current would rise to a very large value and destroy the diode. The resistor takes the rest of the supply emf and so limits the current to a safe value.`,
  "phys-ocrb-h557-2024-p3::2(c)": `The graph of I against V for a semiconductor diode: In forward bias (positive V), the current is very small for V below about 0.5 V (the threshold voltage), then increases very steeply and exponentially once V exceeds the threshold (approximately 0.6–0.7 V). In reverse bias (negative V), the current is approximately zero (a very small, nearly constant reverse saturation current) for all reverse voltages within the normal operating range, until breakdown voltage is reached (not normally shown on A-level graphs). The sketch should show: a curve that hugs the x-axis for V > 0 up to ~0.6 V, then rises steeply; and a flat line very close to the I = 0 axis for negative V.`,
  "phys-ocrb-h557-2024-p3::2(d)": `In forward bias, the current increases very steeply with voltage, so very small changes in voltage produce large changes in current. A standard ammeter and voltmeter may have insufficient precision to measure both accurately. To improve accuracy:
1. Use a milliammeter (or microammeter for reverse bias) with a small full-scale deflection and high sensitivity, so that the small forward currents near threshold and any reverse currents can be measured accurately.
2. Use a high-precision voltmeter (with high input impedance) to measure the small potential differences across the diode accurately, particularly in the threshold region where V changes by only a few millivolts.
3. For the reverse bias region, use a microammeter, since the reverse current may be only a few microamps.
4. Use a rheostat or potential divider to allow fine control of the voltage, since the steep I–V characteristic means coarse voltage changes would skip many data points in the important threshold region.`,
  "phys-ocrb-h557-2024-p3::3(a)": `Using the lens formula 1/v − 1/u = 1/f (with the sign convention that u is negative for a real object):
The formula can be written as 1/v + 1/|u| = 1/f, or in the form used here 1/v = 1/f + 1/u.

Row 2: u = −0.115 m → 1/u = 1/(−0.115) = −8.70 m⁻¹
Row 3: v = 0.394 m → 1/v = 1/0.394 = 2.54 m⁻¹
Row 4: u = −0.154 m → 1/u = −6.49 m⁻¹; v = 0.245 m → 1/v = 4.08 m⁻¹

Completed table values:
- Row 2: 1/u = −8.70 m⁻¹, 1/v = 1.85 m⁻¹ (given)
- Row 3: 1/u = −7.75 m⁻¹ (given), 1/v = 2.54 m⁻¹
- Row 4: 1/u = −6.49 m⁻¹, 1/v = 4.08 m⁻¹`,
  "phys-ocrb-h557-2024-p3::3(b)": `Set the axes up as instructed: label the x-axis 1/u / m⁻¹ running from −12 at the left to 0, and the y-axis 1/v / m⁻¹ running from 0 up to +12, choosing scales that fill the grid and are easy to read — for example 1 cm to 1 m⁻¹ on the x-axis and 2 cm to 1 m⁻¹ on the y-axis.

Plot the five points from the completed table as small sharp crosses (not blobs):

(−9.53, 1.37), (−8.70, 1.85), (−7.75, 2.54), (−6.49, 4.08), (−4.67, 5.78)

Then draw one thin ruled line of best fit through them, with roughly equal numbers of points just above and just below it, and extend it beyond the outermost points so that it cuts both axes. Since 1/v = 1/u + 1/f the line has a gradient of about +1; it should meet the y-axis a little above +10 m⁻¹ and the x-axis at about −11 m⁻¹.`,
  "phys-ocrb-h557-2024-p3::3(c)": `The lens equation 1/v − 1/u = 1/f can be written

1/v = 1/u + 1/f

so on this graph the y-intercept (where 1/u = 0) is 1/f, and the x-intercept (where 1/v = 0) is −1/f.

Reading both intercepts from the line of best fit:
y-intercept = 10.1 m⁻¹, giving 1/f = 10.1 m⁻¹
x-intercept = −10.8 m⁻¹, giving 1/f = 10.8 m⁻¹

mean value of 1/f = ½(10.1 + 10.8) = 10.45 m⁻¹

f = 1/10.45 = 0.0957 m

focal length = 0.096 m`,
  "phys-ocrb-h557-2024-p3::3(d)": `Sources of uncertainty and limitations:
1. Measurement of object distance u: the position of the object (e.g. a lamp or cross-wire) and the optical centre of the lens are difficult to locate precisely; parallax errors when reading the optical bench scale introduce uncertainty in u. Similarly, locating the exact position of the sharpest image to measure v is subjective — different observers may judge 'sharp' differently.
2. The lens has a finite thickness; the thin lens formula assumes a thin lens, so the use of a thick lens introduces systematic error.
3. Chromatic aberration: the focal length varies with wavelength; white light gives a slightly blurred image, so using a monochromatic filter eliminates this by ensuring all light has the same wavelength and therefore the same focal length. This reduces the spread in image position and makes determining v more precise.
4. Spherical aberration: rays passing through the outer edges of the lens focus at a slightly different point than paraxial rays, blurring the image. Using a small aperture (stop) reduces this.
5. The range of u values is limited by the length of the optical bench and the requirement that v must be positive (real image). Extending the range of u would give a longer best-fit line and reduce the uncertainty in the intercept (and hence in f).

Improvements:
- Use a monochromatic filter to eliminate chromatic aberration, giving a sharper image and more precise v measurements.
- Use a bright, well-defined object (e.g. illuminated cross-wire or LED point source) to make judging the sharp image easier.
- Take repeated measurements of v for each value of u and average them to reduce random errors.
- Use a camera or CCD detector to objectively determine when the image is sharpest, removing the subjective judgement.
- Use a longer optical bench to extend the range of u values and reduce the percentage uncertainty in each measurement.`,
  "phys-ocrb-h557-2024-p3::4(a)": `Momentum is conserved in the impact, and since the spacecraft becomes embedded the two bodies move together afterwards:

m_DART × u = (m_DART + m_Dimorphos) × v

The mass of Dimorphos is so much greater than that of DART that 570 + 4.8 × 10⁹ ≈ 4.8 × 10⁹ kg, so

v = (570 × 6000)/(4.8 × 10⁹) = (3.42 × 10⁶)/(4.8 × 10⁹)

v = 7.1 × 10⁻⁴ m s⁻¹

Assumption: all of DART's linear momentum is transferred to the linear momentum of Dimorphos — none of it sets Dimorphos rotating or is carried away by material ejected from the surface, Dimorphos stays intact and the whole of the spacecraft ends up embedded in it. (Because 6.0 km s⁻¹ is a relative velocity, the answer is the change in the velocity of Dimorphos.)`,
  "phys-ocrb-h557-2024-p3::4(b)": `What matters is the ratio of the two masses rather than the difference between them. For the real collision

4.8 × 10⁹ / 570 = 8.4 × 10⁶

so Dimorphos is about 8.4 million times as massive as DART.

To reproduce that ratio on the air track, either the rider playing the part of the spacecraft would have to have a mass of

150 g ÷ (8.4 × 10⁶) ≈ 1.8 × 10⁻⁸ kg = 18 μg

if the 150 g rider represents the asteroid, or the rider playing the part of the asteroid would have to have a mass of

150 g × (8.4 × 10⁶) ≈ 1.3 × 10⁶ kg

if the 150 g rider represents the spacecraft. Neither an 18 μg rider nor a 1300 tonne rider is possible on a laboratory air track, and the velocity given to the struck rider would be smaller than the approach velocity by the same factor of 8.4 × 10⁶, far too small for the ultrasonic ranging device to detect. Modelling the DART collision with this apparatus is therefore impractical.`,
  "phys-ocrb-h557-2024-p3::4(c)(i)": `The two riders have equal masses and the first is assumed to stop dead, so conservation of momentum gives

0.150 × u = 0.150 × v₂ , so u = v₂

Reading Fig. 4.3 where the line meets the velocity axis at t = 0, the second rider leaves the collision at 0.90 m s⁻¹.

maximum velocity = 0.90 m s⁻¹`,
  "phys-ocrb-h557-2024-p3::4(c)(ii)": `The line on Fig. 4.3 is straight, so the deceleration is constant. Reading its two ends: v = 0.90 m s⁻¹ at t = 0 and v = 0.80 m s⁻¹ at t = 1.0 s.

a = Δv/Δt = (0.90 − 0.80)/1.0 = 0.10 m s⁻²

F = ma = 0.150 × 0.10

magnitude of force = 0.015 N`,
  "phys-ocrb-h557-2024-p3::4(c)(iii)": `Momentum is conserved. Taking the original direction of the 150 g rider as positive, it rebounds so its final velocity is −0.23 m s⁻¹, and its approach velocity is the 0.90 m s⁻¹ found in part (i):

0.150 × 0.90 = 0.150 × (−0.23) + 0.250 × v
0.135 = −0.0345 + 0.250v
0.250v = 0.1695
v = 0.68 m s⁻¹

The 250 g rider therefore moves away at 0.68 m s⁻¹, which is smaller than the 0.90 m s⁻¹ shown in Fig. 4.3 for the 150 g rider.`,
  "phys-ocrb-h557-2024-p3::4(d)": `The graph (Fig. 4.5) shows the velocity of the rider with the sail decreasing more rapidly than the rider without the sail (Fig. 4.3). The shape of the graph is a curve (not a straight line) — the rate of decrease of velocity becomes smaller as the velocity decreases. This is because the drag force is proportional to v² (F_D ∝ v²): when the rider moves fast, the drag force is large, causing rapid deceleration; as the rider slows down, the drag force decreases (proportionally to v²), so the deceleration also decreases, producing a curved (convex) velocity–time graph rather than the linear graph seen without the sail.`,
  "phys-ocrb-h557-2024-p3::4(e)": `Plan to investigate F_D ∝ v²:

Aim: To test whether the drag force on the rider (with sail) is proportional to the square of its velocity.

Apparatus and method:
1. Set up the air track horizontally and attach the sail to the 250 g rider. Position the ultrasonic ranging device at one end to record the velocity–time graph of the rider after a collision.
2. Use a pulley and hanging weights attached to the rider to apply a known, constant driving force to the rider, allowing the rider to reach a terminal velocity. At terminal velocity, the driving force equals the drag force: F_D = F_drive = mg (weight of hanging mass). Record the terminal velocity v_terminal using the ultrasonic ranging device or by reading the constant final velocity from the velocity–time graph.
3. Vary the driving force by changing the hanging mass, and record the corresponding terminal velocity for each force. This gives pairs of (F_D, v_terminal).
4. Alternatively (using the fan): use the variable-speed fan directed at the sail to apply a drag force while the rider moves. Use the anemometer to measure wind speed and the ranging device to measure rider deceleration after a collision (as in the original experiment). Adjust fan speed and repeat.

Data analysis:
If F_D ∝ v², then F_D = kv² for some constant k. Plot F_D against v²: if the relationship holds, the graph should be a straight line through the origin. Calculate the gradient k.
Alternatively, from the free-deceleration experiment: the equation of motion is ma = −kv². By differentiating the v–t data (finding dv/dt = a at each instant), plot a against v² — if F_D ∝ v², this graph should be linear through the origin.

Diagram: air track with 250 g rider fitted with sail, ultrasonic ranging device at one end, pulley at the other end with hanging masses on a string, anemometer positioned near the sail.

Conclusion criterion: If the graph of F_D against v² is a straight line passing through the origin, the hypothesis F_D ∝ v² is confirmed. If it is curved or has a non-zero intercept, the relationship does not hold.`,
};